INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261201-case-01','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০১: পুকুরের ভোরবেলার রহস্য','রাতে সব ঠিকঠাক। ভোরে উঠে মাছচাষি রহিম মিয়া দেখলেন, পুকুরভর্তি মাছ পানির ওপর মুখ তুলে হাঁসফাঁস করছে, কয়েকটা ভেসেও উঠেছে। রোদ চড়তেই বাকিরা আবার স্বাভাবিক।','["তাঁর সন্দেহ: কেউ বিষ দিয়েছে। কিন্তু প্রমাণ কী বলছে?"]','[{"label": "SRAC (Mississippi State University) fact", "url": "https://srac.msstate.edu/pdfs/Fact%20Sheets/4601%20Measuring%20Dissolved%20Oxygen%20Concentration%20in%20Aquaculture.pdf"}, {"label": "Mississippi State University Extension", "url": "https://extension.msstate.edu/natural-resources/fisheries/pond-and-lake-management/fish-kills"}]','[{"src": "/media/goyenda-bhabu/261201-case-01-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০১: পুকুরের ভোরবেলার রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261201-case-01-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০১: পুকুরের ভোরবেলার রহস্য, কার্ড 2"}]','["Dead Fish in a River 2.jpg by Gannu03, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Dead_Fish_in_a_River_2.jpg", "365 Ponds.jpg by Zitu.madcap0901125, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:365_Ponds.jpg"]','physics','eye','deep',1,'2026-12-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261202-case-01-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০১-এর সমাধান: আসামি অক্সিজেনের ঘাটতি!','দিনে পুকুরের শ্যাওলা আর জলজ উদ্ভিদ সূর্যের আলোয় অক্সিজেন ছাড়ে। রাতে আলো নেই, তাই অক্সিজেন তৈরি বন্ধ, কিন্তু শ্যাওলা, মাছ, পানির জীবাণু সবাই সারারাত অক্সিজেন খরচ করে যায়।','["ফলে সূর্য ওঠার আগে-পরে পানিতে অক্সিজেন সবচেয়ে কম থাকে, আর মাছ ওপরে উঠে খাবি খায়। গরমে আর মেঘলা গুমোট রাতে বিপদ বাড়ে, বেশি খাবার বা সার দিলেও। তাই অনেক চাষি রাতে এয়ারেটর চালান।\\nবিষ দেওয়ার অভিযোগ তোলার আগে তাই প্রমাণ দেখা জরুরি!"]','[{"label": "SRAC (Mississippi State University) fact", "url": "https://srac.msstate.edu/pdfs/Fact%20Sheets/4601%20Measuring%20Dissolved%20Oxygen%20Concentration%20in%20Aquaculture.pdf"}, {"label": "Mississippi State University Extension", "url": "https://extension.msstate.edu/natural-resources/fisheries/pond-and-lake-management/fish-kills"}]','[{"src": "/media/goyenda-bhabu/261202-case-01-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০১-এর সমাধান: আসামি অক্সিজেনের ঘাটতি!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261202-case-01-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০১-এর সমাধান: আসামি অক্সিজেনের ঘাটতি!, কার্ড 2"}]','["Dead Fish in a River 2.jpg by Gannu03, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Dead_Fish_in_a_River_2.jpg", "365 Ponds.jpg by Zitu.madcap0901125, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:365_Ponds.jpg"]','physics','eye','deep',1,'2026-12-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261208-case-02','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০২: খেজুরের রসের রহস্য','শীতের ভোরে গাছি করিম ভাই হাঁড়ি নামালেন: রস মিষ্টি, ঠান্ডা, দারুণ। দুপুরে সেই একই হাঁড়ির রস ঝাঁঝালো আর টক! সন্ধ্যায় আরও টক, অথচ হাঁড়ি একবারও খোলা হয়নি।','["করিম ভাইয়ের সন্দেহ: কেউ কিছু মিশিয়েছে। কিন্তু সত্যিই কি তাই?"]','[{"label": "SRAC (Mississippi State University) fact", "url": "https://srac.msstate.edu/pdfs/Fact%20Sheets/4601%20Measuring%20Dissolved%20Oxygen%20Concentration%20in%20Aquaculture.pdf"}, {"label": "Mississippi State University Extension", "url": "https://extension.msstate.edu/natural-resources/fisheries/pond-and-lake-management/fish-kills"}]','[{"src": "/media/goyenda-bhabu/261208-case-02-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০২: খেজুরের রসের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261208-case-02-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০২: খেজুরের রসের রহস্য, কার্ড 2"}]','["Neera phoenix.JPG by Pakshya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Neera_phoenix.JPG", "Nargun date palm garden.jpg by Prokash majumder, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Nargun_date_palm_garden.jpg"]','physics','eye','deep',1,'2026-12-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261209-case-02-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০২-এর সমাধান: আসামি খুদে ইস্ট আর ব্যাকটেরিয়া!','খেজুরের রসে প্রচুর চিনি থাকে। রস নামানোর পর থেকেই ইস্ট (যেমন Saccharomyces) সেই চিনিকে খেয়ে অ্যালকোহল বানাতে থাকে, আর ল্যাকটিক অ্যাসিড ব্যাকটেরিয়া বানায় অ্যাসিড। গবেষণায় দেখা গেছে, গাঁজনের সময় রসের pH কমে আর অ্যাসিড ও অ্যালকোহল বাড়ে। এই অ্যাসিডই রসকে টক করে। গাছির কোনো দোষ নেই!','["⚠️ কিন্তু একটা জরুরি কথা: কাঁচা খেজুরের রস বাদুড়ের লালায় দূষিত হতে পারে, আর তাতে নিপাহ ভাইরাস ছড়াতে পারে। বাংলাদেশে ২০০১ সাল থেকে প্রায় প্রতি বছর নিপাহ সংক্রমণ ধরা পড়েছে। WHO বলছে, টাটকা রস ফুটিয়ে নিন আর সংগ্রহের জায়গায় ঢাকনা দিয়ে বাদুড় ঠেকান।"]','[{"label": "SRAC (Mississippi State University) fact", "url": "https://srac.msstate.edu/pdfs/Fact%20Sheets/4601%20Measuring%20Dissolved%20Oxygen%20Concentration%20in%20Aquaculture.pdf"}, {"label": "Mississippi State University Extension", "url": "https://extension.msstate.edu/natural-resources/fisheries/pond-and-lake-management/fish-kills"}]','[{"src": "/media/goyenda-bhabu/261209-case-02-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০২-এর সমাধান: আসামি খুদে ইস্ট আর ব্যাকটেরিয়া!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261209-case-02-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০২-এর সমাধান: আসামি খুদে ইস্ট আর ব্যাকটেরিয়া!, কার্ড 2"}]','["Neera phoenix.JPG by Pakshya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Neera_phoenix.JPG", "Nargun date palm garden.jpg by Prokash majumder, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Nargun_date_palm_garden.jpg"]','physics','eye','deep',1,'2026-12-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261215-case-03','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৩: লাল হয়ে যাওয়া গেটের রহস্য','গত বছর রং করা গেটের গায়ে এখন লাল ছোপ, হাত দিলে লালচে গুঁড়ো লাগে। দারোয়ান বলছেন, রংটা নকল ছিল। কিন্তু প্রমাণ কী বলছে?','["গত বছর রং করা গেটের গায়ে এখন লাল ছোপ, হাত দিলে লালচে গুঁড়ো লাগে। দারোয়ান বলছেন, রংটা নকল ছিল। কিন্তু প্রমাণ কী বলছে?"]','[{"label": "PopSci", "url": "https://www.popsci.com/science/what-is-rust/"}, {"label": "Tutopiya (Cambridge IGCSE chemistry)", "url": "https://www.tutopiya.com/lesson-notes/igcse-cambridge-chemistry/rusting-and-alloys/"}]','[{"src": "/media/goyenda-bhabu/261215-case-03-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৩: লাল হয়ে যাওয়া গেটের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261215-case-03-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৩: লাল হয়ে যাওয়া গেটের রহস্য, কার্ড 2"}]','["Rusty iron bars - geograph.org.uk - 7061654.jpg by Alan Hughes, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Rusty_iron_bars_-_geograph.org.uk_-_7061654.jpg", "Rusty gate.JPG by Jotpe, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rusty_gate.JPG"]','physics','eye','deep',1,'2026-12-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261217-case-03-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৩-এর সমাধান: লোহা, অক্সিজেন আর পানি!','লোহার ওপর পানি আর বাতাসের অক্সিজেন থাকলে লোহা ধীরে ধীরে আয়রন অক্সাইডে বদলে যায়: সেটাই মরচে। মরচের স্তর ছিদ্রযুক্ত, তাই ভেতরে বাতাস-পানি ঢুকতেই থাকে।','["• লবণ মরচের গতি বাড়ায়: তাই সাগরের কাছে, কক্সবাজার বা চট্টগ্রামের উপকূলে গেট দ্রুত নষ্ট হয়।\\n• রং বা তেল-গ্রিজ বাতাস-পানি আটকে রাখে। চটে গেলেই আবার রং দিন।\\n• দস্তার (জিংক) প্রলেপ লোহার বদলে নিজে ক্ষয় হয়: একে বলে সুরক্ষা।"]','[{"label": "PopSci", "url": "https://www.popsci.com/science/what-is-rust/"}, {"label": "Tutopiya (Cambridge IGCSE chemistry)", "url": "https://www.tutopiya.com/lesson-notes/igcse-cambridge-chemistry/rusting-and-alloys/"}]','[{"src": "/media/goyenda-bhabu/261217-case-03-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৩-এর সমাধান: লোহা, অক্সিজেন আর পানি!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261217-case-03-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৩-এর সমাধান: লোহা, অক্সিজেন আর পানি!, কার্ড 2"}]','["Rusty iron bars - geograph.org.uk - 7061654.jpg by Alan Hughes, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Rusty_iron_bars_-_geograph.org.uk_-_7061654.jpg", "Rusty gate.JPG by Jotpe, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rusty_gate.JPG"]','physics','eye','deep',1,'2026-12-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261222-case-04','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৪: ভোরের কুয়াশার রহস্য','শীতের ভোরে চারদিক ধোঁয়াটে সাদা, দশ হাত দূরের জিনিসও ঝাপসা। বেলা ১১টায় সব পরিষ্কার! মাঝি বলছেন, নদীর পানি ফুটে ওঠে কুয়াশা। কিন্তু সত্যিই কি তাই?','["শীতের ভোরে চারদিক ধোঁয়াটে সাদা, দশ হাত দূরের জিনিসও ঝাপসা। বেলা ১১টায় সব পরিষ্কার! মাঝি বলছেন, নদীর পানি ফুটে ওঠে কুয়াশা। কিন্তু সত্যিই কি তাই?"]','[{"label": "Met Office", "url": "https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/fog"}, {"label": "Boldmethod", "url": "https://www.boldmethod.com/blog/lists/2024/10/four-signs-that-radiation-fog-is-about-to-form/"}, {"label": "US National Weather Service", "url": "https://www.weather.gov/safety/fog"}]','[{"src": "/media/goyenda-bhabu/261222-case-04-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৪: ভোরের কুয়াশার রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261222-case-04-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৪: ভোরের কুয়াশার রহস্য, কার্ড 2"}]','["Foggy Winter Morning in Bangladesh.jpg by ZahidTushar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Foggy_Winter_Morning_in_Bangladesh.jpg", "Fog morning of river side.jpg by Shikdernazim2, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fog_morning_of_river_side.jpg"]','physics','eye','deep',1,'2026-12-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261223-case-04-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৪-এর সমাধান: ঠান্ডা আর্দ্র বাতাস!','কুয়াশা হলো মাটির কাছে ভেসে থাকা মেঘ, অতি ক্ষুদ্র পানির কণার সমষ্টি। পরিষ্কার, শান্ত রাতে মাটি তাপ হারিয়ে ঠান্ডা হয়, পাশের বাতাসও ঠান্ডা হয়। আর্দ্র বাতাস এত ঠান্ডা হলে বাষ্প ঘনীভূত হয়ে কণা হয়ে যায়। রোদে মাটি গরম হলে কুয়াশা সাধারণত কেটে যায়।','["• দৃষ্টিসীমা ১,০০০ মিটারের কম হলে কুয়াশা। ১০০ মিটারের কম হলে ঘন কুয়াশা।\\n• বৈমানিকদের নিয়ম: তাপমাত্রা আর শিশিরাঙ্কের ব্যবধান ৩° সেলসিয়াসের মধ্যে এলে কুয়াশার আশঙ্কা।\\n• ঘন কুয়াশায় সড়ক, নৌ আর আকাশপথে দুর্ঘটনার ঝুঁকি বাড়ে। গতি কমান, বাতি জ্বালান।"]','[{"label": "Met Office", "url": "https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/fog"}, {"label": "Boldmethod", "url": "https://www.boldmethod.com/blog/lists/2024/10/four-signs-that-radiation-fog-is-about-to-form/"}, {"label": "US National Weather Service", "url": "https://www.weather.gov/safety/fog"}]','[{"src": "/media/goyenda-bhabu/261223-case-04-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৪-এর সমাধান: ঠান্ডা আর্দ্র বাতাস!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261223-case-04-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৪-এর সমাধান: ঠান্ডা আর্দ্র বাতাস!, কার্ড 2"}]','["Foggy Winter Morning in Bangladesh.jpg by ZahidTushar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Foggy_Winter_Morning_in_Bangladesh.jpg", "Fog morning of river side.jpg by Shikdernazim2, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fog_morning_of_river_side.jpg"]','physics','eye','deep',1,'2026-12-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261229-case-05','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৫: টক হয়ে যাওয়া দুধের রহস্য','রাতে দুধ জ্বাল দিয়ে ঢেকে রাখা হলো। সকালে ঢাকনা খুলতেই টক গন্ধ, দুধ কাটা কাটা! কাজের খালার সন্দেহ, কেউ লেবুর রস ফেলেছে। কিন্তু সত্যিই কি তাই?','["রাতে দুধ জ্বাল দিয়ে ঢেকে রাখা হলো। সকালে ঢাকনা খুলতেই টক গন্ধ, দুধ কাটা কাটা! কাজের খালার সন্দেহ, কেউ লেবুর রস ফেলেছে। কিন্তু সত্যিই কি তাই?"]','[{"label": "How It Works", "url": "https://www.howitworksdaily.com/why-does-milk-turn-sour/"}, {"label": "Science World", "url": "https://www.scienceworld.ca/stories/what-made-our-milk-go-bad/"}]','[{"src": "/media/goyenda-bhabu/261229-case-05-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৫: টক হয়ে যাওয়া দুধের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261229-case-05-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৫: টক হয়ে যাওয়া দুধের রহস্য, কার্ড 2"}]','["Lait caillé 01.jpg by Cheikh cherif, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Lait_caill%C3%A9_01.jpg", "Overflowing boiling milk during gruhapravesam.jpg by Bssasidhar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Overflowing_boiling_milk_during_gruhapravesam.jpg"]','physics','eye','deep',1,'2026-12-29');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261230-case-05-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৫-এর সমাধান: ল্যাকটিক অ্যাসিড ব্যাকটেরিয়া!','দুধে মিশে থাকা ব্যাকটেরিয়া ঘরের তাপমাত্রায় দুধের চিনি (ল্যাকটোজ) খেয়ে ল্যাকটিক অ্যাসিড বানায়। অ্যাসিড বাড়লে pH কমে, দুধ টক হয়, আর কেসিন প্রোটিন জমাট বেঁধে ছানা হয়।','["• ফ্রিজে রাখলে ব্যাকটেরিয়ার কাজ ধীর হয়, তাই দুধ অনেক বেশি দিন টেকে।\\n• এই ছানাই পনির বানানোর ভিত্তি। ইচ্ছে করে অ্যাসিড দিয়ে দুধ কাটালেই ছানা।\\n• খোলার পর অন্য জীবাণু ঢুকে প্রোটিন বা চর্বি ভেঙে দুর্গন্ধ বানাতে পারে। গন্ধ খারাপ হলে খাবেন না।"]','[{"label": "How It Works", "url": "https://www.howitworksdaily.com/why-does-milk-turn-sour/"}, {"label": "Science World", "url": "https://www.scienceworld.ca/stories/what-made-our-milk-go-bad/"}]','[{"src": "/media/goyenda-bhabu/261230-case-05-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৫-এর সমাধান: ল্যাকটিক অ্যাসিড ব্যাকটেরিয়া!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/261230-case-05-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৫-এর সমাধান: ল্যাকটিক অ্যাসিড ব্যাকটেরিয়া!, কার্ড 2"}]','["Lait caillé 01.jpg by Cheikh cherif, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Lait_caill%C3%A9_01.jpg", "Overflowing boiling milk during gruhapravesam.jpg by Bssasidhar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Overflowing_boiling_milk_during_gruhapravesam.jpg"]','physics','eye','deep',1,'2026-12-30');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270105-case-06','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৬: রাতের আলো-চোখের রহস্য','রাতের গলিতে টর্চ ফেলতেই বিড়ালের চোখ জ্বলে ওঠে, অথচ টর্চ নিভতেই আর জ্বলে না। পাশের বাসার ছেলেটা বলছে, চোখে নাকি ব্যাটারি আছে! আসল ঘটনা কী?','["রাতের গলিতে টর্চ ফেলতেই বিড়ালের চোখ জ্বলে ওঠে, অথচ টর্চ নিভতেই আর জ্বলে না। পাশের বাসার ছেলেটা বলছে, চোখে নাকি ব্যাটারি আছে! আসল ঘটনা কী?"]','[{"label": "Science News", "url": "https://www.sci.news/biology/tapetum-lucidum-10711.html"}, {"label": "GBH (WGBH)", "url": "https://www.wgbh.org/news/national/2022-04-11/why-do-cats-eyes-glow-in-the-dark"}]','[{"src": "/media/goyenda-bhabu/270105-case-06-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৬: রাতের আলো-চোখের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270105-case-06-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৬: রাতের আলো-চোখের রহস্য, কার্ড 2"}]','["Cat''s glowing eyes at night , Bangladesh.jpg by Tanvir Rahat, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cat%27s_glowing_eyes_at_night_%2C_Bangladesh.jpg", "Black cat with glowing eyes under the car.jpg by Saipul bakrie, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Black_cat_with_glowing_eyes_under_the_car.jpg"]','physics','eye','deep',1,'2027-01-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270106-case-06-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৬-এর সমাধান: চোখের ভেতরের আয়না!','রেটিনার পেছনে আছে টেপেটাম লুসিডাম নামে একটা স্তর। রেটিনা যে আলো শুষে নিতে পারেনি, সেটাকে সে আবার রেটিনার ওপর দিয়ে ফেরত পাঠায়। রেটিনার কোষ দ্বিতীয়বার আলো ধরার সুযোগ পায়, তাই অল্প আলোয়ও দেখা সহজ। টর্চের আলো সেই স্তরে লেগে ফিরে আসে, আর আমরা দেখি জ্বলজ্বলে চোখ।','["• বিড়ালের ক্ষেত্রে এই স্তরের প্রতিফলক উপাদান রিবোফ্লাভিন (ভিটামিন বি)।\\n• দামও আছে: ছবি একটু ঝাপসা হয়। স্পষ্ট দেখতে বিড়ালকে মানুষের তুলনায় প্রায় সাত গুণ কাছে আসতে হয়।\\n• শেয়াল, ভেড়া, ছাগল, মাছ, ডলফিনেরও আছে। মানুষ, পাখি, সরীসৃপের নেই।"]','[{"label": "Science News", "url": "https://www.sci.news/biology/tapetum-lucidum-10711.html"}, {"label": "GBH (WGBH)", "url": "https://www.wgbh.org/news/national/2022-04-11/why-do-cats-eyes-glow-in-the-dark"}]','[{"src": "/media/goyenda-bhabu/270106-case-06-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৬-এর সমাধান: চোখের ভেতরের আয়না!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270106-case-06-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৬-এর সমাধান: চোখের ভেতরের আয়না!, কার্ড 2"}]','["Cat''s glowing eyes at night , Bangladesh.jpg by Tanvir Rahat, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cat%27s_glowing_eyes_at_night_%2C_Bangladesh.jpg", "Black cat with glowing eyes under the car.jpg by Saipul bakrie, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Black_cat_with_glowing_eyes_under_the_car.jpg"]','physics','eye','deep',1,'2027-01-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270112-case-07','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৭: লাল আকাশের রহস্য','দুপুরে আকাশ ঘন নীল, অথচ বিকেলে পশ্চিম আকাশ লালচে-কমলা। চায়ের দোকানের কাকা বলছেন, সব ধুলার কাণ্ড। প্রমাণ কী বলছে?','["দুপুরে আকাশ ঘন নীল, অথচ বিকেলে পশ্চিম আকাশ লালচে-কমলা। চায়ের দোকানের কাকা বলছেন, সব ধুলার কাণ্ড। প্রমাণ কী বলছে?"]','[{"label": "Science Focus", "url": "https://www.sciencefocus.com/planet-earth/why-are-sunsets-red"}, {"label": "Royal Museums Greenwich", "url": "https://www.rmg.co.uk/stories/space-astronomy/why-sky-blue"}]','[{"src": "/media/goyenda-bhabu/270112-case-07-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৭: লাল আকাশের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270112-case-07-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৭: লাল আকাশের রহস্য, কার্ড 2"}]','["Red sky (Chondipur) in 2022.01.jpg by CAPTAIN RAJU, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Red_sky_%28Chondipur%29_in_2022.01.jpg", "Beautiful sky in red color.jpg by Ibrahim Husain Meraj, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Beautiful_sky_in_red_color.jpg"]','physics','eye','deep',1,'2027-01-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270113-case-07-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৭-এর সমাধান: আলোর লম্বা পথ আর বিচ্ছুরণ!','বাতাসের অণু নীলের মতো ছোট তরঙ্গের আলোকে বেশি ছড়ায় (রেলে বিচ্ছুরণ)। সূর্য দিগন্তের কাছে থাকলে আলো অনেক লম্বা পথ পেরোয়। নীল আলো ছড়িয়ে অন্য দিকে চলে যায়, আর লাল-কমলা আলো আমাদের চোখে পৌঁছায়।','["• দুপুরে আলো কম বায়ুস্তর পেরোয়, কম ছড়ায়, তাই সূর্য সাদা দেখায়।\\n• একই কারণে সূর্যোদয়ের আকাশও লালচে হয়।\\n• দিনের আকাশ নীল কারণ ছড়িয়ে পড়া নীল আলো সব দিক থেকে আমাদের চোখে আসে।"]','[{"label": "Science Focus", "url": "https://www.sciencefocus.com/planet-earth/why-are-sunsets-red"}, {"label": "Royal Museums Greenwich", "url": "https://www.rmg.co.uk/stories/space-astronomy/why-sky-blue"}]','[{"src": "/media/goyenda-bhabu/270113-case-07-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৭-এর সমাধান: আলোর লম্বা পথ আর বিচ্ছুরণ!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270113-case-07-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৭-এর সমাধান: আলোর লম্বা পথ আর বিচ্ছুরণ!, কার্ড 2"}]','["Red sky (Chondipur) in 2022.01.jpg by CAPTAIN RAJU, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Red_sky_%28Chondipur%29_in_2022.01.jpg", "Beautiful sky in red color.jpg by Ibrahim Husain Meraj, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Beautiful_sky_in_red_color.jpg"]','physics','eye','deep',1,'2027-01-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270119-case-08','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৮: হারিয়ে যাওয়া তারার রহস্য','গ্রামের আকাশে অসংখ্য তারা, ঢাকার পরিষ্কার আকাশেও হাতে-গোনা কয়েকটা। বন্ধু বলছে, ঢাকায় মেঘ বেশি। আসল আসামি কে?','["গ্রামের আকাশে অসংখ্য তারা, ঢাকার পরিষ্কার আকাশেও হাতে-গোনা কয়েকটা। বন্ধু বলছে, ঢাকায় মেঘ বেশি। আসল আসামি কে?"]','[{"label": "Khadka et al., Heliyon 2024", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11337016/"}, {"label": "AGRIS (FAO)", "url": "https://agris.fao.org/search/en/records/68d294b3b3b40a20d61819ef"}, {"label": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/nipah-virus"}]','[{"src": "/media/goyenda-bhabu/270119-case-08-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৮: হারিয়ে যাওয়া তারার রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270119-case-08-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৮: হারিয়ে যাওয়া তারার রহস্য, কার্ড 2"}]','["Dhaka... A city of lights. (20839088256).jpg by Arghya Banik from Bangladesh, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Dhaka..._A_city_of_lights._%2820839088256%29.jpg", "Milky Way (164025919).jpeg by Topu Saha, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Milky_Way_%28164025919%29.jpeg"]','physics','eye','deep',1,'2027-01-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270120-case-08-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৮-এর সমাধান: আলোক দূষণ (স্কাইগ্লো)!','রাস্তা, দোকান আর বিজ্ঞাপনের আলো বাতাসে ছড়িয়ে আকাশের জমিন উজ্জ্বল করে দেয়: একে বলে স্কাইগ্লো। তখন ম্লান তারার সঙ্গে আকাশের পার্থক্য ধরা যায় না, তাই আগে ম্লান তারা হারায়।','["• বোর্টল স্কেল ১ থেকে ৯: ১ মানে সবচেয়ে অন্ধকার আকাশ, ৯ মানে শহরের মাঝখান।\\n• খালি চোখে ছায়াপথ দেখতে সাধারণত বোর্টল ৪ বা তার চেয়ে অন্ধকার আকাশ লাগে।\\n• ভালো আকাশের জন্য আলো কম এমন জায়গায় যান, কখনো শহর থেকে ৩০ থেকে ৯০ মিনিটের পথ।"]','[{"label": "Khadka et al., Heliyon 2024", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11337016/"}, {"label": "AGRIS (FAO)", "url": "https://agris.fao.org/search/en/records/68d294b3b3b40a20d61819ef"}, {"label": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/nipah-virus"}]','[{"src": "/media/goyenda-bhabu/270120-case-08-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৮-এর সমাধান: আলোক দূষণ (স্কাইগ্লো)!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270120-case-08-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৮-এর সমাধান: আলোক দূষণ (স্কাইগ্লো)!, কার্ড 2"}]','["Dhaka... A city of lights. (20839088256).jpg by Arghya Banik from Bangladesh, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Dhaka..._A_city_of_lights._%2820839088256%29.jpg", "Milky Way (164025919).jpeg by Topu Saha, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Milky_Way_%28164025919%29.jpeg"]','physics','eye','deep',1,'2027-01-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270126-case-09','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৯: পচে না যে মধু','দুই বছর আগের সুন্দরবনের মধু খোলা অবস্থায় আলমারিতে পড়ে আছে, অথচ গন্ধ-স্বাদ ঠিকই আছে। পাশের ঝুড়ির ফল কবেই পচে গেছে। দাদি বলছেন, মধুতে ম্যাজিক আছে! আসল রহস্য কী?','["দুই বছর আগের সুন্দরবনের মধু খোলা অবস্থায় আলমারিতে পড়ে আছে, অথচ গন্ধ-স্বাদ ঠিকই আছে। পাশের ঝুড়ির ফল কবেই পচে গেছে। দাদি বলছেন, মধুতে ম্যাজিক আছে! আসল রহস্য কী?"]','[{"label": "Khadka et al., Heliyon 2024", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11337016/"}, {"label": "AGRIS (FAO)", "url": "https://agris.fao.org/search/en/records/68d294b3b3b40a20d61819ef"}, {"label": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/nipah-virus"}]','[{"src": "/media/goyenda-bhabu/270126-case-09-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৯: পচে না যে মধু, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270126-case-09-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৯: পচে না যে মধু, কার্ড 2"}]','["Fresh honeycomb dripping honey India.jpg by Vraj Acharya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fresh_honeycomb_dripping_honey_India.jpg", "Honey Collection in Sundarbans.jpg by Mustmamun, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Honey_Collection_in_Sundarbans.jpg"]','physics','eye','deep',1,'2027-01-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270127-case-09-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #০৯-এর সমাধান: কম পানি, অ্যাসিড আর এনজাইম!','মৌমাছি ডানা নেড়ে নেক্টার থেকে পানি শুকায়, তাই মধুতে পানি মাত্র প্রায় ১৭%। জীবাণু বাড়তে পারে না। এনজাইম গ্লুকোজকে গ্লুকোনিক অ্যাসিড বানায়, ফলে pH প্রায় ৪। সঙ্গে হাইড্রোজেন পারক্সাইড তৈরি হয়, যা জীবাণুর বৃদ্ধি আটকায়।','["• মধুর পানির সক্রিয়তা প্রায় ০.৬, যা ০.৭৫-এর নিচে: এর নিচে বেশিরভাগ ছত্রাক-ব্যাকটেরিয়া বাড়ে না।\\n• মধু জমে চিনির দানা বাঁধা নষ্ট হওয়া নয়: ওটা শুধু স্ফটিকীভবন।\\n• মিশরের প্রাচীন সমাধিতে সিল করা পাত্রে হাজার বছরের পুরনো মধু পাওয়া গেছে।"]','[{"label": "Khadka et al., Heliyon 2024", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11337016/"}, {"label": "AGRIS (FAO)", "url": "https://agris.fao.org/search/en/records/68d294b3b3b40a20d61819ef"}, {"label": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/nipah-virus"}]','[{"src": "/media/goyenda-bhabu/270127-case-09-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৯-এর সমাধান: কম পানি, অ্যাসিড আর এনজাইম!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270127-case-09-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #০৯-এর সমাধান: কম পানি, অ্যাসিড আর এনজাইম!, কার্ড 2"}]','["Fresh honeycomb dripping honey India.jpg by Vraj Acharya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fresh_honeycomb_dripping_honey_India.jpg", "Honey Collection in Sundarbans.jpg by Mustmamun, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Honey_Collection_in_Sundarbans.jpg"]','physics','eye','deep',1,'2027-01-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270202-case-10','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১০: গ্লাসের বাইরের পানির রহস্য','ঠান্ডা পানির গ্লাস টেবিলে রাখতেই বাইরে ফোঁটা ফোঁটা পানি, গ্লাস কিন্তু অক্ষত। ছোট ভাই বলছে কাচে অদৃশ্য ফুটো আছে। পানি আসলে এল কোথা থেকে?','["ঠান্ডা পানির গ্লাস টেবিলে রাখতেই বাইরে ফোঁটা ফোঁটা পানি, গ্লাস কিন্তু অক্ষত। ছোট ভাই বলছে কাচে অদৃশ্য ফুটো আছে। পানি আসলে এল কোথা থেকে?"]','[{"label": "US National Weather Service", "url": "https://www.weather.gov/arx/why_dewpoint_vs_humidity"}, {"label": "USGS", "url": "https://www.usgs.gov/special-topics/water-science-school/science/condensation-and-water-cycle"}]','[{"src": "/media/goyenda-bhabu/270202-case-10-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১০: গ্লাসের বাইরের পানির রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270202-case-10-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১০: গ্লাসের বাইরের পানির রহস্য, কার্ড 2"}]','["Condensation droplets on glass surface.jpg by Dreamora96x, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Condensation_droplets_on_glass_surface.jpg", "CoCo Ichibanya Drinking water.jpg by Corpse Reviver, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:CoCo_Ichibanya_Drinking_water.jpg"]','physics','eye','deep',1,'2027-02-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270203-case-10-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১০-এর সমাধান: ঘরের বাতাসের জলীয় বাষ্প!','ঠান্ডা গ্লাসের গায়ে লেগে আশপাশের বাতাস ঠান্ডা হয়। বাতাস তার শিশিরাঙ্কের নিচে নামলে বাড়তি জলীয় বাষ্প তরল পানি হয়ে জমে। অর্থাৎ পানিটা গ্লাসের ভেতর থেকে আসেনি: এসেছে বাতাস থেকে।','["• শিশিরাঙ্ক (ডিউ পয়েন্ট) হলো সেই তাপমাত্রা, যেখানে বাতাস ১০০% আর্দ্র হয়ে আর বাষ্প ধরে রাখতে পারে না।\\n• ঠান্ডা কাচে ঘেমে যাওয়া জানালা আর ঘেমে যাওয়া চশমার লেন্সও একই ঘটনা।\\n• বেশি আর্দ্র, গরম দিনে ফোঁটা বেশি জমে।"]','[{"label": "US National Weather Service", "url": "https://www.weather.gov/arx/why_dewpoint_vs_humidity"}, {"label": "USGS", "url": "https://www.usgs.gov/special-topics/water-science-school/science/condensation-and-water-cycle"}]','[{"src": "/media/goyenda-bhabu/270203-case-10-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১০-এর সমাধান: ঘরের বাতাসের জলীয় বাষ্প!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270203-case-10-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১০-এর সমাধান: ঘরের বাতাসের জলীয় বাষ্প!, কার্ড 2"}]','["Condensation droplets on glass surface.jpg by Dreamora96x, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Condensation_droplets_on_glass_surface.jpg", "CoCo Ichibanya Drinking water.jpg by Corpse Reviver, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:CoCo_Ichibanya_Drinking_water.jpg"]','physics','eye','deep',1,'2027-02-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270209-case-11','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১১: উল্টো ঘুমের রহস্য','পুরনো আমগাছে সারাদিন ডজন ডজন প্রাণী উল্টো ঝুলে, ঘুমের মধ্যেও পড়ে না। পাড়ার কাকা বলছেন, উল্টো থাকলে রক্ত মাথায় উঠবে। আসল রহস্য কী?','["পুরনো আমগাছে সারাদিন ডজন ডজন প্রাণী উল্টো ঝুলে, ঘুমের মধ্যেও পড়ে না। পাড়ার কাকা বলছেন, উল্টো থাকলে রক্ত মাথায় উঠবে। আসল রহস্য কী?"]','[{"label": "Reconnect With Nature", "url": "https://www.reconnectwithnature.org/news-events/the-buzz/nature-curiosity-why-don-t-bats-get-dizzy-when-ha"}, {"label": "Farmers'' Almanac", "url": "https://www.farmersalmanac.com/?p=442604"}]','[{"src": "/media/goyenda-bhabu/270209-case-11-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১১: উল্টো ঘুমের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270209-case-11-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১১: উল্টো ঘুমের রহস্য, কার্ড 2"}]','["Fruit bats roost in Kanyakumari (Cape Comarin) JEG1812.jpg by PJeganathan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fruit_bats_roost_in_Kanyakumari_%28Cape_Comarin%29_JEG1812.jpg", "Indian Flying Fox Yawning at Rani Pokhari, Bhaktapur.jpg by Sunuwargr, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Indian_Flying_Fox_Yawning_at_Rani_Pokhari%2C_Bhaktapur.jpg"]','physics','eye','deep',1,'2027-02-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270210-case-11-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১১-এর সমাধান: পায়ের টেন্ডনের তালা!','বাদুড়ের পায়ের বিশেষ টেন্ডন আঙুলগুলো বাঁকিয়ে তালার মতো আটকে রাখে। শরীরের ওজনই সেই তালা বন্ধ রাখে, তাই ঝুলে থাকতে পেশির শক্তি লাগে না। ছাড়তে চাইলে তবেই পেশি লাগে।','["• বাদুড়ের ডানা পাখির মতো জোরালো নয়, মাটি থেকে উড়তে কষ্ট। ঝুলে থাকলে শুধু ছেড়ে দিলেই উড়াল শুরু।\\n• ছোট শরীরে অভিকর্ষ রক্তপ্রবাহে নজরকাড়া প্রভাব ফেলে না। সবচেয়ে বড় বাদুড় ফ্লাইং ফক্সও সর্বোচ্চ প্রায় ২.৫ পাউন্ড (১.১ কেজি)।\\n• পেছনমুখী হাঁটুও ঝুলে থাকতে সাহায্য করে।"]','[{"label": "Reconnect With Nature", "url": "https://www.reconnectwithnature.org/news-events/the-buzz/nature-curiosity-why-don-t-bats-get-dizzy-when-ha"}, {"label": "Farmers'' Almanac", "url": "https://www.farmersalmanac.com/?p=442604"}]','[{"src": "/media/goyenda-bhabu/270210-case-11-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১১-এর সমাধান: পায়ের টেন্ডনের তালা!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270210-case-11-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১১-এর সমাধান: পায়ের টেন্ডনের তালা!, কার্ড 2"}]','["Fruit bats roost in Kanyakumari (Cape Comarin) JEG1812.jpg by PJeganathan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fruit_bats_roost_in_Kanyakumari_%28Cape_Comarin%29_JEG1812.jpg", "Indian Flying Fox Yawning at Rani Pokhari, Bhaktapur.jpg by Sunuwargr, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Indian_Flying_Fox_Yawning_at_Rani_Pokhari%2C_Bhaktapur.jpg"]','physics','eye','deep',1,'2027-02-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270216-case-12','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১২: রংধনুর রহস্য','বৃষ্টি থামার পর রোদ উঠেছে, আর রংধনু ফুটেছে ঠিক সূর্যের উল্টো দিকে। সূর্যের দিকে কেন নয়? ছেলেটা দৌড়ে যাচ্ছে ধরতে। ধরা যায়?','["বৃষ্টি থামার পর রোদ উঠেছে, আর রংধনু ফুটেছে ঠিক সূর্যের উল্টো দিকে। সূর্যের দিকে কেন নয়? ছেলেটা দৌড়ে যাচ্ছে ধরতে। ধরা যায়?"]','[{"label": "SRAC (Mississippi State University) fact", "url": "https://srac.msstate.edu/pdfs/Fact%20Sheets/4601%20Measuring%20Dissolved%20Oxygen%20Concentration%20in%20Aquaculture.pdf"}, {"label": "Mississippi State University Extension", "url": "https://extension.msstate.edu/natural-resources/fisheries/pond-and-lake-management/fish-kills"}]','[{"src": "/media/goyenda-bhabu/270216-case-12-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১২: রংধনুর রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270216-case-12-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১২: রংধনুর রহস্য, কার্ড 2"}]','["Double rainbow at bd.jpg by Engr.Raju, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Double_rainbow_at_bd.jpg", "Rainbow in Sundarbans.jpg by Md. Rifat Hasan Jihan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rainbow_in_Sundarbans.jpg"]','physics','eye','deep',1,'2027-02-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270217-case-12-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১২-এর সমাধান: বৃষ্টির ফোঁটা!','সূর্যের আলো ফোঁটায় ঢুকে বেঁকে যায়, ভেতরের পেছনের দিকে একবার ঠিকরে ফেরে, বেরোনোর সময় আবার বাঁকে। লাল আলো প্রায় ৪২° কোণে, নীল প্রায় ৪০° কোণে ফিরে আসে। তাই সূর্যের উল্টো বিন্দুকে ঘিরে রঙিন বৃত্ত তৈরি হয়।','["• সূর্যের উল্টো বিন্দু (অ্যান্টিসোলার পয়েন্ট) আপনার মাথার ছায়ার দিকে।\\n• রংধনু কোনো নির্দিষ্ট জায়গায় নেই। প্রত্যেকে নিজের চোখ থেকে আলাদা শঙ্কুর বৃষ্টিফোঁটা দেখে, তাই ধরা যায় না।\\n• মাটি নিচের অংশ আড়াল করে বলে আমরা সাধারণত অর্ধবৃত্ত দেখি।"]','[{"label": "SRAC (Mississippi State University) fact", "url": "https://srac.msstate.edu/pdfs/Fact%20Sheets/4601%20Measuring%20Dissolved%20Oxygen%20Concentration%20in%20Aquaculture.pdf"}, {"label": "Mississippi State University Extension", "url": "https://extension.msstate.edu/natural-resources/fisheries/pond-and-lake-management/fish-kills"}]','[{"src": "/media/goyenda-bhabu/270217-case-12-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১২-এর সমাধান: বৃষ্টির ফোঁটা!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270217-case-12-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১২-এর সমাধান: বৃষ্টির ফোঁটা!, কার্ড 2"}]','["Double rainbow at bd.jpg by Engr.Raju, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Double_rainbow_at_bd.jpg", "Rainbow in Sundarbans.jpg by Md. Rifat Hasan Jihan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rainbow_in_Sundarbans.jpg"]','physics','eye','deep',1,'2027-02-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270223-case-13','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৩: চাঁদ কি সত্যিই বড়?','সন্ধ্যায় দিগন্তে ওঠা পূর্ণিমার চাঁদ বিশাল আর কমলা, রাতে মাথার ওপর ছোট আর সাদাটে। ছাদের আড্ডায় কেউ বলছে, নিচে নামলে কাছে আসে বলে বড়। সত্যিই কি তাই?','["সন্ধ্যায় দিগন্তে ওঠা পূর্ণিমার চাঁদ বিশাল আর কমলা, রাতে মাথার ওপর ছোট আর সাদাটে। ছাদের আড্ডায় কেউ বলছে, নিচে নামলে কাছে আসে বলে বড়। সত্যিই কি তাই?"]','[{"label": "Science Focus", "url": "https://www.sciencefocus.com/planet-earth/why-are-sunsets-red"}, {"label": "Royal Museums Greenwich", "url": "https://www.rmg.co.uk/stories/space-astronomy/why-sky-blue"}]','[{"src": "/media/goyenda-bhabu/270223-case-13-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৩: চাঁদ কি সত্যিই বড়?, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270223-case-13-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৩: চাঁদ কি সত্যিই বড়?, কার্ড 2"}]','["Rising Full Moon - Flickr - halfrain.jpg by halfrain, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Rising_Full_Moon_-_Flickr_-_halfrain.jpg", "The Full Moon above the Horizon (Taken by SpicyVoice).jpg by SpicyVoice, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_Full_Moon_above_the_Horizon_%28Taken_by_SpicyVoice%29.jpg"]','physics','eye','deep',1,'2027-02-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270224-case-13-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৩-এর সমাধান: আমাদের মস্তিষ্কের হিসাব!','নাসা বলছে, চাঁদের আপাত মাপ দিগন্তে আর আকাশের ওপরে একই: ব্যাপারটা আমাদের মস্তিষ্কের দেখার ধরনের সঙ্গে জড়িত। সামনের গাছ-বাড়ির পাশে চাঁদকে বড় মনে হয়। এর পূর্ণ ব্যাখ্যা এখনো বিজ্ঞানীরা নিশ্চিত করতে পারেননি।','["• বুড়ো আঙুলের পরীক্ষা: হাত বাড়িয়ে নিচু চাঁদ ঢাকুন, পরে উঁচু চাঁদ ঢাকুন। দুবারই একই মাপ।\\n• দিগন্তে চাঁদ আসলে কাছে নয়, বেশি দূরে: কয়েক হাজার কিলোমিটার বেশি।\\n• নিচু চাঁদ কমলা দেখায়, কারণ আলো বেশি বায়ুস্তর পেরিয়ে আসে।"]','[{"label": "Science Focus", "url": "https://www.sciencefocus.com/planet-earth/why-are-sunsets-red"}, {"label": "Royal Museums Greenwich", "url": "https://www.rmg.co.uk/stories/space-astronomy/why-sky-blue"}]','[{"src": "/media/goyenda-bhabu/270224-case-13-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৩-এর সমাধান: আমাদের মস্তিষ্কের হিসাব!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270224-case-13-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৩-এর সমাধান: আমাদের মস্তিষ্কের হিসাব!, কার্ড 2"}]','["Rising Full Moon - Flickr - halfrain.jpg by halfrain, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Rising_Full_Moon_-_Flickr_-_halfrain.jpg", "The Full Moon above the Horizon (Taken by SpicyVoice).jpg by SpicyVoice, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_Full_Moon_above_the_Horizon_%28Taken_by_SpicyVoice%29.jpg"]','physics','eye','deep',1,'2027-02-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270302-case-14','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৪: পানির ওপর হাঁটা পোকার রহস্য','পুকুরের পানির ওপর একটা পোকা দিব্যি ছুটে বেড়াচ্ছে, ডুবছে না। ছেলেটা বলছে, ওর পায়ে অদৃশ্য জুতো। আসল রহস্য কী?','["পুকুরের পানির ওপর একটা পোকা দিব্যি ছুটে বেড়াচ্ছে, ডুবছে না। ছেলেটা বলছে, ওর পায়ে অদৃশ্য জুতো। আসল রহস্য কী?"]','[{"label": "Physics Today", "url": "https://physicstoday.aip.org/quick-study/walking-on-water"}, {"label": "USGS", "url": "https://www.usgs.gov/media/images/surface-tension-allows-a-water-strider-walk-water"}]','[{"src": "/media/goyenda-bhabu/270302-case-14-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৪: পানির ওপর হাঁটা পোকার রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270302-case-14-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৪: পানির ওপর হাঁটা পোকার রহস্য, কার্ড 2"}]','["Pond skaters (Gerris lacustris).jpg by Charles J. Sharp, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Pond_skaters_%28Gerris_lacustris%29.jpg", "Water strider Gerris lacustris.jpg by Richard Bartz, CC BY-SA 2.5, https://commons.wikimedia.org/wiki/File:Water_strider_Gerris_lacustris.jpg"]','physics','eye','deep',1,'2027-03-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270303-case-14-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৪-এর সমাধান: পানির পৃষ্ঠটান!','পানির পৃষ্ঠটান পানির ওপরটা স্থিতিস্থাপক চামড়ার মতো টান টান রাখে। পোকার লম্বা পা শরীরের ভার অনেকটা জায়গায় ছড়িয়ে দেয়। আর পানি-বিরাগী ছোট লোম পা ভিজতে দেয় না, তাই ও ডোবে না।','["• মাঝের পা দাঁড়ের মতো পানি ঠেলে পিছনে ঘূর্ণি তৈরি করে, তাতেই সামনে এগোয়।\\n• পৃষ্ঠটান বড় ভূমিকা নেয় মূলত প্রায় ২.৬ মিলিমিটারের চেয়ে ছোট মাপে।\\n• লম্বা, সরু, নমনীয় পা আর লোম মিলে ভারসাম্য রাখে।"]','[{"label": "Physics Today", "url": "https://physicstoday.aip.org/quick-study/walking-on-water"}, {"label": "USGS", "url": "https://www.usgs.gov/media/images/surface-tension-allows-a-water-strider-walk-water"}]','[{"src": "/media/goyenda-bhabu/270303-case-14-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৪-এর সমাধান: পানির পৃষ্ঠটান!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270303-case-14-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৪-এর সমাধান: পানির পৃষ্ঠটান!, কার্ড 2"}]','["Pond skaters (Gerris lacustris).jpg by Charles J. Sharp, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Pond_skaters_%28Gerris_lacustris%29.jpg", "Water strider Gerris lacustris.jpg by Richard Bartz, CC BY-SA 2.5, https://commons.wikimedia.org/wiki/File:Water_strider_Gerris_lacustris.jpg"]','physics','eye','deep',1,'2027-03-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270309-case-15','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৫: কাঁচা আম পাকার রহস্য','কাঁচা আম একটা পাকা কলার সঙ্গে কাগজের ব্যাগে রাখা হলো। দুই দিন পর ব্যাগের আম নরম আর সুগন্ধি, ঝুড়ির আম এখনো শক্ত। দাদি বলছেন কলার জন্যই। সত্যি?','["কাঁচা আম একটা পাকা কলার সঙ্গে কাগজের ব্যাগে রাখা হলো। দুই দিন পর ব্যাগের আম নরম আর সুগন্ধি, ঝুড়ির আম এখনো শক্ত। দাদি বলছেন কলার জন্যই। সত্যি?"]','[{"label": "PopSci", "url": "https://www.popsci.com/science/what-is-rust/"}, {"label": "Tutopiya (Cambridge IGCSE chemistry)", "url": "https://www.tutopiya.com/lesson-notes/igcse-cambridge-chemistry/rusting-and-alloys/"}]','[{"src": "/media/goyenda-bhabu/270309-case-15-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৫: কাঁচা আম পাকার রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270309-case-15-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৫: কাঁচা আম পাকার রহস্য, কার্ড 2"}]','["Mango Bangladesh (3).JPG by Shahnoor Habib Munmun, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Mango_Bangladesh_%283%29.JPG", "Mango Bangladesh 18.jpg by Salim_Khandoker, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Mango_Bangladesh_18.jpg"]','physics','eye','deep',1,'2027-03-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270310-case-15-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৫-এর সমাধান: ইথিলিন গ্যাস!','আম আর কলা ক্লাইম্যাকটেরিক ফল: গাছ থেকে তোলার পরও পাকতে থাকে। পাকার সময় এরা ইথিলিন গ্যাস ছাড়ে, যা স্টার্চকে চিনিতে বদলানোর এনজাইমকে সক্রিয় করে। কাগজের ব্যাগ গ্যাসটাকে ফলের কাছে জমিয়ে রাখে, তাই পাকা দ্রুত হয়।','["• প্লাস্টিক নয়, কাগজের ব্যাগ: প্লাস্টিকে বাতাস চলাচল বন্ধ হয়ে ফল পচে যেতে পারে।\\n• গরম তাপমাত্রায় পাকা দ্রুত, ঠান্ডায় ধীর।\\n• কলা পুরো পাকার আগে ফ্রিজে রাখবেন না: খোসা কালো হয়ে পাকা এলোমেলো হয়।"]','[{"label": "PopSci", "url": "https://www.popsci.com/science/what-is-rust/"}, {"label": "Tutopiya (Cambridge IGCSE chemistry)", "url": "https://www.tutopiya.com/lesson-notes/igcse-cambridge-chemistry/rusting-and-alloys/"}]','[{"src": "/media/goyenda-bhabu/270310-case-15-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৫-এর সমাধান: ইথিলিন গ্যাস!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270310-case-15-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৫-এর সমাধান: ইথিলিন গ্যাস!, কার্ড 2"}]','["Mango Bangladesh (3).JPG by Shahnoor Habib Munmun, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Mango_Bangladesh_%283%29.JPG", "Mango Bangladesh 18.jpg by Salim_Khandoker, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Mango_Bangladesh_18.jpg"]','physics','eye','deep',1,'2027-03-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270316-case-16','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৬: আলো আগে, গুড়গুড় পরে','কালবৈশাখীর বিকেলে আকাশ চিরে ঝলক, আর শব্দ এল কয়েক সেকেন্ড পরে। ছাদে দাঁড়ানো কাকু বলছেন, শব্দ নাকি রাস্তায় আটকে ছিল! সত্যি কী ঘটেছে?','["কালবৈশাখীর বিকেলে আকাশ চিরে ঝলক, আর শব্দ এল কয়েক সেকেন্ড পরে। ছাদে দাঁড়ানো কাকু বলছেন, শব্দ নাকি রাস্তায় আটকে ছিল! সত্যি কী ঘটেছে?"]','[{"label": "Atmospheric Optics", "url": "https://www.atoptics.co.uk/blog/rays-through-a-large-raindrop/"}, {"label": "Arizona State University", "url": "https://www.asu.edu/courses/phs208/patternsbb/PiN/mod/light/opticsnature/bow.html"}]','[{"src": "/media/goyenda-bhabu/270316-case-16-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৬: আলো আগে, গুড়গুড় পরে, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270316-case-16-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৬: আলো আগে, গুড়গুড় পরে, কার্ড 2"}]','["Fury of the sky.jpg by Yuriy Stolypin, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Fury_of_the_sky.jpg", "Lightning over ESO Headquarters.jpg by ESO/P. Horálek, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Lightning_over_ESO_Headquarters.jpg"]','physics','eye','deep',1,'2027-03-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270317-case-16-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৬-এর সমাধান: আলো আর শব্দের গতির ফারাক!','আলো সেকেন্ডে প্রায় ৩ লাখ কিলোমিটার চলে, শব্দ বাতাসে সেকেন্ডে প্রায় ৩৪৩ মিটার। তাই ঝলক প্রায় তাৎক্ষণিক চোখে পড়ে, আর বজ্রের শব্দ কানে আসতে সময় লাগে। শব্দের ১ কিলোমিটার যেতে লাগে প্রায় ৩ সেকেন্ড।','["• ঝলক থেকে গুড়গুড় পর্যন্ত সেকেন্ড গুনে ৩ দিয়ে ভাগ দিন: প্রায় কিলোমিটারে দূরত্ব। যেমন ১৫ সেকেন্ড = প্রায় ৫ কিমি।\\n• বজ্রের শব্দ শোনা মানেই আপনি ঝুঁকির মধ্যে: ঘরে যান, শেষ গুড়গুড়ের পর ৩০ মিনিট অপেক্ষা করুন। গাছের নিচে দাঁড়াবেন না।\\n• বজ্রের শব্দ সাধারণত ৮ থেকে ২০ কিমি দূর পর্যন্ত শোনা যায়।"]','[{"label": "Atmospheric Optics", "url": "https://www.atoptics.co.uk/blog/rays-through-a-large-raindrop/"}, {"label": "Arizona State University", "url": "https://www.asu.edu/courses/phs208/patternsbb/PiN/mod/light/opticsnature/bow.html"}]','[{"src": "/media/goyenda-bhabu/270317-case-16-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৬-এর সমাধান: আলো আর শব্দের গতির ফারাক!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270317-case-16-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৬-এর সমাধান: আলো আর শব্দের গতির ফারাক!, কার্ড 2"}]','["Fury of the sky.jpg by Yuriy Stolypin, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Fury_of_the_sky.jpg", "Lightning over ESO Headquarters.jpg by ESO/P. Horálek, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Lightning_over_ESO_Headquarters.jpg"]','physics','eye','deep',1,'2027-03-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270323-case-17','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৭: প্রথম বৃষ্টির গন্ধের রহস্য','কয়েক মাসের খরার পর প্রথম বৃষ্টি, আর মাটি থেকে সেই চেনা সুবাস। ছেলেটা বলছে, মাটি গলে যাচ্ছে বলেই গন্ধ। গন্ধটা আসলে কার?','["কয়েক মাসের খরার পর প্রথম বৃষ্টি, আর মাটি থেকে সেই চেনা সুবাস। ছেলেটা বলছে, মাটি গলে যাচ্ছে বলেই গন্ধ। গন্ধটা আসলে কার?"]','[{"label": "PopSci", "url": "https://www.popsci.com/science/what-is-rust/"}, {"label": "Tutopiya (Cambridge IGCSE chemistry)", "url": "https://www.tutopiya.com/lesson-notes/igcse-cambridge-chemistry/rusting-and-alloys/"}]','[{"src": "/media/goyenda-bhabu/270323-case-17-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৭: প্রথম বৃষ্টির গন্ধের রহস্য, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270323-case-17-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৭: প্রথম বৃষ্টির গন্ধের রহস্য, কার্ড 2"}]','["Rain in rainy season in Bangladesh.jpg by Mayeenul Islam, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rain_in_rainy_season_in_Bangladesh.jpg", "Monsoon (36877269620).jpg by lensnmatter, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Monsoon_%2836877269620%29.jpg"]','physics','eye','deep',1,'2027-03-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270324-case-17-answer','goyenda-bhabu','card','গোয়েন্দা ভাবু · কেস #১৭-এর সমাধান: মাটির ব্যাকটেরিয়ার জিওসমিন!','মাটির অ্যাকটিনোব্যাকটেরিয়া (বিশেষ করে স্ট্রেপটোমাইসিস) জিওসমিন নামে যৌগ তৈরি করে। খরায় এরা সুপ্ত থাকে, বৃষ্টিতে সক্রিয় হয়। এই গন্ধের নাম পেট্রিকোর। মানুষ জিওসমিন ধরতে পারে প্রতি ট্রিলিয়নে কয়েক ভাগের মতো অল্প পরিমাণেও।','["• ‘পেট্রিকোর’ শব্দটা ১৯৬৪ সালে অস্ট্রেলিয়ার সিএসআইআরওর দুই গবেষক তৈরি করেন।\\n• বজ্রসহ বৃষ্টিতে বজ্রের ওজোনও কখনো গন্ধে যোগ হয়।\\n• বিজ্ঞানীদের ধারণা, আদি যেসব মানুষ পানির গন্ধ পেতেন, তাঁদের বেঁচে থাকার সম্ভাবনা বেশি ছিল।"]','[{"label": "PopSci", "url": "https://www.popsci.com/science/what-is-rust/"}, {"label": "Tutopiya (Cambridge IGCSE chemistry)", "url": "https://www.tutopiya.com/lesson-notes/igcse-cambridge-chemistry/rusting-and-alloys/"}]','[{"src": "/media/goyenda-bhabu/270324-case-17-answer-1.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৭-এর সমাধান: মাটির ব্যাকটেরিয়ার জিওসমিন!, কার্ড 1"}, {"src": "/media/goyenda-bhabu/270324-case-17-answer-2.webp", "width": 960, "height": 1200, "alt": "গোয়েন্দা ভাবু · কেস #১৭-এর সমাধান: মাটির ব্যাকটেরিয়ার জিওসমিন!, কার্ড 2"}]','["Rain in rainy season in Bangladesh.jpg by Mayeenul Islam, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rain_in_rainy_season_in_Bangladesh.jpg", "Monsoon (36877269620).jpg by lensnmatter, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Monsoon_%2836877269620%29.jpg"]','physics','eye','deep',1,'2027-03-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270105-01-naming-a-feeling','mon-bhalo-bhabu','card','অনুভূতির নাম বললে মস্তিষ্ক একটু শান্ত হয়','২০০৭ সালের ইউসিএলএ-র পরীক্ষা, ৩০ জন প্রাপ্তবয়স্ক','["▸ ২০০৭ সালে ইউসিএলএ-র গবেষকরা ৩০ জনকে রাগী বা ভীত মুখের ছবি দেখান।\\n▸ একই মানুষ কখনও ছবির আবেগের নাম বললেন (''রাগী''), কখনও শুধু একটা নাম (''হ্যারি'')।\\n▸ আবেগের নাম বলার সময় মস্তিষ্কের ভয়-সংকেতের অংশ অ্যামিগডালা কম সাড়া দিল।", "এক কথায়: অনুভূতিকে শব্দ দিলে ঝোঁকটা একটু শান্ত হয়, তবে ফল মৃদু। এটা চিকিৎসার বিকল্প নয়।\\nঘরে করে দেখুন: মন খারাপ হলে একটা শব্দ বাছুন: ''আমি এখন ... লাগছে''।"]','[{"label": "ScienceDaily", "url": "https://sciencedaily.com/releases/2007/06/070622090727.htm"}, {"label": "semel.ucla.edu record of Lieberman et al", "url": "https://teams.semel.ucla.edu/node/4368"}]','[{"src": "/media/mon-bhalo-bhabu/270105-01-naming-a-feeling-1.webp", "width": 960, "height": 1200, "alt": "অনুভূতির নাম বললে মস্তিষ্ক একটু শান্ত হয়, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270105-01-naming-a-feeling-2.webp", "width": 960, "height": 1200, "alt": "অনুভূতির নাম বললে মস্তিষ্ক একটু শান্ত হয়, কার্ড 2"}]','["Aaron Burden aaronburden, CC0, https://commons.wikimedia.org/wiki/File:Writing_with_a_fountain_pen_(Unsplash).jpg"]','health','heart','coral',1,'2027-01-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270112-02-twenty-minutes-in-nature','mon-bhalo-bhabu','card','প্রায় ২০ মিনিটের সবুজেই শরীর হালকা হয়','৩৬ জন শহরবাসীর লালায় স্ট্রেসের চিহ্ন কম','["▸ ২০১৯ সালে মিশিগান বিশ্ববিদ্যালয়ের গবেষকরা ৮ সপ্তাহ ধরে ৩৬ জন শহরবাসীকে অনুসরণ করেন।\\n▸ সপ্তাহে অন্তত ৩ বার, কমপক্ষে ১০ মিনিট প্রকৃতিতে থাকতে বলা হয়; সময়-জায়গা ওঁরাই বাছতেন।\\n▸ লালা পরীক্ষায় দেখা গেল, প্রায় ২০ মিনিটের প্রকৃতি-অভিজ্ঞতায় কর্টিসল কমে।", "এক কথায়: প্রায় ২০ মিনিটেই লাভ শুরু, এরপর আরও কমে, তবে ধীরে। ছোট গবেষণা, তাই এটা শুরুর ইঙ্গিত।\\nঘরে করে দেখুন: আজ ফোন পকেটে রেখে ২০ মিনিট গাছের নিচে বসুন।"]','[{"label": "PMC6458297", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6458297"}, {"label": "ScienceDaily", "url": "https://sciencedaily.com/releases/2019/04/190404074915.htm"}]','[{"src": "/media/mon-bhalo-bhabu/270112-02-twenty-minutes-in-nature-1.webp", "width": 960, "height": 1200, "alt": "প্রায় ২০ মিনিটের সবুজেই শরীর হালকা হয়, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270112-02-twenty-minutes-in-nature-2.webp", "width": 960, "height": 1200, "alt": "প্রায় ২০ মিনিটের সবুজেই শরীর হালকা হয়, কার্ড 2"}]','["Chris Gorringe, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Forest_of_Dean_-_A_sunlit_path_next_to_Soudley_Ponds_-_geograph.org.uk_-_8148125.jpg"]','health','heart','coral',1,'2027-01-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270119-03-ten-minutes-petting-animals','mon-bhalo-bhabu','card','১০ মিনিট আদর করলে চাপটা একটু কমে','২০১৯ সালে ২৪৯ জন কলেজ-শিক্ষার্থীর পরীক্ষা','["▸ ওয়াশিংটন স্টেট বিশ্ববিদ্যালয়ে ২৪৯ জন শিক্ষার্থীকে চার দলে ভাগ করা হয়।\\n▸ এক দল ১০ মিনিট বিড়াল-কুকুরকে আদর করল; বাকিরা শুধু দেখল, ছবি দেখল, বা অপেক্ষা করল।\\n▸ যারা সরাসরি আদর করল, তাদের লালায় কর্টিসল পরে কম পাওয়া গেল।", "এক কথায়: লাভটা সাময়িক, গবেষকরাও তাই বলেন। দীর্ঘমেয়াদি উপকার এই পরীক্ষায় মাপা হয়নি।\\nজানেন কি: অন্য তিন দলের তুলনায় শুধু সরাসরি আদর করা দলের কর্টিসল কম ছিল।"]','[{"label": "WSU News", "url": "https://news.wsu.edu/2019/07/15/study-demonstrates-stress-reduction-benefits-petting-dogs-cats/"}, {"label": "Neuroscience News on the same trial", "url": "https://neurosciencenews.com/cat-dog-stress-reduction-14490/"}]','[{"src": "/media/mon-bhalo-bhabu/270119-03-ten-minutes-petting-animals-1.webp", "width": 960, "height": 1200, "alt": "১০ মিনিট আদর করলে চাপটা একটু কমে, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270119-03-ten-minutes-petting-animals-2.webp", "width": 960, "height": 1200, "alt": "১০ মিনিট আদর করলে চাপটা একটু কমে, কার্ড 2"}]','["Josephguy15 2.0, CC0, https://commons.wikimedia.org/wiki/File:Cat_petted.jpg", "Xoqoni Said, CC0, https://commons.wikimedia.org/wiki/File:A_Kitten_Relaxing_While_Being_Petted.jpg"]','health','heart','coral',1,'2027-01-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270126-04-writing-worries-before-an-exam','mon-bhalo-bhabu','card','দুশ্চিন্তা লিখে ফেললে নম্বর বাড়তে পারে','২০১১ সালের শিকাগো গবেষণা: পরীক্ষার ঠিক আগে','["▸ ২০১১ সালে শিকাগো বিশ্ববিদ্যালয়ে ২০ জন কলেজ-শিক্ষার্থী একটি চাপের অঙ্ক পরীক্ষা দেয়।\\n▸ অর্ধেক পরীক্ষার আগে ১০ মিনিট নিজের দুশ্চিন্তা লিখল; বাকিরা চুপ করে বসল।\\n▸ লেখা দলের নির্ভুলতা প্রায় ৫% বাড়ল; চুপ-বসা দলের কমল প্রায় ১২%।", "এক কথায়: নমুনা ছোট, তবে ইঙ্গিত পরিষ্কার: ভয় কাগজে নামালে মাথায় একটু জায়গা খালি হয়।\\nঘরে করে দেখুন: পরীক্ষা বা ইন্টারভিউয়ের আগে ১০ মিনিট নিজের ভয়গুলো লিখে ফেলুন।"]','[{"label": "University of Chicago News", "url": ""}, {"label": "ScienceDaily", "url": "https://sciencedaily.com/releases/2011/01/110113141605.htm"}]','[{"src": "/media/mon-bhalo-bhabu/270126-04-writing-worries-before-an-exam-1.webp", "width": 960, "height": 1200, "alt": "দুশ্চিন্তা লিখে ফেললে নম্বর বাড়তে পারে, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270126-04-writing-worries-before-an-exam-2.webp", "width": 960, "height": 1200, "alt": "দুশ্চিন্তা লিখে ফেললে নম্বর বাড়তে পারে, কার্ড 2"}]','["lecroitg, CC0, https://commons.wikimedia.org/wiki/File:Test-986769_640.jpg"]','health','heart','coral',1,'2027-01-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270202-05-awe-and-generosity','mon-bhalo-bhabu','card','বিস্ময়ে তাকালে মানুষ বেশি উদার হয়','২০১৫ সালের গবেষণা: পাঁচটি পরীক্ষা, ইউক্যালিপটাসের বন','["▸ ২০১৫ সালে ইউসি ইরভিনের গবেষকরা বিস্ময় আর উদারতা নিয়ে পাঁচটি পরীক্ষা করেন।\\n▸ প্রথমে ১,৫০০-র বেশি মার্কিন মানুষের জরিপ; পরে ৭৫ থেকে ২৫৪ জনের দলে পরীক্ষা, একটিতে বিশাল ইউক্যালিপটাস বন।\\n▸ যাঁরা বেশি বিস্ময় বোধ করেছেন, তাঁরা রাফেল-টিকিট ভাগের খেলায় বেশি উদার ছিলেন।", "এক কথায়: বিস্ময় আর উদারতার যোগ পাঁচটি পরীক্ষাতেই মিলেছে। কেন, তা নিয়ে আরও গবেষণা দরকার।\\nঘরে করে দেখুন: আজ এক মিনিট উঁচু গাছ বা খোলা আকাশের দিকে তাকিয়ে থাকুন।"]','[{"label": "UCI News", "url": "https://news.uci.edu/?p=21151"}, {"label": "ScienceDaily", "url": "https://sciencedaily.com/releases/2015/05/150519091132.htm"}]','[{"src": "/media/mon-bhalo-bhabu/270202-05-awe-and-generosity-1.webp", "width": 960, "height": 1200, "alt": "বিস্ময়ে তাকালে মানুষ বেশি উদার হয়, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270202-05-awe-and-generosity-2.webp", "width": 960, "height": 1200, "alt": "বিস্ময়ে তাকালে মানুষ বেশি উদার হয়, কার্ড 2"}]','["B 897, CC0, https://commons.wikimedia.org/wiki/File:Eucalyptus_Forest,_Benambra_National_Park.jpg"]','health','heart','coral',1,'2027-02-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270209-06-smell-and-memory','mon-bhalo-bhabu','card','গন্ধ থেকে ফেরা স্মৃতি বেশি আবেগের','নাম বা ছবির চেয়ে গন্ধ বেশি নাড়া দেয়','["▸ গবেষক র‍্যাচেল হার্জ দেখেছেন, গন্ধে জাগা স্মৃতি নাম, ছবি বা শব্দে জাগা স্মৃতির চেয়ে আবেগে ভরা।\\n▸ ২০০৪ সালের ব্রেন-স্ক্যানে প্রিয় স্মৃতির সুগন্ধি শুঁকতেই আবেগের কেন্দ্র অ্যামিগডালা বেশি সাড়া দেয়।\\n▸ পরের এক পর্যালোচনায় বলা হয়েছে, গন্ধে জাগা স্মৃতি প্রায়ই বেশি মধুরও।", "এক কথায়: আবেগ বেশি জাগে, এটুকু মিলেছে। কতটা বেশি আর কেন, তা নিয়ে আরও গবেষণা চলছে।\\nজানেন কি: এক গবেষণা অনুযায়ী গন্ধ নস্টালজিয়া জাগিয়েছে অন্য গন্ধের চেয়ে প্রায় সাড়ে ৬ গুণ বেশি।"]','[{"label": "Scientific American", "url": "https://scientificamerican.com/article/smells-like-old-times"}, {"label": "PMC5039451", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5039451"}]','[{"src": "/media/mon-bhalo-bhabu/270209-06-smell-and-memory-1.webp", "width": 960, "height": 1200, "alt": "গন্ধ থেকে ফেরা স্মৃতি বেশি আবেগের, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270209-06-smell-and-memory-2.webp", "width": 960, "height": 1200, "alt": "গন্ধ থেকে ফেরা স্মৃতি বেশি আবেগের, কার্ড 2"}]','["Yallu007, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:JASMINE_BY_Y7.jpg"]','health','heart','coral',1,'2027-02-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270216-07-talking-to-yourself-by-name','mon-bhalo-bhabu','card','নিজের নাম ধরে ডাকলে ভয় কমে আসে','ইউনিভার্সিটি অব মিশিগান, ২০১৪ ও ২০১৭','["▸ ২০১৪ সালে ইথান ক্রসের দল ৮৯ জন শিক্ষার্থীকে ৫ মিনিট প্রস্তুতি দিয়ে ''স্বপ্নের চাকরি''র বক্তৃতা করতে বলে।\\n▸ প্রস্তুতির সময় একদল ''আমি'' বলে ভাবল, অন্যদল নিজের নাম আর ''সে'' দিয়ে, যেন অন্য কাউকে বলছে।\\n▸ নাম-দিয়ে-ভাবা দল কম লজ্জা পেল এবং বক্তৃতায় একটু ভালো নম্বরও পেল।", "এক কথায়: প্রভাব সামান্য, নমুনা ছোট। ২০১৭ সালের ব্রেন-স্ক্যানেও আবেগের সাড়া কমার ইঙ্গিত মিলেছে।\\nঘরে করে দেখুন: নার্ভাস লাগলে মনে মনে নিজের নাম বসিয়ে বলুন: ''... তুমি পারবে''।"]','[{"label": "ScienceBlog summary of Kross et al. 2014", "url": "https://scienceblog.com/?p=594934"}, {"label": "abstract of Kross et al. 2014 via Europe", "url": ""}, {"label": "Psychology Today", "url": ""}]','[{"src": "/media/mon-bhalo-bhabu/270216-07-talking-to-yourself-by-name-1.webp", "width": 960, "height": 1200, "alt": "নিজের নাম ধরে ডাকলে ভয় কমে আসে, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270216-07-talking-to-yourself-by-name-2.webp", "width": 960, "height": 1200, "alt": "নিজের নাম ধরে ডাকলে ভয় কমে আসে, কার্ড 2"}]','["Johann Andreas Thelot, CC0, https://commons.wikimedia.org/wiki/File:Mirror_MET_DP105726.jpg"]','health','heart','coral',1,'2027-02-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270223-08-nostalgia-and-warmth','mon-bhalo-bhabu','card','পুরনো সুখের স্মৃতিতে ঠান্ডাও কম লাগে','২০১২ সালের গবেষণা: সাউদাম্পটনসহ তিন বিশ্ববিদ্যালয়','["▸ গবেষকরা দেখলেন, ঠান্ডা দিনে বা ঠান্ডা ঘরে মানুষ বেশি নস্টালজিক হয়ে পড়ে।\\n▸ ঠান্ডা ঘরে কেউ মধুর পুরনো স্মৃতি ভাবল, কেউ সাধারণ স্মৃতি; স্মৃতি-ভাবা দল ঘরটাকে বেশি গরম ঠাওরাল।\\n▸ বরফ-ঠান্ডা পানিতে হাত রাখার পরীক্ষায় নস্টালজিক দল বেশিক্ষণ হাত রাখল।", "এক কথায়: অনুভূতির সঙ্গে শরীরের আরামের যোগ দেখা গেল। এটা অনুভব বদলায়, ঘরের তাপমাত্রা নয়।\\nজানেন কি: ৩০ দিনের ডায়েরি-পরীক্ষায় ঠান্ডার দিনে নস্টালজিয়ার অনুভূতি বেশি মিলেছে।"]','[{"label": "LiveScience via NBC News", "url": ""}, {"label": "EurekAlert release", "url": "https://eurekalert.org/news-releases/708181"}, {"label": "abstract of Zhou et al. 2012", "url": ""}]','[{"src": "/media/mon-bhalo-bhabu/270223-08-nostalgia-and-warmth-1.webp", "width": 960, "height": 1200, "alt": "পুরনো সুখের স্মৃতিতে ঠান্ডাও কম লাগে, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270223-08-nostalgia-and-warmth-2.webp", "width": 960, "height": 1200, "alt": "পুরনো সুখের স্মৃতিতে ঠান্ডাও কম লাগে, কার্ড 2"}]','["Pink Sherbet Photography from , CC BY 2.0, https://commons.wikimedia.org/wiki/File:Free_vintage_handwritten_letter_texture_for_layers_(2980933249).jpg"]','health','heart','coral',1,'2027-02-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270302-09-sleep-and-mood','mon-bhalo-bhabu','card','এক রাত ঘুম না হলে মন বেশি নাড়া খায়','২০০৭ সালে বার্কলির গবেষণা: ২৬ জন, ৩৫ ঘণ্টা জাগা','["▸ ২০০৭ সালে ক্যালিফোর্নিয়া বিশ্ববিদ্যালয়, বার্কলির ২৬ জন সুস্থ তরুণ-তরুণী পরীক্ষায় অংশ নেন।\\n▸ একদল ৩৫ ঘণ্টা জেগে থাকে, অন্যদল স্বাভাবিক ঘুমায়; তারপর ১০০টি ছবি দেখানো হয়।\\n▸ জাগা দলের আবেগ-কেন্দ্র খারাপ ছবিতে ৬০%-এর বেশি সাড়া দেয়।", "এক কথায়: ছোট নমুনা, এক রাতের পরীক্ষা। ঘুমের সঙ্গে মেজাজের যোগ বোঝায়, এটা রোগ-নির্ণয় নয়।\\nঘরে করে দেখুন: আজ ফোন সরিয়ে একটু আগে শুয়ে দেখুন, কাল মেজাজ কেমন থাকে।"]','[{"label": "UC Berkeley News Archive", "url": ""}, {"label": "News-Medical", "url": "https://news-medical.net/news/2007/10/22/31586.aspx"}]','[{"src": "/media/mon-bhalo-bhabu/270302-09-sleep-and-mood-1.webp", "width": 960, "height": 1200, "alt": "এক রাত ঘুম না হলে মন বেশি নাড়া খায়, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270302-09-sleep-and-mood-2.webp", "width": 960, "height": 1200, "alt": "এক রাত ঘুম না হলে মন বেশি নাড়া খায়, কার্ড 2"}]','["Afifa Afrin, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Door_open;_empty_bed_with_pillow_and_side_pillow_01.jpg"]','health','heart','coral',1,'2027-03-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270316-11-eating-together','mon-bhalo-bhabu','card','একসঙ্গে খেলে জীবন বেশি ভালো লাগে','অক্সফোর্ডের রবিন ডানবারের জরিপ, ২০১৭','["▸ ২০১৭ সালে অক্সফোর্ডের রবিন ডানবার যুক্তরাজ্যের ২,০০০-এর বেশি প্রাপ্তবয়স্কের জরিপ করেন।\\n▸ প্রশ্ন ছিল: কতবার অন্যদের সঙ্গে খান, আর জীবন নিয়ে কেমন লাগে।\\n▸ যাঁরা বেশি একসঙ্গে খান, তাঁরা বেশি সুখী ও সন্তুষ্ট, তাঁদের ভরসার বন্ধুও বেশি।", "এক কথায়: মূলত জরিপের তথ্য, নিজের বলা উত্তর। তাই ''কারণ'' বলা কঠিন, তবে যোগটা স্পষ্ট।\\nজানেন কি: ওই জরিপে সপ্তাহের ২১ বেলার খাবারের গড়ে ১০টি একা খাওয়া হয়।"]','[{"label": "Psychology Today", "url": "https://psychologytoday.com/us/blog/friendly-interest/202002/what-youre-missing-out-when-you-eat-your-desk"}, {"label": "welldoing.org on the Big Lunch survey", "url": "https://welldoing.org/article/social-eating-helps-connect-communities"}, {"label": "abstract of Dunbar 2017", "url": ""}]','[{"src": "/media/mon-bhalo-bhabu/270316-11-eating-together-1.webp", "width": 960, "height": 1200, "alt": "একসঙ্গে খেলে জীবন বেশি ভালো লাগে, কার্ড 1"}, {"src": "/media/mon-bhalo-bhabu/270316-11-eating-together-2.webp", "width": 960, "height": 1200, "alt": "একসঙ্গে খেলে জীবন বেশি ভালো লাগে, কার্ড 2"}]','["Marajozkee, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Bengali_vegetarian_thali.jpg"]','health','heart','coral',1,'2027-03-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261205-01-jc-bose','dadur-khata','card','দাদুর খাতা, পাতা ০১: গাছেরও সাড়া আছে','ময়মনসিংহে জন্ম নেওয়া এক বিজ্ঞানী যন্ত্র বানিয়ে মাপলেন গাছের সাড়া।','["• ১৮৫৮: ৩০ নভেম্বর ময়মনসিংহে জন্ম জগদীশচন্দ্র বসুর।\\n• ক্রেস্কোগ্রাফ: নিজের তৈরি এই যন্ত্রে গাছের খুব সামান্য নড়াচড়াও বহুগুণ বড় করে মাপা যেত।\\n• ১৯১৭: কলকাতায় গড়ে তোলেন বসু বিজ্ঞান মন্দির (বোস ইনস্টিটিউট)।", "দাদু বলেন: গাছ কথা বলে না, কিন্তু সাড়া দেয়। সেটা মাপতে লেগেছিল এক বাঙালির ধৈর্য।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/261205-01-jc-bose-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০১: গাছেরও সাড়া আছে, কার্ড 1"}, {"src": "/media/dadur-khata/261205-01-jc-bose-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০১: গাছেরও সাড়া আছে, কার্ড 2"}]','["The Birth Centenary Committee, Public domain, https://commons.wikimedia.org/wiki/File:J.C.Bose.JPG", "Biswarup Ganguly, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Crescograph_-_Jagadish_Chandra_Bose_Museum_-_Bose_Institute_-_Kolkata_2011-07-26_4040_Cropped.JPG"]','history','book','teal',1,'2026-12-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261212-02-concert-for-bangladesh','dadur-khata','card','দাদুর খাতা, পাতা ০২: বাংলাদেশের জন্য এক কনসার্ট','১৯৭১ সালে নিউইয়র্কে, যুদ্ধের শরণার্থীদের পাশে দাঁড়াতে।','["• ১ আগস্ট ১৯৭১: নিউইয়র্কের ম্যাডিসন স্কয়ার গার্ডেনে একই দিনে দুটি শো।\\n• আয়োজক: জর্জ হ্যারিসন ও রবিশঙ্কর।\\n• ৪০,০০০: দর্শক এসেছিলেন; অর্থ গেল বাংলাদেশের শরণার্থীদের সাহায্যে।", "দাদু বলেন: বিজয়ের মাসে মনে রাখি: সেই কঠিন সময়ে দূর দেশের মানুষও পাশে দাঁড়িয়েছিল।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "George Harrison official site", "url": "https://www.georgeharrison.com/films/the-concert-for-bangladesh/"}]','[{"src": "/media/dadur-khata/261212-02-concert-for-bangladesh-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০২: বাংলাদেশের জন্য এক কনসার্ট, কার্ড 1"}, {"src": "/media/dadur-khata/261212-02-concert-for-bangladesh-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০২: বাংলাদেশের জন্য এক কনসার্ট, কার্ড 2"}]','["Richard Warren Lipack, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:BANGLADESHconcert1971Lipack_frame.jpg", "John Malmin, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Musicians_Ravi_Shankar_and_George_Harrison_in_Los_Angeles,_Calif.,_1967.jpg"]','history','book','teal',1,'2026-12-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261219-03-rokeya-sultanas-dream','dadur-khata','card','দাদুর খাতা, পাতা ০৩: ১৯০৫ সালের উড়ন্ত গাড়ি','বেগম রোকেয়ার ''সুলতানার স্বপ্ন'': যে দেশ চলে বিজ্ঞানে।','["• ১৮৮০: ৯ ডিসেম্বর রংপুরের পায়রাবন্দে জন্ম।\\n• ১৯০৫: ইংরেজিতে ছাপা হয় ''সুলতানার স্বপ্ন'': সৌরতাপে রান্না, আকাশে উড়ন্ত গাড়ি।\\n• ১৯০৯-১৯১১: ভাগলপুরে মেয়েদের স্কুল শুরু, ১৯১১ সালে কলকাতায়।", "দাদু বলেন: যে যুগে মেয়েদের পড়াই কঠিন, সে যুগে তিনি কল্পনায় গড়লেন বিজ্ঞানের দেশ।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}, {"label": "full text", "url": ""}]','[{"src": "/media/dadur-khata/261219-03-rokeya-sultanas-dream-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৩: ১৯০৫ সালের উড়ন্ত গাড়ি, কার্ড 1"}, {"src": "/media/dadur-khata/261219-03-rokeya-sultanas-dream-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৩: ১৯০৫ সালের উড়ন্ত গাড়ি, কার্ড 2"}]','["Unknown authorUnknown author, Public domain, https://commons.wikimedia.org/wiki/File:Rokeya_Sakhawat_Hussain.jpg"]','history','book','teal',1,'2026-12-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261226-04-mahasthangarh','dadur-khata','card','দাদুর খাতা, পাতা ০৪: মাটির নিচে এক প্রাচীন শহর','বগুড়ার মহাস্থানগড়: বাংলাদেশের সবচেয়ে পুরনো প্রত্নস্থান।','["• খ্রিস্টপূর্ব ৩য় শতক: অন্তত এত পুরনো এই শহর; নাম ছিল পুণ্ড্রনগর।\\n• করতোয়া: শহরের পূর্ব পাশ দিয়ে বয়ে যায় এই নদী।\\n• ব্রাহ্মী লিপি: এখানে মিলেছে ব্রাহ্মী লিপিতে লেখা প্রাচীন শিলালিপি।", "দাদু বলেন: পায়ের নিচের মাটিও ইতিহাসের বই, শুধু পড়তে জানতে হয়।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/261226-04-mahasthangarh-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৪: মাটির নিচে এক প্রাচীন শহর, কার্ড 1"}, {"src": "/media/dadur-khata/261226-04-mahasthangarh-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৪: মাটির নিচে এক প্রাচীন শহর, কার্ড 2"}]','["Zaheed Sarwer Khan, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Old_brick_walls_of_Mahasthangarh.jpg"]','history','book','teal',1,'2026-12-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270102-05-sn-bose','dadur-khata','card','দাদুর খাতা, পাতা ০৫: ঢাকা থেকে আইনস্টাইনকে চিঠি','এক তরুণ শিক্ষকের কয়েক পাতা বদলে দিল পদার্থবিজ্ঞান।','["• ১৮৯৪: ১ জানুয়ারি কলকাতায় জন্ম; ১৯২১ থেকে ঢাকা বিশ্ববিদ্যালয়ে।\\n• ১৯২৪: কণা গোনার নতুন হিসাব লিখে পাঠালেন সরাসরি আইনস্টাইনকে।\\n• বোসন: আইনস্টাইন নিজে জার্মানে অনুবাদ করে ছাপালেন; এক শ্রেণির কণার নাম হলো বোসন।", "দাদু বলেন: একটা চিঠি আর অনেকখানি সাহস। বাকিটা ইতিহাস।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/270102-05-sn-bose-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৫: ঢাকা থেকে আইনস্টাইনকে চিঠি, কার্ড 1"}, {"src": "/media/dadur-khata/270102-05-sn-bose-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৫: ঢাকা থেকে আইনস্টাইনকে চিঠি, কার্ড 2"}]','["Unknown authorUnknown author (, Public domain, https://commons.wikimedia.org/wiki/File:Satyendra-nath-bose.jpg"]','history','book','teal',1,'2027-01-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270109-06-ors','dadur-khata','card','দাদুর খাতা, পাতা ০৬: লবণ-চিনির পানি, লাখো প্রাণ','খাবার স্যালাইনের গল্প, যার শিকড় এই বাংলায়।','["• ১৯৬০-এর দশক: ঢাকার কলেরা গবেষণাগারে (আজকের আইসিডিডিআর,বি) মুখে খাওয়ার স্যালাইন নিয়ে বড় কাজ হয়।\\n• ১৯৭১: শরণার্থী শিবিরে ডা. দিলীপ মহলানবিশের দল কলেরা রোগীদের স্যালাইন খাওয়ালেন।\\n• ৩০% থেকে ৩.৬%: কলেরায় মৃত্যুর হার নেমে এল এতটা।", "দাদু বলেন: সবচেয়ে বড় আবিষ্কার সবসময় দামি হয় না।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/diarrhoeal-disease"}]','[{"src": "/media/dadur-khata/270109-06-ors-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৬: লবণ-চিনির পানি, লাখো প্রাণ, কার্ড 1"}, {"src": "/media/dadur-khata/270109-06-ors-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৬: লবণ-চিনির পানি, লাখো প্রাণ, কার্ড 2"}]','["Cjp24, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Oral_rehydration_salts_(ORS)_-_Packet.jpg"]','history','book','teal',1,'2027-01-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270116-07-fr-khan','dadur-khata','card','দাদুর খাতা, পাতা ০৭: আকাশছোঁয়া বাড়ির বাঙালি কারিগর','ফজলুর রহমান খানের ''টিউব'' ভাবনায় দাঁড়াল সিয়ার্স টাওয়ার।','["• টিউব: ভবনের বাইরের দেয়ালকে ফাঁপা নলের মতো শক্ত করে বাতাসের ধাক্কা সামলানো।\\n• প্রকৌশলী: সিয়ার্স টাওয়ারের কাঠামো-নকশার মূল মানুষ ফজলুর রহমান খান।\\n• ১৯৭৩-১৯৯৮: এটাই ছিল বিশ্বের সবচেয়ে উঁচু ভবন।", "দাদু বলেন: উঁচু হতে হলে ভেতরটা হালকা, বাইরেটা শক্ত। মানুষের বেলাতেও কি তাই?"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Lehigh University", "url": "https://www.lehigh.edu/~infrk/2011.08.article.html"}]','[{"src": "/media/dadur-khata/270116-07-fr-khan-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৭: আকাশছোঁয়া বাড়ির বাঙালি কারিগর, কার্ড 1"}, {"src": "/media/dadur-khata/270116-07-fr-khan-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৭: আকাশছোঁয়া বাড়ির বাঙালি কারিগর, কার্ড 2"}]','["Alvesgaspar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Willis_Tower,_Chicago_September_2016-26.jpg"]','history','book','teal',1,'2027-01-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270123-08-wari-bateshwar','dadur-khata','card','দাদুর খাতা, পাতা ০৮: গ্রামের মাটিতে দুর্গ-নগর','নরসিংদীর উয়ারী-বটেশ্বর, প্রায় আড়াই হাজার বছর আগের।','["• ১৯৩০-এর দশক: স্কুলশিক্ষক হানিফ পাঠান মাটিতে পাওয়া পুরনো জিনিস জমাতে শুরু করেন।\\n• ২০০০: শুরু হয় নিয়মিত খনন।\\n• ৬০০ × ৬০০ মিটার: পরিখায় ঘেরা দুর্গ; মিলেছে পুঁতি আর ছাপাঙ্কিত রুপার মুদ্রা।", "দাদু বলেন: একজন শিক্ষকের কৌতূহল না থাকলে শহরটা হয়তো আজও ঘুমিয়ে থাকত।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/270123-08-wari-bateshwar-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৮: গ্রামের মাটিতে দুর্গ-নগর, কার্ড 1"}, {"src": "/media/dadur-khata/270123-08-wari-bateshwar-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৮: গ্রামের মাটিতে দুর্গ-নগর, কার্ড 2"}]','["Redmin, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Wari-Bateshwar_Museum,_Narsingdi,_Bangladesh_01.jpg"]','history','book','teal',1,'2027-01-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270130-09-zero','dadur-khata','card','দাদুর খাতা, পাতা ০৯: শূন্যের লম্বা যাত্রা','দক্ষিণ এশিয়ার গণিত থেকে সারা পৃথিবীর হিসাবে।','["• ৬২৮: ব্রহ্মগুপ্ত শূন্যকে একটি সংখ্যা ধরে তার হিসাবের নিয়ম লিখলেন।\\n• হিন্দু-আরবি অঙ্ক: শূন্যসহ ১০টি অঙ্ক আর ঘরের মান: এই পদ্ধতির নাম এটাই।\\n• ১২০২: ফিবোনাচ্চির বই ইউরোপে এই সংখ্যাপদ্ধতি জনপ্রিয় করে।", "দাদু বলেন: কিছু-না-কে একটা নাম দেওয়া, এটাই ছিল সবচেয়ে বড় কিছু।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "MacTutor", "url": ""}]','[{"src": "/media/dadur-khata/270130-09-zero-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৯: শূন্যের লম্বা যাত্রা, কার্ড 1"}, {"src": "/media/dadur-khata/270130-09-zero-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ০৯: শূন্যের লম্বা যাত্রা, কার্ড 2"}]','["National Geographic, Public domain, https://commons.wikimedia.org/wiki/File:Bakhshali_manuscript.jpg"]','history','book','teal',1,'2027-01-30');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270206-10-charyapada','dadur-khata','card','দাদুর খাতা, পাতা ১০: বাংলার সবচেয়ে পুরনো কবিতা','নেপালের রাজদরবারের গ্রন্থাগারে পাওয়া তালপাতার পুঁথি।','["• হরপ্রসাদ শাস্ত্রী: নেপালের রাজদরবারের গ্রন্থাগারে খুঁজে পান পুঁথিটি।\\n• ১৯১৬: বঙ্গীয় সাহিত্য পরিষদ থেকে প্রকাশ।\\n• ৪৭: পুঁথিতে পদ, মানে ছোট কবিতা, আছে ৪৭টি।", "দাদু বলেন: হাজার বছর আগেও কেউ এই ভাষায় মনের কথা লিখে গেছেন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/270206-10-charyapada-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১০: বাংলার সবচেয়ে পুরনো কবিতা, কার্ড 1"}, {"src": "/media/dadur-khata/270206-10-charyapada-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১০: বাংলার সবচেয়ে পুরনো কবিতা, কার্ড 2"}]','["Mohmoni, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:%E0%A6%9A%E0%A6%B0%E0%A7%8D%E0%A6%AF%E0%A6%BE%E0%A6%AA%E0%A6%A6-%E0%A6%8F%E0%A6%B0_%E0%A7%A9%E0%A7%AF_%E0%A6%A8%E0%A6%82_%E0%A6%AA%E0%A7%"]','history','book','teal',1,'2027-02-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270213-11-first-bangla-type','dadur-khata','card','দাদুর খাতা, পাতা ১১: প্রথম ছাপা বাংলা হরফ','হুগলিতে ছাপা এক ব্যাকরণ বইয়ের পাতায়।','["• ১৭৭৮: ন্যাথানিয়েল ব্রাসি হালহেডের বাংলা ব্যাকরণ ছাপা হয়।\\n• প্রথম: এই বইয়েই বাংলা অক্ষর প্রথম ছাপার হরফে আসে।\\n• হুগলি: বইয়ের প্রথম পাতাতেই লেখা: Printed at Hoogly in Bengal।", "দাদু বলেন: হাতের লেখা থেকে ছাপার হরফ, সেখান থেকে আজ আপনার ফোনের পর্দা।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}, {"label": "the book''s title page", "url": ""}]','[{"src": "/media/dadur-khata/270213-11-first-bangla-type-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১১: প্রথম ছাপা বাংলা হরফ, কার্ড 1"}, {"src": "/media/dadur-khata/270213-11-first-bangla-type-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১১: প্রথম ছাপা বাংলা হরফ, কার্ড 2"}]','["Nathaniel Brassey Halhed, Public domain, https://commons.wikimedia.org/wiki/File:A_Grammar_of_the_Bengal_Language.png"]','history','book','teal',1,'2027-02-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270220-12-mother-language-day','dadur-khata','card','দাদুর খাতা, পাতা ১২: একুশ এখন সব মাতৃভাষার দিন','১৯৫২ সালের ঢাকা থেকে আন্তর্জাতিক মাতৃভাষা দিবস।','["• ১৯৫২: ২১ ফেব্রুয়ারি ঢাকায় মাতৃভাষা বাংলার দাবিতে প্রাণ দেন ভাষাশহীদেরা।\\n• ১৯৯৯: নভেম্বরে ইউনেস্কো দিনটিকে আন্তর্জাতিক মাতৃভাষা দিবস ঘোষণা করে।\\n• বাংলাদেশ: এই উদ্যোগ এসেছিল বাংলাদেশ থেকেই।", "দাদু বলেন: যে ভাষায় আমরা স্বপ্ন দেখি, তার জন্য যাঁরা প্রাণ দিয়েছেন, তাঁদের প্রতি শ্রদ্ধা।"]','[{"label": "Wikipedia", "url": ""}, {"label": "United Nations", "url": ""}]','[{"src": "/media/dadur-khata/270220-12-mother-language-day-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১২: একুশ এখন সব মাতৃভাষার দিন, কার্ড 1"}, {"src": "/media/dadur-khata/270220-12-mother-language-day-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১২: একুশ এখন সব মাতৃভাষার দিন, কার্ড 2"}]','["Rabindranath Tagore, Public domain, https://commons.wikimedia.org/wiki/File:Tagore_handwriting_Bengali.jpg"]','history','book','teal',1,'2027-02-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270227-13-muslin','dadur-khata','card','দাদুর খাতা, পাতা ১৩: যে কাপড়ের ভেতর দিয়ে হাত দেখা যায়','ঢাকাই মসলিন আর তার হারানো তুলার গল্প।','["• ফুটি কার্পাস: এই বিশেষ তুলা থেকেই হতো সবচেয়ে মিহি মসলিনের সুতা।\\n• নদীর পাড়: এই তুলা জন্মাত ঢাকার আশপাশে নদীতীরের কিছু এলাকায়।\\n• পতন: ইংল্যান্ডের কলের সস্তা কাপড়ের সাথে পাল্লায় হারিয়ে যায় এই শিল্প।", "দাদু বলেন: কিছু জিনিস হারায় দামে নয়, অবহেলায়।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/270227-13-muslin-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৩: যে কাপড়ের ভেতর দিয়ে হাত দেখা যায়, কার্ড 1"}, {"src": "/media/dadur-khata/270227-13-muslin-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৩: যে কাপড়ের ভেতর দিয়ে হাত দেখা যায়, কার্ড 2"}]','["Faizul Latif Chowdhury, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Muslin_transparency_2015_Kolkata.jpg"]','history','book','teal',1,'2027-02-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270306-14-meghnad-saha','dadur-khata','card','দাদুর খাতা, পাতা ১৪: তারার তাপমাত্রা বোঝার সূত্র','ঢাকার এক গ্রামের ছেলে মেঘনাদ সাহার আবিষ্কার।','["• ১৮৯৩: ৬ অক্টোবর ঢাকা জেলার শেওড়াতলী গ্রামে জন্ম।\\n• সাহা সমীকরণ: ১৯২০ সালের দিকে তৈরি; তারার আলোর বর্ণালি থেকে তাপমাত্রা বোঝার চাবি।\\n• তারার আলো: দূরের তারার আলোতেই লুকিয়ে থাকে তার ভেতরের খবর।", "দাদু বলেন: তারা ছুঁতে না পারলেও তার আলো পড়ে তাকে চেনা যায়।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/270306-14-meghnad-saha-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৪: তারার তাপমাত্রা বোঝার সূত্র, কার্ড 1"}, {"src": "/media/dadur-khata/270306-14-meghnad-saha-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৪: তারার তাপমাত্রা বোঝার সূত্র, কার্ড 2"}]','["Unknown authorUnknown author, Public domain, https://commons.wikimedia.org/wiki/File:Photograph_of_Scientist_Meghnad_Saha.jpg"]','history','book','teal',1,'2027-03-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270313-15-jamal-nazrul-islam','dadur-khata','card','দাদুর খাতা, পাতা ১৫: মহাবিশ্বের শেষ কোথায়?','জামাল নজরুল ইসলামের বই ছাপল কেমব্রিজ।','["• ১৯৩৯: ২৪ ফেব্রুয়ারি ঝিনাইদহে জন্ম।\\n• ১৯৮৩: কেমব্রিজ ইউনিভার্সিটি প্রেস ছাপে তাঁর বই ''দ্য আলটিমেট ফেট অব দ্য ইউনিভার্স''।\\n• চট্টগ্রাম: দেশে ফিরে চট্টগ্রাম বিশ্ববিদ্যালয়ের গাণিতিক ও ভৌত বিজ্ঞান গবেষণাকেন্দ্রের হাল ধরেন।", "দাদু বলেন: বিদেশের বড় সুযোগ ছেড়ে তিনি দেশে ফিরেছিলেন, নিজের ছাত্রদের কাছে।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/dadur-khata/270313-15-jamal-nazrul-islam-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৫: মহাবিশ্বের শেষ কোথায়?, কার্ড 1"}, {"src": "/media/dadur-khata/270313-15-jamal-nazrul-islam-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৫: মহাবিশ্বের শেষ কোথায়?, কার্ড 2"}]','["Intakhab ctg, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Jamal_Nazrul_Islam_addressing_in_inaugural_ceremony_of_bookstall_Baatighar_cropped.jpg"]','history','book','teal',1,'2027-03-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270320-16-dhaka-university','dadur-khata','card','দাদুর খাতা, পাতা ১৬: ঢাকায় এল এক বিশ্ববিদ্যালয়','৮৪৭ জন ছাত্র নিয়ে শুরু হলো ক্লাস।','["• ১ জুলাই ১৯২১: ঢাকা বিশ্ববিদ্যালয়ে ক্লাস শুরু।\\n• ৮৪৭: প্রথম দিনের ছাত্রসংখ্যা।\\n• সত্যেন বসু: এখানে পড়ানোর সময়েই লিখেছিলেন বিখ্যাত বোসন-গবেষণা।", "দাদু বলেন: বিশ্ববিদ্যালয় মানে শুধু দালান নয়, প্রশ্ন করার সাহস।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/dadur-khata/270320-16-dhaka-university-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৬: ঢাকায় এল এক বিশ্ববিদ্যালয়, কার্ড 1"}, {"src": "/media/dadur-khata/270320-16-dhaka-university-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৬: ঢাকায় এল এক বিশ্ববিদ্যালয়, কার্ড 2"}]','["Tarunsamanta, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Curzon_Hall,_Dhaka_University_04.jpg"]','history','book','teal',1,'2027-03-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270327-17-un-membership','dadur-khata','card','দাদুর খাতা, পাতা ১৭: বিশ্বসভায় বাংলাদেশ','স্বাধীনতার মাসে মনে রাখি: জাতিসংঘে আমাদের আসন।','["• ১৭ সেপ্টেম্বর ১৯৭৪: বাংলাদেশ জাতিসংঘের পূর্ণ সদস্য হয়।\\n• ৫০ বছর: ২০২৪ সালে এই সদস্যপদের ৫০ বছর পূর্ণ হয়েছে।\\n• ২১ ফেব্রুয়ারি: বাংলাদেশের উদ্যোগেই ইউনেস্কো এই দিনকে আন্তর্জাতিক মাতৃভাষা দিবস করেছে।", "দাদু বলেন: স্বাধীনতা মানে নিজের নামে বিশ্বের দরবারে বসার অধিকার।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "United Nations", "url": ""}]','[{"src": "/media/dadur-khata/270327-17-un-membership-1.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৭: বিশ্বসভায় বাংলাদেশ, কার্ড 1"}, {"src": "/media/dadur-khata/270327-17-un-membership-2.webp", "width": 960, "height": 1200, "alt": "দাদুর খাতা, পাতা ১৭: বিশ্বসভায় বাংলাদেশ, কার্ড 2"}]','["Basil D Soufi, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:United_Nations_General_Assembly_Hall_(3).jpg"]','history','book','teal',1,'2027-03-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270107-01-krikalev-time-travel-0-02-seconds','time-machine-tiffin-box','card','৮০৩ দিন মহাকাশে থেকে তিনি ০.০২ সেকেন্ড ভবিষ্যতে','মির স্টেশন: ক্রিকালেভের কয়েকটি অভিযানের ঘর','["▸ গল্পের টাইম মেশিনে চড়লেই ঝট করে ভবিষ্যতে পৌঁছনো যায়।\\n▸ স্টেশন খুব জোরে ছোটে, তাই ওখানে ঘড়ি সামান্য ধীরে চলে।\\n▸ ৮০৩ দিন ৯ ঘণ্টা ৩৯ মিনিট কক্ষপথে থেকে ফারাক প্রায় ১/৪৮ সেকেন্ড।", "এক কথায়: টাইম মেশিন নেই, তবে ভবিষ্যতে এক ছোট্ট লাফ সত্যি।\\nভাবুন: ৮০৩ দিনে ঘড়ি কত সেকেন্ড এগোত, আগে অনুমান করে ০.০২-এর সাথে মেলান।"]','[{"label": "Guinness World Records", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270107-01-krikalev-time-travel-0-02-seconds-1.webp", "width": 960, "height": 1200, "alt": "৮০৩ দিন মহাকাশে থেকে তিনি ০.০২ সেকেন্ড ভবিষ্যতে, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270107-01-krikalev-time-travel-0-02-seconds-2.webp", "width": 960, "height": 1200, "alt": "৮০৩ দিন মহাকাশে থেকে তিনি ০.০২ সেকেন্ড ভবিষ্যতে, কার্ড 2"}]','["NASA, Public domain, https://commons.wikimedia.org/wiki/File:STS-76_Mir_Space_Station_survey_-_Kristall,_Base_Module_and_Spektr.jpg", "NASA, Public domain, https://commons.wikimedia.org/wiki/File:Mir_space_station_12_June_1998.jpg"]','physics','sparkle','deep',1,'2027-01-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270114-02-capek-robot-word-forced-labour','time-machine-tiffin-box','card','রোবট'' শব্দের মানে চেক ভাষায় জোর-খাটুনি','চাপেকের নাটক R.U.R.: ছাপা ১৯২০, মঞ্চে ১৯২১','["▸ নাটকে কারখানার কাজ করে মানুষের বানানো কৃত্রিম শ্রমিকেরা।\\n▸ চেক ''রোবোতা'' মানে জোর-খাটুনি; নামটা ভেবেছিলেন ভাই ইয়োসেফ।\\n▸ নাটক থেকে শব্দটা ছড়ায়; আজ সারা বিশ্বে যন্ত্রমানুষের নাম।", "এক কথায়: নামেই লেখা: রোবটের জন্ম খাটুনি করে দেওয়ার জন্য।\\nখুঁজে দেখুন: বাড়ির এমন যন্ত্র খুঁজুন, যে আপনার খাটুনি কমায়; নামটা লিখে রাখুন।"]','[{"label": "Linda Hall Library", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270114-02-capek-robot-word-forced-labour-1.webp", "width": 960, "height": 1200, "alt": "রোবট'' শব্দের মানে চেক ভাষায় জোর-খাটুনি, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270114-02-capek-robot-word-forced-labour-2.webp", "width": 960, "height": 1200, "alt": "রোবট'' শব্দের মানে চেক ভাষায় জোর-খাটুনি, কার্ড 2"}]','["WPA, Public domain, https://commons.wikimedia.org/wiki/File:WPA-Marionette-Theatre-Presents-RUR-LOC-200216613.jpg", "Henri Manuel, Public domain, https://commons.wikimedia.org/wiki/File:R._U._R._(Karel_%C4%8Capek)_-_Com%C3%A9die_des_Champs-%C3%89lys%C3%A9es,_26_mars_1924_-_photo_Henri_Manuel.jpg"]','physics','sparkle','deep',1,'2027-01-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270121-03-gps-clocks-38-microseconds-relativity','time-machine-tiffin-box','card','প্রতিদিন ৩৮ মাইক্রোসেকেন্ড এগোয় জিপিএস উপগ্রহের ঘড়ি','NIST-এর পরমাণু ঘড়ি; জিপিএস উপগ্রহেও এমন ঘড়ি থাকে','["▸ গল্পে ঘড়ি থামে বা উল্টো চলে; সূত্রে সময় সত্যিই বদলায়।\\n▸ কক্ষপথে টান কম তাই ঘড়ি দ্রুত, গতিতে ধীর; মিলিয়ে ৩৮ বেশি।\\n▸ ঠিক না করলে রোজ প্রায় ১১ কিমি ভুল জমত; আগেই ঘড়ি ঠিক করা হয়।", "এক কথায়: সময়ের হিসাব মেলানো হয় বলেই ফোনের ম্যাপ ঠিক পথ দেখায়।\\nখুঁজে দেখুন: ফোনের লোকেশন বন্ধ-চালু করে দেখুন ম্যাপ কত দ্রুত আপনাকে খোঁজে।"]','[{"label": "NIST", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270121-03-gps-clocks-38-microseconds-relativity-1.webp", "width": 960, "height": 1200, "alt": "প্রতিদিন ৩৮ মাইক্রোসেকেন্ড এগোয় জিপিএস উপগ্রহের ঘড়ি, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270121-03-gps-clocks-38-microseconds-relativity-2.webp", "width": 960, "height": 1200, "alt": "প্রতিদিন ৩৮ মাইক্রোসেকেন্ড এগোয় জিপিএস উপগ্রহের ঘড়ি, কার্ড 2"}]','["National Institute of Standard, Public domain, https://commons.wikimedia.org/wiki/File:Atomic_Clock015.jpg", "U.S. Space Force image by [nul, Public domain, https://commons.wikimedia.org/wiki/File:GPS_IIF_12_moves_to_next_processing_phase_toward_launch_(2386299).jpeg"]','physics','sparkle','deep',1,'2027-01-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270128-04-clarke-geostationary-orbit-1945','time-machine-tiffin-box','card','১৯৪৫-এর এক প্রবন্ধ আজ ৩৬ হাজার কিমি ওপরে সত্যি','আর্থার সি. ক্লার্ক আর স্থির কক্ষপথের উপগ্রহ','["▸ ক্লার্ক লিখলেন: মহাকাশের এক ''রেডিও টাওয়ার'' সারা পৃথিবী ঢেকে দেবে।\\n▸ প্রায় ৩৬ হাজার কিমি উঁচুতে উপগ্রহ পৃথিবীর সাথে ঘুরে এক জায়গায় স্থির দেখায়।\\n▸ ১৯৬৪ সালে সিনকম ৩ প্রথম এই কক্ষপথে পৌঁছায়; সংকেত ছড়ানোই এর কাজ।", "এক কথায়: একটা প্রবন্ধের ভাবনাই আজ আকাশ থেকে সংকেত নামায়।\\nখুঁজে দেখুন: আজ আপনার এলাকার একটা ডিশ-অ্যান্টেনা কোন দিকে তাক করা, লক্ষ করুন।"]','[{"label": "Engineering and Technology History Wiki", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "ITU News", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270128-04-clarke-geostationary-orbit-1945-1.webp", "width": 960, "height": 1200, "alt": "১৯৪৫-এর এক প্রবন্ধ আজ ৩৬ হাজার কিমি ওপরে সত্যি, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270128-04-clarke-geostationary-orbit-1945-2.webp", "width": 960, "height": 1200, "alt": "১৯৪৫-এর এক প্রবন্ধ আজ ৩৬ হাজার কিমি ওপরে সত্যি, কার্ড 2"}]','["NASA on The Commons, Public domain, https://commons.wikimedia.org/wiki/File:Syncom,_the_First_Geosynchronous_Satellite_(9467417546).jpg", "NOAASatellites, Public domain, https://commons.wikimedia.org/wiki/File:GOES-U_Satellite_EMI-EMC_Testing_(53187216386).jpg"]','physics','sparkle','deep',1,'2027-01-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270204-05-dolly-sheep-clone-adult-cell','time-machine-tiffin-box','card','প্রাপ্তবয়স্ক ভেড়ার একটি কোষ থেকে ডলি','ডলি: প্রাপ্তবয়স্ক কোষ থেকে ক্লোন হওয়া প্রথম স্তন্যপায়ী','["▸ গল্পে ক্লোন মানে নিমেষে তৈরি একই চেহারার আরেকজন।\\n▸ বাস্তবে পূর্ণবয়স্ক ভেড়ার স্তনগ্রন্থির কোষ থেকে ডিমে নতুন প্রাণ গড়া হয়।\\n▸ ডলির জন্ম ১৯৯৬-এ, রোসলিন ইনস্টিটিউটে; এখন সে এডিনবরার জাদুঘরে।", "এক কথায়: ক্লোন নিমেষে হয় না; বছরের পর বছর পরীক্ষার ফল ডলি।\\nভাবুন: ক্লোন করা প্রাণী আর যমজ ভাই-বোনের মধ্যে কী মিল আর কী অমিল, দুটো করে লিখুন।"]','[{"label": "National Museums Scotland", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270204-05-dolly-sheep-clone-adult-cell-1.webp", "width": 960, "height": 1200, "alt": "প্রাপ্তবয়স্ক ভেড়ার একটি কোষ থেকে ডলি, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270204-05-dolly-sheep-clone-adult-cell-2.webp", "width": 960, "height": 1200, "alt": "প্রাপ্তবয়স্ক ভেড়ার একটি কোষ থেকে ডলি, কার্ড 2"}]','["Sgerbic, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Dolly_the_Sheep_National_Museum_of_Scotland.jpg", "M J Richardson, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Dolly_at_the_National_Museum_Scotland_-_geograph.org.uk_-_5051696.jpg"]','physics','sparkle','deep',1,'2027-02-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270211-06-quantum-teleportation-143-km-state-not-matter','time-machine-tiffin-box','card','১৪৩ কিমি দূরে টেলিপোর্ট হলো আলোর অবস্থা','ক্যানারি দ্বীপপুঞ্জ: লা পালমা থেকে টেনেরিফে','["▸ গল্পে টেলিপোর্টে মানুষ এক জায়গা থেকে মুহূর্তে অন্য জায়গায় পৌঁছে যায়।\\n▸ বাস্তবে সরে শুধু একটা কণার অবস্থা, কোনো বস্তু বা শক্তি নয়।\\n▸ ২০১২ সালে লা পালমা থেকে টেনেরিফে ১৪৩ কিমি দূরে আলোর কণার অবস্থা পাঠানো হয়।", "এক কথায়: মানুষ নয়, তথ্যের টেলিপোর্ট সত্যি।\\nভাবুন: মানচিত্রে ১৪৩ কিমি দূরত্বটা নিজের এলাকার কোন দুই জায়গার সমান, বের করুন।"]','[{"label": "Max Planck Institute of Quantum Optics", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "arXiv 1205.3909", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270211-06-quantum-teleportation-143-km-state-not-matter-1.webp", "width": 960, "height": 1200, "alt": "১৪৩ কিমি দূরে টেলিপোর্ট হলো আলোর অবস্থা, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270211-06-quantum-teleportation-143-km-state-not-matter-2.webp", "width": 960, "height": 1200, "alt": "১৪৩ কিমি দূরে টেলিপোর্ট হলো আলোর অবস্থা, কার্ড 2"}]','["Gerda Arendt, CC0, https://commons.wikimedia.org/wiki/File:Roque_de_los_Muchachos_observatory,_La_Palma.jpg", "H. Raab (User:Vesta), CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:ESA_Optical_ground_Station.jpg"]','physics','sparkle','deep',1,'2027-02-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270218-07-deep-space-1-ion-engine-92-millinewtons','time-machine-tiffin-box','card','আয়ন ইঞ্জিনের ঠেলা মাত্র ৯২ মিলিনিউটন','নাসার ডিপ স্পেস ১: ১৯৯৮ সালের আয়ন-চালিত মহাকাশযান','["▸ সিনেমায় মহাকাশযান আগুনের ঝলকে এক লাফে ছুটে যায়।\\n▸ আয়ন ইঞ্জিন জেনন গ্যাসের কণা ছুড়ে ঠেলে; সর্বোচ্চ জোর মাত্র ৯২ মিলিনিউটন।\\n▸ উৎক্ষেপণ ২৪ অক্টোবর ১৯৯৮; ইঞ্জিন চলেছে ১৬,২৬৫ ঘণ্টা, গতি বেড়েছে প্রায় ৪.৩ কিমি/সেকেন্ড।", "এক কথায়: ঠেলা সামান্য, কিন্তু অনেক ঘণ্টা চললে গতি বিশাল।\\nভাবুন: খুব কম ঠেলা বছরের পর বছর চললে গতির কী হয়, এক লাইনে লিখুন।"]','[{"label": "NASA Science", "url": ""}, {"label": "NASA History", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270218-07-deep-space-1-ion-engine-92-millinewtons-1.webp", "width": 960, "height": 1200, "alt": "আয়ন ইঞ্জিনের ঠেলা মাত্র ৯২ মিলিনিউটন, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270218-07-deep-space-1-ion-engine-92-millinewtons-2.webp", "width": 960, "height": 1200, "alt": "আয়ন ইঞ্জিনের ঠেলা মাত্র ৯২ মিলিনিউটন, কার্ড 2"}]','["NASA/JPL, Public domain, https://commons.wikimedia.org/wiki/File:Deep_Space_1_ion_engine.jpg", "NASA/JPL, Public domain, https://commons.wikimedia.org/wiki/File:Deep_Space_1_lifted.jpg"]','physics','sparkle','deep',1,'2027-02-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270225-08-holography-gabor-electron-microscope','time-machine-tiffin-box','card','হলোগ্রামের জন্ম মাইক্রোস্কোপ ভালো করতে গিয়ে','ডেনিস গ্যাবর আর ত্রিমাত্রিক আলোর ছবি','["▸ সিনেমায় হলোগ্রাম মানে হাওয়ায় ভাসা ত্রিমাত্রিক ছবি।\\n▸ ১৯৪০-এর দশকে গ্যাবর আলোর তরঙ্গের ছাপ ধরে রাখার কৌশল বের করেন।\\n▸ ১৯৬০-এর দশকের শুরুতে লেজারে জীবন্ত ত্রিমাত্রিক ছবি হয়; গ্যাবর ১৯৭১-এ নোবেল পান।", "এক কথায়: হলোগ্রাম গল্পের আবিষ্কার নয়, মাইক্রোস্কোপের সমস্যা থেকে জন্মেছে।\\nখুঁজে দেখুন: আজ ব্যাংকনোট বা কার্ডে হলোগ্রাম-স্টিকার খুঁজে নাড়িয়ে দেখুন কী বদলায়।"]','[{"label": "SPIE Photonics Focus", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270225-08-holography-gabor-electron-microscope-1.webp", "width": 960, "height": 1200, "alt": "হলোগ্রামের জন্ম মাইক্রোস্কোপ ভালো করতে গিয়ে, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270225-08-holography-gabor-electron-microscope-2.webp", "width": 960, "height": 1200, "alt": "হলোগ্রামের জন্ম মাইক্রোস্কোপ ভালো করতে গিয়ে, কার্ড 2"}]','["Dominic Alves, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Visa_Dove_Hologram_Rainbow.jpg", "Harris, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hologram_by_Ken_Harris,_2012_Switzerland.jpg"]','physics','sparkle','deep',1,'2027-02-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270311-10-cochlear-implant-bionic-ear','time-machine-tiffin-box','card','২০১৯ পর্যন্ত ৭ লক্ষের বেশি কক্লিয়ার ইমপ্লান্ট বসেছে','কক্লিয়ার ইমপ্লান্ট: কানের ভেতরের ''বায়োনিক'' যন্ত্র','["▸ সাইবর্গের গল্পে যন্ত্র বসিয়ে হারানো ইন্দ্রিয় ফিরে আসে।\\n▸ ইমপ্লান্ট কানের নষ্ট অংশ এড়িয়ে সরাসরি শ্রবণ-স্নায়ুকে সংকেত দেয়।\\n▸ প্রথম ধারণা ১৯৫৭ সালের; ২০১৯ সালের মধ্যে নিবন্ধিত যন্ত্র প্রায় ৭ লক্ষ ৩৭ হাজার।", "এক কথায়: যন্ত্র কান সারায় না, কিন্তু শব্দের পথ নতুন করে খুলে দেয়।\\nখুঁজে দেখুন: আজ চোখ বন্ধ করে এক মিনিট শুধু শুনুন, কতগুলো আলাদা শব্দ ধরলেন, গুনুন।"]','[{"label": "NIDCD", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270311-10-cochlear-implant-bionic-ear-1.webp", "width": 960, "height": 1200, "alt": "২০১৯ পর্যন্ত ৭ লক্ষের বেশি কক্লিয়ার ইমপ্লান্ট বসেছে, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270311-10-cochlear-implant-bionic-ear-2.webp", "width": 960, "height": 1200, "alt": "২০১৯ পর্যন্ত ৭ লক্ষের বেশি কক্লিয়ার ইমপ্লান্ট বসেছে, কার্ড 2"}]','["Thomas.haslwanter, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cochlear_Implant,_by_MedEl.jpg", "Tiia Monto, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Cochlear_implant_2.jpg"]','physics','sparkle','deep',1,'2027-03-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270318-11-shanghai-maglev-30-km-8-minutes','time-machine-tiffin-box','card','ভাসমান ট্রেন ৩০ কিমি পথ যায় ৮ মিনিটে','সাংহাইয়ের ম্যাগলেভ: পুডং বিমানবন্দরের পথে','["▸ ভবিষ্যতের গল্পে ট্রেন হাওয়ায় ভেসে ছোটে।\\n▸ চুম্বকের টানে ট্রেন লাইন না ছুঁয়ে ভেসে চলে।\\n▸ সাংহাইয়ে ৩০ কিমির লাইন; ২০০৩ সালে পরীক্ষায় ছুটেছে ৫০১ কিমি/ঘণ্টায়।", "এক কথায়: ভাসমান ট্রেন গল্প নয়; একটা শহরেই রোজ চলে।\\nহিসাব করুন: ৩০ কিমি ৮ মিনিটে গেলে ঘণ্টায় গড় গতি কত, আন্দাজ করে হিসাব মেলান।"]','[{"label": "Maglev Board", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/time-machine-tiffin-box/270318-11-shanghai-maglev-30-km-8-minutes-1.webp", "width": 960, "height": 1200, "alt": "ভাসমান ট্রেন ৩০ কিমি পথ যায় ৮ মিনিটে, কার্ড 1"}, {"src": "/media/time-machine-tiffin-box/270318-11-shanghai-maglev-30-km-8-minutes-2.webp", "width": 960, "height": 1200, "alt": "ভাসমান ট্রেন ৩০ কিমি পথ যায় ৮ মিনিটে, কার্ড 2"}]','["kallerna, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Shanghai_Maglev_2.jpg", "kallerna, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Shanghai_Maglev_3.jpg"]','physics','sparkle','deep',1,'2027-03-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270104-01-storm-cloud-lives-30-to-60-minutes','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ১: ঝড়ের পরে','ঝড়ের একটা মেঘের পুরো জীবন মাত্র ৩০ থেকে ৬০ মিনিট (মার্কিন আবহাওয়া সংস্থা, NWS)।','["নৌকাটা যখন ঘাট ছাড়ল, আকাশ ছিল ঝকঝকে নীল। তুলি তখনো জানত না, বিকেলের আগেই সেই আকাশ কালো হয়ে যাবে।\\n\\"ওই মেঘটা দেখেছ?\\" নীলা আঙুল তুলে দেখাল। দূরে, নদীর ওপারে, একটা মেঘ উঁচু হয়ে উঠছে। ঠিক যেন একটা বিশাল ফুলকপি।\\nআরিফ হাসল। \\"একটা মেঘ দেখে ভয়?\\"\\nনীলা হাসল না। বইয়ে সে পড়েছে, এই মেঘের নাম কিউমুলোনিম্বাস। আর এই মেঘ কখনো একা আসে না।", "বিজ্ঞান: ঝড় হঠাৎ আসে, কিন্তু বেশিক্ষণ থাকে না। উঁচু হয়ে ওঠা মেঘ দেখলে আগেই সাবধান হওয়া যায়।"]','[{"label": "National Weather Service", "url": ""}, {"label": "NOAA National Severe Storms Laboratory", "url": "https://www.nssl.noaa.gov/education/svrwx101/thunderstorms/"}]','[{"src": "/media/rohosser-dwip/270104-01-storm-cloud-lives-30-to-60-minutes-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ১: ঝড়ের পরে, কার্ড 1"}, {"src": "/media/rohosser-dwip/270104-01-storm-cloud-lives-30-to-60-minutes-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ১: ঝড়ের পরে, কার্ড 2"}]','["Kingshuk Mondal, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Cumulonimbus_cloud_over_the_Sundarbans,_West_Bengal,_India_02.jpg", "John Robert McPherson, CC0, https://commons.wikimedia.org/wiki/File:Cumulonimbus_Oxley_Creek_and_Brisbane_River_Graceville_P1410880.jpg"]','nature','leaf','teal',1,'2027-01-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270111-02-settle-muddy-water-then-boil','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ২: পানি আছে, খাওয়ার পানি নেই','ঘোলা পানি ফুটানোর আগে ছেঁকে বা থিতিয়ে নিতে হয়, তারপর ১ মিনিট টগবগ করে ফুটাতে হয় (CDC)।','["ঝড় থেমেছে। কিন্তু চারদিকে শুধু পানি আর পানি, আর তার সবটাই ঘোলা। আরিফ আঁজলা ভরে পানি তুলতে যাচ্ছিল।\\n\\"থামো!\\" নীলা চিৎকার করে উঠল। \\"এই পানি এখন খেলে পেট খারাপ হবে।\\"\\nশুভ একটা খালি বোতল এনে দিল। নীলা তাতে নদীর পানি ভরে বালির ওপর রেখে দিল। \\"একটু অপেক্ষা করো।\\"\\nকিছুক্ষণ পর বোতলের তলায় কাদা জমতে শুরু করল। ওপরের পানিটা ধীরে ধীরে পরিষ্কার হয়ে এল।\\nতুলি ফিসফিস করে বলল, \\"কিন্তু এটাকে তো ফুটাতে হবে। আগুন কোথায় পাব?\\"", "বিজ্ঞান: ঘোলা পানিতে আগে ময়লা সরান, তারপর ফুটান; এই ক্রমটাই নিরাপদ।"]','[{"label": "CDC", "url": "https://www.cdc.gov/water-emergency/about"}, {"label": "WHO", "url": "https://www.who.int/publications/i/item/WHO-FWC-WSH-15.02"}]','[{"src": "/media/rohosser-dwip/270111-02-settle-muddy-water-then-boil-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ২: পানি আছে, খাওয়ার পানি নেই, কার্ড 1"}, {"src": "/media/rohosser-dwip/270111-02-settle-muddy-water-then-boil-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ২: পানি আছে, খাওয়ার পানি নেই, কার্ড 2"}]','["Sufe, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Bankside_of_Padma_River_Bangladesh.jpg", "Sidheeq, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Clay_water_pot.jpg"]','nature','leaf','teal',1,'2027-01-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270118-03-olympic-flame-lit-by-sunlight','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৩: আগুন','অলিম্পিকের শিখা আজও অলিম্পিয়ায় সূর্যের আলো আর অবতল আয়না দিয়ে জ্বালানো হয় (AP)।','["রাত নামার আগে আগুন চাই। শুভ ভেজা কাঠ জড়ো করে বসে আছে, কিন্তু দেশলাই নেই।\\nনীলা চুপ করে আকাশের দিকে তাকিয়ে রইল। হঠাৎ তার মনে পড়ল অলিম্পিকের শিখার কথা। সেই শিখা নাকি আজও জ্বালানো হয় সূর্যের আলোয়, একটা বাঁকা আয়নায় আলো জড়ো করে।\\n\\"আলো এক জায়গায় জড়ো হলে তাপও জড়ো হয়,\\" সে বলল।\\nআরিফ বিশ্বাস করল না। \\"আকাশ তো আবার মেঘলা হয়ে আসছে!\\"\\nনীলা হাসল। \\"তাই তো সময় খুব কম।\\"", "বিজ্ঞান: আলো এক জায়গায় জড়ো হলে তাপও জড়ো হয়, তাই রোদ ছাড়া এই আগুন জ্বলে না।"]','[{"label": "AP via WCPO", "url": ""}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Olympic_flame"}]','[{"src": "/media/rohosser-dwip/270118-03-olympic-flame-lit-by-sunlight-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৩: আগুন, কার্ড 1"}, {"src": "/media/rohosser-dwip/270118-03-olympic-flame-lit-by-sunlight-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৩: আগুন, কার্ড 2"}]','["dronepicr, CC BY 2.0, https://commons.wikimedia.org/wiki/File:The_Olympic_Flame_lighting_ceremony_will_take_place_at_Ancient_Olympia_(51224127695).jpg", "Rosso Robot, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:2010_Summer_Youth_Olympics_torch_ignition_ceremony-olympic_torch_ignition.jpg"]','nature','leaf','teal',1,'2027-01-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270125-04-shadow-tip-shows-west','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৪: উত্তর কোন দিকে?','কাঠির ছায়ার ডগায় দাগ দিয়ে ১৫ মিনিট অপেক্ষা করলে প্রথম দাগের দিকটা পশ্চিম। সূর্যঘড়ির কাঁটাকে বলে গনোমন; খাড়া কাঠিও একই কাজ করে (The Old Farmer''s Almanac, Le Cadranier)।','["\\"আমরা উত্তর দিকে যাব,\\" আরিফ জোর দিয়ে বলল। \\"কিন্তু উত্তর কোন দিকে?\\" নীলা জানতে চাইল।\\nআরিফ আকাশের দিকে তাকাল। সূর্য ঢলে পড়ছে, কিন্তু কোথায়, সে নিশ্চিত নয়।\\nনীলা বালিতে একটা সোজা কাঠি পুঁতল। ছায়ার ডগায় রাখল একটা শামুকের খোল। তারপর সবাইকে বলল, \\"পনেরো মিনিট চুপচাপ বসো।\\"\\nছায়াটা ধীরে ধীরে সরে গেল। নীলা নতুন ডগায় আরেকটা খোল রাখল। \\"প্রথমটা পশ্চিম। আমরা এতক্ষণ উল্টো দিকে যাচ্ছিলাম।\\"\\nতুলি তখন ফিসফিস করে বলল, \\"নীলাপু, ওই দেখো... বালিতে কীসের দাগ?\\"", "বিজ্ঞান: এই পদ্ধতি মোটামুটি ঠিক; মার্চ আর সেপ্টেম্বরে সবচেয়ে নির্ভুল।"]','[{"label": "The Old Farmer''s Almanac", "url": "https://lecadranier.com/en/finding-the-north-without-a-compass-2-5-with-a-stick-and-30-minutes/"}, {"label": "Le Cadranier", "url": "https://lecadranier.com/en/finding-the-north-without-a-compass-2-5-with-a-stick-and-30-minutes/"}]','[{"src": "/media/rohosser-dwip/270125-04-shadow-tip-shows-west-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৪: উত্তর কোন দিকে?, কার্ড 1"}, {"src": "/media/rohosser-dwip/270125-04-shadow-tip-shows-west-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৪: উত্তর কোন দিকে?, কার্ড 2"}]','["Charlie from UK, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Sundial_(that_seemed_to_be_in_shadow_even_on_a_sunny_day!)_(7434806728).jpg", "Basile Morin, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sundial_Garden_in_Singapore_Botanic_Gardens.jpg"]','nature','leaf','teal',1,'2027-01-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270201-05-pugmarks-versus-camera-traps','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৫: বালিতে অচেনা পায়ের ছাপ','২০০৪ সালে সুন্দরবনে পায়ের ছাপ গুনে ৪৪০টি বাঘ ধরা হয়েছিল; ২০২৪-এর ক্যামেরা-জরিপে মিলেছে অন্তত ১২৫টি প্রাপ্তবয়স্ক বাঘ (Mongabay, Gulf Times)।','["বালির ওপর ছাপের সারি। প্রতিটা ছাপ গভীর, আর সামনের দিকটা চওড়া।\\n\\"বাঘ!\\" আরিফ চিৎকার করে উঠল।\\nনীলা মাথা নাড়ল। \\"না। বাঘের থাবার ছাপে আঙুলের দাগ আলাদা থাকে। এটা জুতার ছাপ, কেউ ভারী বোঝা নিয়ে হেঁটেছে। দেখো, গোড়ালির দিকটা বেশি গভীর।\\"\\nশুভ ঢোক গিলল। \\"তার মানে এই দ্বীপে আমরা একা নই।\\"\\nতুলি ছাপের পাশে একটা কাগজের টুকরো কুড়িয়ে পেল। তাতে লেখা কয়েকটা সংখ্যা।", "বিজ্ঞান: ছাপ অনেক কিছু বলে, কিন্তু একা ছাপ দিয়ে গুনলে ভুল হতে পারে।"]','[{"label": "Mongabay", "url": "https://news.mongabay.com/2024/10/tiger-population-census-in-bangladesh-shows-a-hopeful-upward-trend-in-the-sundarbans/"}, {"label": "Gulf Times", "url": "https://www.gulf-times.com/story/448055/bangladesh-concludes-tiger-census"}]','[{"src": "/media/rohosser-dwip/270201-05-pugmarks-versus-camera-traps-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৫: বালিতে অচেনা পায়ের ছাপ, কার্ড 1"}, {"src": "/media/rohosser-dwip/270201-05-pugmarks-versus-camera-traps-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৫: বালিতে অচেনা পায়ের ছাপ, কার্ড 2"}]','["Maitra, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sunderbans_Pugmarks,_West_Bengal,_India.tif", "Jayne Stockdale, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Royal_Bengal_Tiger_in_Sundarbans_National_Park.jpg"]','nature','leaf','teal',1,'2027-02-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270208-06-glowing-plankton','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৬: রাতের আলো','ডাইনোফ্ল্যাজেলেট নামের অণুজীবের কোষে ধাক্কা লাগলে নীল-সবুজ আলো ঝলকে ওঠে (MBARI, UT Marine Science)।','["রাত নেমেছে। চাঁদ নেই, আকাশে শুধু তারা। শুভ পানির ধারে বসে ছিল। হঠাৎ সে চমকে উঠল।\\n\\"নীলাপু! পানিতে আগুন!\\"\\nনীলা ছুটে এল। শুভর ছোঁয়া জায়গায় নীলচে সবুজ আলো ঝিলিক দিয়ে মিলিয়ে গেল। আরিফ লাঠি দিয়ে পানি নাড়ল। আরও আলো জ্বলে উঠল, যেন কেউ তারার গুঁড়ো ছড়িয়ে দিয়েছে।\\n\\"ভয় পেয়ো না,\\" নীলা হাসল। \\"এগুলো খুব ছোট প্রাণ। ধাক্কা খেলেই আলো দেয়।\\"\\nতুলি অবাক হয়ে বলল, \\"তাহলে ওরাই আমাদের রাতের বাতি।\\"", "বিজ্ঞান: আলো আসে প্রাণের ভেতর থেকেই; ধাক্কা লাগলেই সেই আলো জ্বলে ওঠে।"]','[{"label": "MBARI", "url": "https://www.mbari.org/?p=86876"}, {"label": "UT Marine Science Institute", "url": "https://utmsi.utexas.edu/?p=5006"}]','[{"src": "/media/rohosser-dwip/270208-06-glowing-plankton-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৬: রাতের আলো, কার্ড 1"}, {"src": "/media/rohosser-dwip/270208-06-glowing-plankton-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৬: রাতের আলো, কার্ড 2"}]','["catalano82, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Dinoflagellate_lumincescence.jpg", "Mike, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Dinoflagellate_bioluminescence_3.jpg"]','nature','leaf','teal',1,'2027-02-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270215-07-tides-twice-a-day','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৭: জোয়ার','জোয়ার-ভাটার এক চক্র ২৪ ঘণ্টা ৫০ মিনিটের, আর বেশির ভাগ উপকূলে দিনে দুবার জোয়ার আর দুবার ভাটা হয় (NOAA)।','["সকালের বালির চর বিকেলে আর নেই। ঢেউ এসে পা ধুয়ে দিল।\\n\\"দ্বীপটা ছোট হয়ে যাচ্ছে!\\" শুভ আঁতকে উঠল।\\nনীলা শান্ত গলায় বলল, \\"না, জোয়ার এসেছে। চাঁদের টানে সাগরের পানি ফুলে ওঠে। ছয় ঘণ্টা পর আবার নামবে।\\"\\nআরিফ হাতের ঘড়ি দেখল। \\"সকালে যখন ভাটা ছিল, তখন সময় ছিল আটটা। তাহলে পরের জোয়ার কখন?\\"\\nনীলা বালিতে দাগ কেটে হিসাব করল। \\"আমরা এখানে থাকলে রাতেই সব ডুবে যাবে। উঁচু জায়গা খুঁজতে হবে।\\"", "বিজ্ঞান: সূর্যের চেয়ে চাঁদের টান দ্বিগুণেরও বেশি, তাই জোয়ার-ভাটার ঘড়ি চাঁদের।"]','[{"label": "NOAA NESDIS / SciJinks", "url": "https://www.nesdis.noaa.gov/about/k-12-education/oceans-coasts/what-causes-tides"}, {"label": "NOAA National Weather Service JetStream", "url": "https://www.nesdis.noaa.gov/about/k-12-education/oceans-coasts/what-causes-tides"}]','[{"src": "/media/rohosser-dwip/270215-07-tides-twice-a-day-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৭: জোয়ার, কার্ড 1"}, {"src": "/media/rohosser-dwip/270215-07-tides-twice-a-day-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৭: জোয়ার, কার্ড 2"}]','["Md Faysal Ahmed, CC0, https://commons.wikimedia.org/wiki/File:Cox%27s_Bazar_beach_(3991311).jpg", "Tanweer Morshed, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Cox%27s_Bazar_sea_beach_01.jpg"]','nature','leaf','teal',1,'2027-02-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270222-08-mirror-flash-295-km','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৮: সংকেত','১৮৯৪ সালে ৮ ইঞ্চি আয়নার হেলিওগ্রাফে ১৮৩ মাইল (২৯৫ কিমি) দূরে সংকেত পাঠানো হয়েছিল (Wikipedia)।','["সন্ধ্যার আগে দিগন্তে একটা ছোট্ট নৌকা দেখা গেল। আরিফ লাফিয়ে উঠল, \\"ওদের ডাকো!\\"\\n\\"চিৎকারে কাজ হবে না,\\" নীলা বলল। শুভর ব্যাগ থেকে সে ছোট একটা আয়না বের করল। \\"আলো সোজা পথে চলে। আয়নায় সূর্যের আলো ধরে ওদের দিকে ফেললে ঝলকটা অনেক দূর যায়।\\"\\nসে আয়নাটা একটু কাত করল, একবার, দুবার, তিনবার। আলোর ঝিলিক ঢেউয়ের ওপর দিয়ে ছুটে গেল।\\nনৌকাটা থামল না। তুলি হতাশ হয়ে বলল, \\"ওরা কি দেখতে পায়নি?\\"", "বিজ্ঞান: আলো সোজা পথে চলে, তাই আয়না ঠিক দিকে ধরলে ঝলক অনেক দূরে পৌঁছায়।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Heliograph"}, {"label": "Royal Signals Museum datasheet", "url": "https://royal-signals.org.uk/Datasheets/Heliograph.php"}]','[{"src": "/media/rohosser-dwip/270222-08-mirror-flash-295-km-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৮: সংকেত, কার্ড 1"}, {"src": "/media/rohosser-dwip/270222-08-mirror-flash-295-km-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৮: সংকেত, কার্ড 2"}]','["Hp.Baumeler, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Heliograph,_Museum_Swakopmund.jpg", "The Flickr user named signalmi, CC0, https://commons.wikimedia.org/wiki/File:Signaling_Mirror_B-1_USAF_Spec_41063.jpg"]','nature','leaf','teal',1,'2027-02-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270301-09-godwit-flies-eight-days-nonstop','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ৯: পাখির খাতা','স্যাটেলাইটে ট্র্যাক করা একটা গডউইট পাখি ৮ দিনেরও বেশি, ৭,২০০ মাইল না থেমে উড়েছিল (ScienceDaily, USGS)।','["তুলির পাওয়া খাতাটা ভিজে, কিন্তু পাতাগুলো পড়া যাচ্ছে। প্রতি পাতায় তারিখ, পাখির নাম আর সংখ্যা।\\n\\"এগুলো পাখি গোনার হিসাব,\\" নীলা বলল। \\"যে এটা লিখেছে, সে পরিযায়ী পাখির পেছনে ঘুরছে।\\"\\nশুভ জিজ্ঞেস করল, \\"পাখিরা কতদূর যায়?\\"\\nনীলা খাতার একটা পাতা খুলে দেখাল। \\"কেউ কেউ হাজার হাজার কিলোমিটার, বিশ্রাম ছাড়াই। একটা পাখি নাকি আট দিন ধরে একটানা উড়েছিল।\\"\\nআরিফ উঁচু গলায় বলল, \\"এই দ্বীপে কেউ পাখি গুনতে এসেছিল। সে কোথায়?\\"", "বিজ্ঞান: ছোট পাখির শরীরেও লুকিয়ে আছে অবিশ্বাস্য সহ্যশক্তি আর পথের জ্ঞান।"]','[{"label": "ScienceDaily", "url": "https://sciencedaily.com/releases/2007/09/070915131205.htm"}, {"label": "USGS", "url": "https://www.usgs.gov/publications/crossing-ultimate-ecological-barrier-evidence-11000-km-long-non-stop-flight-alaska-new"}]','[{"src": "/media/rohosser-dwip/270301-09-godwit-flies-eight-days-nonstop-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৯: পাখির খাতা, কার্ড 1"}, {"src": "/media/rohosser-dwip/270301-09-godwit-flies-eight-days-nonstop-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ৯: পাখির খাতা, কার্ড 2"}]','["Pseudopanax at English Wikiped, Public domain, https://commons.wikimedia.org/wiki/File:Flock_of_bar-tailed_godwits_flying_past.jpg", "USFWSAlaska, Public domain, https://commons.wikimedia.org/wiki/File:Bar-tailed_godwits_(53706875977).jpg"]','nature','leaf','teal',1,'2027-03-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270308-10-pole-star-equals-latitude','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ১০: তারার মানচিত্র','উত্তর গোলার্ধে ধ্রুবতারা দিগন্তের যত ডিগ্রি ওপরে, সেটাই মোটামুটি পর্যবেক্ষকের অক্ষাংশ।','["আকাশ পরিষ্কার। হাজার তারা, আর সবগুলো ধীরে ধীরে ঘুরছে। শুধু একটা তারা প্রায় জায়গায় স্থির।\\n\\"ওটাই ধ্রুবতারা,\\" নীলা বলল। \\"সপ্তর্ষিমণ্ডল ধরে খুঁজে পেয়েছি। ওটা সবসময় উত্তরে থাকে।\\"\\nআরিফ হাত তুলে দিগন্ত থেকে তারাটার উচ্চতা মাপল। \\"আমার হাতের মুঠোর আড়াই মাপ। মানে কত?\\"\\n\\"মুঠো মোটামুটি দশ ডিগ্রি,\\" নীলা বলল। \\"তাহলে প্রায় ২৫ ডিগ্রি। বাংলাদেশের অক্ষাংশের কাছাকাছি।\\"\\nতুলি মুচকি হাসল। \\"তাহলে আমরা বাংলাদেশের কাছেই আছি!\\"", "বিজ্ঞান: একটা তারা দেখেই বোঝা যায়, পৃথিবীর কোন অক্ষাংশে আছেন।"]','[{"label": "Astro Navigation Demystified", "url": "https://astronavigationdemystified.com/latitude-from-polaris/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Polaris"}]','[{"src": "/media/rohosser-dwip/270308-10-pole-star-equals-latitude-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ১০: তারার মানচিত্র, কার্ড 1"}, {"src": "/media/rohosser-dwip/270308-10-pole-star-equals-latitude-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ১০: তারার মানচিত্র, কার্ড 2"}]','["International Gemini Observato, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Star_Trails_Above_Gemini_North_(iotw2506a).jpg", "Steve Ryan from Groveland, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Steve_Ryan_-_Stars_around_Polaris_-_Day_62_(by-sa).jpg"]','nature','leaf','teal',1,'2027-03-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270315-11-waterbird-census-in-january','rohosser-dwip','card','রহস্যের দ্বীপ, অধ্যায় ১১: খাতার মালিক','১৯৮৭ থেকে শুরু হওয়া এশীয় জলচর পাখি গণনায় ২৭টি দেশের ৬,১০০-র বেশি জলাভূমি গোনা হয়েছে (Wetlands International)।','["ঝোপের আড়াল থেকে একজন মানুষ বেরিয়ে এলেন। গলায় দূরবিন, হাতে নোটবই। \\"তোমরা তো আমার খাতাটা পেয়েছ,\\" তিনি হেসে বললেন।\\nশুভ এক পা পিছিয়ে গেল। আরিফ শক্ত গলায় জানতে চাইল, \\"আপনি কে?\\"\\n\\"আমি পাখি গুনি,\\" তিনি বললেন। \\"প্রতি বছর জানুয়ারিতে, এই দ্বীপে আর আরও অনেক জলাভূমিতে। পাখি বাড়ছে না কমছে, গুনলেই তো জানা যায়।\\"\\nনীলার মুখে হাসি ফুটল। \\"তার মানে ছাপগুলো আপনার?\\"\\nতিনি মাথা নাড়লেন। \\"আর শোনো, তোমাদের খোঁজে মানুষ বেরিয়েছে। আমার রেডিওতে খবর এসেছে।\\"", "বিজ্ঞান: বছরের পর বছর গুনলেই বোঝা যায়, কোন পাখি বাড়ছে আর কোনটা কমছে।"]','[{"label": "Wetlands International South Asia", "url": "https://south-asia.wetlands.org/?p=1516"}, {"label": "The Better India", "url": "https://www.thebetterindia.com/42193/bird-census-asian-waterbird-count/"}]','[{"src": "/media/rohosser-dwip/270315-11-waterbird-census-in-january-1.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ১১: খাতার মালিক, কার্ড 1"}, {"src": "/media/rohosser-dwip/270315-11-waterbird-census-in-january-2.webp", "width": 960, "height": 1200, "alt": "রহস্যের দ্বীপ, অধ্যায় ১১: খাতার মালিক, কার্ড 2"}]','["MamunSheikh121, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Asian_Openbill_Stork_(_Anastomus_oscitans)_in_Gazipur,_Bangladesh.jpg", "Charles J. Sharp, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Lesser_whistling_ducks_(Dendrocygna_javanica).jpg"]','nature','leaf','teal',1,'2027-03-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270103-01-dhaka-the-biggest-city-by-2050','dhaka-2100','card','২০৫০ সালে ঢাকা হতে পারে বিশ্বের সবচেয়ে বড় শহর','জাতিসংঘের প্রজেকশন: তখন মানুষ হবে ৫ কোটি ২১ লাখ','["▸ জাতিসংঘের ২০২৫ সালের হিসাবে ঢাকায় প্রায় ৩ কোটি ৬৬ লাখ মানুষ; বিশ্বে দ্বিতীয়, ২৫ বছর আগে নবম।\\n▸ প্রজেকশন বলছে ২০৫০ সালে ঢাকা হবে ৫ কোটি ২১ লাখ, আর জাকার্তা ৫ কোটি ১৮ লাখ।\\n▸ জাতিসংঘের সংজ্ঞায় শহর মানে অন্তত ৫০ হাজার মানুষের ঘনবসতির এলাকা।", "এক কথায়: ২০৫০-এর ঢাকা নিয়ে এটা জাতিসংঘের প্রজেকশন, ভবিষ্যদ্বাণী নয়।\\nআজ আমরা কী করতে পারি: পাড়ার একটা সমস্যা (নালা, ফুটপাথ) ছবি তুলে সিটি কর্পোরেশনকে জানান।"]','[{"label": "Dhaka Tribune", "url": "https://www.dhakatribune.com/bangladesh/bangladesh-environment/397420/dhaka-emerges-2nd-most-populous-city-in-the-world"}, {"label": "The Financial Express", "url": "https://www.dhakatribune.com/bangladesh/bangladesh-environment/397420/dhaka-emerges-2nd-most-populous-city-in-the-world"}, {"label": "UN News", "url": "https://www.dhakatribune.com/bangladesh/bangladesh-environment/397420/dhaka-emerges-2nd-most-populous-city-in-the-world"}]','[{"src": "/media/dhaka-2100/270103-01-dhaka-the-biggest-city-by-2050-1.webp", "width": 960, "height": 1200, "alt": "২০৫০ সালে ঢাকা হতে পারে বিশ্বের সবচেয়ে বড় শহর, কার্ড 1"}, {"src": "/media/dhaka-2100/270103-01-dhaka-the-biggest-city-by-2050-2.webp", "width": 960, "height": 1200, "alt": "২০৫০ সালে ঢাকা হতে পারে বিশ্বের সবচেয়ে বড় শহর, কার্ড 2"}]','["Tarunno, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Skyline_View_of_the_City_of_Dhaka_on_a_Cloudy_Day.jpg", "Jubair1985, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hatirjheel_Lake_Dhaka_Bangladesh.jpg"]','nature','drop','teal',1,'2027-01-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270110-02-metro-line-60000-passengers-an-hour','dhaka-2100','card','একটা মেট্রো লাইনে ঘণ্টায় ৬০ হাজার যাত্রী','এমআরটি লাইন-৬: ২০২২ সালে চালু, উত্তরা থেকে আগারগাঁও','["▸ লাইন-৬ যাত্রী নেওয়া শুরু করে ২০২২ সালের ২৯ ডিসেম্বর; প্রথম অংশ ১১.৭৩ কিলোমিটার, স্টেশন ৯টি।\\n▸ পুরো সক্ষমতায় ঘণ্টায় এক দিকে ৬০ হাজার যাত্রী বইতে পারবে; এখন রোজ ৩.৫ থেকে ৪ লাখ চড়ছেন।\\n▸ ২০১৫ সালের পরিবহন পরিকল্পনায় ২০৩৫ সালের মধ্যে ঢাকায় আরও মেট্রো লাইনের লক্ষ্য আছে।", "এক কথায়: মেট্রো-জাল পরিকল্পনা; লাইন-৬ আজকের প্রমাণ।\\nআজ আমরা কী করতে পারি: মেট্রো স্টেশনে দাঁড়ালে ভেবে দেখুন, একটা ট্রেন কত বাসের যাত্রী একসাথে নিচ্ছে।"]','[{"label": "UNB", "url": "https://unb.com.bd/category/bangladesh/dhaka-metro-rail-uttara-to-agargaon-route-a-detail-overview/107405"}, {"label": "The Daily Star", "url": "https://www.thedailystar.net/slow-reads/big-picture/news/dhakas-metro-rail-mass-transit-solution-or-missed-opportunity-4155146"}]','[{"src": "/media/dhaka-2100/270110-02-metro-line-60000-passengers-an-hour-1.webp", "width": 960, "height": 1200, "alt": "একটা মেট্রো লাইনে ঘণ্টায় ৬০ হাজার যাত্রী, কার্ড 1"}, {"src": "/media/dhaka-2100/270110-02-metro-line-60000-passengers-an-hour-2.webp", "width": 960, "height": 1200, "alt": "একটা মেট্রো লাইনে ঘণ্টায় ৬০ হাজার যাত্রী, কার্ড 2"}]','["Wasiul Bahar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Train_entering_at_Agargaon_metro_station_Platform.jpg", "Wasiul Bahar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Agargaon_metro_nameplate_at_Agargaon_metro_station_Platform.jpg"]','nature','drop','teal',1,'2027-01-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270117-03-sea-level-by-2100','dhaka-2100','card','২১০০ সালে সমুদ্র হতে পারে প্রায় ১ মিটার উঁচু','বেশি কার্বন ছাড়লে: আইপিসিসির প্রজেকশন, বিশ্বের গড়','["▸ আইপিসিসির ২০২১ প্রতিবেদন: কার্বন খুব কম ছাড়লে ২১০০ সালে সমুদ্র ০.২৮ থেকে ০.৫৫ মিটার বাড়ার সম্ভাবনাই বেশি।\\n▸ কার্বন খুব বেশি ছাড়লে সম্ভাব্য পরিসর ০.৬৩ থেকে ১.০১ মিটার; মাঝামাঝি পথে ০.৪৪ থেকে ০.৭৬।\\n▸ এটা বিশ্বের গড়; আর ২১০০ সালের পরও সমুদ্র কয়েক শতক ধরে বাড়তে থাকবে।", "এক কথায়: সমুদ্র কত বাড়বে, নির্ভর করে কার্বনের ওপর।\\nআজ আমরা কী করতে পারি: বাসায় ফ্যান, বাতি আর এসি কতক্ষণ চলে লিখে ফেলুন; কম বিদ্যুৎ মানে কম কার্বন।"]','[{"label": "Hong Kong Observatory", "url": ""}, {"label": "Carbon Brief", "url": "https://www.carbonbrief.org/in-depth-qa-the-ipccs-sixth-assessment-report-on-climate-science/"}]','[{"src": "/media/dhaka-2100/270117-03-sea-level-by-2100-1.webp", "width": 960, "height": 1200, "alt": "২১০০ সালে সমুদ্র হতে পারে প্রায় ১ মিটার উঁচু, কার্ড 1"}, {"src": "/media/dhaka-2100/270117-03-sea-level-by-2100-2.webp", "width": 960, "height": 1200, "alt": "২১০০ সালে সমুদ্র হতে পারে প্রায় ১ মিটার উঁচু, কার্ড 2"}]','["Helena Wright, CC BY 2.0, https://commons.wikimedia.org/wiki/File:River_erosion_in_Bangladesh_(15255986711).jpg", "Amdadphoto, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Boat_on_a_Tidal_River.jpg"]','nature','drop','teal',1,'2027-01-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270124-04-delta-plan-2100','dhaka-2100','card','একটা পরিকল্পনা চলবে ২১০০ সাল পর্যন্ত','বাংলাদেশ ব-দ্বীপ পরিকল্পনা ২১০০, ২০১৮ সালে অনুমোদিত','["▸ জাতীয় অর্থনৈতিক পরিষদ ২০১৮ সালে বদ্বীপ পরিকল্পনা অনুমোদন করে; বাস্তবায়ন চলবে ২১০০ সাল পর্যন্ত।\\n▸ প্রথম ধাপে ২০৩০ সালের মধ্যে ৮০টি প্রকল্প, খরচ ধরা হয়েছে ৩৭.৫ বিলিয়ন ডলার।\\n▸ দেশ ভাগ হয়েছে ছয় হটস্পটে: উপকূল, বরেন্দ্র, হাওর, পাহাড়, নদী-মোহনা আর নগর।", "এক কথায়: লক্ষ্য ২১০০ সাল; আজ চলছে প্রথম ধাপ।\\nআজ আমরা কী করতে পারি: আপনার জেলা কোন হটস্পটে পড়ে, ইউনিয়ন বা সিটি অফিস থেকে জেনে নিন।"]','[{"label": "bdnews24.com", "url": "https://bdnews24.com/economy/bangladesh-approves-delta-plan-2100-for-sustainable-water-management"}, {"label": "The Business Standard", "url": ""}]','[{"src": "/media/dhaka-2100/270124-04-delta-plan-2100-1.webp", "width": 960, "height": 1200, "alt": "একটা পরিকল্পনা চলবে ২১০০ সাল পর্যন্ত, কার্ড 1"}, {"src": "/media/dhaka-2100/270124-04-delta-plan-2100-2.webp", "width": 960, "height": 1200, "alt": "একটা পরিকল্পনা চলবে ২১০০ সাল পর্যন্ত, কার্ড 2"}]','["Pantho Reja bd, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Boats_are_on_Padma_river.jpg", "Rehana Sarker, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Meghna_River,_Cumilla,_Bangladesh_by_Rehana_Sarker.jpg"]','nature','drop','teal',1,'2027-01-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270207-06-padma-bridge-6-15-km','dhaka-2100','card','একটা সেতু বছরে জিডিপি ১% থেকে ১.৭% বাড়াতে পারে','পদ্মা সেতু: ৬.১৫ কিমি, ঢাকার সাথে ২১ জেলার যোগ','["▸ পদ্মা সেতু ৬.১৫ কিলোমিটার লম্বা, ৪১টি স্প্যান; উদ্বোধন ২০২২ সালের ২৫ জুন।\\n▸ ঢাকার সাথে ২১টি দক্ষিণ ও দক্ষিণ-পশ্চিম জেলার সড়ক যোগাযোগ হয়; ভ্রমণে ২-৩ ঘণ্টা কমার কথা।\\n▸ প্রজেকশন: সেতুর কারণে বছরে জাতীয় জিডিপি প্রায় ১ থেকে ১.৭% বাড়তে পারে।", "এক কথায়: সেতু চালু; জিডিপির বাড়তি অংশ এখনো প্রজেকশন।\\nআজ আমরা কী করতে পারি: আপনার রোজকার গন্তব্যে কোন পথে কত সময় লাগে লিখে রাখুন; পথ ছোট হলে কী বদলায় ভাবুন।"]','[{"label": "Asian Age", "url": "https://dailyasianage.com/news/312081/padma-bridge-new-face-of-bangladesh"}, {"label": "Dhaka Courier", "url": "https://dhakacourier.com.bd/news/Reportage/How-nations-get-built/5313"}, {"label": "inauguration Saturday 25 June", "url": ""}]','[{"src": "/media/dhaka-2100/270207-06-padma-bridge-6-15-km-1.webp", "width": 960, "height": 1200, "alt": "একটা সেতু বছরে জিডিপি ১% থেকে ১.৭% বাড়াতে পারে, কার্ড 1"}, {"src": "/media/dhaka-2100/270207-06-padma-bridge-6-15-km-2.webp", "width": 960, "height": 1200, "alt": "একটা সেতু বছরে জিডিপি ১% থেকে ১.৭% বাড়াতে পারে, কার্ড 2"}]','["Azim Khan Ronnie, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Padma_Bridge_03.jpg", "GucciNuzayer, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Padma_Bridge_Side_2.jpg"]','nature','drop','teal',1,'2027-02-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270214-07-rivers-are-living-persons','dhaka-2100','card','বাংলাদেশের নদী এখন আইনের চোখে জীবন্ত','২০১৯ সালে হাইকোর্টের রায়, তুরাগ থেকে শুরু','["▸ ২০১৯ সালের ৩০ জানুয়ারি হাইকোর্ট দখল ঠেকাতে তুরাগ নদীকে ''আইনি ব্যক্তি'' ঘোষণা করে।\\n▸ রায়ে বলা হয়, দেশের সব নদী একই মর্যাদা পাবে; জাতীয় নদী রক্ষা কমিশন হবে অভিভাবক।\\n▸ আদালত জানায়, দেশের প্রায় ৪৫০ নদীর বেশিরভাগই দখলকারীদের হাতে।", "এক কথায়: রায় আছে; নদী বাঁচানো এখন সবার কাজ।\\nআজ আমরা কী করতে পারি: আপনার এলাকার নদী বা খালের একটা ছবি তুলে রাখুন; দুই বছর পর তুলনা করবেন।"]','[{"label": "Dhaka Tribune", "url": "https://www.dhakatribune.com/bangladesh/court/167534/turag-given-%E2%80%98legal-person%E2%80%99-status-to-save-it-from"}, {"label": "UNB", "url": "https://unb.com.bd/category/Bangladesh/all-rivers-are-living-entities-hc/21789"}]','[{"src": "/media/dhaka-2100/270214-07-rivers-are-living-persons-1.webp", "width": 960, "height": 1200, "alt": "বাংলাদেশের নদী এখন আইনের চোখে জীবন্ত, কার্ড 1"}, {"src": "/media/dhaka-2100/270214-07-rivers-are-living-persons-2.webp", "width": 960, "height": 1200, "alt": "বাংলাদেশের নদী এখন আইনের চোখে জীবন্ত, কার্ড 2"}]','["Wonderlane, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Boats_and_people_on_the_Turag_River,_Dhaka,_Bangladesh.jpg", "Yahya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:A_passenger_boat_on_the_Buriganga_River_in_Dhaka.jpg"]','nature','drop','teal',1,'2027-02-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270221-08-heavier-monsoon-rain','dhaka-2100','card','প্রতি ১° গরমে চরম বৃষ্টি প্রায় ৭% বেশি','আইপিসিসির প্রজেকশন: দিনের চরম বৃষ্টি, বিশ্বের গড়','["▸ আইপিসিসি বলছে, পৃথিবী ১° গরম হলে দিনের চরম বৃষ্টি প্রায় ৭% বাড়ে।\\n▸ দক্ষিণ এশিয়ায় গ্রীষ্মকালীন বর্ষার বৃষ্টি বাড়ার প্রজেকশন আছে, তবে আস্থা মাঝারি।\\n▸ বাংলাদেশের জন্য প্রজেকশন: ভারী বৃষ্টিতে সমভূমিতে বন্যা বাড়তে পারে।", "এক কথায়: আস্থা মাঝারি, তাই তৈরি থাকাই বুদ্ধি।\\nআজ আমরা কী করতে পারি: বর্ষার আগে বাড়ির সামনের নালা বা ড্রেনে আবর্জনা জমেছে কি না, দেখে নিন।"]','[{"label": "The Business Standard", "url": "https://www.downtoearth.org.in/climate-change/what-the-new-ipcc-ar6-report-means-for-indian-cities-78425"}, {"label": "Down To Earth", "url": "https://www.downtoearth.org.in/climate-change/what-the-new-ipcc-ar6-report-means-for-indian-cities-78425"}]','[{"src": "/media/dhaka-2100/270221-08-heavier-monsoon-rain-1.webp", "width": 960, "height": 1200, "alt": "প্রতি ১° গরমে চরম বৃষ্টি প্রায় ৭% বেশি, কার্ড 1"}, {"src": "/media/dhaka-2100/270221-08-heavier-monsoon-rain-2.webp", "width": 960, "height": 1200, "alt": "প্রতি ১° গরমে চরম বৃষ্টি প্রায় ৭% বেশি, কার্ড 2"}]','["ASaber91, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Rain_in_Dhaka_(27925530974).jpg", "Aashaa, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Rain_filled_Dhaka_Street,2014.jpg"]','nature','drop','teal',1,'2027-02-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270228-09-purbachal-new-town','dhaka-2100','card','১০ লাখের শহরে থাকতে পারে প্রায় ২৭ লাখ মানুষ','পূর্বাচল নিউ টাউন: রাজউকের নকশা আর প্রজেকশন','["▸ রাজউক ১৯৯৫ সালে প্রকল্প শুরু করে; এলাকা প্রায় ৬,২২৭ একর, প্লট প্রায় ২৫ হাজার।\\n▸ নকশা ছিল ১০ লাখ মানুষের; ২০২১ সালে রাজউকের এক কর্মকর্তা বলেন, থাকবেন প্রায় ২৭ লাখ।\\n▸ মূল লক্ষ্য ছিল ২০১০ সালের জুন; মেয়াদ বারবার বেড়ে ২০২২ সাল পর্যন্ত গেছে।", "এক কথায়: নকশা ১০ লাখের, প্রজেকশন ২৭ লাখ।\\nআজ আমরা কী করতে পারি: নতুন শহরের নকশা দেখলে লক্ষ করুন: স্কুল, হাসপাতাল আর বাস কত দূরে রাখা হয়েছে।"]','[{"label": "The Daily Star", "url": "https://www.thedailystar.net/frontpage/news/extension-chaotic-capital-2107289"}, {"label": "The Financial Express", "url": "https://www.thedailystar.net/frontpage/news/extension-chaotic-capital-2107289"}]','[{"src": "/media/dhaka-2100/270228-09-purbachal-new-town-1.webp", "width": 960, "height": 1200, "alt": "১০ লাখের শহরে থাকতে পারে প্রায় ২৭ লাখ মানুষ, কার্ড 1"}, {"src": "/media/dhaka-2100/270228-09-purbachal-new-town-2.webp", "width": 960, "height": 1200, "alt": "১০ লাখের শহরে থাকতে পারে প্রায় ২৭ লাখ মানুষ, কার্ড 2"}]','["Salim_Khandoker, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Internal_roads_of_Purbachal_New_Town_.jpg", "Salim_Khandoker, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Joy_Bangla_Chattor,_Purbachal_(2).jpg"]','nature','drop','teal',1,'2027-02-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270307-10-floods-every-year','dhaka-2100','card','প্রতি বছর দেশের প্রায় ২০% ডোবে','স্বাভাবিক বন্যায়; বড় বন্যায় অর্ধেকেরও বেশি','["▸ গবেষণা বলে, স্বাভাবিক বছরে দেশের প্রায় ২০% এলাকা বন্যায় ডোবে।\\n▸ ইতিহাসের বড় বন্যাগুলোয় দেশের মোট এলাকার অর্ধেকেরও বেশি ডুবেছে।\\n▸ ২০২০ সালে প্রায় ৩০% এলাকা ডুবেছিল, যেখানে বদ্বীপ পরিকল্পনার লক্ষ্য ছিল ২৫%।", "এক কথায়: বন্যা আমাদের নিত্যসঙ্গী, তাই পরিকল্পনা জরুরি।\\nআজ আমরা কী করতে পারি: আপনার এলাকার সবচেয়ে উঁচু আশ্রয়কেন্দ্র বা স্কুল কোনটা, জেনে রাখুন।"]','[{"label": "Chowdhury", "url": ""}, {"label": "The Business Standard", "url": ""}]','[{"src": "/media/dhaka-2100/270307-10-floods-every-year-1.webp", "width": 960, "height": 1200, "alt": "প্রতি বছর দেশের প্রায় ২০% ডোবে, কার্ড 1"}, {"src": "/media/dhaka-2100/270307-10-floods-every-year-2.webp", "width": 960, "height": 1200, "alt": "প্রতি বছর দেশের প্রায় ২০% ডোবে, কার্ড 2"}]','["Nahid.rajbd, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Flood_in_bangladesh_2016.jpg", "Nahid.rajbd, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Flood_in_bangladesh_2016_4.jpg"]','nature','drop','teal',1,'2027-03-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270314-11-rooppur-2400-mw','dhaka-2100','card','রূপপুরের দুই চুল্লি দেবে ২৪০০ মেগাওয়াট','পরিকল্পনা: দেশের বিদ্যুতের আনুমানিক ১০-১২%','["▸ রূপপুর পারমাণবিক কেন্দ্রে দুটি VVER-১২০০ চুল্লি; প্রতিটি ১২০০ মেগাওয়াট, মোট ২৪০০।\\n▸ ২০২৬ সালের এপ্রিলে প্রথম ইউনিটে জ্বালানি ভরা শুরু হয়; পূর্ণ সক্ষমতা ধরা হয়েছে ২০২৭ সালে।\\n▸ কেন্দ্রটি দেশের বিদ্যুতের আনুমানিক ১০-১২% জোগান দেবে; খরচের প্রায় ৯০% রুশ ঋণ।", "এক কথায়: বিদ্যুৎ-পরিকল্পনার বড় ধাপ, ২০২৭-এ পূর্ণ সক্ষমতা ধরা।\\nআজ আমরা কী করতে পারি: বাসার মাসিক বিদ্যুৎ বিলের ইউনিট লিখে রাখুন; কোন যন্ত্র সবচেয়ে বেশি খায় ভাবুন।"]','[{"label": "Dhaka Tribune", "url": "https://www.dhakatribune.com/bangladesh/development/408906/bangladesh-enters-nuclear-era-with-rooppur-fuel"}, {"label": "The Business Standard", "url": ""}]','[{"src": "/media/dhaka-2100/270314-11-rooppur-2400-mw-1.webp", "width": 960, "height": 1200, "alt": "রূপপুরের দুই চুল্লি দেবে ২৪০০ মেগাওয়াট, কার্ড 1"}, {"src": "/media/dhaka-2100/270314-11-rooppur-2400-mw-2.webp", "width": 960, "height": 1200, "alt": "রূপপুরের দুই চুল্লি দেবে ২৪০০ মেগাওয়াট, কার্ড 2"}]','["Dean Calma / IAEA, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Rooppur_Nuclear_Power_Plant_2023.jpg", "মোঃ সাকিবুল হাসান, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Cooling_Tower_of_Rooppur_Nuclear_Power_Plant_(3).jpg"]','nature','drop','teal',1,'2027-03-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261203-experiment-01-floating-egg','ghore-boshe-biggan','card','ঘরে বসে বিজ্ঞান · পরীক্ষা #০১: ভাসমান ডিমের জাদু','একই ডিম, দুই গ্লাস পানি। একটায় ডিম ডুবে যায়, আরেকটায় দিব্যি ভেসে থাকে! লাগবে শুধু ডিম, পানি আর লবণ।','["ছবিগুলো সোয়াইপ করে ধাপগুলো দেখো, তারপর বাসায় বড়দের সাথে করে ফেলো।", "কেন হয়? লবণ গলে গেলে পানির ঘনত্ব বাড়ে। লবণ পানি ডিমের চেয়ে বেশি ঘন হয়ে গেলে ডিম ভেসে ওঠে।\\nতোমার ডিম কয় চামচ লবণে ভাসল?"]','[{"label": "Science News Explores", "url": "https://www.snexplores.org/article/experiment-salt-sea-egg-float"}, {"label": "Randolph College", "url": "https://tnst.go.randolphcollege.edu/?p=133"}]','[{"src": "/media/ghore-boshe-biggan/261203-experiment-01-floating-egg-1.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০১: ভাসমান ডিমের জাদু, কার্ড 1"}, {"src": "/media/ghore-boshe-biggan/261203-experiment-01-floating-egg-2.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০১: ভাসমান ডিমের জাদু, কার্ড 2"}]','[]','chemistry','flask','coral',1,'2026-12-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261210-experiment-02-running-pepper','ghore-boshe-biggan','card','ঘরে বসে বিজ্ঞান · পরীক্ষা #০২: সাবান দেখে পালায় গোলমরিচ!','এক বাটি পানি, একটু গোলমরিচের গুঁড়া আর এক ফোঁটা সাবান। আঙুল ছোঁয়াতেই সব গোলমরিচ এক দৌড়ে কিনারে!','["কেন? পানির ওপরের কণাগুলো একে অপরকে টেনে রাখে (পৃষ্ঠটান)। সাবান সেই টান কমিয়ে দেয়, আর চারপাশের পানি গোলমরিচকে টেনে নিয়ে যায়।", "বড়দের সাথে করে দেখো। দ্বিতীয়বার কি একই পানিতে কাজ করল?"]','[{"label": "Science News Explores", "url": "https://www.snexplores.org/article/experiment-salt-sea-egg-float"}, {"label": "Randolph College", "url": "https://tnst.go.randolphcollege.edu/?p=133"}]','[{"src": "/media/ghore-boshe-biggan/261210-experiment-02-running-pepper-1.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০২: সাবান দেখে পালায় গোলমরিচ!, কার্ড 1"}, {"src": "/media/ghore-boshe-biggan/261210-experiment-02-running-pepper-2.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০২: সাবান দেখে পালায় গোলমরিচ!, কার্ড 2"}]','[]','chemistry','flask','coral',1,'2026-12-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261217-experiment-03-walking-water','ghore-boshe-biggan','card','ঘরে বসে বিজ্ঞান · পরীক্ষা #০৩: পানি হাঁটে টিস্যু বেয়ে!','তিনটা গ্লাস, দুই রঙের পানি আর দুটো টিস্যু। এক-দুই ঘণ্টা পর দেখবে, খালি গ্লাসটা নিজে নিজেই ভরে উঠছে, তা-ও নতুন রঙে!','["কেন? টিস্যুর আঁশের সরু ফাঁকে পানি নিজের টানে ওপরে উঠে আসে। একে বলে কৈশিক ক্রিয়া।", "বড়দের সাথে করে দেখো। লাল আর হলুদ মিশে কোন রং হলো?"]','[{"label": "Science News Explores", "url": "https://www.snexplores.org/article/experiment-salt-sea-egg-float"}, {"label": "Randolph College", "url": "https://tnst.go.randolphcollege.edu/?p=133"}]','[{"src": "/media/ghore-boshe-biggan/261217-experiment-03-walking-water-1.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০৩: পানি হাঁটে টিস্যু বেয়ে!, কার্ড 1"}, {"src": "/media/ghore-boshe-biggan/261217-experiment-03-walking-water-2.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০৩: পানি হাঁটে টিস্যু বেয়ে!, কার্ড 2"}]','[]','chemistry','flask','coral',1,'2026-12-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261224-experiment-04-magic-comb','ghore-boshe-biggan','card','ঘরে বসে বিজ্ঞান · পরীক্ষা #০৪: চিরুনি দিয়ে কাগজ তোলা!','শুকনো চুলে কয়েকবার চিরুনি চালাও, তারপর কাগজের ছোট টুকরোর কাছে ধরো। টুকরোগুলো লাফিয়ে চিরুনিতে লেগে যাবে!','["কেন? ঘষা লেগে চিরুনিতে স্থির বিদ্যুৎ জমে, আর সেটা কাগজকে টেনে নেয়। শীতের শুকনো বাতাসে এই পরীক্ষা সবচেয়ে ভালো হয়, কারণ আর্দ্র বাতাসে চার্জ তাড়াতাড়ি হারিয়ে যায়।", "বড়দের সাথে করে দেখো। তোমার চিরুনি একবারে কয়টা টুকরো তুলল?"]','[{"label": "schoolphysics (UK)", "url": "https://schoolphysics.co.uk/age11-14/Electricity%20and%20magnetism/Electrostatics/text/Electrostatics_in_the_wet/index.html"}, {"label": "NZCER Assessment Resource Banks", "url": "https://arbs.nzcer.org.nz/resources/magic-comb"}]','[{"src": "/media/ghore-boshe-biggan/261224-experiment-04-magic-comb-1.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০৪: চিরুনি দিয়ে কাগজ তোলা!, কার্ড 1"}, {"src": "/media/ghore-boshe-biggan/261224-experiment-04-magic-comb-2.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০৪: চিরুনি দিয়ে কাগজ তোলা!, কার্ড 2"}]','[]','chemistry','flask','coral',1,'2026-12-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261231-experiment-05-oil-water-and-soap','ghore-boshe-biggan','card','ঘরে বসে বিজ্ঞান · পরীক্ষা #০৫: তেল-পানির ঝগড়া মেটাবে সাবান!','বয়ামে পানি আর তেল নিয়ে ঝাঁকাও: একটু পরেই আবার আলাদা। এবার কয়েক ফোঁটা সাবান দিয়ে ঝাঁকাও: মিশ্রণ ঘোলাটে হয়ে অনেকক্ষণ মিশে থাকে!','["কেন? সাবানের কণার এক মাথা পানি ভালোবাসে, অন্য মাথা তেল। ওরা তেলকে খুদে খুদে ফোঁটায় ভেঙে পানিতে ছড়িয়ে রাখে। থালাবাসন ধোয়ার রহস্যও এটাই।", "বড়দের সাথে করে দেখো। সাবান ছাড়া আর সাবানসহ, কোনটা কতক্ষণ মিশে থাকল?"]','[{"label": "Encyclopaedia Britannica", "url": "https://www.britannica.com/story/how-does-soap-work"}, {"label": "Popular Science", "url": "https://www.popsci.com/health/how-does-soap-keep-you-clean-a-chemist-explains-the-science-of-soap"}]','[{"src": "/media/ghore-boshe-biggan/261231-experiment-05-oil-water-and-soap-1.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০৫: তেল-পানির ঝগড়া মেটাবে সাবান!, কার্ড 1"}, {"src": "/media/ghore-boshe-biggan/261231-experiment-05-oil-water-and-soap-2.webp", "width": 960, "height": 1200, "alt": "ঘরে বসে বিজ্ঞান · পরীক্ষা #০৫: তেল-পানির ঝগড়া মেটাবে সাবান!, কার্ড 2"}]','[]','chemistry','flask','coral',1,'2026-12-31');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261204-number-01-206-bones','shorirer-bhetore','card','সংখ্যার ম্যাজিক: ২০৬','একজন প্রাপ্তবয়স্ক মানুষের শরীরে সাধারণত ২০৬টা হাড় থাকে। কিন্তু জন্মের সময় শিশুর থাকে প্রায় ৩০০টা হাড় আর তরুণাস্থির টুকরো!','["বড় হতে হতে এগুলোর অনেকগুলো জোড়া লেগে এক হয়ে যায়। মাথার খুলি, মেরুদণ্ডের নিচের অংশ, সবখানেই এমন হয়।", "তাহলে বলো তো, তোমার শরীরে কি এখনো সব হাড় জোড়া লাগা শেষ হয়েছে? (উত্তর: সম্ভবত না, কিছু হাড় কুড়ি বছরের পরেও জোড়া লাগে!)"]','[{"label": "Popular Science", "url": "https://www.popsci.com/story/health/bones-human-skeleton/"}, {"label": "Discover Magazine", "url": "https://www.discovermagazine.com/how-many-bones-are-in-the-human-body-and-other-fascinating-facts-about-45520"}]','[{"src": "/media/shorirer-bhetore/261204-number-01-206-bones-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ২০৬, কার্ড 1"}]','["Wellcome Collection (CC BY 4.0), Wikimedia Commons"]','body','heart','coral',1,'2026-12-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261206-zoom-01-your-hand','shorirer-bhetore','card','জুম করে দেখো: তোমার হাত','রোজ যে হাত দিয়ে লেখো, খাও, খেলো, তাতেই লুকিয়ে আছে দারুণ সব বিস্ময়:','["১. একটা হাতেই (কবজিসহ) ২৭টা হাড়।\\n২. আঙুলের ছাপ তৈরি হয় জন্মের আগেই, আর যমজ ভাইবোনের ছাপও আলাদা।\\n৩. হাতের নখ মাসে প্রায় সাড়ে ৩ মিলিমিটার বাড়ে, পায়ের নখের চেয়ে প্রায় দ্বিগুণ দ্রুত।", "নিজের আঙুলের ছাপটা একবার কাছ থেকে দেখো তো, কেমন নকশা: প্যাঁচানো, ঢেউ, নাকি ফাঁস?"]','[{"label": "StatPearls (NCBI Bookshelf)", "url": "https://ncbi.nlm.nih.gov/books/NBK547684"}, {"label": "Washington State Twin Registry", "url": "https://wstwinregistry.org/twin-faqs/identical-fingerprints/"}, {"label": "Harvard BioNumbers", "url": "https://bionumbers.hms.harvard.edu/bionumber.aspx?id=112380"}]','[{"src": "/media/shorirer-bhetore/261206-zoom-01-your-hand-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখো: তোমার হাত, কার্ড 1"}]','["Basile Morin (CC BY-SA 4.0), Wikimedia Commons"]','body','heart','coral',1,'2026-12-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270105-01-sneeze','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০১: হাঁচির সময় চোখ বন্ধ হয় কেন?','ইচ্ছা করে নয়: শরীর নিজেই সিদ্ধান্ত নেয়।','["১. নাকে ধুলো বা ঝাঁঝ ঢুকলেই স্নায়ু খবর পাঠায় মস্তিষ্কে।\\n২. সেখান থেকে একসাথে হুকুম যায় বুক, গলা, মুখ আর চোখের পাতার পেশিতে।\\n৩. জোরে বাতাস বেরিয়ে যায়, সাথে চোখও বন্ধ হয়। পুরোটাই রিফ্লেক্স।", "আসল কথা: হাঁচি একটি রিফ্লেক্স: আপনি ভাবার আগেই কাজ শেষ।\\nএখনই পরখ: চোখ খোলা রেখে হাঁচি দেওয়ার চেষ্টা করেছেন কখনো?"]','[{"label": "Wikipedia", "url": ""}, {"label": "How It Works", "url": ""}]','[{"src": "/media/shorirer-bhetore/270105-01-sneeze-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০১: হাঁচির সময় চোখ বন্ধ হয় কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270105-01-sneeze-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০১: হাঁচির সময় চোখ বন্ধ হয় কেন?, কার্ড 2"}]','["James Gathany, Public domain, https://commons.wikimedia.org/wiki/File:Sneeze.JPG"]','body','heart','coral',1,'2027-01-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270112-02-goose-bumps','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০২: শীতে গায়ে কাঁটা দেয় কেন?','প্রতিটি লোমের গোড়ায় আছে এক ক্ষুদে পেশি।','["১. লোমের গোড়ার ছোট্ট পেশির নাম অ্যারেক্টর পিলি।\\n২. ঠান্ডা লাগলে বা ভয় পেলে এই পেশি নিজে থেকেই টান দেয়, লোম খাড়া হয়।\\n৩. লোমশ প্রাণীর গায়ে খাড়া লোমের ফাঁকে বাতাস আটকে শরীর গরম থাকে।", "আসল কথা: আমাদের লোম কম, তাই শুধু কাঁটাই দেয়: পুরনো এক উষ্ণতার কৌশল।\\nএখনই পরখ: প্রিয় কোনো গান শুনেও কি গায়ে কাঁটা দেয়?"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Medical News Today", "url": "https://www.medicalnewstoday.com/articles/goosebumps-on-skin"}]','[{"src": "/media/shorirer-bhetore/270112-02-goose-bumps-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০২: শীতে গায়ে কাঁটা দেয় কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270112-02-goose-bumps-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০২: শীতে গায়ে কাঁটা দেয় কেন?, কার্ড 2"}]','["Ildar Sagdejev (Specious), CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:2003-09-17_Goose_bumps.jpg"]','body','heart','coral',1,'2027-01-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270119-03-onion-tears','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০৩: পেঁয়াজ কাটলে কান্না কেন?','ছুরির এক টানে ছড়িয়ে পড়ে এক অদৃশ্য ঝাঁঝ।','["১. কাটা পেঁয়াজের কোষ ভাঙলে একটি এনজাইম কাজ শুরু করে।\\n২. তৈরি হয় সালফারের এক উদ্বায়ী যৌগ, বাতাসে ভেসে চোখে পৌঁছায়।\\n৩. চোখ জ্বালা করে, আর চোখ পানি দিয়ে সেই ঝাঁঝ ধুয়ে ফেলতে চায়।", "আসল কথা: কান্না নয়, চোখের নিজের ধোয়ার ব্যবস্থা।\\nএখনই পরখ: ঠান্ডা পেঁয়াজ আর ধারালো ছুরিতে কি কম কাঁদেন?"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Discover Magazine", "url": "https://www.discovermagazine.com/why-do-onions-make-us-cry-3138"}]','[{"src": "/media/shorirer-bhetore/270119-03-onion-tears-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৩: পেঁয়াজ কাটলে কান্না কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270119-03-onion-tears-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৩: পেঁয়াজ কাটলে কান্না কেন?, কার্ড 2"}]','["Anniwinner, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cutting_onion_bulb.jpg", "Gaurav Dhwaj Khadka, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Onion_Chopped.jpg"]','body','heart','coral',1,'2027-01-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270126-04-chilli-heat','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০৪: মরিচে আগুন নেই, তবু জ্বলে কেন?','জিভের তাপ-সেন্সরকে বোকা বানায় মরিচ।','["১. মরিচের ঝালের কারণ ক্যাপসাইসিন নামের একটি যৌগ।\\n২. এটি জিভের সেই সেন্সর চালু করে, যা আসল তাপ টের পায় (TRPV1)।\\n৩. মস্তিষ্ক ভাবে মুখ পুড়ছে, অথচ তাপমাত্রা একটুও বাড়েনি।", "আসল কথা: এই তাপ-সেন্সর খুঁজে ২০২১ সালে নোবেল পেয়েছিলেন ডেভিড জুলিয়াস।\\nএখনই পরখ: পাখিরা মরিচের ঝাল টের পায় না: ওদের সেন্সর আলাদা।"]','[{"label": "Wikipedia", "url": ""}, {"label": "NobelPrize.org", "url": ""}]','[{"src": "/media/shorirer-bhetore/270126-04-chilli-heat-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৪: মরিচে আগুন নেই, তবু জ্বলে কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270126-04-chilli-heat-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৪: মরিচে আগুন নেই, তবু জ্বলে কেন?, কার্ড 2"}]','["ALAMIN, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Green_chili_pepper_on_plant_Bangladesh_2.jpg", "Jiafei Slay Queen, CC0, https://commons.wikimedia.org/wiki/File:Bird%27s_eye_chili.jpg"]','body','heart','coral',1,'2027-01-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270202-05-wrinkly-fingers','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০৫: পুকুরে নামলে আঙুল কুঁচকায় কেন?','পানি ঢুকে ফোলে না: হুকুম দেয় স্নায়ু।','["১. অনেকক্ষণ পানিতে থাকলে আঙুলের ডগার রক্তনালি সরু হয়ে যায়।\\n২. এই কাজটি নিয়ন্ত্রণ করে স্নায়ু; স্নায়ু ক্ষতিগ্রস্ত আঙুলে ভাঁজ পড়ে না।\\n৩. ২০১৩ সালের এক গবেষণায় কোঁচকানো আঙুলে ভেজা মার্বেল ধরা ১২% দ্রুত হয়েছে।", "আসল কথা: ভাঁজ হয়তো ভেজা দিনের টায়ারের খাঁজ: এটা এখনো গবেষণার বিষয়।\\nএখনই পরখ: গোসলের পর আঙুল আর পায়ের পাতা মিলিয়ে দেখুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Physics Today", "url": ""}]','[{"src": "/media/shorirer-bhetore/270202-05-wrinkly-fingers-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৫: পুকুরে নামলে আঙুল কুঁচকায় কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270202-05-wrinkly-fingers-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৫: পুকুরে নামলে আঙুল কুঁচকায় কেন?, কার্ড 2"}]','["Sebastian Wallroth, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Wrinkly_Fingers_001.JPG", "Lincanary, Public domain, https://commons.wikimedia.org/wiki/File:Adult_sole_showing_water_immersion_wrinkling.JPG"]','body','heart','coral',1,'2027-02-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270209-06-fingerprints','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০৬: জন্মের আগেই আঁকা আঙুলের ছাপ','মায়ের পেটেই তৈরি হয় আপনার স্বাক্ষর।','["১. গর্ভের প্রায় ১২-১৩তম সপ্তাহে আঙুলে রেখা গড়া শুরু হয়।\\n২. ১৪-১৫তম সপ্তাহের মধ্যে নকশা পাকা, থাকে সারাজীবন।\\n৩. অভিন্ন যমজের ছাপও খুব মেলে, কিন্তু হুবহু এক নয়।", "আসল কথা: জিন নকশা ঠিক করে, গর্ভের ছোট ছোট পার্থক্য দেয় শেষ টান।\\nএখনই পরখ: নিজের দশ আঙুলের ছাপও একরকম নয়: মিলিয়ে দেখুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Yale Scientific", "url": ""}]','[{"src": "/media/shorirer-bhetore/270209-06-fingerprints-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৬: জন্মের আগেই আঁকা আঙুলের ছাপ, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270209-06-fingerprints-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৬: জন্মের আগেই আঁকা আঙুলের ছাপ, কার্ড 2"}]','["Kevin Dooley, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Fingerprints_close-up.jpg"]','body','heart','coral',1,'2027-02-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270216-07-yawning','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০৭: হাই কেন ছোঁয়াচে?','এই লেখা পড়তে পড়তেই হাই আসছে কি?।','["১. অন্যকে হাই তুলতে দেখলেই অনেক সময় আমাদেরও হাই আসে।\\n২. এই ছোঁয়াচে হাই দেখা গেছে শিম্পাঞ্জি আর কুকুরের মধ্যেও।\\n৩. কেন ছোঁয়াচে, তা নিয়ে বিজ্ঞানীরা এখনো একমত নন।", "আসল কথা: হাইয়ের আসল কাজ কী, তা এখনো খোলা প্রশ্ন।\\nএখনই পরখ: ছবিটা দেখার পর ৩০ সেকেন্ডের মধ্যে হাই এসেছে?"]','[{"label": "Wikipedia", "url": ""}, {"label": "Scientific American blog", "url": ""}]','[{"src": "/media/shorirer-bhetore/270216-07-yawning-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৭: হাই কেন ছোঁয়াচে?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270216-07-yawning-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৭: হাই কেন ছোঁয়াচে?, কার্ড 2"}]','["Yathin S Krishnappa, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Panthera_leo_yawn_(Kgalagadi,_2012).jpg", "Martin Falbisoner, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Yawning_Infant,_August_2018.jpg"]','body','heart','coral',1,'2027-02-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270302-09-pins-and-needles','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ০৯: পায়ে ঝিঁঝিঁ ধরে কেন?','অনেকক্ষণ বসে থাকলে পা যেন ''ঘুমিয়ে'' পড়ে।','["১. একভাবে বসলে পায়ের স্নায়ুর ওপর চাপ পড়ে।\\n২. চাপে স্নায়ুর রক্ত সরবরাহ কমে, খবর পাঠানো থেমে যায়।\\n৩. চাপ সরলে রক্ত ফেরে, স্নায়ু আবার জাগে: তখনই সুই ফোটার অনুভূতি।", "আসল কথা: ঝিঁঝিঁ মানে স্নায়ু আবার কাজে ফিরছে।\\nএখনই পরখ: কনুইয়ের ''ফানি বোন'' আসলে হাড় নয়, একটি স্নায়ু।"]','[{"label": "Wikipedia", "url": ""}, {"label": "NHS", "url": ""}]','[{"src": "/media/shorirer-bhetore/270302-09-pins-and-needles-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৯: পায়ে ঝিঁঝিঁ ধরে কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270302-09-pins-and-needles-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ০৯: পায়ে ঝিঁঝিঁ ধরে কেন?, কার্ড 2"}]','["Pure male feet, CC0, https://commons.wikimedia.org/wiki/File:Soles_of_Bare_Feet.jpg"]','body','heart','coral',1,'2027-03-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270309-10-milk-teeth','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ১০: ২০টি দাঁত যায়, ৩২টি আসে','দুধদাঁত পড়ার পেছনে আছে নিচের নতুন দাঁত।','["১. শিশুর দুধদাঁত সাধারণত ২০টি: ওপরে ১০, নিচে ১০।\\n২. নিচ থেকে স্থায়ী দাঁত উঠতে থাকে, দুধদাঁত ধীরে ধীরে নড়ে যায়।\\n৩. বড়দের স্থায়ী দাঁত সাধারণত ৩২টি।", "আসল কথা: দুধদাঁতের মোলার জায়গা ছাড়ে প্রিমোলারকে।\\nএখনই পরখ: জিভ দিয়ে নিজের দাঁত গুনে দেখুন তো কয়টি?"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Dentalcare.com", "url": "https://www.dentalcare.com/en-us/ce-courses/ce651/primary-permanent-dentition-eruption-sequences"}]','[{"src": "/media/shorirer-bhetore/270309-10-milk-teeth-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ১০: ২০টি দাঁত যায়, ৩২টি আসে, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270309-10-milk-teeth-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ১০: ২০টি দাঁত যায়, ৩২টি আসে, কার্ড 2"}]','["danielkirsch, CC0, https://commons.wikimedia.org/wiki/File:Laugh-4558471.jpg"]','body','heart','coral',1,'2027-03-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270316-11-tickling','shorirer-bhetore','card','শরীরের ভেতরে, স্ক্যান ১১: নিজেকে কাতুকুতু দেওয়া যায় না কেন?','মস্তিষ্ক আগেই জানে আপনার আঙুল কোথায় যাবে।','["১. কাতুকুতুর জন্য দরকার একটু চমক।\\n২. নিজের হাত নড়ার আগেই মস্তিষ্ক তার অনুভূতির হিসাব করে রাখে।\\n৩. অনুভূতি প্রত্যাশামতো, চমক নেই, তাই হাসিও নেই।", "আসল কথা: প্রশ্নটা অ্যারিস্টটলও করেছিলেন, দুই হাজার বছরেরও বেশি আগে।\\nএখনই পরখ: এখনই নিজের পায়ের তালুতে কাতুকুতু দিয়ে দেখুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Yale Scientific", "url": "https://www.yalescientific.org/2015/05/why-cant-you-tickle-yourself/"}]','[{"src": "/media/shorirer-bhetore/270316-11-tickling-1.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ১১: নিজেকে কাতুকুতু দেওয়া যায় না কেন?, কার্ড 1"}, {"src": "/media/shorirer-bhetore/270316-11-tickling-2.webp", "width": 960, "height": 1200, "alt": "শরীরের ভেতরে, স্ক্যান ১১: নিজেকে কাতুকুতু দেওয়া যায় না কেন?, কার্ড 2"}]','["Kyle Flood from Victoria, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Tickle.jpg"]','body','heart','coral',1,'2027-03-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270106-01-which-line-is-longer','moner-khela','card','মনের খেলা, খেলা ০১: কোন দাগটা বড়?','ক না খ? স্কেল ধরার আগে চোখে বলুন।','["১. দুটো দাগই একদম সমান লম্বা। স্কেল ধরে মেপে দেখুন।\\n২. মাথার তীর ভেতরে না বাইরে, তা দেখে মগজ দৈর্ঘ্যের ভুল আন্দাজ করে।\\n৩. ১৮৮৯ সালে জার্মান সমাজবিজ্ঞানী ম্যুলার-লায়ার ধাঁধাটি প্রথম দেখান।", "চ্যালেঞ্জ: স্কেল না ধরে বলুন: ক বড়, না খ?", "মগজের কারসাজি: চোখ শুধু ছবি তোলে; মাপ বোঝে মগজ, আর আশপাশ দেখে সে ভুলও করে।\\nএখনই খেলুন: স্ক্রিনে স্কেল ধরে দুটো দাগ মাপুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "APA Dictionary of Psychology", "url": ""}]','[{"src": "/media/moner-khela/270106-01-which-line-is-longer-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০১: কোন দাগটা বড়?, কার্ড 1"}, {"src": "/media/moner-khela/270106-01-which-line-is-longer-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০১: কোন দাগটা বড়?, কার্ড 2"}]','["Scaredpoet, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Dixon-Ticonderoga-Assorted-Pencils.jpg"]','body','bulb','deep',1,'2027-01-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270113-02-say-the-colour','moner-khela','card','মনের খেলা, খেলা ০২: শব্দ নয়, রংটা বলুন!','জোরে জোরে কালির রং বলুন, লেখাটা নয়।','["১. পড়া আমাদের এত অভ্যাস যে শব্দ চোখে পড়লেই মগজ পড়ে ফেলে।\\n২. কালির রং বলতে গেলে সেই পড়াটা থামাতে হয়, তাই দেরি আর ভুল হয়।\\n৩. ১৯৩৫ সালে জন রিডলি স্ট্রুপ এটি প্রকাশ করেন: নাম স্ট্রুপ এফেক্ট।", "চ্যালেঞ্জ: ঘড়ি ধরে ৯টি শব্দের কালির রং বলুন।", "মগজের কারসাজি: পড়া চলে নিজে নিজে, রং বলা সচেতন কাজ: দুটোর লড়াইয়ে আপনি হোঁচট খান।\\nএখনই খেলুন: এবার শুধু শব্দগুলো পড়ুন, দেখুন কত সহজ!"]','[{"label": "Wikipedia", "url": ""}, {"label": "Simply Psychology", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270113-02-say-the-colour-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০২: শব্দ নয়, রংটা বলুন!, কার্ড 1"}, {"src": "/media/moner-khela/270113-02-say-the-colour-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০২: শব্দ নয়, রংটা বলুন!, কার্ড 2"}]','["Aaron Burden aaronburden, CC0, https://commons.wikimedia.org/wiki/File:Crayons_beside_child_coloring_(Unsplash).jpg"]','body','bulb','deep',1,'2027-01-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270120-03-smiling-potato','moner-khela','card','মনের খেলা, খেলা ০৩: আলুটা কি হাসছে?','মেঘে, দেয়ালে, আলুতে: মুখ দেখি কেন?।','["১. এলোমেলো দাগে চেনা ছবি দেখার ঝোঁকের নাম প্যারেইডোলিয়া।\\n২. সবচেয়ে বেশি দেখি মুখ: মেঘে, গাড়ির সামনে, জড় বস্তুতে।\\n৩. মুখ চেনার কাজ করে মগজের যে অংশ, সে বস্তুর গড়নেও ভুল করে মুখ পড়ে নেয়।", "চ্যালেঞ্জ: আলুর চোখ আর হাসি খুঁজে পেলেন?", "মগজের কারসাজি: শুধু মানুষ নয়, রিসাস বানরও জড় বস্তুতে মুখ দেখে!\\nএখনই খেলুন: চারপাশে তাকান: সুইচবোর্ড, বালতি, গাড়ি।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Psychology Today", "url": "https://www.psychologytoday.com/us/basics/pareidolia"}]','[{"src": "/media/moner-khela/270120-03-smiling-potato-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৩: আলুটা কি হাসছে?, কার্ড 1"}, {"src": "/media/moner-khela/270120-03-smiling-potato-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৩: আলুটা কি হাসছে?, কার্ড 2"}]','["Andy Mabbett, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Potato_pareidolia_(happy)_2025-04-04_-_Andy_Mabbett_-_01.jpg"]','body','bulb','deep',1,'2027-01-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270127-04-blind-spot','moner-khela','card','মনের খেলা, খেলা ০৪: চোখে এক ফাঁকা জায়গা!','লাল বিন্দুটা উধাও করে দিন।','["১. চোখের পর্দার যেখান থেকে স্নায়ু মগজে যায়, সেখানে আলো ধরার কোষ নেই।\\n২. তাই প্রতিটি চোখে একটি ছোট্ট অন্ধ বিন্দু থাকে।\\n৩. মগজ আশপাশের ছবি আর অন্য চোখের তথ্য দিয়ে ফাঁকটা ভরিয়ে দেয়।", "চ্যালেঞ্জ: বাঁ চোখ বুজে ✚ দেখুন, ফোন কাছে আনুন।", "মগজের কারসাজি: আপনি যা দেখেন, তার এক টুকরো আসলে মগজের নিজের আঁকা!\\nএখনই খেলুন: দূরত্ব বদলে দেখুন, কখন বিন্দু ফিরে আসে।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270127-04-blind-spot-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৪: চোখে এক ফাঁকা জায়গা!, কার্ড 1"}, {"src": "/media/moner-khela/270127-04-blind-spot-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৪: চোখে এক ফাঁকা জায়গা!, কার্ড 2"}]','["Qirille, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Human_eye_close_up_2.jpg"]','body','bulb','deep',1,'2027-01-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270203-05-tip-of-the-tongue','moner-khela','card','মনের খেলা, খেলা ০৫: জিভের ডগায় আছে, মনে আসছে না!','এই ফলের নাম কী? চট করে বলুন।','["১. শব্দটা জানি বলে টের পাই, কিন্তু মুখে আসে না: এর নাম টিপ অব দ্য টাং।\\n২. তখনো প্রায়ই প্রথম অক্ষর বা শব্দের ছন্দটা মনে পড়ে।\\n৩. সাধারণত একটু পরে শব্দটা নিজে থেকেই মনে চলে আসে।", "চ্যালেঞ্জ: কাটলে তারা, স্বাদে টক-মিষ্টি: কোন ফল?", "মগজের কারসাজি: স্মৃতি হারায়নি, শুধু খুঁজে আনার পথে একটু জট। উত্তর: কামরাঙা!\\nএখনই খেলুন: কামরাঙা শুনে কি ''আরে হ্যাঁ!'' বললেন?"]','[{"label": "Wikipedia", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270203-05-tip-of-the-tongue-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৫: জিভের ডগায় আছে, মনে আসছে না!, কার্ড 1"}, {"src": "/media/moner-khela/270203-05-tip-of-the-tongue-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৫: জিভের ডগায় আছে, মনে আসছে না!, কার্ড 2"}]','["Wilfredor, CC0, https://commons.wikimedia.org/wiki/File:Man_thinking_on_Recife.jpg"]','body','bulb','deep',1,'2027-02-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270210-06-own-name-in-a-crowd','moner-khela','card','মনের খেলা, খেলা ০৬: ভিড়েও নিজের নাম শুনি কীভাবে?','হাজার কথার মাঝে মগজের ছাঁকনি।','["১. অনেক কথার ভিড়ে একটি কণ্ঠে মন দিতে পারার নাম ককটেল পার্টি এফেক্ট।\\n২. বাকি কথা পুরো হারায় না: না-শোনা কথার মধ্যেও নিজের নাম ধরা পড়ে।\\n৩. ১৯৫৩ সালে বিজ্ঞানী কলিন চেরি এই সমস্যার নাম দেন।", "চ্যালেঞ্জ: এই ভিড়ে কেউ আপনার নাম ডাকলে?", "মগজের কারসাজি: মগজ চুপচাপ সবই শোনে, শুধু জরুরিটা আপনাকে জানায়।\\nএখনই খেলুন: টিভি চলার সময় কাউকে আস্তে আপনার নাম বলতে বলুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270210-06-own-name-in-a-crowd-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৬: ভিড়েও নিজের নাম শুনি কীভাবে?, কার্ড 1"}, {"src": "/media/moner-khela/270210-06-own-name-in-a-crowd-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৬: ভিড়েও নিজের নাম শুনি কীভাবে?, কার্ড 2"}]','["Derek Bridges, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Freret_Street_Festival_2013_Creole_String_Beans_crowd_1.jpg"]','body','bulb','deep',1,'2027-02-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270217-07-hands-up-with-the-group','moner-khela','card','মনের খেলা, খেলা ০৭: সবাই হাত তুললে আমিও তুলি কেন?','ভুল উত্তরেও দলের সাথে থাকার টান।','["১. মনোবিজ্ঞানী সলোমন অ্যাশের পরীক্ষায় প্রশ্ন ছিল সহজ: কোন দাগটা সমান?\\n২. ঘরের বাকিরা ছিল সাজানো লোক, তারা ইচ্ছা করে ভুল উত্তর দিত।\\n৩. সেই প্রশ্নগুলোর প্রায় এক-তৃতীয়াংশ উত্তরে মানুষ দলের ভুলটাই মেনে নিল।", "চ্যালেঞ্জ: আপনি নিশ্চিত নন: হাত তুলবেন?", "মগজের কারসাজি: একা থাকলে ভুল হতো ১%-এরও কম। দলের চাপ এতটাই জোরালো!\\nএখনই খেলুন: পরের মিটিংয়ে খেয়াল করুন, প্রথম হাতটা কে তোলে।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Simply Psychology", "url": ""}]','[{"src": "/media/moner-khela/270217-07-hands-up-with-the-group-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৭: সবাই হাত তুললে আমিও তুলি কেন?, কার্ড 1"}, {"src": "/media/moner-khela/270217-07-hands-up-with-the-group-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৭: সবাই হাত তুললে আমিও তুলি কেন?, কার্ড 2"}]','["Viktoria.sm2012, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Uchit_0.jpg"]','body','bulb','deep',1,'2027-02-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270224-08-word-loses-meaning','moner-khela','card','মনের খেলা, খেলা ০৮: কলা কলা কলা... মানে কী?','একই শব্দ বারবার বললে অর্থ হারায়!।','["১. একই শব্দ দ্রুত বারবার বললে কিছুক্ষণ তা অর্থহীন আওয়াজের মতো লাগে।\\n২. এর নাম সিমান্টিক স্যাটিয়েশন; নামটি আসে ১৯৬২ সালের এক গবেষণা থেকে।\\n৩. কেন হয়, এখনো পুরো বোঝা যায়নি; একটি ধারণা: বারবার একই কাজে মগজের সাড়া কমে।", "চ্যালেঞ্জ: জোরে ৩০ বার ''কলা'' বলুন, তারপর শুনুন।", "মগজের কারসাজি: অর্থটা হারায়নি, মগজ একটু হাঁপিয়ে গেছে; একটু পরেই ফিরবে।\\nএখনই খেলুন: নিজের নাম দিয়ে চেষ্টা করুন, ২০ বার!"]','[{"label": "Wikipedia", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270224-08-word-loses-meaning-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৮: কলা কলা কলা... মানে কী?, কার্ড 1"}, {"src": "/media/moner-khela/270224-08-word-loses-meaning-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৮: কলা কলা কলা... মানে কী?, কার্ড 2"}]','["Shixart1985, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Child_studies_and_writes_in_notebook_at_a_table_with_focus_and_concentration_in_a_bright_indoor_setting.jpg"]','body','bulb','deep',1,'2027-02-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270303-09-right-in-front-of-us','moner-khela','card','মনের খেলা, খেলা ০৯: চোখের সামনে ছিল, দেখলাম না!','এক কাজে মন দিলে বাকিটা উধাও।','["১. বিখ্যাত ''অদৃশ্য গরিলা'' পরীক্ষায় দর্শকদের বাস্কেটবলের পাস গুনতে বলা হয়।\\n২. মাঝখানে গরিলার পোশাকে একজন হেঁটে যান, অনেকেই তাঁকে খেয়ালই করেননি।\\n৩. মন এক জায়গায় আটকে থাকলে সামনের অপ্রত্যাশিত জিনিসও আমরা দেখি না।", "চ্যালেঞ্জ: না তাকিয়ে বলুন: পেছনে বেঞ্চ কয়টা?", "মগজের কারসাজি: চোখ সব দেখে, কিন্তু ''দেখা'' হয় সেখানেই, যেখানে মন।\\nএখনই খেলুন: ছবিটায় আবার তাকান, বেঞ্চগুলো গুনুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Simply Psychology", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270303-09-right-in-front-of-us-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৯: চোখের সামনে ছিল, দেখলাম না!, কার্ড 1"}, {"src": "/media/moner-khela/270303-09-right-in-front-of-us-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ০৯: চোখের সামনে ছিল, দেখলাম না!, কার্ড 2"}]','["Gkbediako, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:A_Ghanaian_Basketball_Coach_Passing_Drill.jpg"]','body','bulb','deep',1,'2027-03-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270310-10-which-circle-is-bigger','moner-khela','card','মনের খেলা, খেলা ১০: মাঝের কোন বৃত্তটা বড়?','বড়দের মাঝে ছোট, ছোটদের মাঝে বড়?।','["১. মাঝের দুটি কমলা রঙের বৃত্ত আসলে একদম সমান।\\n২. বড় বৃত্তে ঘেরা বৃত্তটা ছোট লাগে, ছোট বৃত্তে ঘেরাটা বড়।\\n৩. ১৮৯০-এর দশকে হেরমান এবিংহাউস এটি দেখান: নাম এবিংহাউস ইলিউশন।", "চ্যালেঞ্জ: ক না খ: কোনটার মাঝের বৃত্ত বড় লাগছে?", "মগজের কারসাজি: মগজ কোনো কিছুর মাপ বোঝে আশপাশের সাথে তুলনা করে।\\nএখনই খেলুন: আঙুল দিয়ে মাঝের দুটি বৃত্ত মেপে দেখুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "APA Dictionary", "url": ""}]','[{"src": "/media/moner-khela/270310-10-which-circle-is-bigger-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ১০: মাঝের কোন বৃত্তটা বড়?, কার্ড 1"}, {"src": "/media/moner-khela/270310-10-which-circle-is-bigger-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ১০: মাঝের কোন বৃত্তটা বড়?, কার্ড 2"}]','["Joe Ravi, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Mandarin_Oranges_(Citrus_Reticulata).jpg"]','body','bulb','deep',1,'2027-03-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270317-11-habit-in-21-days','moner-khela','card','মনের খেলা, খেলা ১১: ২১ দিনে অভ্যাস? আসলে কত?','ঘাসে রোজ হাঁটলে তবেই পথ তৈরি হয়।','["১. ''২১ দিনে অভ্যাস'' কথাটা জনপ্রিয়, কিন্তু গবেষণা তা বলে না।\\n২. একটি গবেষণায় নতুন অভ্যাস স্বয়ংক্রিয় হতে গড়ে লেগেছে ৬৬ দিন।\\n৩. মানুষ আর কাজভেদে সময় লেগেছে ১৮ থেকে ২৫৪ দিন।", "চ্যালেঞ্জ: যে অভ্যাসটা গড়তে চান, আজ প্রথম দিন।", "মগজের কারসাজি: ঘাসের পথের মতো: রোজ হাঁটলেই পথ স্পষ্ট হয়, দিন গুনে নয়।\\nএখনই খেলুন: একটা ছোট অভ্যাস বাছুন, রোজ একই সময়ে করুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Healthline", "url": ""}]','[{"src": "/media/moner-khela/270317-11-habit-in-21-days-1.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ১১: ২১ দিনে অভ্যাস? আসলে কত?, কার্ড 1"}, {"src": "/media/moner-khela/270317-11-habit-in-21-days-2.webp", "width": 960, "height": 1200, "alt": "মনের খেলা, খেলা ১১: ২১ দিনে অভ্যাস? আসলে কত?, কার্ড 2"}]','["Secretlondon, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Desire_line_June_2021.jpg"]','body','bulb','deep',1,'2027-03-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261213-zoom-02-barn-owl','pranir-duniya','card','জুম করে দেখো: লক্ষ্মীপেঁচা','রাতের নিঃশব্দ শিকারি লক্ষ্মীপেঁচার মাথাতেই আছে তিনটা দারুণ ‘যন্ত্র’:','["১. চোখ নলের মতো লম্বা, নড়াতে পারে না। তাই পেঁচা পুরো মাথা ঘোরায়, প্রায় ২৭০ ডিগ্রি পর্যন্ত।\\n২. এক কান আরেক কানের চেয়ে একটু উঁচুতে, তাই অন্ধকারেও শব্দের ঠিকানা নিখুঁত বোঝে।\\n৩. ডানার পালকের কিনারা খাঁজকাটা আর নরম, তাই ওড়ে প্রায় নিঃশব্দে।", "রাতে কখনো পেঁচার ডাক শুনেছ?"]','[{"label": "Live Science", "url": "https://www.livescience.com/26771-how-owls-rotate-heads.html"}, {"label": "Stanford Birds", "url": "https://web.stanford.edu/group/stanfordbirds/text/essays/How_Owls_Hunt.html"}, {"label": "Audubon", "url": "https://www.audubon.org/magazine/10-fun-facts-about-american-barn-owl"}]','[{"src": "/media/pranir-duniya/261213-zoom-02-barn-owl-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখো: লক্ষ্মীপেঁচা, কার্ড 1"}]','["Quejaytee (CC BY-SA 4.0), Wikimedia Commons"]','biology','paw','teal',1,'2026-12-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261218-number-03-peregrine-dive','pranir-duniya','card','সংখ্যার ম্যাজিক: ৩০০+','পেরিগ্রিন শাহিন (পেরিগ্রিন ফ্যালকন) পৃথিবীর সবচেয়ে দ্রুতগামী প্রাণী। উঁচু আকাশ থেকে শিকারের দিকে ডানা গুটিয়ে ঝাঁপ দেওয়ার সময় এর গতি ঘণ্টায় ৩০০ কিলোমিটার ছাড়িয়ে যায়, প্রায় ৩২০ কিলোমিটারের মতো!','["মজার ব্যাপার, এই শিকারি পাখি শীতকালে অতিথি হয়ে বাংলাদেশেও আসে, যদিও খুব কম দেখা যায়।", "তুমি কি কখনো আকাশে বাজপাখিকে শিকারের দিকে ঝাঁপ দিতে দেখেছ?"]','[{"label": "Cornell Lab of Ornithology, All About Bi", "url": "https://allaboutbirds.org/guide/Peregrine_Falcon"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Falcon"}]','[{"src": "/media/pranir-duniya/261218-number-03-peregrine-dive-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৩০০+, কার্ড 1"}]','["FlightEditor (CC BY-SA 4.0), Wikimedia Commons"]','biology','paw','teal',1,'2026-12-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270219-number-08-elephant-pregnancy','pranir-duniya','card','সংখ্যার ম্যাজিক: ২২ মাস','হাতি তার বাচ্চাকে পেটে রাখে প্রায় ২২ মাস, মানে প্রায় দুই বছর! স্মিথসোনিয়ান ন্যাশনাল জু-র হিসাবে এশিয়ান হাতির গর্ভকাল ২১.৫ থেকে ২২ মাস, যা স্থলের স্তন্যপায়ীদের মধ্যে সবচেয়ে বেশি।','["তুলনায় মানুষের ৯ মাস।"]','[{"label": "Smithsonian''s National Zoo", "url": "https://nationalzoo.si.edu/animals/asian-elephant"}, {"label": "Discover Magazine", "url": "https://www.discovermagazine.com/5-of-the-longest-gestation-periods-in-the-animal-kingdom-47315"}]','[{"src": "/media/pranir-duniya/270219-number-08-elephant-pregnancy-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ২২ মাস, কার্ড 1"}]','["Panchalmaulik01 (CC BY 4.0), Wikimedia Commons"]','biology','paw','teal',1,'2027-02-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270228-zoom-09-gecko-feet','pranir-duniya','card','জুম করে দেখুন: টিকটিকি/গেকোর পা','দেয়াল আর ছাদে টিকটিকি কীভাবে হাঁটে? ছবিতে ওর পায়ের নিচটা দেখুন:','["১. আঙুলের নিচে লাখ লাখ খুদে লোম, যাদের নাম সেটি। প্রতিটি আবার শাখা মেলে আরও সূক্ষ্ম ডগায় (স্প্যাচুলা) শেষ।\\n২. আঠা নেই! অণুদের মধ্যকার ক্ষীণ টান (ভ্যান ডার ওয়ালস বল) এই সূক্ষ্ম ডগাগুলোকে দেয়ালে আঁকড়ে ধরে রাখে।\\n৩. পা তোলার সময় ওরা আঙুল গুটিয়ে (পিলিং) আস্তে আস্তে ছাড়িয়ে নেয়, তাই আটকে যায় না।"]','[{"label": "PNAS (Autumn et al. 2002)", "url": ""}, {"label": "PNAS (Tian et al. 2006)", "url": ""}]','[{"src": "/media/pranir-duniya/270228-zoom-09-gecko-feet-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: টিকটিকি/গেকোর পা, কার্ড 1"}]','[]','biology','paw','teal',1,'2027-02-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270110-zoom-02-chameleon-eye','pranir-duniya','card','জুম করে দেখুন: গিরগিটির চোখ','গিরগিটির চোখ যেন দুটো ছোট্ট ঘুরন্ত টাওয়ার!','["১. দুই চোখ আলাদা আলাদা দিকে ঘুরতে পারে। শিকার ঠিক করলে দুই চোখ একসাথে সেদিকে তাক করে, যাতে জিভ ঠিক জায়গায় ছুটে যায়।\\n২. চোখের পাতা জোড়া লাগা, মাঝখানে শুধু একটা ছোট ফুটো, যেটা দিয়ে ও দেখে।\\n৩. ওদের বাইরের কান নেই। ডালের কাঁপুনি টের পেয়ে ওরা সংকেত বোঝে বলে জানা যায়।"]','[{"label": "PetMD", "url": "https://www.petmd.com/cat/general-health/cat-vision"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tapetum_lucidum"}, {"label": "All About Vision", "url": "https://www.allaboutvision.com/eye-care/pets-animals/cat-third-eyelid/"}]','[{"src": "/media/pranir-duniya/270110-zoom-02-chameleon-eye-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: গিরগিটির চোখ, কার্ড 1"}]','[]','biology','paw','teal',1,'2027-01-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270117-zoom-03-cat-eye','pranir-duniya','card','জুম করে দেখুন: বিড়ালের চোখ','বিড়ালের চোখ কাছ থেকে দেখেছেন কখনো?','["১. আলোর সাথে মণি ছোট-বড় হয়: উজ্জ্বল আলোয় সরু ফালি, অন্ধকারে প্রায় গোল হয়ে খুলে যায়।\\n২. রেটিনার পেছনে আয়নার মতো একটা স্তর আছে, নাম ট্যাপেটাম লুসিডাম। আলোকে সে আবার রেটিনার দিকে ফেরায়, তাই কম আলোতেও দেখতে সুবিধা, আর রাতে আলো পড়লে চোখ জ্বলে ওঠে।\\n৩. চোখের কোণে লুকানো একটা পাতলা তৃতীয় পাতা আছে, যা চোখ ভেজা রাখে আর বাড়তি সুরক্ষা দেয়।"]','[{"label": "PetMD", "url": "https://www.petmd.com/cat/general-health/cat-vision"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tapetum_lucidum"}, {"label": "All About Vision", "url": "https://www.allaboutvision.com/eye-care/pets-animals/cat-third-eyelid/"}]','[{"src": "/media/pranir-duniya/270117-zoom-03-cat-eye-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: বিড়ালের চোখ, কার্ড 1"}]','["Faris Algosaibi (CC BY 2.0), Wikimedia Commons"]','biology','paw','teal',1,'2027-01-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270122-number-04-giraffe-neck','pranir-duniya','card','সংখ্যার ম্যাজিক: ৭টা','পৃথিবীর সবচেয়ে লম্বা গলার প্রাণী জিরাফ, অথচ ওর গলায় হাড় (কশেরুকা) মাত্র ৭টা, ঠিক মানুষের মতো! প্রায় সব স্তন্যপায়ী প্রাণীরই তা-ই।','["তফাত হলো আকারে: জিরাফের এক-একটা কশেরুকা লম্বা হয়ে প্রায় ২৫ সেন্টিমিটারের মতো হয়।"]','[{"label": "Giraffe Conservation Foundation", "url": ""}, {"label": "PMC", "url": ""}]','[{"src": "/media/pranir-duniya/270122-number-04-giraffe-neck-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৭টা, কার্ড 1"}]','[]','biology','paw','teal',1,'2027-01-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270129-number-05-hummingbird-heart','pranir-duniya','card','সংখ্যার ম্যাজিক: ১,২০০ পর্যন্ত','হামিংবার্ড এত ছোট যে ওজন মাত্র কয়েক গ্রাম, আর ওড়ার সময় ডানা নাড়ে সেকেন্ডে কয়েক ডজন বার। ওই শক্তির জন্য ওদের হৃৎপিণ্ডও ছোটে ঝড়ের গতিতে: ওড়ার সময় ১,০০০ থেকে ১,২০০ বারের বেশিও; সবচেয়ে বেশি মাপা ১,২৬০ (ব্লু-থ্রোটেড)।','["তুলনায় বিশ্রামে আমাদের হৃদয় মিনিটে ৬০-১০০ বার ধুকপুক করে, মানে হামিংবার্ডের হৃদয় ১০ গুণেরও বেশি দ্রুত।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hummingbird"}]','[{"src": "/media/pranir-duniya/270129-number-05-hummingbird-heart-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ১,২০০ পর্যন্ত, কার্ড 1"}]','["Andy  Morffew (CC BY 2.0), Wikimedia Commons"]','biology','paw','teal',1,'2027-01-29');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270314-zoom-11-kingfisher','pranir-duniya','card','জুম করে দেখুন: মাছরাঙা','পুকুরপাড়ের ডালে বসে থাকা মাছরাঙার দুটো দারুণ রহস্য:','["১. ডুব দেওয়ার সময় একটা তৃতীয় চোখের পাতা ওদের চোখ ঢেকে রক্ষা করে।\\n২. ওর লম্বা, ছুঁচালো ঠোঁটের আদলে জাপানের বুলেট ট্রেন শিনকানসেনের নাক নতুন করে বানিয়ে সুড়ঙ্গে ঢোকার ‘গুম’ শব্দ কমানো হয়েছিল বলে জানা যায়।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nictitating_membrane"}, {"label": "UX Collective", "url": "https://uxdesign.cc/shinkansen-the-bullet-train-inspired-by-kingfishers-bf6173cc5eae?gi=4ecb6feefc7d"}, {"label": "A-Z Animals", "url": "https://a-z-animals.com/blog/kingfisher-saved-rattled-homes-from-japans-bullet-train/"}]','[{"src": "/media/pranir-duniya/270314-zoom-11-kingfisher-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: মাছরাঙা, কার্ড 1"}]','["Luiz Lapa (CC BY 2.0), Wikimedia Commons"]','biology','paw','teal',1,'2027-03-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270321-zoom-12-peacock-feather','pranir-duniya','card','জুম করে দেখুন: ময়ূরের পালক','ময়ূরের পালকের ঝলমলে নীল-সবুজ রং আসলে রঙের গুঁড়ো নয়, গড়নের কারসাজি!','["১. রঙের বড় অংশ আসে পালকের খুদে গঠনে আলোর প্রতিফলন থেকে (বিজ্ঞানের ভাষায় ‘স্ট্রাকচারাল কালার’)।\\n২. পালকের উপরের স্তরে মেলানিনের সরু দণ্ড সাজানো আছে জালির মতো, যা আলোর বিশেষ রংকে ফিরিয়ে দেয়।\\n৩. দণ্ডগুলোর ব্যবধান বদলালে রংও বদলায়: অল্প তফাতেই নীল থেকে সবুজ। (কিছু জায়গায় রঞ্জকও ভূমিকা রাখে।)"]','[{"label": "PNAS (Zi et al. 2003)", "url": ""}, {"label": "HyperPhysics (Georgia State University)", "url": ""}]','[{"src": "/media/pranir-duniya/270321-zoom-12-peacock-feather-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: ময়ূরের পালক, কার্ড 1"}]','[]','biology','paw','teal',1,'2027-03-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270107-01-cat-lands-on-its-feet','pranir-duniya','card','পাড়ার কেন? ০১: বিড়াল প্রায় সবসময় পায়ে পড়ে কেন?','শূন্যে থাকতেই শরীর মুচড়ে নেয় বিড়াল।','["১. কানের ভেতরের ভারসাম্য-যন্ত্র আর চোখ দিয়ে আগে বোঝে কোনটা নিচে।\\n২. শরীর মাঝখান থেকে বাঁকিয়ে আগে সামনের অংশ, পরে পেছনের অংশ ঘোরায়।\\n৩. মেরুদণ্ড খুব নমনীয়, কাজের কলারবোন নেই: তাই এত মোচড় সম্ভব।", "এক কথায়: ভেতরের কান বলে কোনটা নিচে, নমনীয় শরীর করে বাকি কাজ।\\nমনে রাখুন: উঁচু থেকে পড়লে বিড়ালও ব্যথা পায়, সাবধান।"]','[{"label": "Wikipedia (Cat righting reflex); Wikipedia (Falling cat problem); Science ABC (Why do cats always land on their feet?); Nautilus", "url": ""}]','[{"src": "/media/pranir-duniya/270107-01-cat-lands-on-its-feet-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০১: বিড়াল প্রায় সবসময় পায়ে পড়ে কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270107-01-cat-lands-on-its-feet-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০১: বিড়াল প্রায় সবসময় পায়ে পড়ে কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-01-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270114-02-cow-chews-all-day','pranir-duniya','card','পাড়ার কেন? ০২: গরু সারাক্ষণ চিবায় কেন?','খাওয়া শেষ, তবু চোয়াল থামে না।','["১. ঘাস গিলে প্রথমে জমা রাখে পেটের বড় কুঠুরি রুমেনে।\\n২. সেখানে অগণিত জীবাণু ঘাসের শক্ত সেলুলোজ ভাঙে।\\n৩. আধভাঙা খাবার আবার মুখে ফিরিয়ে চিবায়: এরই নাম জাবর কাটা।", "এক কথায়: গরুর পাকস্থলীর চারটি কুঠুরি: ঘাস হজমের জীবন্ত কারখানা।\\nমাঠে খুঁজুন: বসে থাকা গরু খাওয়া ছাড়াই কতক্ষণ চিবায়, ঘড়ি ধরে দেখুন।"]','[{"label": "Wikipedia (Cud); Wikipedia (Ruminant); BackyardNature", "url": ""}, {"label": "Jim Conrad (Cow)", "url": ""}]','[{"src": "/media/pranir-duniya/270114-02-cow-chews-all-day-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০২: গরু সারাক্ষণ চিবায় কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270114-02-cow-chews-all-day-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০২: গরু সারাক্ষণ চিবায় কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-01-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270121-03-pigeon-head-bob','pranir-duniya','card','পাড়ার কেন? ০৩: কবুতর হাঁটলে মাথা দোলায় কেন?','আসলে মাথা দোলে না, ক্ষণিক স্থির থাকে।','["১. হাঁটার সময় শরীর এগোয়, কিন্তু মাথা এক মুহূর্ত শূন্যে স্থির থাকে।\\n২. শরীর এগিয়ে গেলে মাথা এক ঝটকায় সামনে এসে আবার থামে।\\n৩. থেমে থাকার মুহূর্তে চোখ পায় স্থির, পরিষ্কার ছবি।", "এক কথায়: থেমে থেমে দেখা: মাথা স্থির রেখেই দৃষ্টি স্থির রাখে কবুতর।\\nছাদে খুঁজুন: হাঁটন্ত কবুতরের মাথায় চোখ রাখুন: থামা-ঝটকার ছন্দ।"]','[{"label": "Birdorable (Head-bobbing explained); Troje et al. 2012", "url": ""}, {"label": "Frontiers conf. abstract; Wikipedia (Columbidae); Wikipedia (Bird vision)", "url": ""}]','[{"src": "/media/pranir-duniya/270121-03-pigeon-head-bob-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৩: কবুতর হাঁটলে মাথা দোলায় কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270121-03-pigeon-head-bob-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৩: কবুতর হাঁটলে মাথা দোলায় কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-01-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270128-04-dog-tail-wag','pranir-duniya','card','পাড়ার কেন? ০৪: লেজ নাড়া মানেই কি খুশি?','কুকুরের লেজ আসলে এক সংকেতের পতাকা।','["১. লেজ দিয়ে কুকুর নিজের মনের অবস্থা জানায়।\\n২. খুশি ছাড়াও উত্তেজনায় নাড়ে: লেজ নাড়া মানেই বন্ধুত্ব নয়।\\n৩. লেজের অবস্থানেও মানে বদলায়: পায়ের ফাঁকে গোঁজা লেজ মানে ভয়।", "এক কথায়: লেজের সাথে কান, চোখ আর শরীর মিলিয়ে পড়ুন কুকুরের মন।\\nনিরাপদে দেখুন: অচেনা কুকুরের লেজ নড়লেই কাছে যাবেন না।"]','[{"label": "PetMD (Why do dogs wag their tails?); Wikipedia (Dog communication)", "url": ""}]','[{"src": "/media/pranir-duniya/270128-04-dog-tail-wag-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৪: লেজ নাড়া মানেই কি খুশি?, কার্ড 1"}, {"src": "/media/pranir-duniya/270128-04-dog-tail-wag-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৪: লেজ নাড়া মানেই কি খুশি?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-01-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270204-05-duck-stays-dry','pranir-duniya','card','পাড়ার কেন? ০৫: হাঁস পানিতে নেমেও ভেজে না কেন?','লেজের গোড়ায় আছে নিজস্ব তেলের কৌটা।','["১. লেজের গোড়ার একটি গ্রন্থি (প্রিন গ্ল্যান্ড) তেল তৈরি করে।\\n২. ঠোঁটে সেই তেল তুলে পালকে পালকে মাখায়: একে বলে প্রিনিং।\\n৩. পরিষ্কার, সাজানো পালক পানি আটকায়, ভেতরটা থাকে শুকনো।", "এক কথায়: হাঁসের রোজকার সাজগোজই ওর রেইনকোট।\\nপুকুরে খুঁজুন: পানি থেকে উঠে হাঁস ঠোঁট লেজের দিকে নেয় কি না দেখুন।"]','[{"label": "KQED Science (What makes water roll off a duck''s back?); Wikipedia (Uropygial gland); Wikipedia (Preening)", "url": ""}]','[{"src": "/media/pranir-duniya/270204-05-duck-stays-dry-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৫: হাঁস পানিতে নেমেও ভেজে না কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270204-05-duck-stays-dry-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৫: হাঁস পানিতে নেমেও ভেজে না কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-02-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270211-06-goat-square-pupil','pranir-duniya','card','পাড়ার কেন? ০৬: ছাগলের চোখের মণি চারকোনা কেন?','ঘাস খেতে খেতেই চারদিকে নজর।','["১. ছাগল, ভেড়ার মণি খাড়া নয়, আড়াআড়ি লম্বা।\\n২. এতে চোখ দুপাশে অনেকখানি দেখে: শিকারি এলে আগেই ধরা পড়ে।\\n৩. মাথা নিচু করে ঘাস খেলেও চোখ ঘুরে মণিকে মাটির সমান্তরাল রাখে।", "এক কথায়: যারা শিকার হয়, তাদের মণি প্রায়ই আড়াআড়ি: চারপাশ দেখার যন্ত্র।\\nহাটে খুঁজুন: ছাগল মাথা নামালে মণিটা কি সোজা থাকে? দেখুন।"]','[{"label": "Banks et al. 2015", "url": ""}, {"label": "Science Advances (PMC4643806); UC Berkeley News (7 Aug 2015); Wikipedia (Pupil)", "url": ""}]','[{"src": "/media/pranir-duniya/270211-06-goat-square-pupil-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৬: ছাগলের চোখের মণি চারকোনা কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270211-06-goat-square-pupil-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৬: ছাগলের চোখের মণি চারকোনা কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-02-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270218-07-egret-follows-the-cow','pranir-duniya','card','পাড়ার কেন? ০৭: গরুর পিছে পিছে বক ঘোরে কেন?','রাখালি নয়, বকের নিজের লাভ।','["১. গরু হাঁটলে ঘাসের ভেতর থেকে পোকামাকড় লাফিয়ে ওঠে।\\n২. গো-বক ঠিক তখনই ঠোকর দিয়ে সেগুলো ধরে ফেলে।\\n৩. বড় প্রাণীর পাশে থাকলে অনেক বেশি পোকা ধরে।", "এক কথায়: গরু খায় ঘাস, বক খায় গরুর তাড়ানো পোকা: চমৎকার জুটি।\\nমাঠে খুঁজুন: চরতে থাকা গরুর পায়ের কাছে কটা বক, গুনে দেখুন।"]','[{"label": "Wikipedia (Western cattle egret); Animal Diversity Web (Bubulcus ibis); Audubon Field Guide (Cattle Egret)", "url": ""}]','[{"src": "/media/pranir-duniya/270218-07-egret-follows-the-cow-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৭: গরুর পিছে পিছে বক ঘোরে কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270218-07-egret-follows-the-cow-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৭: গরুর পিছে পিছে বক ঘোরে কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-02-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270225-08-gecko-drops-its-tail','pranir-duniya','card','পাড়ার কেন? ০৮: টিকটিকির লেজ খসে পড়ে কেন?','বিপদে লেজ ফেলে পালানোর কৌশল।','["১. শিকারি লেজ ধরলে টিকটিকি নিজেই লেজের একটা অংশ ছেড়ে দেয়।\\n২. খসে পড়া লেজ কিছুক্ষণ নড়তে থাকে, শিকারির নজর থাকে সেদিকে।\\n৩. এই ফাঁকে টিকটিকি পালায়; পরে নতুন লেজ গজাতে পারে।", "এক কথায়: লেজ হারিয়ে প্রাণ বাঁচানো: এর নাম অটোটমি।\\nদেয়ালে খুঁজুন: লেজের রং আলাদা? হয়তো সেটাই নতুন লেজ।"]','[{"label": "Wikipedia (Autotomy); CaliforniaHerps (Lizard tail loss)", "url": ""}]','[{"src": "/media/pranir-duniya/270225-08-gecko-drops-its-tail-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৮: টিকটিকির লেজ খসে পড়ে কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270225-08-gecko-drops-its-tail-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৮: টিকটিকির লেজ খসে পড়ে কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-02-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270304-09-dog-pants','pranir-duniya','card','পাড়ার কেন? ০৯: কুকুর জিভ বের করে হাঁপায় কেন?','আমাদের মতো ঘামতে পারে না কুকুর।','["১. লোমে ঢাকা শরীরে ঘামগ্রন্থি খুব কম, মূলত পায়ের তলায়।\\n২. তাই হাঁপিয়ে জিভ আর ফুসফুসের ভেজা অংশে বাতাস চালায়।\\n৩. পানি বাষ্প হয়ে উড়ে যায়, সাথে নিয়ে যায় শরীরের তাপ।", "এক কথায়: জিভটাই কুকুরের ফ্যান: হাঁপানো মানে শরীর ঠান্ডা করা।\\nগরমে খেয়াল: দুপুরে পাড়ার কুকুরের জন্য এক বাটি পানি রাখুন।"]','[{"label": "AKC (Do dogs sweat?); Wikipedia (Dog anatomy)", "url": ""}]','[{"src": "/media/pranir-duniya/270304-09-dog-pants-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৯: কুকুর জিভ বের করে হাঁপায় কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270304-09-dog-pants-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ০৯: কুকুর জিভ বের করে হাঁপায় কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-03-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270311-10-buffalo-mud-bath','pranir-duniya','card','পাড়ার কেন? ১০: মহিষ কাদায় গড়াগড়ি খায় কেন?','নোংরামি নয়, এটা মহিষের এসি।','["১. গরমে শরীর ঠান্ডা রাখতে মহিষের পানি বা কাদা লাগে।\\n২. কাদায় গড়ালে গায়ে পড়ে মোটা কাদার প্রলেপ।\\n৩. কাদা আর পানি গায়ের তাপ টেনে নিয়ে শরীর ঠান্ডা রাখে।", "এক কথায়: কাদা-স্নান মহিষের শরীর ঠান্ডা রাখার পুরোনো কৌশল।\\nগ্রামে খুঁজুন: দুপুরের রোদে মহিষ কোথায়: পানিতে না ছায়ায়?"]','[{"label": "Wikipedia (Water buffalo); Akshayakalpa Good Food Matters (Why buffalo wallow)", "url": ""}]','[{"src": "/media/pranir-duniya/270311-10-buffalo-mud-bath-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ১০: মহিষ কাদায় গড়াগড়ি খায় কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270311-10-buffalo-mud-bath-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ১০: মহিষ কাদায় গড়াগড়ি খায় কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-03-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270318-11-frog-throat-balloon','pranir-duniya','card','পাড়ার কেন? ১১: ব্যাঙের গলা বেলুনের মতো ফোলে কেন?','ছোট্ট শরীরে বিশাল আওয়াজের রহস্য।','["১. ডাকে মূলত পুরুষ ব্যাঙ, সঙ্গীকে কাছে ডাকতে।\\n২. ডাকের শব্দ তৈরি হয় স্বরযন্ত্রে, ঠিক আমাদের মতো।\\n৩. ফোলানো গলার থলি সেই আওয়াজ আরও জোরালো করে।", "এক কথায়: গলার থলিটাই ব্যাঙের মাইক আর স্পিকার।\\nবর্ষায় শুনুন: প্রথম বৃষ্টির রাতে কটা আলাদা সুর শোনেন, গুনুন।"]','[{"label": "Wikipedia (Vocal sac); Science News Explores (Frogs'' vocal sacs)", "url": ""}]','[{"src": "/media/pranir-duniya/270318-11-frog-throat-balloon-1.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ১১: ব্যাঙের গলা বেলুনের মতো ফোলে কেন?, কার্ড 1"}, {"src": "/media/pranir-duniya/270318-11-frog-throat-balloon-2.webp", "width": 960, "height": 1200, "alt": "পাড়ার কেন? ১১: ব্যাঙের গলা বেলুনের মতো ফোলে কেন?, কার্ড 2"}]','[]','biology','paw','teal',1,'2027-03-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261225-number-04-dragonfly-95-percent','pokar-shohor','card','সংখ্যার ম্যাজিক: ৯৫%','পুকুরপাড়ে উড়ে বেড়ানো ফড়িং আসলে দুর্দান্ত শিকারি। গবেষণায় দেখা গেছে, ফড়িং যত ছোট পোকাকে তাড়া করে, তার প্রায় ৯৫ ভাগ পর্যন্ত ধরে ফেলে। (বড় শিকার হলে সাফল্য একটু কম।)','["শিকার কোন দিকে যাবে, ফড়িং উড়তে উড়তেই তা আন্দাজ করে, আর মাঝপথে গিয়ে ধরে ফেলে।", "এরপর ফড়িং দেখলে একটু খেয়াল করে দেখো, কীভাবে হঠাৎ দিক বদলায়!"]','[{"label": "Combes et al. 2013, Integrative and Comp", "url": "https://academic.oup.com/icb/article/53/5/787/733390"}, {"label": "UC Davis", "url": "https://aggiehero.ucdavis.edu/blog/how-dragonflies-catch-prey-midair"}]','[{"src": "/media/pokar-shohor/261225-number-04-dragonfly-95-percent-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৯৫%, কার্ড 1"}]','["Leviathan (talk) (CC BY-SA 3.0), Wikimedia Commons"]','biology','butterfly','mint',1,'2026-12-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270207-zoom-06-honey-bee','pokar-shohor','card','জুম করে দেখুন: মৌমাছি','সরষে ফুলে বসা মৌমাছিকে কাছ থেকে দেখলে:','["১. মৌমাছির পাঁচটা চোখ: দুই পাশে দুটো বড় যৌগিক চোখ, আর মাথার ওপরে আলোর তীব্রতা বোঝার তিনটে ছোট চোখ।\\n২. ভাসার সময় ওরা সেকেন্ডে প্রায় ২৩০ বার ডানা নাড়ে। ওই দ্রুত ঝাপটাতেই তৈরি হয় চেনা গুনগুন শব্দ।\\n৩. পেছনের পায়ে আছে পরাগ জমানোর ঝুড়ির মতো খাঁজ, যেখানে ফুলের পরাগ চেপে বাসায় নিয়ে যায়।"]','[{"label": "Animal Corner", "url": ""}, {"label": "PNAS (Altshuler et al. 2005)", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/pokar-shohor/270207-zoom-06-honey-bee-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: মৌমাছি, কার্ড 1"}]','[]','biology','butterfly','mint',1,'2027-02-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270214-zoom-07-ant-face','pokar-shohor','card','জুম করে দেখুন: পিঁপড়ার মুখ','ছবির এই ছোট্ট মুখেই কত রহস্য!','["১. শুঁড় দিয়ে পিঁপড়ারা নিজেদের ছুঁয়ে খবর আদানপ্রদান করে। এমনকি একজন আরেকজনকে ছুঁয়ে ছুঁয়ে খাবারের কাছে পথ দেখিয়ে নিয়ে যায়।\\n২. এক পিঁপড়া মুখ থেকে আরেকজনের মুখে তরল খাবার তুলে দেয়। বিজ্ঞানের নাম ট্রফালাক্সিস।\\n৩. ওদের দুটো থলি: একটায় (ক্রপ) খাবার জমা থাকে ভাগ করার জন্য, আরেকটায় নিজের হজম হয়।"]','[{"label": "AntWiki", "url": "https://antwiki.org/wiki/Trophallaxis"}, {"label": "AntWiki", "url": "https://www.antwiki.org/wiki/The_Ants_Chapter_7"}, {"label": "Meurville & LeBoeuf 2021, Myrmecological", "url": "https://antwiki.org/w/images/5/54/Meurville,_M.-P.,_LeBoeuf,_A.C._2021._Trophallaxis_(10.25849@myrmecol.news_031-001).pdf"}]','[{"src": "/media/pokar-shohor/270214-zoom-07-ant-face-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: পিঁপড়ার মুখ, কার্ড 1"}]','["Diego Delso (CC BY-SA 4.0), Wikimedia Commons"]','biology','butterfly','mint',1,'2027-02-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270103-zoom-01-butterfly-wing','pokar-shohor','card','জুম করে দেখো: প্রজাপতির ডানা','ছবিতে যা দেখছেন, তা এক ময়ূরী প্রজাপতির ডানার অংশ, ক্যামেরায় অনেক বড় করে তোলা। কাছ থেকে দেখলে দেখা যায়, ডানা ছোট ছোট আঁশে ঢাকা!','["১. রং আসে অসংখ্য খুদে আঁশ থেকে, যেগুলো দেখতে ছোট লোম বা পাতের মতো।\\n২. ডানার ‘চোখ’ পাখিকে ভয় দেখায়। এক পরীক্ষায় চোখ রং করে ঢেকে দেওয়া প্রজাপতিদের নীল টিট পাখি বেশি ধরে খেয়েছিল।\\n৩. আঁশ সহজে খসে যায়, তাই কিছু ক্ষেত্রে মাকড়সার জাল থেকে ছুটে পালানো সহজ হয় বলে মনে করা হয়।"]','[{"label": "American Museum of Natural History", "url": "https://www.amnh.org/exhibitions/butterflies/anatomy"}, {"label": "Vallin et al. 2005, Biology Letters", "url": "https://www.researchgate.net/publication/7721184_Prey_survival_by_predator_intimidation_An_experimental_study_of_peacock_butterfly_defence_against_blue_tits"}]','[{"src": "/media/pokar-shohor/270103-zoom-01-butterfly-wing-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখো: প্রজাপতির ডানা, কার্ড 1"}]','["Franz van Duns (CC BY-SA 4.0), Wikimedia Commons"]','biology','butterfly','mint',1,'2027-01-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270124-zoom-04-mosquito','pokar-shohor','card','জুম করে দেখুন: মশা','ছবির মশাটা রক্ত খেয়ে পেট লাল করে ফেলেছে। কাছ থেকে দেখলে:','["১. মশার সুঁড় আসলে একটা খাপ, যার ভেতরে ছয়টা সরু সুঁইয়ের মতো অংশের গোছা। কামড়ানোর সময় খাপটা বেঁকে বাইরে থাকে, আর সুঁইগুলো ঢোকে ত্বকে।\\n২. কামড়ায় শুধু স্ত্রী মশা, কারণ ডিম তৈরির জন্য ওদের রক্তের প্রোটিন দরকার। পুরুষ মশার ওসব লাগে না।\\n৩. মানুষ খুঁজতে ওরা ব্যবহার করে আমাদের নিঃশ্বাসের কার্বন ডাই-অক্সাইড আর শরীরের নানা গন্ধ।", "বাড়ির আশপাশে জমে থাকা পানি পরিষ্কার রাখুন। আপনাকেই মশা বেশি কামড়ায় কেন, কখনো ভেবেছেন?"]','[{"label": "Wikipedia", "url": ""}, {"label": "Baylor College of Medicine", "url": ""}, {"label": "PMC", "url": ""}]','[{"src": "/media/pokar-shohor/270124-zoom-04-mosquito-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: মশা, কার্ড 1"}]','[]','biology','butterfly','mint',1,'2027-01-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270131-zoom-05-spider-web','pokar-shohor','card','জুম করে দেখুন: মাকড়সার জাল','সকালে ঝোপের ফাঁকে ছড়ানো জালের দিকে তাকালে:','["১. কেন্দ্র থেকে বেরোনো সোজা সুতাগুলো আঠাহীন, ওগুলো জালের কাঠামো।\\n২. শিকার ধরে প্যাঁচানো সুতাগুলো, যেগুলো ছোট ছোট আঠার ফোঁটায় মোড়া।\\n৩. মাকড়সা সাধারণত আঠাহীন সুতার ওপর দিয়েই চলাফেরা করে, তাই নিজের জালে নিজে আটকায় না। (কিছু প্রজাতির পায়ের গড়নও এতে সাহায্য করে।)", "ভোরের শিশিরে মাকড়সার জাল দেখেছেন কখনো? কেমন লেগেছিল?"]','[{"label": "Ohio State University BYGL", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "Journal of Experimental Biology", "url": ""}]','[{"src": "/media/pokar-shohor/270131-zoom-05-spider-web-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: মাকড়সার জাল, কার্ড 1"}]','[]','biology','butterfly','mint',1,'2027-01-31');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270307-zoom-10-housefly','pokar-shohor','card','জুম করে দেখুন: মাছি','ঘরের চেনা মাছিকেও কাছ থেকে দেখলে অবাক হতে হয়:','["১. মাছির স্বাদ নেওয়ার অঙ্গ আছে পায়ে, তাই খাবারে বসামাত্রই চিনি টের পায়।\\n২. প্রতিটি চোখ হাজার হাজার ছোট লেন্সে গড়া যৌগিক চোখ, ফলে প্রায় সব দিকে নজর রাখতে পারে।\\n৩. মাছি খাবারের ওপর লালা (হজমের রস) ফেলে সেটা গলিয়ে নেয়, তারপর স্পঞ্জের মতো মুখ দিয়ে চুষে খায়।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Housefly"}, {"label": "Science World", "url": "https://www.scienceworld.ca/resource/eat-housefly-eat-barf/"}]','[{"src": "/media/pokar-shohor/270307-zoom-10-housefly-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: মাছি, কার্ড 1"}]','["Diego Delso (CC BY-SA 4.0), Wikimedia Commons"]','biology','butterfly','mint',1,'2027-03-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270104-01-dung-beetle-navigator','pokar-shohor','card','গোবরে পোকা সোজা পথে চলে কীভাবে?','রাতের আকাশ তার রাস্তার ম্যাপ।','["গোবরে পোকা, পোকার শহরে পদ: শহরের সাফাইকর্মী ও নেভিগেটর।\\n১. গোবরের বল বানিয়ে গড়িয়ে নেয় নিরাপদ জায়গায়।\\n২. সোজা লাইনে চলে, যাতে অন্য পোকা বল কেড়ে নিতে না পারে।\\n৩. রাতে আকাশগঙ্গার আলো দেখে দিক ঠিক রাখে।", "এক কথায়: আকাশগঙ্গা দেখে পথ চেনে: এমন পোকা আর জানা নেই।\\nমাঠে খুঁজুন: গরুর মাঠে গোল বল ঠেলছে এমন পোকা দেখেছেন?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dung_beetle"}, {"label": "Dacke et al. 2013", "url": ""}]','[{"src": "/media/pokar-shohor/270104-01-dung-beetle-navigator-1.webp", "width": 960, "height": 1200, "alt": "গোবরে পোকা সোজা পথে চলে কীভাবে?, কার্ড 1"}, {"src": "/media/pokar-shohor/270104-01-dung-beetle-navigator-2.webp", "width": 960, "height": 1200, "alt": "গোবরে পোকা সোজা পথে চলে কীভাবে?, কার্ড 2"}]','["Bernard DUPONT from FRANCE, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Large_Copper_Dung_Beetle_(Kheper_nigroaeneus)_rolling_a_dung_ball_(15823074113).jpg", "Bernard DUPONT from FRANCE, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Dung_Beetle_(Gymnopleurus_virens)_rolling_a_ball_(13738596023).jpg"]','biology','butterfly','mint',1,'2027-01-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270111-02-cricket-ears-on-legs','pokar-shohor','card','ঝিঁঝিঁ পোকার কান কোথায়?','মাথায় খুঁজবেন না, দেখুন পায়ে।','["ঝিঁঝিঁ পোকা, পোকার শহরে পদ: শহরের রাতের গায়ক।\\n১. সামনের পায়ের হাঁটুর নিচে পাতলা পর্দা: এটাই কান।\\n২. পুরুষ ঝিঁঝিঁ এক ডানা আরেক ডানায় ঘষে গান গায়।\\n৩. সেই গান শুনে স্ত্রী ঝিঁঝিঁ পা দিয়ে খুঁজে নেয় গায়ককে।", "এক কথায়: ডানায় গান, পায়ে কান: ঝিঁঝিঁর পুরো শরীরই এক রেডিও।\\nরাতে শুনুন: ঝিঁঝিঁর ডাক গরমে দ্রুত হয় কি না খেয়াল করুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cricket_(insect"}, {"label": "Frontiers in Neuroscience 2022", "url": "https://www.frontiersin.org/articles/10.3389/fnins.2022.1087050/full"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cricket_(insect"}]','[{"src": "/media/pokar-shohor/270111-02-cricket-ears-on-legs-1.webp", "width": 960, "height": 1200, "alt": "ঝিঁঝিঁ পোকার কান কোথায়?, কার্ড 1"}, {"src": "/media/pokar-shohor/270111-02-cricket-ears-on-legs-2.webp", "width": 960, "height": 1200, "alt": "ঝিঁঝিঁ পোকার কান কোথায়?, কার্ড 2"}]','["Holger Krisp, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Zweifleckgrille_Gryllus_bimaculatus_1.jpg", "Holger Krisp, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Zweifleckgrille_Gryllus_bimaculatus_2.jpg"]','biology','butterfly','mint',1,'2027-01-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270118-03-water-strider-walks-on-water','pokar-shohor','card','পানির ওপর হাঁটে কোন পোকা?','ছবির কালো গোল ছায়াগুলো আসলে পায়ের ছাপ।','["জলমাকড়, পোকার শহরে পদ: পুকুরের ফেরিওয়ালা।\\n১. পায়ে লাখো সূক্ষ্ম লোম, তাতে পানি লাগে না।\\n২. লম্বা পায়ে ওজন ছড়িয়ে দেয়, পানির ওপরের টান ভাঙে না।\\n৩. পানিতে শুধু ছোট্ট টোল পড়ে: সেই টোলের ছায়াই কালো গোল।", "এক কথায়: পানি-না-ভেজানো লোম আর ছড়ানো পা: ডোবার প্রশ্নই নেই।\\nপুকুরে খুঁজুন: রোদে পানির নিচে পায়ের গোল ছায়া দেখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gerridae"}, {"label": "Gao & Jiang / PMC3973396", "url": ""}]','[{"src": "/media/pokar-shohor/270118-03-water-strider-walks-on-water-1.webp", "width": 960, "height": 1200, "alt": "পানির ওপর হাঁটে কোন পোকা?, কার্ড 1"}, {"src": "/media/pokar-shohor/270118-03-water-strider-walks-on-water-2.webp", "width": 960, "height": 1200, "alt": "পানির ওপর হাঁটে কোন পোকা?, কার্ড 2"}]','["Brocken Inaglory, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Surface_waves_and_water_striders.JPG", "Trazyanderson, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Water_Strider,_Rush_River,_Wisconsin.jpg"]','biology','butterfly','mint',1,'2027-01-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270125-04-firefly-lantern','pokar-shohor','card','জোনাকির আলো গরম হয় না কেন?','পেটের শেষে এক রাসায়নিক বাতিঘর।','["জোনাকি পোকা, পোকার শহরে পদ: শহরের রাতের বাতিওয়ালা।\\n১. পেটের নিচের দিকে বিশেষ আলোর অঙ্গ আছে।\\n২. সেখানে লুসিফেরিন নামের পদার্থ অক্সিজেনের সাথে বিক্রিয়া করে।\\n৩. আলো জ্বলে প্রায় তাপ ছাড়াই: একে বলে ঠান্ডা আলো।", "এক কথায়: জ্বলে, পোড়ায় না: জোনাকির আলো রসায়নের জাদু।\\nরাতে দেখুন: প্রতিটি জোনাকির জ্বলা-নেভার ছন্দ আলাদা কি না।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Firefly"}, {"label": "National Geographic", "url": "https://www.nationalgeographic.com/animals/invertebrates/facts/fireflies"}]','[{"src": "/media/pokar-shohor/270125-04-firefly-lantern-1.webp", "width": 960, "height": 1200, "alt": "জোনাকির আলো গরম হয় না কেন?, কার্ড 1"}, {"src": "/media/pokar-shohor/270125-04-firefly-lantern-2.webp", "width": 960, "height": 1200, "alt": "জোনাকির আলো গরম হয় না কেন?, কার্ড 2"}]','["KKPCW（Kyu3）, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Firefly_on_the_white_wall_-_3.jpg", "Terry Priest, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:F2019-07-02_1982.jpg"]','biology','butterfly','mint',1,'2027-01-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270201-05-termite-mound-air','pokar-shohor','card','উইপোকার ঢিবিতে এসি কীভাবে চলে?','মাটির টাওয়ারের ভেতর দিনরাত বাতাস ঘোরে।','["উইপোকা, পোকার শহরে পদ: শহরের স্থপতি।\\n১. মাটি, লালা আর বিষ্ঠা মিশিয়ে বিশাল ঢিবি বানায়।\\n২. ভেতরে অসংখ্য সুড়ঙ্গ আর নালি, ঠিক বাড়ির পাইপের মতো।\\n৩. দিন-রাতের তাপের ওঠানামায় ভেতরে বাতাস ঘোরে।", "এক কথায়: বিদ্যুৎ ছাড়াই বাতাস চলাচল: উইপোকা প্রকৌশলীর গুরু।\\nমাঠে খুঁজুন: গাছের গোড়ায় মাটির সুড়ঙ্গ-রেখা: উইপোকার রাস্তা।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Termite_mound"}, {"label": "King", "url": ""}]','[{"src": "/media/pokar-shohor/270201-05-termite-mound-air-1.webp", "width": 960, "height": 1200, "alt": "উইপোকার ঢিবিতে এসি কীভাবে চলে?, কার্ড 1"}, {"src": "/media/pokar-shohor/270201-05-termite-mound-air-2.webp", "width": 960, "height": 1200, "alt": "উইপোকার ঢিবিতে এসি কীভাবে চলে?, কার্ড 2"}]','["brewbooks from near Seattle, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Flickr_-_brewbooks_-_Cathedral_Termite_Mound_-_Litchfield_National_Park.jpg", "Ianperegian, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cathedral_Termite_Mound.jpg"]','biology','butterfly','mint',1,'2027-02-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270208-06-silkworm-one-thread','pokar-shohor','card','একটা গুটিতে কত সুতা?','উত্তর: মাত্র একটা, তবে শত শত মিটার লম্বা।','["রেশম পোকা, পোকার শহরে পদ: শহরের দর্জি।\\n১. মুখের কাছের গ্রন্থি থেকে তরল রেশম বের করে।\\n২. মাথা দুলিয়ে নিজের চারপাশে গুটি বোনে।\\n৩. পুরো গুটি একটানা একটি সুতা: শত শত মিটার লম্বা।", "এক কথায়: একটি পোকা, একটি সুতা: তাতেই রাজশাহী সিল্কের শুরু।\\nবাজারে দেখুন: রেশমি কাপড় ছুঁয়ে দেখুন কত মসৃণ।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bombyx_mori"}, {"label": "FAO Silk Reeling and Testing Manual", "url": "https://www.fao.org/4/x2099e/x2099e02.htm"}]','[{"src": "/media/pokar-shohor/270208-06-silkworm-one-thread-1.webp", "width": 960, "height": 1200, "alt": "একটা গুটিতে কত সুতা?, কার্ড 1"}, {"src": "/media/pokar-shohor/270208-06-silkworm-one-thread-2.webp", "width": 960, "height": 1200, "alt": "একটা গুটিতে কত সুতা?, কার্ড 2"}]','["Biswarup Ganguly, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Assamese_Cocoons_-_Samia_cynthia_Red_-_Samia_cynthia_White_-_Antheraea_assamensis_-_Bombyx_mori_-_Kolkata_2013-06-04_8562.JPG", "LoggaWiggler, CC0, https://commons.wikimedia.org/wiki/File:Cut-cocoon.jpg"]','biology','butterfly','mint',1,'2027-02-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270215-07-mantis-turns-head','pokar-shohor','card','কোন পোকা ঘাড় ঘুরিয়ে তাকায়?','ম্যান্টিস: মাথা ঘোরায় প্রায় অর্ধেক পাক।','["ম্যান্টিস, পোকার শহরে পদ: শহরের পাহারাদার।\\n১. ঘাড় খুব নমনীয়: মাথা ঘোরায় প্রায় ১৮০ ডিগ্রি।\\n২. দুই চোখে ত্রিমাত্রিক দৃষ্টি: শিকার দেখে নিখুঁত।\\n৩. কাঁটাওয়ালা সামনের পা দিয়ে খপ করে শিকার ধরে।", "এক কথায়: নড়ে কম, দেখে বেশি: ম্যান্টিস ধৈর্যের শিকারি।\\nবাগানে খুঁজুন: সবুজ পাতায় স্থির বসে থাকা ম্যান্টিস।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mantis"}, {"label": "Newcastle University press release 2016", "url": ""}]','[{"src": "/media/pokar-shohor/270215-07-mantis-turns-head-1.webp", "width": 960, "height": 1200, "alt": "কোন পোকা ঘাড় ঘুরিয়ে তাকায়?, কার্ড 1"}, {"src": "/media/pokar-shohor/270215-07-mantis-turns-head-2.webp", "width": 960, "height": 1200, "alt": "কোন পোকা ঘাড় ঘুরিয়ে তাকায়?, কার্ড 2"}]','["harum.koh from Kobe city, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Giant_Asian_Mantis_(Hierodula_patellifera)_(15378561530).jpg", "harum.koh from Kobe city, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Giant_Asian_Mantis_(Hierodula_patellifera)_(15522107252).jpg"]','biology','butterfly','mint',1,'2027-02-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270222-08-ladybird-eats-aphids','pokar-shohor','card','লেডিবার্ড কৃষকের বন্ধু কেন?','ছোট্ট লাল পোকা, বড় শিকারি।','["লেডিবার্ড বিটল, পোকার শহরে পদ: শহরের বাগান-পুলিশ।\\n১. গাছের রস চোষা জাব পোকা খেয়ে সাফ করে।\\n২. বড় পোকা আর ছানা দুজনেই জাব পোকা শিকার করে।\\n৩. উজ্জ্বল রং শত্রুকে জানায়: আমি খেতে বিস্বাদ।", "এক কথায়: লাল জামার পাহারাদার: গাছ বাঁচায় বিষ ছাড়াই।\\nবাগানে খুঁজুন: যেখানে জাব পোকা, তার আশেপাশেই লেডিবার্ড।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Coccinellidae"}, {"label": "Biology", "url": "https://doi.org/10.3390/biology14030245"}]','[{"src": "/media/pokar-shohor/270222-08-ladybird-eats-aphids-1.webp", "width": 960, "height": 1200, "alt": "লেডিবার্ড কৃষকের বন্ধু কেন?, কার্ড 1"}, {"src": "/media/pokar-shohor/270222-08-ladybird-eats-aphids-2.webp", "width": 960, "height": 1200, "alt": "লেডিবার্ড কৃষকের বন্ধু কেন?, কার্ড 2"}]','["Greyson Orlando, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Ladybug_aphids.JPG", "Luc Viatour, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Coccinella_septempunctata_Luc_Viatour.JPG"]','biology','butterfly','mint',1,'2027-02-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270301-09-butterfly-straw-tongue','pokar-shohor','card','প্রজাপতির স্ট্র কোথায় থাকে?','মুখের নিচে গুটিয়ে রাখা লম্বা নল।','["প্রজাপতি, পোকার শহরে পদ: শহরের মধু-ডেলিভারি।\\n১. লম্বা নলটি দুটি সরু অংশ জুড়ে তৈরি।\\n২. না খাওয়ার সময় স্প্রিংয়ের মতো গুটিয়ে রাখে।\\n৩. ফুলে বসে নল খুলে স্ট্রয়ের মতো মধু টানে।", "এক কথায়: গুটানো স্ট্র সবসময় সাথে: প্রজাপতির পকেট-জুসবার।\\nফুলে দেখুন: বসা প্রজাপতির নল খোলা না গুটানো।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Proboscis"}, {"label": "Insects 2024", "url": "https://doi.org/10.3390/insects15120922"}, {"label": "J. Morphology 2022", "url": "https://doi.org/10.1002/jmor.21510"}]','[{"src": "/media/pokar-shohor/270301-09-butterfly-straw-tongue-1.webp", "width": 960, "height": 1200, "alt": "প্রজাপতির স্ট্র কোথায় থাকে?, কার্ড 1"}, {"src": "/media/pokar-shohor/270301-09-butterfly-straw-tongue-2.webp", "width": 960, "height": 1200, "alt": "প্রজাপতির স্ট্র কোথায় থাকে?, কার্ড 2"}]','["nottsexminer, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Brimstone_Butterfly_(8109891932).jpg", "Steve Jurvetson from Menlo Par, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Jurvetson_-_spiral_proboscis_(by).jpg"]','biology','butterfly','mint',1,'2027-03-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270308-10-weaver-ants-build-nests','pokar-shohor','card','লাল পিঁপড়া পাতার বাসা বানায় কীভাবে?','টানে একদল, সেলাই করে ছানারা।','["লাল পিঁপড়া, পোকার শহরে পদ: শহরের রাজমিস্ত্রি।\\n১. কর্মীরা শিকল বানিয়ে দুটি পাতা টেনে কাছে আনে।\\n২. আরেক দল মুখে লার্ভা ধরে আলতো চাপ দেয়।\\n৩. লার্ভার রেশম দিয়ে পাতা জোড়া লাগে: তৈরি বাসা।", "এক কথায়: দলের টান আর ছানার রেশম: সেলাই করা পাতার বাড়ি।\\nগাছে খুঁজুন: আম গাছে পাতা মোড়ানো বল: লাল পিঁপড়ার বাসা।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Weaver_ant"}, {"label": "PLoS One 2016", "url": ""}, {"label": "Sci. Reports 2018", "url": ""}]','[{"src": "/media/pokar-shohor/270308-10-weaver-ants-build-nests-1.webp", "width": 960, "height": 1200, "alt": "লাল পিঁপড়া পাতার বাসা বানায় কীভাবে?, কার্ড 1"}, {"src": "/media/pokar-shohor/270308-10-weaver-ants-build-nests-2.webp", "width": 960, "height": 1200, "alt": "লাল পিঁপড়া পাতার বাসা বানায় কীভাবে?, কার্ড 2"}]','["RidhaAnshari85, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Semut_rangrang.jpg", "RidhaAnshari85, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Semut_Rangrang_Yang_Sedang_Gotong_Royong.jpg"]','biology','butterfly','mint',1,'2027-03-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270315-11-bee-pollen-basket','pokar-shohor','card','মৌমাছির পায়ে ঝুড়ি কেন?','পেছনের পায়ে ফুলের রেণু ভরে বাড়ি ফেরে।','["মৌমাছি, পোকার শহরে পদ: শহরের ডেলিভারি কর্মী।\\n১. পেছনের পায়ে চকচকে খাঁজ, চারপাশে লোমের বেড়া।\\n২. রেণু একটু মধু বা রসে ভিজিয়ে চেপে ভরে।\\n৩. দুই পায়ে দুটি রেণুর বল নিয়ে চাকে ফেরে।", "এক কথায়: পায়েই বাজারের ব্যাগ: মৌমাছির রেণুর ঝুড়ি।\\nসরিষা ক্ষেতে দেখুন: মৌমাছির পায়ে হলুদ রেণুর বল।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pollen_basket"}, {"label": "PeerJ 2025", "url": "https://doi.org/10.7717/peerj.19749"}]','[{"src": "/media/pokar-shohor/270315-11-bee-pollen-basket-1.webp", "width": 960, "height": 1200, "alt": "মৌমাছির পায়ে ঝুড়ি কেন?, কার্ড 1"}, {"src": "/media/pokar-shohor/270315-11-bee-pollen-basket-2.webp", "width": 960, "height": 1200, "alt": "মৌমাছির পায়ে ঝুড়ি কেন?, কার্ড 2"}]','["Tetsuya Shimizu, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Apis_cerana_japonica.jpg", "WATANABE Hitoshi 渡辺仁, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Apis_cerana_japonica_449664167.jpg"]','biology','butterfly','mint',1,'2027-03-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270218-map-07-great-barrier-reef','neel-gobhire','card','ভাবুর ম্যাপ: গ্রেট ব্যারিয়ার রিফ','অস্ট্রেলিয়ার উত্তর-পূর্ব উপকূলে কোরাল সাগরে ছড়ানো গ্রেট ব্যারিয়ার রিফ পৃথিবীর বৃহত্তম প্রবাল ব্যবস্থা। লম্বায় প্রায় ২,৩০০ কিলোমিটার, তাতে আছে প্রায় ২,৯০০টি আলাদা প্রবালপ্রাচীর আর প্রায় ৯০০টি দ্বীপ।','["প্রবাল পাথর নয়, ছোট্ট ছোট্ট প্রাণীদের বসতি, যারা সংখ্যায় লাখে লাখে একসাথে থাকে। (সংখ্যাগুলো উৎসভেদে কিছুটা আলাদা।)"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Great_Barrier_Reef"}, {"label": "Great Barrier Reef Foundation", "url": "https://greatbarrierreef.org/about-the-reef/great-barrier-reef-facts/"}, {"label": "Distance", "url": "https://en.wikipedia.org/wiki/Great_Barrier_Reef"}]','[{"src": "/media/neel-gobhire/270218-map-07-great-barrier-reef-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: গ্রেট ব্যারিয়ার রিফ, কার্ড 1"}]','["Ank Kumar (CC BY-SA 4.0), Wikimedia Commons"]','nature','fish','teal',1,'2027-02-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270115-number-03-octopus-hearts','neel-gobhire','card','সংখ্যার ম্যাজিক: ৩টা হৃদয়','অক্টোপাসের হৃদয় তিনটা! দুটো ‘ফুলকা-হৃদয়’ রক্তকে ফুলকার ভেতর দিয়ে পাঠায়, আর বড় তৃতীয়টা সেই অক্সিজেন-ভরা রক্ত ছড়িয়ে দেয় পুরো শরীরে।','["আরেক মজা: ওদের রক্ত নীল! অক্সিজেন বহন করে হিমোসায়ানিন নামের তামাযুক্ত একটা উপাদান, আমাদের লোহাযুক্ত হিমোগ্লোবিনের জায়গায়।"]','[{"label": "The Sea (thesea.org)", "url": "https://thesea.org/how-many-hearts-does-an-octopus-have/"}, {"label": "Emerging Infectious Diseases / PMC", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7392445/"}]','[{"src": "/media/neel-gobhire/270115-number-03-octopus-hearts-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৩টা হৃদয়, কার্ড 1"}]','["LASZLO ILYES (CC BY 2.0), Wikimedia Commons"]','nature','fish','teal',1,'2027-01-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270312-number-11-ocean-water-share','neel-gobhire','card','সংখ্যার ম্যাজিক: ৯৬.৫%','পৃথিবীর সব পানির প্রায় ৯৬.৫ শতাংশ সাগরে (USGS-এর হিসাব; অনেক জায়গায় গোল করে ৯৭% লেখা হয়)। মিঠা পানি মাত্র প্রায় ২.৫ শতাংশ, আর তারও বড় অংশ জমে আছে বরফ আর হিমবাহে, কিছুটা মাটির নিচে।','["অর্থাৎ আমাদের নদী, পুকুর, হ্রদের পানি পৃথিবীর মোট পানির একটুখানি। তাই পানির যত্ন নেওয়া জরুরি।"]','[{"label": "USGS Water Science School", "url": "https://www.usgs.gov/water-science-school/science/how-much-water-there-earth"}, {"label": "NOAA National Ocean Service", "url": "https://oceanservice.noaa.gov/facts/wherewater.html"}]','[{"src": "/media/neel-gobhire/270312-number-11-ocean-water-share-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৯৬.৫%, কার্ড 1"}]','["King of Hearts (CC BY-SA 4.0), Wikimedia Commons"]','nature','fish','teal',1,'2027-03-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270102-01-why-the-sea-is-salty','neel-gobhire','card','সমুদ্রের পানি লোনা কেন?','নদীর পানি মিষ্টি, তবু সাগর লোনা!','["১. বৃষ্টি পাহাড়-পাথর ক্ষইয়ে খনিজ লবণ ধুয়ে নেয়।\\n২. নদী সেই লবণ বয়ে নিয়ে যায় সাগরে, সাগরের তলার ফাটল থেকেও আসে।\\n৩. কিছু লবণ সাগরের জীবেরা কাজে লাগায়, বাকিটা জমে বহু যুগ ধরে।", "এক কথায়: লক্ষ বছরের জমানো লবণ: তাই সাগর লোনা।\\nসৈকতে দেখুন: শুকানো ভেজা পায়ে সাদা লবণের দাগ।"]','[{"label": "NOAA Ocean Service", "url": "https://oceanservice.noaa.gov/facts/whysalty.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Seawater"}]','[{"src": "/media/neel-gobhire/270102-01-why-the-sea-is-salty-1.webp", "width": 960, "height": 1200, "alt": "সমুদ্রের পানি লোনা কেন?, কার্ড 1"}, {"src": "/media/neel-gobhire/270102-01-why-the-sea-is-salty-2.webp", "width": 960, "height": 1200, "alt": "সমুদ্রের পানি লোনা কেন?, কার্ড 2"}]','["S.M.Tanim, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sea_Salt_Farming.jpg", "Dennis G. Jarvis, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Tunisia-3916_-_Salt_Crystals_(7849884490).jpg"]','nature','fish','teal',1,'2027-01-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270109-02-why-hilsa-swims-up-rivers','neel-gobhire','card','সাগরের ইলিশ নদীতে কেন?','ডিম পাড়তে উল্টো স্রোতে লম্বা যাত্রা','["১. ইলিশ বড় হয় সাগরে, বঙ্গোপসাগরের লোনা পানিতে।\\n২. ডিম পাড়ার সময় হলে স্রোতের উল্টো দিকে নদীতে ওঠে।\\n৩. মিঠা পানিতে ডিম ফুটে বাচ্চা হয়, এই জাটকা পরে সাগরে ফেরে।", "এক কথায়: সাগরে বড় হওয়া, নদীতে জন্ম: ইলিশ দুই পানির মাছ।\\nবাজারে দেখুন: জাটকা ধরা-বেচা নিষেধ কেন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hilsa_shad"}, {"label": "Biomolecules 2025", "url": ""}]','[{"src": "/media/neel-gobhire/270109-02-why-hilsa-swims-up-rivers-1.webp", "width": 960, "height": 1200, "alt": "সাগরের ইলিশ নদীতে কেন?, কার্ড 1"}, {"src": "/media/neel-gobhire/270109-02-why-hilsa-swims-up-rivers-2.webp", "width": 960, "height": 1200, "alt": "সাগরের ইলিশ নদীতে কেন?, কার্ড 2"}]','["Fahad Faisal, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hilsa_Ilisha_Fish.jpg", "DelwarHossain, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Safe_mother_hilsa_fish.jpg"]','nature','fish','teal',1,'2027-01-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270116-03-shushuk-is-not-a-fish','neel-gobhire','card','শুশুক কি মাছ?','নদীতে থাকে, কিন্তু শ্বাস নেয় বাতাসে','["১. শুশুক স্তন্যপায়ী: বাচ্চাকে দুধ খাওয়ায়, মাছ নয়।\\n২. ফুসফুসে শ্বাস নেয়, তাই বারবার পানির ওপরে ভেসে ওঠে।\\n৩. চোখে প্রায় দেখে না: শব্দের প্রতিধ্বনি শুনে পথ চেনে।", "এক কথায়: নদীর ডলফিন শুশুক: চোখ নয়, কান দিয়ে দেখে।\\nনৌকা থেকে দেখুন: পানিতে হঠাৎ ভুস করে ওঠা পিঠ।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/South_Asian_river_dolphin"}, {"label": "Genome Biology and Evolution 2025", "url": ""}]','[{"src": "/media/neel-gobhire/270116-03-shushuk-is-not-a-fish-1.webp", "width": 960, "height": 1200, "alt": "শুশুক কি মাছ?, কার্ড 1"}, {"src": "/media/neel-gobhire/270116-03-shushuk-is-not-a-fish-2.webp", "width": 960, "height": 1200, "alt": "শুশুক কি মাছ?, কার্ড 2"}]','["Munshi Abul Barakat, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Ganges_river_Dolphin_,_The_National_Aquatic_Animal_of_India.jpg", "MSH Sourav, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:South_Asian_river_dolphin%C2%A9_Md_Sharif_Hossain_Sourav.jpg"]','nature','fish','teal',1,'2027-01-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270123-04-why-tides-come-and-go','neel-gobhire','card','সাগরের পানি সরে যায় কেন?','সকালে যেখানে ঢেউ, বিকেলে সেখানে বালি','["১. চাঁদের টানে সাগরের পানি একদিকে ফুলে ওঠে: জোয়ার।\\n২. পৃথিবী ঘোরার সাথে সেই ফোলা জায়গা সরে যায়: ভাটা।\\n৩. সূর্যও টানে, তবে চাঁদের টানই বেশি কাজ করে।", "এক কথায়: জোয়ার-ভাটার আসল কারিগর আকাশের চাঁদ।\\nসৈকতে দেখুন: ভাটায় বালিতে বসা নৌকা।"]','[{"label": "NOAA Ocean Service", "url": "https://oceanservice.noaa.gov/education/tutorial_tides/tides02_cause.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tide"}]','[{"src": "/media/neel-gobhire/270123-04-why-tides-come-and-go-1.webp", "width": 960, "height": 1200, "alt": "সাগরের পানি সরে যায় কেন?, কার্ড 1"}, {"src": "/media/neel-gobhire/270123-04-why-tides-come-and-go-2.webp", "width": 960, "height": 1200, "alt": "সাগরের পানি সরে যায় কেন?, কার্ড 2"}]','["Amdadphoto, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fishing_Boats_at_Low_Tide.jpg", "Sadafriyan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cox%27s_wave.JPG"]','nature','fish','teal',1,'2027-01-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270130-05-whales-sing','neel-gobhire','card','তিমি কেন গান গায়?','সাগরের নিচে ঘণ্টার পর ঘণ্টা সুর','["১. পুরুষ হাম্পব্যাক তিমি লম্বা, বারবার ফিরে আসা গান গায়।\\n২. একেকটি গান কয়েক মিনিট থেকে আধঘণ্টার বেশি চলে।\\n৩. কেন গায়, বিজ্ঞানীরা এখনও পুরো নিশ্চিত নন: সম্ভবত সঙ্গী খোঁজে।", "এক কথায়: সাগরের সবচেয়ে বড় গায়ক: গান এখনও এক রহস্য।\\nশুনে দেখুন: হাম্পব্যাক তিমির গান খুঁজে শুনুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Humpback_whale"}, {"label": "Proc. R. Soc. B 2004", "url": ""}, {"label": "Garland et al. 2011", "url": ""}]','[{"src": "/media/neel-gobhire/270130-05-whales-sing-1.webp", "width": 960, "height": 1200, "alt": "তিমি কেন গান গায়?, কার্ড 1"}, {"src": "/media/neel-gobhire/270130-05-whales-sing-2.webp", "width": 960, "height": 1200, "alt": "তিমি কেন গান গায়?, কার্ড 2"}]','["Giles Laurent, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:001_Humpback_whale_breaching_in_Ballena_Marine_National_Park_Photo_by_Giles_Laurent.jpg", "Jakub Hałun, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Humpback_whale,_Faxafl%C3%B3i_Bay,_Iceland,_20230507_1029_5616.jpg"]','nature','fish','teal',1,'2027-01-30');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270206-06-turtle-hatchlings-find-the-sea','neel-gobhire','card','ছোট্ট কচ্ছপ সাগর চেনে কীভাবে?','মা নেই পাশে, তবু ঠিক পথে','["১. মা কচ্ছপ সৈকতের বালিতে গর্ত করে ডিম পেড়ে চলে যায়।\\n২. বালির তাপমাত্রাই ঠিক করে বাচ্চা ছেলে হবে না মেয়ে।\\n৩. ডিম ফুটে বাচ্চারা একা একাই সাগরের দিকে ছোটে।", "এক কথায়: জন্মেই একা যাত্রা: অলিভ রিডলি সাহসের নাম।\\nসৈকতে মানুন: ডিমের জায়গায় রাতে আলো নয়।"]','[{"label": "NOAA Fisheries", "url": "https://www.fisheries.noaa.gov/species/olive-ridley-turtle"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Olive_ridley_sea_turtle"}]','[{"src": "/media/neel-gobhire/270206-06-turtle-hatchlings-find-the-sea-1.webp", "width": 960, "height": 1200, "alt": "ছোট্ট কচ্ছপ সাগর চেনে কীভাবে?, কার্ড 1"}, {"src": "/media/neel-gobhire/270206-06-turtle-hatchlings-find-the-sea-2.webp", "width": 960, "height": 1200, "alt": "ছোট্ট কচ্ছপ সাগর চেনে কীভাবে?, কার্ড 2"}]','["Bethany McCarter, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Olive_Ridley_Sea_Turtle_Hatchlings.jpg", "Aliva Sahoo, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hatchlings_of_Olive_Ridley.jpg"]','nature','fish','teal',1,'2027-02-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270213-07-koi-breathes-air','neel-gobhire','card','কই মাছ ডাঙায় বাঁচে কীভাবে?','কানকোর ভেতরে লুকানো এক শ্বাসের ঘর','["১. কানকোর ওপরে ভাঁজ করা এক অঙ্গ: গোলকধাঁধার মতো দেখতে।\\n২. এই অঙ্গ দিয়ে কই সরাসরি বাতাস থেকে শ্বাস নেয়।\\n৩. শরীর ভেজা থাকলে ডাঙায় পাখনা দিয়ে কিছুটা এগোতে পারে।", "এক কথায়: পানির মাছ, বাতাসেও শ্বাস: কই এক জেদি সাঁতারু।\\nবৃষ্টির পরে দেখুন: উঠোনের কই পানিতে ফেরান।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Anabas_testudineus"}, {"label": "Frontiers in Physiology 2022", "url": ""}]','[{"src": "/media/neel-gobhire/270213-07-koi-breathes-air-1.webp", "width": 960, "height": 1200, "alt": "কই মাছ ডাঙায় বাঁচে কীভাবে?, কার্ড 1"}, {"src": "/media/neel-gobhire/270213-07-koi-breathes-air-2.webp", "width": 960, "height": 1200, "alt": "কই মাছ ডাঙায় বাঁচে কীভাবে?, কার্ড 2"}]','["Abu Hamas, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Anabas_testudineus_52464343.jpg", "Nayan j Nath, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Anabas_testudineus_climbing_perch.jpg"]','nature','fish','teal',1,'2027-02-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270220-08-red-crab-hides','neel-gobhire','card','লাল কাঁকড়া লুকায় কেন?','এক পা এগোলেই সবাই গর্তে উধাও','["১. লাল ভূত কাঁকড়া সৈকতের বালিতে গর্ত খুঁড়ে থাকে।\\n২. উঁচু ডাঁটার মাথায় চোখ: দূর থেকেই নড়াচড়া টের পায়।\\n৩. বিপদ বুঝলেই গর্তে ঢোকে, পরে আবার বের হয়।", "এক কথায়: লুকোচুরির ওস্তাদ: উঁচু চোখ আর গোপন গর্ত।\\nসৈকতে দেখুন: বালিতে কাঁকড়ার বল-নকশা।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ocypode_macrocera"}, {"label": "Marine Pollution Bulletin 2026", "url": ""}, {"label": "Scientific Reports 2024", "url": ""}]','[{"src": "/media/neel-gobhire/270220-08-red-crab-hides-1.webp", "width": 960, "height": 1200, "alt": "লাল কাঁকড়া লুকায় কেন?, কার্ড 1"}, {"src": "/media/neel-gobhire/270220-08-red-crab-hides-2.webp", "width": 960, "height": 1200, "alt": "লাল কাঁকড়া লুকায় কেন?, কার্ড 2"}]','["Md shahanshah bappy, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Ocypode_macrocera,_Teknaf_Wildlife_Sanctuary_02.jpg", "Parvezahmed, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Art_work_by_red_crabs_in_the_beach.jpg"]','nature','fish','teal',1,'2027-02-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270227-09-glowing-waves','neel-gobhire','card','রাতের ঢেউ জ্বলে কেন?','নীল আলোর পেছনে খুদে প্রাণী','["১. সাগরে ভাসে খুদে অণুজীব ডাইনোফ্ল্যাজেলেট।\\n২. ঢেউয়ের ধাক্কায় তাদের শরীরে রাসায়নিক বিক্রিয়া হয়।\\n৩. সেই বিক্রিয়ায় জ্বলে নীল আলো।", "এক কথায়: ধাক্কা লাগলেই আলো: সাগরের জীবন্ত জোনাকি।\\nরাতে দেখুন: অন্ধকার ঢেউয়ে নীল ঝিলিক।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bioluminescence"}, {"label": "Biology Open 2025", "url": ""}]','[{"src": "/media/neel-gobhire/270227-09-glowing-waves-1.webp", "width": 960, "height": 1200, "alt": "রাতের ঢেউ জ্বলে কেন?, কার্ড 1"}, {"src": "/media/neel-gobhire/270227-09-glowing-waves-2.webp", "width": 960, "height": 1200, "alt": "রাতের ঢেউ জ্বলে কেন?, কার্ড 2"}]','["Saltytog, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Bioluminescence_in_San_Diego.jpg", "makelessnoise from Bountiful, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Dinoflagellate_luminescence.jpg"]','nature','fish','teal',1,'2027-02-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270306-10-rivers-built-bangladesh','neel-gobhire','card','বাংলাদেশ বানিয়েছে কে?','উত্তর: নদীর বয়ে আনা পলিমাটি','["১. হিমালয় থেকে নদী বয়ে আনে বিপুল পলি।\\n২. গঙ্গা-ব্রহ্মপুত্রের পলি জমে তৈরি বিশ্বের সবচেয়ে বড় ব-দ্বীপ।\\n৩. বাংলাদেশের প্রায় ৮০ ভাগ এই ব-দ্বীপের ওপরে।", "এক কথায়: আমরা দাঁড়িয়ে আছি নদীর উপহারের ওপর।\\nনদীতে দেখুন: বর্ষায় নদীর ঘোলা পানি: ওটাই পলি।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ganges_Delta"}, {"label": "Nature Communications 2024", "url": ""}, {"label": "PNAS 2019", "url": "https://doi.org/10.1073/pnas.1913714116"}]','[{"src": "/media/neel-gobhire/270306-10-rivers-built-bangladesh-1.webp", "width": 960, "height": 1200, "alt": "বাংলাদেশ বানিয়েছে কে?, কার্ড 1"}, {"src": "/media/neel-gobhire/270306-10-rivers-built-bangladesh-2.webp", "width": 960, "height": 1200, "alt": "বাংলাদেশ বানিয়েছে কে?, কার্ড 2"}]','["O.V.E.R.V.I.E.W., CC BY 2.0, https://commons.wikimedia.org/wiki/File:Hooghly-_Brahmaputra_Delta,_Bay_of_Bengal_(India_-_Bangladesh)_(34699016026).jpg", "Jeff Schmaltz, Public domain, https://commons.wikimedia.org/wiki/File:Bangladesh_Satellite_View.jpg"]','nature','fish','teal',1,'2027-03-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270313-11-why-the-sea-is-blue','neel-gobhire','card','সাগর নীল কেন?','আকাশের ছায়া? পুরোটা না!','["১. সূর্যের আলোয় সব রং মেশানো থাকে।\\n২. পানি লাল রঙের আলো শুষে নেয়, ছাঁকনির মতো।\\n৩. বাকি থাকে নীল আলো: তাই গভীর পানি নীল দেখায়।", "এক কথায়: পানি লাল খায়, নীল রাখে: সাগর তাই নীল।\\nসাগরে দেখুন: অগভীর পানি সবুজ, গভীরটা নীল।"]','[{"label": "NOAA Ocean Service", "url": "https://oceanservice.noaa.gov/facts/oceanblue.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Color_of_water"}]','[{"src": "/media/neel-gobhire/270313-11-why-the-sea-is-blue-1.webp", "width": 960, "height": 1200, "alt": "সাগর নীল কেন?, কার্ড 1"}, {"src": "/media/neel-gobhire/270313-11-why-the-sea-is-blue-2.webp", "width": 960, "height": 1200, "alt": "সাগর নীল কেন?, কার্ড 2"}]','["Phoneix hasan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Saint_Martin_Island,_Bangladesh.jpg", "MoonlitFrames, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sunrise_over_Inani_Beach,_Cox%27s_Bazar,_Bangladesh.jpg"]','nature','fish','teal',1,'2027-03-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270204-map-05-sundarbans','praner-bangladesh','card','ভাবুর ম্যাপ: সুন্দরবন','ইউনেস্কোর ভাষায় সুন্দরবনে আছে পৃথিবীর সবচেয়ে বড় ম্যানগ্রোভ বনের এলাকা। এর প্রায় ৬০ শতাংশ (৬,০১৭ বর্গকিমি, মোট প্রায় ১০,২৭৭) আমাদের বাংলাদেশে, বাকি অংশ ভারতে।','["লোনা পানিতে দাঁড়িয়ে থাকা এই বনে চিত্রা হরিণ যেমন আছে, তেমনই আছে রয়্যাল বেঙ্গল টাইগার। বাংলাদেশে বাঘ এখন শুধু সুন্দরবনের ম্যানগ্রোভেই টিকে আছে।"]','[{"label": "UNESCO", "url": "https://www.unesco.org/en/articles/sundarbans?hub=752"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sundarbans"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Bengal_Tiger"}]','[{"src": "/media/praner-bangladesh/270204-map-05-sundarbans-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: সুন্দরবন, কার্ড 1"}]','["Abir0089 (CC BY-SA 4.0), Wikimedia Commons"]','nature','frog','mint',1,'2027-02-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270311-map-10-saint-martins-island','praner-bangladesh','card','ভাবুর ম্যাপ: সেন্ট মার্টিন দ্বীপ','বঙ্গোপসাগরের উত্তর-পূর্ব কোণে, কক্সবাজার-টেকনাফ উপদ্বীপের প্রায় ৯ কিলোমিটার দক্ষিণে এই ছোট্ট দ্বীপ। স্থানীয় নাম নারিকেল জিঞ্জিরা। আয়তন প্রায় ৩ বর্গকিলোমিটার (কিছু সূত্রে ৮, মাপভেদে আলাদা)।','["সবাই একে বাংলাদেশের ‘প্রবাল দ্বীপ’ বলে ডাকে। তবে ২০২২ সালের এক গবেষণায় (চট্টগ্রাম বিশ্ববিদ্যালয়ের গবেষকেরা) দেখা গেছে, দ্বীপটা মূলত পাললিক শিলা আর বালুস্তরে গড়া, তাতে প্রবাল জন্মায় মাত্র।", "ঢাকা থেকে সোজা দূরত্ব প্রায় ৪০০ কিলোমিটার। প্রশ্ন: সেন্ট মার্টিনে গেলে সবচেয়ে কী দেখতে চাইবেন?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Saint_Martin%27s_Island"}, {"label": "Prothom Alo English", "url": "https://en.prothomalo.com/environment/9rpuv1x2ra"}]','[{"src": "/media/praner-bangladesh/270311-map-10-saint-martins-island-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: সেন্ট মার্টিন দ্বীপ, কার্ড 1"}]','["ROCKY (CC BY-SA 4.0), Wikimedia Commons"]','nature','frog','mint',1,'2027-03-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270108-01-hoolock-gibbon-sings','praner-bangladesh','card','বনে গান গায় কে?','গাছের মাথায় জোড়ায় জোড়ায় উল্লুক','["উল্লুক · লাউয়াছড়া, মৌলভীবাজার · অবস্থা: বিপন্ন (IUCN)\\n১. উল্লুক জোড়া বেঁধে থাকে, স্বামী-স্ত্রী মিলে জোরে গান গায়।\\n২. লম্বা হাতে ডাল থেকে ডালে দোল খেয়ে চলে, মাটিতে নামে কম।\\n৩. উত্তর-পূর্ব আর দক্ষিণ-পূর্বের বনে এদের দেখা মেলে।", "এক কথায়: বনের গায়ক উল্লুক: গাছ বাঁচলে গানও বাঁচে।\\nবনে শুনুন: লাউয়াছড়ায় ভোরে উঁচু গাছের দিকে কান পাতুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Western_hoolock_gibbon"}, {"label": "Ecology and Evolution 2026", "url": ""}, {"label": "bioRxiv 2025", "url": ""}]','[{"src": "/media/praner-bangladesh/270108-01-hoolock-gibbon-sings-1.webp", "width": 960, "height": 1200, "alt": "বনে গান গায় কে?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270108-01-hoolock-gibbon-sings-2.webp", "width": 960, "height": 1200, "alt": "বনে গান গায় কে?, কার্ড 2"}]','["Timothy A. Gonsalves, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Male_Hoolock_Gibbon_West_Garo_Oct24_A7CR_03491.jpg", "Abdul Momin, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hoolock_gibbon,_Lawachara_National_Park.jpg"]','nature','frog','mint',1,'2027-01-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270115-02-fishing-cat-swims','praner-bangladesh','card','কোন বিড়াল পানিতে নামে?','মিনি ভয় পায়, তার বুনো আত্মীয় ডুব দেয়','["মেছো বিড়াল · জলাভূমি, সারা দেশে · অবস্থা: ঝুঁকিতে (IUCN)\\n১. মেছো বিড়াল থাকে জলাভূমির ঘন ঝোপে।\\n২. পায়ের আঙুলের মাঝে আধা-পর্দা, ভালো সাঁতারু, ডুবও দেয়।\\n৩. ঘন, স্তরে স্তরে লোম শরীরে পানি ঢুকতে দেয় না।", "এক কথায়: বাঘ নয়, বিড়াল: তবে পানিতে ওস্তাদ শিকারি।\\nমনে রাখুন: মেছো বিড়াল মারবেন না, এরা বিপদে আছে।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Fishing_cat"}, {"label": "Animals 2024", "url": ""}, {"label": "J. Mammalogy 2025", "url": "https://doi.org/10.1093/jmammal/gyae150"}]','[{"src": "/media/praner-bangladesh/270115-02-fishing-cat-swims-1.webp", "width": 960, "height": 1200, "alt": "কোন বিড়াল পানিতে নামে?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270115-02-fishing-cat-swims-2.webp", "width": 960, "height": 1200, "alt": "কোন বিড়াল পানিতে নামে?, কার্ড 2"}]','["Cliff from Arlington, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Fishing_Cat_(Prionailurus_viverrinus)_-b.jpg", "Sanjay Tha Shrestha, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fishing_cat_male_and_female.jpg"]','nature','frog','mint',1,'2027-01-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270122-03-pangolin-armour','praner-bangladesh','card','গায়ে আঁশ, তবু মাছ নয়!','ধাঁধার উত্তর: বনরুই','["বনরুই · পাহাড়ি বন · অবস্থা: মহাবিপন্ন (IUCN)\\n১. বনরুই স্তন্যপায়ী, গায়ে সারি সারি শক্ত আঁশ।\\n২. ভয় পেলে গোল বলের মতো গুটিয়ে যায়।\\n৩. লম্বা আঠালো জিভে পিঁপড়া আর উইপোকা খায়।", "এক কথায়: আঁশের বর্ম পরা পিঁপড়াখেকো: বনরুই এখন মহাবিপন্ন।\\nমনে রাখুন: বনরুই কেনা-বেচা অপরাধ, খবর দিন বন বিভাগে।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chinese_pangolin"}, {"label": "BMC Biology 2024", "url": ""}]','[{"src": "/media/praner-bangladesh/270122-03-pangolin-armour-1.webp", "width": 960, "height": 1200, "alt": "গায়ে আঁশ, তবু মাছ নয়!, কার্ড 1"}, {"src": "/media/praner-bangladesh/270122-03-pangolin-armour-2.webp", "width": 960, "height": 1200, "alt": "গায়ে আঁশ, তবু মাছ নয়!, কার্ড 2"}]','["Yung-Lun Lin, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Manis_pentadactyla_pentadactyla_462300623.jpg", "Licheng Shih, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Manis_pentadactyla_pentadactyla_131662800.jpg"]','nature','frog','mint',1,'2027-01-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270129-04-doel-national-bird','praner-bangladesh','card','দোয়েল কেন এত চেনা?','জাতীয় পাখি থাকে আমাদের উঠোনেই','["দোয়েল · সারা দেশে, বাড়ির আশেপাশে · জাতীয় পাখি\\n১. দোয়েল বাংলাদেশের জাতীয় পাখি।\\n২. মানুষের বাড়ির কাছে থাকতে ভয় পায় না, উঠোনে খাবার খোঁজে।\\n৩. পুরুষ দোয়েল উঁচু ডালে বসে মিষ্টি, নানা সুরে শিস দেয়।", "এক কথায়: কালো-সাদা জামার গায়ক: দোয়েল পাশের বাড়ির পাখি।\\nউঠোনে দেখুন: লেজ খাড়া করে লাফানো কালো-সাদা পাখি।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Oriental_magpie-robin"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php?title=Magpie-robin"}]','[{"src": "/media/praner-bangladesh/270129-04-doel-national-bird-1.webp", "width": 960, "height": 1200, "alt": "দোয়েল কেন এত চেনা?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270129-04-doel-national-bird-2.webp", "width": 960, "height": 1200, "alt": "দোয়েল কেন এত চেনা?, কার্ড 2"}]','["Anjan Kumar Kundu, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Oriental_Magpie_Robin_01.jpg", "Tanvirahmed2009, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Oriental_magpie-robin_bird.jpg"]','nature','frog','mint',1,'2027-01-29');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270205-05-shapla-national-flower','praner-bangladesh','card','শাপলা থাকে কোথায়?','জাতীয় ফুলের ঠিকানা: পুকুর আর বিল','["শাপলা · পুকুর, বিল, ঝিল · জাতীয় ফুল\\n১. শাপলা বাংলাদেশের জাতীয় ফুল।\\n২. স্থির বা ধীরে বয়ে চলা অগভীর পানিতে জন্মায়, পাতা ভাসে পানির ওপরে।\\n৩. দিনে ফোটে; এর ডাঁটা অনেকে সবজি হিসেবে খান।", "এক কথায়: পানিতে ফোটা জাতীয় ফুল: বিলের রানি শাপলা।\\nবিলে দেখুন: সকালে শাপলা ফোটা থাকে কি না দেখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nymphaea_nouchali"}, {"label": "Heliyon 2024", "url": "https://doi.org/10.1016/j.heliyon.2024.e35538"}]','[{"src": "/media/praner-bangladesh/270205-05-shapla-national-flower-1.webp", "width": 960, "height": 1200, "alt": "শাপলা থাকে কোথায়?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270205-05-shapla-national-flower-2.webp", "width": 960, "height": 1200, "alt": "শাপলা থাকে কোথায়?, কার্ড 2"}]','["VasuVR, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:White_Water_Lily_near_Coimbatore.jpg", "Lokeswaran Kaliyappan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:White_water_lily_-_Nymphaea.jpg"]','nature','frog','mint',1,'2027-02-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270212-06-haor-winter-guests','praner-bangladesh','card','শীতে হাওরে এত পাখি কেন?','টাঙ্গুয়ারে প্রতি শীতে প্রায় ২০০ রকম অতিথি','["অতিথি পাখি · টাঙ্গুয়ার হাওর, সুনামগঞ্জ · রামসার জলাভূমি\\n১. প্রতি শীতে টাঙ্গুয়ার হাওরে প্রায় ২০০ রকমের অতিথি পাখি আসে।\\n২. হাওর বিশাল জলাভূমি: মাছ আর জলজ খাবারে ভরা।\\n৩. টাঙ্গুয়ার হাওর আন্তর্জাতিক গুরুত্বের রামসার জলাভূমি।", "এক কথায়: খাবার আর পানি আছে বলেই শীতের অতিথিরা হাওরে আসে।\\nহাওরে মানুন: পাখি শিকার বা তাড়া করা নিষেধ।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tanguar_Haor"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Tanguar_Haor"}]','[{"src": "/media/praner-bangladesh/270212-06-haor-winter-guests-1.webp", "width": 960, "height": 1200, "alt": "শীতে হাওরে এত পাখি কেন?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270212-06-haor-winter-guests-2.webp", "width": 960, "height": 1200, "alt": "শীতে হাওরে এত পাখি কেন?, কার্ড 2"}]','["Ehsan Ali Biswas, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Glossy_ibis_(Plegadis_falcinellus)_in_flight,_Tanguar_Haor,_Sunamganj,_Bangladesh.jpg", "Robinhood-birder, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Brown-headed_gull_(Chroicocephalus_brunnicephalus),_Tanguar_Haor%E2%80%93DSC_1959.jpg"]','nature','frog','mint',1,'2027-02-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270219-07-where-did-vultures-go','praner-bangladesh','card','শকুন হারাল কোথায়?','দাদুর ছেলেবেলার আকাশ ভরা ছিল শকুনে','["বাংলা শকুন · সুন্দরবন ও আশেপাশে · অবস্থা: মহাবিপন্ন (IUCN)\\n১. শকুন মরা পশু খেয়ে প্রকৃতিকে পরিষ্কার রাখে।\\n২. গবাদিপশুর এক ব্যথার ওষুধ ডাইক্লোফেনাক মরা পশুর দেহে থেকে যায়।\\n৩. সেই মাংস খেয়ে শকুনের কিডনি নষ্ট হয়: এ অঞ্চলে কমেছে ৯৯ ভাগ।", "এক কথায়: ঝাড়ুদার পাখি বাঁচাতে পশুর ওষুধে সাবধান হতে হবে।\\nমনে রাখুন: গবাদিপশুকে ডাইক্লোফেনাক নয়।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/White-rumped_vulture"}, {"label": "Oaks et al. 2004", "url": ""}]','[{"src": "/media/praner-bangladesh/270219-07-where-did-vultures-go-1.webp", "width": 960, "height": 1200, "alt": "শকুন হারাল কোথায়?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270219-07-where-did-vultures-go-2.webp", "width": 960, "height": 1200, "alt": "শকুন হারাল কোথায়?, কার্ড 2"}]','["Mahmudul Bari, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:White-rumped_vulture_Sunderbans_Bangladesh.jpg", "Shantanu Kuveskar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:White-rumped_vulture_(Gyps_bengalensis)_Close-up_by_Shantanu_Kuveskar.jpg"]','nature','frog','mint',1,'2027-02-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270226-08-jackfruit-on-the-trunk','praner-bangladesh','card','কাঁঠাল ডালে নয়, গুঁড়িতে কেন?','এত ভারী ফল, তাই ঝোলে মোটা কাণ্ডে','["কাঁঠাল · সারা দেশে, বেশি গাজীপুর-টাঙ্গাইলে · জাতীয় ফল\\n১. কাঁঠাল বাংলাদেশের জাতীয় ফল।\\n২. ফুল আর ফল ধরে মূল কাণ্ড আর মোটা ডালের গোড়ায়।\\n৩. একেকটি কাঁঠাল ১৫-২০ কেজি, কখনো আরও ভারী হয়।", "এক কথায়: বিশাল ফলের ভার বইতে কাঁঠাল ধরে গাছের গুঁড়িতেই।\\nগাছে দেখুন: কাঁঠাল গাছের কাণ্ডে ঝুলন্ত ছোট মুচি।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jackfruit"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Jackfruit"}]','[{"src": "/media/praner-bangladesh/270226-08-jackfruit-on-the-trunk-1.webp", "width": 960, "height": 1200, "alt": "কাঁঠাল ডালে নয়, গুঁড়িতে কেন?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270226-08-jackfruit-on-the-trunk-2.webp", "width": 960, "height": 1200, "alt": "কাঁঠাল ডালে নয়, গুঁড়িতে কেন?, কার্ড 2"}]','["Ssemmanda will, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Jackfruit_growing_on_tree_trunk_in_Uganda.jpg", "Tusasirwe Mackline, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Jackfruit_hanging_on_the_tree.jpg"]','nature','frog','mint',1,'2027-02-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270305-09-breathing-roots','praner-bangladesh','card','কাদা থেকে শিকড় উঁকি দেয় কেন?','সুন্দরবনের গাছ শ্বাস নেয় মাটির ওপরে','["সুন্দরবনের গাছ · সুন্দরবন · বিশ্ব ঐতিহ্য বন\\n১. সুন্দরবনের কাদা জোয়ারে বারবার পানিতে ডোবে।\\n২. এমন ভেজা মাটিতে শিকড়ের বাতাস পাওয়া কঠিন।\\n৩. তাই অনেক গাছের শিকড় খাড়া হয়ে ওপরে ওঠে: শ্বাসমূল দিয়ে বাতাস নেয়।", "এক কথায়: শ্বাসমূল: সুন্দরবনের গাছের স্নরকেল।\\nসুন্দরবনে দেখুন: ভাটায় কাদায় সারি সারি খাড়া শিকড়।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pneumatophore"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Sundarbans,_The"}]','[{"src": "/media/praner-bangladesh/270305-09-breathing-roots-1.webp", "width": 960, "height": 1200, "alt": "কাদা থেকে শিকড় উঁকি দেয় কেন?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270305-09-breathing-roots-2.webp", "width": 960, "height": 1200, "alt": "কাদা থেকে শিকড় উঁকি দেয় কেন?, কার্ড 2"}]','["MD AMANAT ULLAH, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_mudflats_with_pneumatophores_at_Sundarbans.jpg", "Emonjnu, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Root_of_a_mangrove_tree.jpg"]','nature','frog','mint',1,'2027-03-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270312-10-tokay-calls-its-name','praner-bangladesh','card','রাতে নিজের নাম ডাকে কে?','তক্-ক্ষক! দেয়ালের অতিথি','["তক্ষক · ঘরের দেয়াল, গাছ · রাতের শিকারি\\n১. তক্ষকের নামই এসেছে তার ডাক থেকে: তক্-ক্ষক।\\n২. রাতে জাগে, পোকামাকড় শিকার করে খায়।\\n৩. আঙুলের নিচে লাখো সূক্ষ্ম লোম: খাড়া দেয়ালেও আটকে থাকে।", "এক কথায়: নিজের নাম ধরে ডাকা নিশাচর শিকারি: তক্ষক।\\nরাতে শুনুন: দেয়ালের দিক থেকে তক্-ক্ষক ডাক।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tokay_gecko"}, {"label": "Autumn et al. 2002", "url": ""}]','[{"src": "/media/praner-bangladesh/270312-10-tokay-calls-its-name-1.webp", "width": 960, "height": 1200, "alt": "রাতে নিজের নাম ডাকে কে?, কার্ড 1"}, {"src": "/media/praner-bangladesh/270312-10-tokay-calls-its-name-2.webp", "width": 960, "height": 1200, "alt": "রাতে নিজের নাম ডাকে কে?, কার্ড 2"}]','["MH Herpetology, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Tokay_gecko_(Gekko_gecko).jpg", "NasserHalaweh, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Gekkonidae_Gekko_gecko_1.jpg"]','nature','frog','mint',1,'2027-03-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270319-11-haor-sea-and-field','praner-bangladesh','card','বর্ষায় সাগর, শীতে মাঠ!','একই জায়গার দুই রূপ','["হাওর · উত্তর-পূর্বের হাওর · জলাভূমি\\n১. হাওর বাটির মতো নিচু বিশাল জলাভূমি, দেশের উত্তর-পূর্বে।\\n২. জুলাই থেকে নভেম্বর গভীর পানিতে ডুবে সাগরের মতো দেখায়।\\n৩. শীতে পানি নামলে সেই জমিতে বোরো ধান চাষ হয়।", "এক কথায়: পানি এলে মাছের রাজ্য, পানি গেলে ধানের মাঠ।\\nছবিতে মেলান: বর্ষা আর শীতের হাওরের ছবি পাশাপাশি রাখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Haor"}, {"label": "Plant-Environment Interactions 2026", "url": ""}]','[{"src": "/media/praner-bangladesh/270319-11-haor-sea-and-field-1.webp", "width": 960, "height": 1200, "alt": "বর্ষায় সাগর, শীতে মাঠ!, কার্ড 1"}, {"src": "/media/praner-bangladesh/270319-11-haor-sea-and-field-2.webp", "width": 960, "height": 1200, "alt": "বর্ষায় সাগর, শীতে মাঠ!, কার্ড 2"}]','["Rafiqul Islam Tushar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Tanguar_Haor.jpg", "Abdul Momin, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Tanguar_haor,_Bangladesh_01.jpg", "Sujoncristi, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Tanguar_Haor_o_jadukata_nodi.jpg"]','nature','frog','mint',1,'2027-03-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261227-zoom-04-sunflower','sobuj-bondhu','card','জুম করে দেখো: সূর্যমুখী','শীতে মাঠ ভরে ফোটে সূর্যমুখী। কাছ থেকে দেখলে:','["১. মাঝের বাদামি অংশটা একটা ফুল নয়, শত শত থেকে হাজারখানেক খুদে ফুলের মেলা!\\n২. বীজগুলো ঘুরানো সারিতে সাজানো। এক দিকের আর উল্টো দিকের সারি গুনলে প্রায়ই পাওয়া যায় ৩৪ আর ৫৫-এর মতো জোড়া, যেগুলো ‘ফিবোনাচ্চি সংখ্যা’।\\n৩. কচি সূর্যমুখী দিনভর সূর্যের দিকে মুখ ঘোরায়, রাতে আবার পূর্বে ফেরে। বড় হলে বেশিরভাগই পূর্বমুখী হয়ে স্থির থাকে।", "পরের বার সূর্যমুখী দেখলে সারিগুলো গুনে দেখবে?"]','[{"label": "Macquarie University", "url": "https://www.mq.edu.au/__data/assets/pdf_file/0006/1255434/Plant-of-the-week-Sunflowers-and-Fibonacci-2023-1.pdf"}, {"label": "KQED / NPR", "url": "https://www.kqed.org/science/900592/the-mystery-of-why-sunflowers-turn-to-follow-the-sun-solved"}]','[{"src": "/media/sobuj-bondhu/261227-zoom-04-sunflower-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখো: সূর্যমুখী, কার্ড 1"}]','["böhringer friedrich (CC BY-SA 2.5), Wikimedia Commons"]','nature','leaf','mint',1,'2026-12-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270205-number-06-bamboo-growth','sobuj-bondhu','card','সংখ্যার ম্যাজিক: ৯১ সেন্টিমিটার','আমাদের গ্রামবাংলার চেনা বাঁশ আসলে গাছ নয়, ঘাসের পরিবারের সদস্য! আর পৃথিবীর সবচেয়ে দ্রুত বাড়া উদ্ভিদদের একটি।','["গিনেস রেকর্ডের হিসাবে সবচেয়ে দ্রুত বাড়া বাঁশ একদিনে প্রায় ৯১ সেন্টিমিটার (প্রায় ৩ ফুট) পর্যন্ত লম্বা হতে পারে। (সব বাঁশ অবশ্য এত দ্রুত বাড়ে না, এটা কিছু প্রজাতির সর্বোচ্চ হার।)", "আপনার বাড়ির আশপাশের বাঁশঝাড়ের একটা কোড়ল মেপে রাখুন, এক সপ্তাহ পর কতটা বাড়ল জানান।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bamboo"}, {"label": "FlipScience", "url": "https://www.flipscience.ph/flipfacts/how-fast-can-bamboo-grow/"}]','[{"src": "/media/sobuj-bondhu/270205-number-06-bamboo-growth-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৯১ সেন্টিমিটার, কার্ড 1"}]','["Mantokun (CC BY-SA 3.0), Wikimedia Commons"]','nature','leaf','mint',1,'2027-02-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270328-zoom-13-shapla','sobuj-bondhu','card','জুম করে দেখুন: শাপলা','পুকুর-বিলের শাপলাকে কাছ থেকে দেখলে:','["১. শাপলা (Nymphaea nouchali) বাংলাদেশের জাতীয় ফুল, দেশের নদী-জলার প্রতীক।\\n২. ওপর থেকে ফুলটাকে দেখায় তারার মতো: ৪-৫টি বৃতি আর ১৩-১৫টি পাপড়ি।\\n৩. আমাদের জাতীয় প্রতীকে পানির ওপর ভেসে থাকা শাপলা আছে।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nymphaea_nouchali"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Emblem_of_Bangladesh"}]','[{"src": "/media/sobuj-bondhu/270328-zoom-13-shapla-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখুন: শাপলা, কার্ড 1"}]','["Azim Khan Ronnie (CC BY-SA 4.0), Wikimedia Commons"]','nature','leaf','mint',1,'2027-03-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270112-02-taro-leaf-stays-dry','sobuj-bondhu','card','কচুপাতায় পানি দাঁড়ায় না কেন?','ফোঁটাগুলো মুক্তোর মতো গড়িয়ে পড়ে','["১. কচুপাতার গায়ে খালি চোখে না-দেখা খুদে খুদে উঁচু দানা।\\n২. তার ওপর মোমের মতো আস্তর: পানি গায়ে লাগতেই পারে না।\\n৩. ফোঁটা গড়িয়ে যাওয়ার সময় ধুলোও তুলে নেয়: পাতা নিজেই পরিষ্কার।", "এক কথায়: খুদে দানা আর মোমের আস্তর: কচুপাতা নিজেই রেইনকোট।\\nঘরে পরীক্ষা: কচু আর কলাপাতায় পানি ঢালুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lotus_effect"}, {"label": "Quantitative Plant Biology 2023", "url": ""}, {"label": "Carbohydrate Polymers 2025", "url": ""}]','[{"src": "/media/sobuj-bondhu/270112-02-taro-leaf-stays-dry-1.webp", "width": 960, "height": 1200, "alt": "কচুপাতায় পানি দাঁড়ায় না কেন?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270112-02-taro-leaf-stays-dry-2.webp", "width": 960, "height": 1200, "alt": "কচুপাতায় পানি দাঁড়ায় না কেন?, কার্ড 2"}]','["Sankar 1995, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Water_drops_on_taro_plant_leaf.jpg", "Shutter Flora, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Wild_taro_leaf_with_water_droplet.jpg"]','nature','leaf','mint',1,'2027-01-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270119-03-banyan-roots-become-trunks','sobuj-bondhu','card','বটগাছের আসল কাণ্ড কোনটা?','ডাল থেকে ঝুরি নামে, মাটিতে পৌঁছে কাণ্ড হয়','["১. বটের ডাল থেকে সরু ঝুরি নিচে নামে।\\n২. ঝুরি মাটি ছুঁলেই শিকড় গাড়ে, মোটা হয়ে নতুন কাণ্ড হয়ে যায়।\\n৩. ঝিনাইদহের বিশ্ববটে ৩৪৫টি ঝুরি মাটিতে নেমেছে: ২.৩৩ হেক্টর জুড়ে।", "এক কথায়: ঝুরিই নতুন খুঁটি: বট একাই একটা বন।\\nখুঁজে দেখুন: বটের ঝুরি গুনুন: কয়টা মাটি ছুঁয়েছে?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ficus_benghalensis"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php?title=Banyan_Tree"}]','[{"src": "/media/sobuj-bondhu/270119-03-banyan-roots-become-trunks-1.webp", "width": 960, "height": 1200, "alt": "বটগাছের আসল কাণ্ড কোনটা?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270119-03-banyan-roots-become-trunks-2.webp", "width": 960, "height": 1200, "alt": "বটগাছের আসল কাণ্ড কোনটা?, কার্ড 2"}]','["Rahul O R, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_great_banyan_tree.jpg", "Chunu gulia, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_great_banyan_tree_in_kolkata.jpg"]','nature','leaf','mint',1,'2027-01-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270126-04-why-leaves-turn-yellow','sobuj-bondhu','card','ঝরার আগে পাতা হলুদ কেন?','সবুজ রংটা সরে গেলে লুকানো হলুদ বেরিয়ে আসে','["১. পাতার সবুজ রং আসে ক্লোরোফিল থেকে: এটা দিয়েই পাতা খাবার বানায়।\\n২. ঝরার আগে ক্লোরোফিল ভেঙে যায়, গাছ পুষ্টি ফিরিয়ে নেয় কাণ্ডে।\\n৩. আগে থেকেই থাকা হলুদ-কমলা রং তখন চোখে পড়ে।", "এক কথায়: হলুদ নতুন নয়: সবুজের নিচে লুকিয়ে ছিল।\\nখুঁজে দেখুন: সবুজ আর হলুদ পাতা পাশাপাশি রাখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Autumn_leaf_color"}, {"label": "Molecular Horticulture 2021", "url": ""}]','[{"src": "/media/sobuj-bondhu/270126-04-why-leaves-turn-yellow-1.webp", "width": 960, "height": 1200, "alt": "ঝরার আগে পাতা হলুদ কেন?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270126-04-why-leaves-turn-yellow-2.webp", "width": 960, "height": 1200, "alt": "ঝরার আগে পাতা হলুদ কেন?, কার্ড 2"}]','["Star61, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Autumn_yellow_leaves.jpg", "Dmitry Makeev, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Yellow_leaves_-_autumn.jpg"]','nature','leaf','mint',1,'2027-01-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270202-05-roots-know-down','sobuj-bondhu','card','বীজ কীভাবে জানে নিচে কোনদিক?','উল্টো করে পুঁতলেও মূল ঘুরে নিচে যায়','["১. মূলের ডগার কোষে ভারী দানা থাকে, তারা নিচে থিতিয়ে পড়ে।\\n২. এতেই মূল টের পায় মাধ্যাকর্ষণ কোনদিকে।\\n৩. এক হরমোন নিচের দিকে জমে মূলকে নিচে বাঁকায়, কাণ্ড যায় ওপরে।", "এক কথায়: মূলের ডগায় খুদে ‘কম্পাস’: মাধ্যাকর্ষণই পথ দেখায়।\\nঘরে পরীক্ষা: ছোলা উল্টো রাখুন: মূল কোথায় যায়?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gravitropism"}, {"label": "PNAS 2003", "url": "https://doi.org/10.1073/pnas.0437936100"}]','[{"src": "/media/sobuj-bondhu/270202-05-roots-know-down-1.webp", "width": 960, "height": 1200, "alt": "বীজ কীভাবে জানে নিচে কোনদিক?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270202-05-roots-know-down-2.webp", "width": 960, "height": 1200, "alt": "বীজ কীভাবে জানে নিচে কোনদিক?, কার্ড 2"}]','["B. Domangue, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Navy_Bean_Seed_to_Seedling_Germination.jpg"]','nature','leaf','mint',1,'2027-02-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270209-06-banana-is-not-a-tree','sobuj-bondhu','card','কলাগাছ কি আসলে গাছ?','‘কাণ্ড’টা আসলে পাতার খোল পেঁচিয়ে তৈরি','["১. কলাগাছ বিশাল এক বীরুৎ, এর কোনো কাঠ নেই, আছে নরম আঁশ।\\n২. ‘কাণ্ড’টা পাতার খোল একটার ভেতর একটা পেঁচিয়ে তৈরি।\\n৩. কাঁদি দিলেই কাণ্ড মরে যায়, গোড়া থেকে নতুন চারা ওঠে।", "এক কথায়: কাঠ নেই, আছে পাতার পেঁচানো খোল।\\nখুঁজে দেখুন: কলাগাছের একটা খোল খুলে দেখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Banana"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php?title=Banana"}]','[{"src": "/media/sobuj-bondhu/270209-06-banana-is-not-a-tree-1.webp", "width": 960, "height": 1200, "alt": "কলাগাছ কি আসলে গাছ?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270209-06-banana-is-not-a-tree-2.webp", "width": 960, "height": 1200, "alt": "কলাগাছ কি আসলে গাছ?, কার্ড 2"}]','["Moheen Reeyad, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Banana_plants,_Mahamaya_Lake_(01).jpg"]','nature','leaf','mint',1,'2027-02-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270216-07-onion-makes-you-cry','sobuj-bondhu','card','পেঁয়াজ কাটলে চোখে পানি কেন?','কাটা মাত্র এক গ্যাস উড়ে যায় চোখের দিকে','["১. পেঁয়াজ কাটলে কোষ ভাঙে, ভেতরের এনজাইম কাজ শুরু করে।\\n২. এতে তৈরি হয় এক উদ্বায়ী রাসায়নিক, বাতাসে ভেসে চোখে পৌঁছায়।\\n৩. চোখ সেটা ধুয়ে ফেলতে পানি ঝরায়।", "এক কথায়: কান্না নয়, চোখের সুরক্ষা: পেঁয়াজের গ্যাস ধুয়ে ফেলে চোখ।\\nরান্নাঘরে দেখুন: ঠান্ডা পেঁয়াজে কান্না কমে কি?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Syn-Propanethial-S-oxide"}, {"label": "J. Experimental Botany 2004", "url": "https://doi.org/10.1093/jxb/erh138"}]','[{"src": "/media/sobuj-bondhu/270216-07-onion-makes-you-cry-1.webp", "width": 960, "height": 1200, "alt": "পেঁয়াজ কাটলে চোখে পানি কেন?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270216-07-onion-makes-you-cry-2.webp", "width": 960, "height": 1200, "alt": "পেঁয়াজ কাটলে চোখে পানি কেন?, কার্ড 2"}]','["Daniel Paullll, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Cut_onions.jpg", "Animeshkulkarni, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Onion_with_sprouts_(cut).JPG"]','nature','leaf','mint',1,'2027-02-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270223-08-sunflowers-face-east','sobuj-bondhu','card','সূর্যমুখী কি সূর্যের দিকে ঘোরে?','ছোটবেলায় ঘোরে, বড় হলে পূর্বে থামে','["১. কচি সূর্যমুখী দিনে পূর্ব থেকে পশ্চিমে সূর্যের সাথে মাথা ঘোরায়।\\n২. রাতে আবার পূর্বদিকে ফিরে ভোরের অপেক্ষা করে: ভেতরের ঘড়ি ধরে।\\n৩. ফুল ফুটে বড় হলে ঘোরা থামে, মুখ থাকে পূর্বদিকে।", "এক কথায়: শৈশবে সূর্যের পিছে ছোটে, বড় হয়ে পূর্বে স্থির।\\nমাঠে দেখুন: সকালে ফুলগুলো কোনদিকে মুখ করা?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Heliotropism"}, {"label": "Atamian et al. 2016", "url": ""}]','[{"src": "/media/sobuj-bondhu/270223-08-sunflowers-face-east-1.webp", "width": 960, "height": 1200, "alt": "সূর্যমুখী কি সূর্যের দিকে ঘোরে?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270223-08-sunflowers-face-east-2.webp", "width": 960, "height": 1200, "alt": "সূর্যমুখী কি সূর্যের দিকে ঘোরে?, কার্ড 2"}]','["Rohitjahnavi, CC0, https://commons.wikimedia.org/wiki/File:Open_Agriculture_Sunflower_Fields,_Ranebennur,_Karnataka._India_(19328).jpg", "Brandon Weeks, CC BY 3.0, https://commons.wikimedia.org/wiki/File:Sunflower_head.jpg"]','nature','leaf','mint',1,'2027-02-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270302-09-how-mangoes-ripen','sobuj-bondhu','card','আম পাকে কীভাবে?','এক অদৃশ্য গ্যাসের সংকেতে','["১. পাকার সময় আম নিজেই ইথিলিন নামের গ্যাস ছাড়ে।\\n২. এই গ্যাস পাকার কাজ আরও বাড়িয়ে দেয়: আম নরম, মিষ্টি, হলুদ হয়।\\n৩. তাই ইথিলিন কমালে আম দেরিতে পাকে, বেশি দিন টেকে।", "এক কথায়: আম পাকে নিজের গ্যাসের সংকেতে: নাম ইথিলিন।\\nঘরে পরীক্ষা: কাঁচা-পাকা আম এক ব্যাগে রাখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ethylene_as_a_plant_hormone"}, {"label": "Plants 2026", "url": "https://en.wikipedia.org/wiki/Ethylene_as_a_plant_hormone"}]','[{"src": "/media/sobuj-bondhu/270302-09-how-mangoes-ripen-1.webp", "width": 960, "height": 1200, "alt": "আম পাকে কীভাবে?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270302-09-how-mangoes-ripen-2.webp", "width": 960, "height": 1200, "alt": "আম পাকে কীভাবে?, কার্ড 2"}]','["OtuNwachinemere, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Low_hanging_ripe_and_unripe_Mango_fruits.jpg", "Rezowan, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Ripe_Mango_Rezowan.JPG"]','nature','leaf','mint',1,'2027-03-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270309-10-coconut-husk-and-sprout','sobuj-bondhu','card','নারকেলের চারা বেরোয় কোথা দিয়ে?','শক্ত খোলের তিন ‘চোখ’-এর একটি দিয়ে','["১. নারকেলের বাইরের ছোবড়া আঁশ দিয়ে তৈরি: এর নাম কয়ার।\\n২. ভেতরের শক্ত খোলে তিনটি ‘চোখ’, তার একটি দিয়েই চারা বেরোয়।\\n৩. ছোবড়া দিয়ে দড়ি, পাপোশ, ব্রাশ বানানো হয় আমাদের দেশে।", "এক কথায়: শক্ত খোল, নরম ‘চোখ’: সেখান দিয়েই নতুন নারকেল গাছ।\\nখুঁজে দেখুন: তিন ‘চোখ’-এর কোনটা নরম?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Coconut"}, {"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php?title=Coconut"}]','[{"src": "/media/sobuj-bondhu/270309-10-coconut-husk-and-sprout-1.webp", "width": 960, "height": 1200, "alt": "নারকেলের চারা বেরোয় কোথা দিয়ে?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270309-10-coconut-husk-and-sprout-2.webp", "width": 960, "height": 1200, "alt": "নারকেলের চারা বেরোয় কোথা দিয়ে?, কার্ড 2"}]','["Pallavi Dessai, CC0, https://commons.wikimedia.org/wiki/File:Coconut_sprouting.jpg", "Marissa Novais, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Kavuto_(_Sprouted_coconut_palm_tree).jpg"]','nature','leaf','mint',1,'2027-03-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270316-11-why-chilli-is-hot','sobuj-bondhu','card','মরিচ ঝাল লাগে কেন?','গরম না, তবু জিভ পোড়ার অনুভূতি','["১. মরিচে থাকে ক্যাপসাইসিন নামের রাসায়নিক।\\n২. এটা জিভের সেই সেন্সর চালু করে, যেটা আসলে গরম টের পায়।\\n৩. সবচেয়ে বেশি থাকে বীজ ধরে রাখা সাদা অংশে, বীজে নয়।", "এক কথায়: মরিচ জিভকে বোকা বানায়: ঠান্ডাতেও আগুন!\\nরান্নাঘরে দেখুন: সাদা অংশ ফেললে ঝাল কমে কি?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Capsaicin"}, {"label": "Caterina et al. 1997", "url": ""}]','[{"src": "/media/sobuj-bondhu/270316-11-why-chilli-is-hot-1.webp", "width": 960, "height": 1200, "alt": "মরিচ ঝাল লাগে কেন?, কার্ড 1"}, {"src": "/media/sobuj-bondhu/270316-11-why-chilli-is-hot-2.webp", "width": 960, "height": 1200, "alt": "মরিচ ঝাল লাগে কেন?, কার্ড 2"}]','["JIP, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Habanero_cut_in_half_on_a_blue_plate.jpg", "ALAMIN, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Green_chili_pepper_on_plant_Bangladesh_1.jpg"]','nature','leaf','mint',1,'2027-03-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261211-number-02-sixteen-sunrises','mohakashe-bhabu','card','সংখ্যার ম্যাজিক: ১৬','আমরা দিনে একবার সূর্যোদয় দেখি। কিন্তু আন্তর্জাতিক মহাকাশ স্টেশনের নভোচারীরা দেখেন প্রায় ১৬ বার!','["স্টেশনটা ঘণ্টায় প্রায় ২৮,০০০ কিলোমিটার বেগে ছুটছে, পৃথিবীকে একবার ঘুরে আসে মাত্র ৯০ মিনিটের মতো সময়ে। প্রতি পাকেই একবার দিন, একবার রাত।", "ভাবো তো, দিনে ১৬ বার ‘শুভ সকাল’ বলতে হলে কেমন লাগত? 😄"]','[{"label": "NASA Earth Observatory", "url": "https://earthobservatory.nasa.gov/Features/EdLu/ed_lu2.php"}, {"label": "Christian Science Monitor", "url": "https://m.csmonitor.com/Science/2016/0517/Around-the-world-in-90-minutes-ISS-completes-100-000th-orbit"}]','[{"src": "/media/mohakashe-bhabu/261211-number-02-sixteen-sunrises-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ১৬, কার্ড 1"}]','["National Aeronautics and Space Administration (Public domain), Wikimedia Commons"]','space','planet','deep',1,'2026-12-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('261220-zoom-03-saturn','mohakashe-bhabu','card','জুম করে দেখো: শনি গ্রহ','সৌরজগতের সবচেয়ে সুন্দর বলয়ওয়ালা গ্রহ শনি। কাছ থেকে দেখলে:','["১. বলয়গুলো আসলে কোটি কোটি বরফ আর পাথরের টুকরো, কোনোটা ধুলোর মতো খুদে, কোনোটা বাড়ির মতো বড়।\\n২. শনির গড় ঘনত্ব পানির চেয়েও কম!\\n৩. শনিতে একটা দিন মাত্র ১০ ঘণ্টা ৩৩ মিনিটের মতো।", "ছবিটা নাসার ক্যাসিনি মহাকাশযানের তোলা। শনির কোন তথ্যটা তোমাকে সবচেয়ে অবাক করল?"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/saturn/facts"}, {"label": "Canadian Space Agency", "url": "https://www.asc-csa.gc.ca/eng/astronomy/solar-system/saturn.asp"}]','[{"src": "/media/mohakashe-bhabu/261220-zoom-03-saturn-1.webp", "width": 960, "height": 1200, "alt": "জুম করে দেখো: শনি গ্রহ, কার্ড 1"}]','["NASA (Public domain), Wikimedia Commons"]','space','planet','deep',1,'2026-12-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270226-number-09-moon-drifting','mohakashe-bhabu','card','সংখ্যার ম্যাজিক: ৩.৮ সেন্টিমিটার','চাঁদ প্রতি বছর পৃথিবী থেকে প্রায় ৩.৮ সেন্টিমিটার করে দূরে সরে যাচ্ছে। নাসা এই তথ্য দিচ্ছে, যার ভিত্তি অ্যাপোলো অভিযানে চাঁদে রেখে আসা আয়নায় লেজার ফেলে নেওয়া মাপ।','["গতিটা প্রায় আমাদের আঙুলের নখ বাড়ার সমান! কারণ: চাঁদ পৃথিবীতে জোয়ার তোলে, আর সেই ঘর্ষণ চাঁদের কক্ষপথকে একটু একটু বড় করছে।"]','[{"label": "NASA JPL", "url": "https://www.jpl.nasa.gov/news/apollo-11-experiment-continues-to-return-valuable-data/"}, {"label": "NASA Eclipse (GSFC)", "url": "https://eclipse.gsfc.nasa.gov/help/ApolloLaser.html"}]','[{"src": "/media/mohakashe-bhabu/270226-number-09-moon-drifting-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৩.৮ সেন্টিমিটার, কার্ড 1"}]','["Gregory H. Revera (CC BY-SA 3.0), Wikimedia Commons"]','space','planet','deep',1,'2027-02-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270101-number-01-earth-speed','mohakashe-bhabu','card','সংখ্যার ম্যাজিক: ৩০ কিমি/সেকেন্ড','নতুন বছর মানে সূর্যকে ঘিরে পৃথিবীর আরেকটা পাক শুরু। এই পথে পৃথিবীর গড় গতি প্রায় ৩০ কিলোমিটার প্রতি সেকেন্ড, মানে ঘণ্টায় প্রায় ১ লাখ ৭ হাজার কিলোমিটার!','["আমরা কেউ টের পাই না, কারণ গতিটা প্রায় সমান থাকে আর পুরো বাতাস, সাগর, মানুষসহ পৃথিবী একসাথেই ছুটছে।\\nএই গতিতে ঢাকা থেকে চট্টগ্রাম যেতে লাগত ১০ সেকেন্ডেরও কম।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Earth%27s_orbit"}, {"label": "Space.com", "url": "https://www.space.com/33527-how-fast-is-earth-moving.html"}]','[{"src": "/media/mohakashe-bhabu/270101-number-01-earth-speed-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৩০ কিমি/সেকেন্ড, কার্ড 1"}]','["NASA/NOAA (Public domain), Wikimedia Commons"]','space','planet','deep',1,'2027-01-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270108-number-02-sunlight-delay','mohakashe-bhabu','card','সংখ্যার ম্যাজিক: ৮ মিনিট ২০ সেকেন্ড','সূর্য থেকে পৃথিবীর দূরত্ব প্রায় ১৫ কোটি কিলোমিটার। আলোর গতিতে ছুটেও এই পথ পার হতে সময় লাগে গড়ে প্রায় ৮ মিনিট ২০ সেকেন্ড (বছরের সময়ভেদে কয়েক সেকেন্ড কম-বেশি)।','["তার মানে আকাশে যে সূর্যটা এখন দেখছেন, সেটা আসলে ৮ মিনিট ২০ সেকেন্ড আগের সূর্য!"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Earth%27s_orbit"}, {"label": "Space.com", "url": "https://www.space.com/33527-how-fast-is-earth-moving.html"}]','[{"src": "/media/mohakashe-bhabu/270108-number-02-sunlight-delay-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৮ মিনিট ২০ সেকেন্ড, কার্ড 1"}]','["NASA''s Scientific Visualization Studio - KBR Wyle Services, LLC/Scott Wiessinger (Public domain), Wikimedia Commons"]','space','planet','deep',1,'2027-01-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270305-number-10-venus-day','mohakashe-bhabu','card','সংখ্যার ম্যাজিক: ২৪৩ দিন','শুক্র গ্রহ নিজের অক্ষে একবার ঘুরতে সময় নেয় প্রায় ২৪৩ পৃথিবী-দিন। অথচ সূর্যকে একবার ঘুরে আসতে লাগে মাত্র প্রায় ২২৫ দিন।','["মানে ঘূর্ণন ধরলে শুক্রের একটা ‘দিন’ ওর ‘বছর’-এর চেয়ে লম্বা! (সূর্যোদয় থেকে সূর্যোদয় ধরলে অবশ্য প্রায় ১১৭ দিন।) মজার ব্যাপার, শুক্র ঘোরে উল্টো দিকে, তাই সেখানে সূর্য উঠত পশ্চিমে।"]','[{"label": "NASA Space Place", "url": "https://spaceplace.nasa.gov/all-about-venus/en/"}, {"label": "Space.com", "url": "https://www.space.com/venus-atomphere-slows-down-rotation"}]','[{"src": "/media/mohakashe-bhabu/270305-number-10-venus-day-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ২৪৩ দিন, কার্ড 1"}]','["NASA/JPL (Public domain), Wikimedia Commons"]','space','planet','deep',1,'2027-03-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270103-01-same-face-of-the-moon','mohakashe-bhabu','card','চাঁদের একটা মুখই দেখি কেন?','বামে রোজ দেখা পাশ, ডানে যে পাশ পৃথিবী থেকে দেখা যায় না','["১. চাঁদ নিজের অক্ষে ঘুরতে যত সময় নেয় (প্রায় ২৭ দিন), পৃথিবীকে এক পাক দিতেও তত।\\n২. তাই ঘুরতে ঘুরতেও তার একই পাশ সবসময় আমাদের দিকে থাকে।\\n৩. উল্টো পিঠ অন্ধকার নয়: সেখানেও সূর্যের আলো পড়ে, শুধু আমরা দেখি না।", "এক কথায়: চাঁদ ঘোরে ঠিকই, কিন্তু ঘোরা আর পাক দেওয়ার তাল এক।\\nআকাশে খুঁজুন: পূর্ণিমায় দেখুন: দাগগুলো কি একই?"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/moon/tidal-locking/"}, {"label": "NASA Science", "url": "https://science.nasa.gov/moon/tidal-locking/"}]','[{"src": "/media/mohakashe-bhabu/270103-01-same-face-of-the-moon-1.webp", "width": 960, "height": 1200, "alt": "চাঁদের একটা মুখই দেখি কেন?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270103-01-same-face-of-the-moon-2.webp", "width": 960, "height": 1200, "alt": "চাঁদের একটা মুখই দেখি কেন?, কার্ড 2"}]','["NASA/GSFC/Arizona State Univer, Public domain, https://commons.wikimedia.org/wiki/File:Moon_nearside_LRO_5000.jpg", "NASA/GSFC/Arizona State Univer, Public domain, https://commons.wikimedia.org/wiki/File:Moon_Farside_LRO.jpg", "NASA/GSFC/Arizona State Univer, Public domain, https://commons.wikimedia.org/wiki/File:Moon_nearside_LRO_color_mosaic.png"]','space','planet','deep',1,'2027-01-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270110-02-jumping-on-the-moon','mohakashe-bhabu','card','চাঁদে লাফ দিলে কত উঁচুতে উঠব?','১৯৭২, অ্যাপোলো ১৬: ভারী স্যুট পরেও জন ইয়াংয়ের লাফ','["১. চাঁদের টান পৃথিবীর মাত্র ছয় ভাগের এক ভাগ।\\n২. ৬০ কেজির মানুষ সেখানে মাত্র ১০ কেজির মতো ভার টের পাবে।\\n৩. একই জোরে লাফ দিলে প্রায় ছয় গুণ উঁচুতে ওঠা যায়, নামাও হয় ধীরে।", "এক কথায়: টান কম, তাই লাফ উঁচু: চাঁদে সবাই একটু সুপারহিরো।\\nঘরে পরীক্ষা: দেয়াল ছুঁয়ে লাফান, উচ্চতা × ৬ করুন।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/moon/facts/"}, {"label": "NASA/Project Apollo Archive photo AS16-1", "url": ""}]','[{"src": "/media/mohakashe-bhabu/270110-02-jumping-on-the-moon-1.webp", "width": 960, "height": 1200, "alt": "চাঁদে লাফ দিলে কত উঁচুতে উঠব?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270110-02-jumping-on-the-moon-2.webp", "width": 960, "height": 1200, "alt": "চাঁদে লাফ দিলে কত উঁচুতে উঠব?, কার্ড 2"}]','["Project Apollo Archive, Public domain, https://commons.wikimedia.org/wiki/File:AS16-113-18339_(21028582504).jpg", "NASA Charles M. Duke Jr., Public domain, https://commons.wikimedia.org/wiki/File:Young_-_GPN-2000-001131.jpg"]','space','planet','deep',1,'2027-01-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270117-03-dark-spots-on-the-sun','mohakashe-bhabu','card','সূর্যের গায়ে কালো দাগ কেন?','নাসার মহাকাশযান থেকে তোলা সূর্য: গায়ে কালো ফুটকি','["১. এই দাগের নাম সৌরকলঙ্ক (সানস্পট); এগুলো সূর্যের তুলনামূলক ঠান্ডা জায়গা।\\n২. চারপাশ প্রায় ৫,৫০০°সে, দাগ প্রায় ৩,৩০০°সে: কম গরম, তাই কম উজ্জ্বল।\\n৩. চৌম্বক ক্ষেত্র তাপ আটকায়; কোনো কোনো দাগ পৃথিবীর চেয়েও বড়।", "এক কথায়: দাগ পোড়া নয়: আশপাশের চেয়ে ঠান্ডা, তাই কালো।\\nসাবধান: সূর্যের দিকে খালি চোখে কখনো তাকাবেন না।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/sun/sunspots/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sunspot"}]','[{"src": "/media/mohakashe-bhabu/270117-03-dark-spots-on-the-sun-1.webp", "width": 960, "height": 1200, "alt": "সূর্যের গায়ে কালো দাগ কেন?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270117-03-dark-spots-on-the-sun-2.webp", "width": 960, "height": 1200, "alt": "সূর্যের গায়ে কালো দাগ কেন?, কার্ড 2"}]','["NASA/SDO/HMI, CC BY 4.0, https://commons.wikimedia.org/wiki/File:The_Sun_with_sunspots_(iau1508d).jpg", "NASA/SDO/HMI, CC BY 4.0, https://commons.wikimedia.org/wiki/File:The_Sun_with_sunspots_(iau1508d).jpg"]','space','planet','deep',1,'2027-01-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270124-04-shooting-star-is-not-a-star','mohakashe-bhabu','card','খসে পড়া তারা কি সত্যিই তারা?','রাতের আকাশে এক ঝলক আলোর দাগ','["১. ওটা তারা নয়: মহাকাশের ছোট্ট পাথর বা ধুলোর কণা, নাম উল্কা।\\n২. বেশির ভাগই বালুকণা বা মটরের সমান।\\n৩. প্রচণ্ড বেগে বাতাসে ঢুকে প্রায় ৮০-১২০ কিমি ওপরে গরম হয়ে জ্বলে ওঠে।", "এক কথায়: খসা তারা আসলে জ্বলন্ত ধুলোকণা, তারা নয়।\\nআকাশে খুঁজুন: শীতের রাতে মাঠে আকাশ দেখুন।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/solar-system/meteors-meteorites/facts/"}, {"label": "American Meteor Society", "url": ""}]','[{"src": "/media/mohakashe-bhabu/270124-04-shooting-star-is-not-a-star-1.webp", "width": 960, "height": 1200, "alt": "খসে পড়া তারা কি সত্যিই তারা?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270124-04-shooting-star-is-not-a-star-2.webp", "width": 960, "height": 1200, "alt": "খসে পড়া তারা কি সত্যিই তারা?, কার্ড 2"}]','["John Flannery from Richmond Co, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Geminid_Meteor_-_Dec._2012.jpg", "theilr, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Perseid_color_-_Flickr_-_theilr.jpg"]','space','planet','deep',1,'2027-01-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270131-05-what-saturn-rings-are-made-of','mohakashe-bhabu','card','শনির বলয় কী দিয়ে তৈরি?','ক্যাসিনির চোখে ওপর থেকে শনি: বলয়ে সরু ফাঁকও আছে','["১. বলয় একটা শক্ত চাকতি নয়: কোটি কোটি বরফ আর পাথরের টুকরো।\\n২. টুকরোগুলো ধুলোর মতো ছোট থেকে বাড়ির সমান বড়।\\n৩. এত চওড়া বলয়, কিন্তু মূল অংশ মাত্র ১০ মিটারের মতো পুরু।", "এক কথায়: শনির বলয় আসলে বরফকুচির বিশাল মিছিল।\\nআকাশে খুঁজুন: ছোট দূরবিনেও শনির বলয় দেখা যায়।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/saturn/facts/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rings_of_Saturn"}]','[{"src": "/media/mohakashe-bhabu/270131-05-what-saturn-rings-are-made-of-1.webp", "width": 960, "height": 1200, "alt": "শনির বলয় কী দিয়ে তৈরি?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270131-05-what-saturn-rings-are-made-of-2.webp", "width": 960, "height": 1200, "alt": "শনির বলয় কী দিয়ে তৈরি?, কার্ড 2"}]','["NASA/JPL-Caltech/SSI/Cornell, Public domain, https://commons.wikimedia.org/wiki/File:Top_view_of_the_rings_of_Saturn_by_Cassini_-_October_10,_2013.jpg", "NASA / JPL / Space Science Ins, Public domain, https://commons.wikimedia.org/wiki/File:Saturn_during_Equinox.jpg"]','space','planet','deep',1,'2027-01-31');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270207-06-how-astronauts-sleep','mohakashe-bhabu','card','মহাকাশে ঘুমায় কীভাবে?','মহাকাশ স্টেশনে সামান্থা ক্রিস্টোফোরেত্তির ছোট্ট শোবার ঘর','["১. মহাকাশ স্টেশনে ওপর-নিচ নেই; বিছানায় শুলেও ভেসে যেতে হয়।\\n২. তাই স্লিপিং ব্যাগ বাঁধা থাকে দেয়ালে।\\n৩. না বাঁধলে ঘুমের মধ্যে ভেসে গিয়ে যন্ত্রে ধাক্কা লাগতে পারে।", "এক কথায়: মহাকাশে বিছানা দেয়ালে: দাঁড়িয়েও ঘুমানো যায়!\\nঘরে পরীক্ষা: দেয়ালে পিঠ ঠেকিয়ে চোখ বুজুন।"]','[{"label": "ESA", "url": "https://www.esa.int/ESA_Multimedia/Images/2022/01/Samantha_s_sleeping_quarters"}, {"label": "NASA photo ISS042", "url": ""}]','[{"src": "/media/mohakashe-bhabu/270207-06-how-astronauts-sleep-1.webp", "width": 960, "height": 1200, "alt": "মহাকাশে ঘুমায় কীভাবে?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270207-06-how-astronauts-sleep-2.webp", "width": 960, "height": 1200, "alt": "মহাকাশে ঘুমায় কীভাবে?, কার্ড 2"}]','["NASA, Public domain, https://commons.wikimedia.org/wiki/File:ISS-42_Samantha_Cristoforetti_in_her_personal_crew_quarters.jpg", "NASA/Crew of STS-132, Public domain, https://commons.wikimedia.org/wiki/File:International_Space_Station_after_undocking_of_STS-132.jpg"]','space','planet','deep',1,'2027-02-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270214-07-moon-in-the-daytime','mohakashe-bhabu','card','দিনেও চাঁদ দেখা যায় কেন?','ঝকঝকে নীল আকাশে আধখানা চাঁদ','["১. চাঁদ রাতের মতো দিনেও প্রায় সমান সময় আকাশে থাকে।\\n২. সে সূর্যের আলো ফেরায়, আর এত উজ্জ্বল যে দিনের আকাশকেও হারায়।\\n৩. তারারাও দিনে আকাশে থাকে, কিন্তু আকাশ বেশি উজ্জ্বল বলে দেখা যায় না।", "এক কথায়: চাঁদ দিনের আলোকেও হারায়; তারারা পারে না।\\nআকাশে খুঁজুন: অষ্টমীর বিকেলে পূর্ব আকাশে চাঁদ খুঁজুন।"]','[{"label": "NASA", "url": "https://www.nasa.gov/feature/episode-19-we-asked-a-nasa-scientist-why-can-you-see-the-moon-during-the-day"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rayleigh_scattering"}]','[{"src": "/media/mohakashe-bhabu/270214-07-moon-in-the-daytime-1.webp", "width": 960, "height": 1200, "alt": "দিনেও চাঁদ দেখা যায় কেন?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270214-07-moon-in-the-daytime-2.webp", "width": 960, "height": 1200, "alt": "দিনেও চাঁদ দেখা যায় কেন?, কার্ড 2"}]','["Philippe Alès, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Moon_in_daytime.jpg", "Robert Kixmiller, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Daytime_moon_december_2017.jpg"]','space','planet','deep',1,'2027-02-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270221-08-why-the-moon-keeps-its-craters','mohakashe-bhabu','card','চাঁদে এত গর্ত কেন?','অ্যাপোলো ১৭ থেকে তোলা কোপার্নিকাস খাদ','["১. পৃথিবী আর চাঁদ দুজনেই কোটি বছর ধরে মহাকাশের পাথরের আঘাত খেয়েছে।\\n২. পৃথিবীতে বাতাস, বৃষ্টি, গাছপালা আর ভূমিকম্প গর্ত মুছে দেয়।\\n৩. চাঁদে বাতাস-পানি নেই: দুইশো কোটি বছরের পুরোনো গর্তও রয়ে গেছে।", "এক কথায়: চাঁদ আঘাত ভোলে না: মুছে দেওয়ার কেউ নেই।\\nআকাশে খুঁজুন: দূরবিনে চাঁদের কিনারার গর্ত দেখুন।"]','[{"label": "NASA Space Place", "url": "https://spaceplace.nasa.gov/craters/en"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lunar_craters"}]','[{"src": "/media/mohakashe-bhabu/270221-08-why-the-moon-keeps-its-craters-1.webp", "width": 960, "height": 1200, "alt": "চাঁদে এত গর্ত কেন?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270221-08-why-the-moon-keeps-its-craters-2.webp", "width": 960, "height": 1200, "alt": "চাঁদে এত গর্ত কেন?, কার্ড 2"}]','["NASA, Public domain, https://commons.wikimedia.org/wiki/File:Copernicus_crater_AS17-151-23260.jpg", "John Caldwell (York University, Public domain, https://commons.wikimedia.org/wiki/File:Crater_copernicus_on_the_Moon_(opo9914c).jpg"]','space','planet','deep',1,'2027-02-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270228-09-seeing-the-space-station','mohakashe-bhabu','card','মহাকাশ স্টেশন খালি চোখে দেখা যায়?','সন্ধ্যার আকাশে লম্বা এক্সপোজারে স্টেশনের পথ','["১. হ্যাঁ! প্রায় ৪০০ কিমি ওপরে, দেখতে এক উজ্জ্বল চলন্ত তারার মতো।\\n২. নিজের আলো নেই: সূর্যোদয়-সূর্যাস্তের কাছাকাছি সূর্যের আলো ফেরায়।\\n৩. ঘণ্টায় প্রায় ২৮,০০০ কিমি বেগে ছোটে, ৯৩ মিনিটে পৃথিবী এক পাক।", "এক কথায়: জ্বলে-নেভে না, সোজা চলে: ওটাই মহাকাশ স্টেশন।\\nআকাশে খুঁজুন: নাসার Spot the Station-এ সময় দেখুন।"]','[{"label": "NASA", "url": "https://www.nasa.gov/spot-the-station/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/International_Space_Station"}]','[{"src": "/media/mohakashe-bhabu/270228-09-seeing-the-space-station-1.webp", "width": 960, "height": 1200, "alt": "মহাকাশ স্টেশন খালি চোখে দেখা যায়?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270228-09-seeing-the-space-station-2.webp", "width": 960, "height": 1200, "alt": "মহাকাশ স্টেশন খালি চোখে দেখা যায়?, কার্ড 2"}]','["MichaelALearmonth, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_ISS_passing_nearly_overhead_shortly_after_sunset_in_June_2014.jpg", "NASA, Public domain, https://commons.wikimedia.org/wiki/File:STS-134_International_Space_Station_after_undocking.jpg"]','space','planet','deep',1,'2027-02-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270307-10-why-the-moon-has-phases','mohakashe-bhabu','card','চাঁদ কখনো গোল, কখনো কাস্তে কেন?','এক মাসের চাঁদ, একটার পর একটা','["১. চাঁদের অর্ধেকটা সবসময় সূর্যের আলোয় আলোকিত থাকে।\\n২. পৃথিবীকে ঘুরতে ঘুরতে সেই আলো-অর্ধেকের যতটা আমাদের দিকে, ততটাই দেখি।\\n৩. ছায়া নয়: পুরো চক্র প্রায় ২৯.৫ দিনের।", "এক কথায়: চাঁদ বদলায় না: বদলায় আমাদের দেখার কোণ।\\nঘরে পরীক্ষা: অন্ধকার ঘরে টর্চ আর বল দিয়ে কলা বানান।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/moon/moon-phases/"}, {"label": "NASA Science", "url": "https://science.nasa.gov/moon/moon-phases/"}]','[{"src": "/media/mohakashe-bhabu/270307-10-why-the-moon-has-phases-1.webp", "width": 960, "height": 1200, "alt": "চাঁদ কখনো গোল, কখনো কাস্তে কেন?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270307-10-why-the-moon-has-phases-2.webp", "width": 960, "height": 1200, "alt": "চাঁদ কখনো গোল, কখনো কাস্তে কেন?, কার্ড 2"}]','["Jun from Sagamihara, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Joka2000_-_Moon_in_Dec_2005_(by).jpg", "PumpkinSky, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Clouds_passing_Blue_Super_Moon_1.jpg"]','space','planet','deep',1,'2027-03-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270314-11-red-moon-in-an-eclipse','mohakashe-bhabu','card','চন্দ্রগ্রহণে চাঁদ লাল কেন?','পূর্ণ গ্রহণের সময় তোলা চাঁদ','["১. পূর্ণিমায় পৃথিবী সূর্য আর চাঁদের মাঝে এলে চাঁদ পৃথিবীর ছায়ায় ঢাকে।\\n২. তবু কিছু সূর্যালোক পৃথিবীর বাতাস পেরিয়ে বেঁকে ছায়ায় ঢোকে।\\n৩. বাতাস নীল আলো ছড়িয়ে ফেলে; বাকি লালচে আলোয় চাঁদ লাল দেখায়।", "এক কথায়: লাল চাঁদে পৃথিবীর সব সূর্যোদয়-সূর্যাস্তের আলো।\\nআকাশে খুঁজুন: চন্দ্রগ্রহণ খালি চোখে দেখা নিরাপদ।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/eclipses/types/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lunar_eclipse"}]','[{"src": "/media/mohakashe-bhabu/270314-11-red-moon-in-an-eclipse-1.webp", "width": 960, "height": 1200, "alt": "চন্দ্রগ্রহণে চাঁদ লাল কেন?, কার্ড 1"}, {"src": "/media/mohakashe-bhabu/270314-11-red-moon-in-an-eclipse-2.webp", "width": 960, "height": 1200, "alt": "চন্দ্রগ্রহণে চাঁদ লাল কেন?, কার্ড 2"}]','["Giuseppe Donatiello from Oria , CC0, https://commons.wikimedia.org/wiki/File:Lunar_eclipse_on_September_7,_2025_-_Totality_phase_(54774860817).jpg", "Giuseppe Donatiello from Oria , CC0, https://commons.wikimedia.org/wiki/File:Lunar_eclipse_of_February_21,_1989_(53252022745).jpg"]','space','planet','deep',1,'2027-03-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270104-01-invisible-light-of-the-remote','odrissho-mohabishwo','card','রিমোটের আলো চোখে দেখি না কেন?','ফোনের ক্যামেরায় তোলা ছবি: রিমোটের মাথায় জ্বলছে আলো','["১. রিমোট পাঠায় ইনফ্রারেড আলো, ঢেউ প্রায় ৯৪০ ন্যানোমিটার লম্বা।\\n২. এই আলো লালের চেয়েও লম্বা ঢেউয়ের: মানুষের চোখ ধরতে পারে না।\\n৩. ফোন বা ডিজিটাল ক্যামেরার সেন্সর ধরে: তাই পর্দায় বেগুনি-সাদা আলো।", "এক কথায়: আলো আছে, চোখ দেখে না: ক্যামেরা দেখে।\\nঘরে পরীক্ষা: ফোনের ক্যামেরা রিমোটে ধরে বোতাম চাপুন।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/ems/07_infraredwaves/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Remote_control"}]','[{"src": "/media/odrissho-mohabishwo/270104-01-invisible-light-of-the-remote-1.webp", "width": 960, "height": 1200, "alt": "রিমোটের আলো চোখে দেখি না কেন?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270104-01-invisible-light-of-the-remote-2.webp", "width": 960, "height": 1200, "alt": "রিমোটের আলো চোখে দেখি না কেন?, কার্ড 2"}]','["Damien Ramon Naidoo, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Infrared_LEDs_on_Remote.jpg", "Damien Ramon Naidoo, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Infrared_LEDs_on_Windows_Media_Remote.jpg"]','physics','atom','deep',1,'2027-01-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270111-02-does-a-black-hole-eat-everything','odrissho-mohabishwo','card','ব্ল্যাক হোল কি সব গিলে খায়?','২০১৯: প্রথমবার তোলা ব্ল্যাক হোলের ছবি (M87)','["১. দূর থেকে ব্ল্যাক হোলের টান একই ভরের যেকোনো বস্তুর মতোই।\\n২. সূর্যের জায়গায় সমান ভরের ব্ল্যাক হোল বসালে গ্রহরা একই পথে ঘুরত।\\n৩. শুধু ‘ঘটনা দিগন্ত’ পেরোলে আর ফেরা নেই, আলোরও না।", "এক কথায়: ব্ল্যাক হোল ভ্যাকুয়াম ক্লিনার নয়: কাছে গেলেই বিপদ।\\nভেবে দেখুন: সূর্য ব্ল্যাক হোল হলে দিন কেমন হতো?"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/universe/black-holes/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Messier_87"}]','[{"src": "/media/odrissho-mohabishwo/270111-02-does-a-black-hole-eat-everything-1.webp", "width": 960, "height": 1200, "alt": "ব্ল্যাক হোল কি সব গিলে খায়?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270111-02-does-a-black-hole-eat-everything-2.webp", "width": 960, "height": 1200, "alt": "ব্ল্যাক হোল কি সব গিলে খায়?, কার্ড 2"}]','["Event Horizon Telescope, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Black_hole_-_Messier_87_crop_max_res.jpg", "EHT Collaboration, CC BY 4.0, https://commons.wikimedia.org/wiki/File:A_view_of_the_M87_supermassive_black_hole_in_polarised_light.tif"]','physics','atom','deep',1,'2027-01-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270208-06-made-of-star-dust','odrissho-mohabishwo','card','আমরা কি তারার ধুলো?','ক্র্যাব নীহারিকা: ১০৫৪ সালে দেখা এক তারা-বিস্ফোরণের ছাই','["১. কার্বন, অক্সিজেন, লোহার মতো উপাদান তৈরি হয় তারার ভেতরে।\\n২. বড় তারা বিস্ফোরিত হলে সেগুলো মহাকাশে ছড়িয়ে পড়ে।\\n৩. সেই ধুলোতেই গড়া নতুন গ্রহ, আমরাও।", "এক কথায়: আপনার শরীরের লোহা একদিন কোনো তারার ভেতরে ছিল।\\nভেবে দেখুন: রক্তের লোহা কোন তারায় তৈরি হয়েছিল?"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/universe/stars/"}, {"label": "NASA Hubble", "url": "https://science.nasa.gov/universe/stars/"}]','[{"src": "/media/odrissho-mohabishwo/270208-06-made-of-star-dust-1.webp", "width": 960, "height": 1200, "alt": "আমরা কি তারার ধুলো?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270208-06-made-of-star-dust-2.webp", "width": 960, "height": 1200, "alt": "আমরা কি তারার ধুলো?, কার্ড 2"}]','["NASA, Public domain, https://commons.wikimedia.org/wiki/File:Crab_Nebula.jpg", "Hubble Space Telescope, Public domain, https://commons.wikimedia.org/wiki/File:Crab_Nebula_(3885).jpg"]','physics','atom','deep',1,'2027-02-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270215-07-is-darkness-a-thing','odrissho-mohabishwo','card','অন্ধকার কি কোনো জিনিস?','অন্ধকার ঘরে একটা মোমবাতি','["১. অন্ধকার আলাদা কিছু নয়: আলো না থাকার নামই অন্ধকার।\\n২. কোনো জিনিস দেখি তখনই, যখন তার আলো আমাদের চোখে ঢোকে।\\n৩. মোমবাতি জ্বালালে অন্ধকার ‘তাড়ায়’ না: আলো এসে জায়গা ভরে।", "এক কথায়: অন্ধকার আসে না, আলো চলে যায়।\\nঘরে পরীক্ষা: অন্ধকার ঘরে টর্চ জ্বেলে দেয়ালে ফেলুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Darkness"}, {"label": "NASA Science", "url": "https://science.nasa.gov/ems/09_visiblelight/"}]','[{"src": "/media/odrissho-mohabishwo/270215-07-is-darkness-a-thing-1.webp", "width": 960, "height": 1200, "alt": "অন্ধকার কি কোনো জিনিস?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270215-07-is-darkness-a-thing-2.webp", "width": 960, "height": 1200, "alt": "অন্ধকার কি কোনো জিনিস?, কার্ড 2"}]','["Le Priyavrat, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Small_candle_flame.jpg", "Shan Sheehan, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Candle_flame_by_Shan_Sheehan.jpg"]','physics','atom','deep',1,'2027-02-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270222-08-sunlight-takes-8-minutes','odrissho-mohabishwo','card','সূর্যের আলো আসতে কত সময় লাগে?','কুড়িগ্রামের ভোর: এই আলো রওনা দিয়েছে ৮ মিনিট আগে','["১. আলো সেকেন্ডে প্রায় ৩ লাখ কিমি ছোটে।\\n২. তবু সূর্য থেকে পৃথিবী আসতে লাগে প্রায় ৮ মিনিট ২০ সেকেন্ড।\\n৩. তাই সূর্যকে দেখি ৮ মিনিট আগের রূপে।", "এক কথায়: ভোরের সূর্য আসলে একটু পুরোনো সূর্য।\\nসাবধান: সূর্যের দিকে খালি চোখে তাকাবেন না।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Speed_of_light"}, {"label": "NASA Science", "url": "https://science.nasa.gov/learn/basics-of-space-flight/chapter1-1/"}]','[{"src": "/media/odrissho-mohabishwo/270222-08-sunlight-takes-8-minutes-1.webp", "width": 960, "height": 1200, "alt": "সূর্যের আলো আসতে কত সময় লাগে?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270222-08-sunlight-takes-8-minutes-2.webp", "width": 960, "height": 1200, "alt": "সূর্যের আলো আসতে কত সময় লাগে?, কার্ড 2"}]','["Tanvir Rahat, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fishing_scene_at_sunrise,_Kurigram,_Bangladesh.jpg", "Emonjnu, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sunrise_from_a_river_of_sundarbans.jpg"]','physics','atom','deep',1,'2027-02-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270301-09-is-the-universe-growing','odrissho-mohabishwo','card','মহাবিশ্ব কি বড় হচ্ছে?','হাবলের ছবি: আকাশের ছোট্ট এক টুকরোয় প্রায় ১০,০০০ ছায়াপথ','["১. দূরের ছায়াপথগুলো পরস্পর থেকে সরছে।\\n২. এই ছবির অনেক আলো প্রায় ১৩০০ কোটি বছরের পুরোনো।\\n৩. প্রসারণ এখন আরও দ্রুত হচ্ছে; কারণের নাম ডার্ক এনার্জি, রহস্য এখনো।", "এক কথায়: মহাবিশ্ব ফুলছে, কেন জোরে ফুলছে কেউ জানে না।\\nঘরে পরীক্ষা: বেলুনে বিন্দু এঁকে ফোলান, দূরত্ব দেখুন।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/dark-energy/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hubble_Ultra-Deep_Field"}]','[{"src": "/media/odrissho-mohabishwo/270301-09-is-the-universe-growing-1.webp", "width": 960, "height": 1200, "alt": "মহাবিশ্ব কি বড় হচ্ছে?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270301-09-is-the-universe-growing-2.webp", "width": 960, "height": 1200, "alt": "মহাবিশ্ব কি বড় হচ্ছে?, কার্ড 2"}]','["NASA and the European Space Ag, Public domain, https://commons.wikimedia.org/wiki/File:Hubble_ultra_deep_field.jpg", "NASA, Public domain, https://commons.wikimedia.org/wiki/File:NASA-HS201427a-HubbleUltraDeepField2014-20140603.jpg"]','physics','atom','deep',1,'2027-03-01');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270308-10-does-energy-run-out','odrissho-mohabishwo','card','শক্তি কি শেষ হয়ে যায়?','নৌকার ছাদে সোলার প্যানেল: রোদ বদলে যাচ্ছে বিদ্যুতে','["১. শক্তি সৃষ্টিও হয় না, ধ্বংসও না।\\n২. সোলার প্যানেল রোদকে বিদ্যুৎ বানায়, বিদ্যুৎ বাতিতে আলো আর তাপ।\\n৩. ফুরায় শুধু সহজে কাজে লাগানোর শক্তি।", "এক কথায়: শক্তি ফুরায় না, শুধু রূপ বদলায়।\\nভেবে দেখুন: ভাত খেলে শক্তি কোথা থেকে আসে?"]','[{"label": "OpenStax College Physics 2e", "url": "https://openstax.org/books/college-physics-2e/pages/7-6-conservation-of-energy"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Conservation_of_energy"}]','[{"src": "/media/odrissho-mohabishwo/270308-10-does-energy-run-out-1.webp", "width": 960, "height": 1200, "alt": "শক্তি কি শেষ হয়ে যায়?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270308-10-does-energy-run-out-2.webp", "width": 960, "height": 1200, "alt": "শক্তি কি শেষ হয়ে যায়?, কার্ড 2"}]','["Helena Wright, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Solar_panel_on_boat_(36676764031).jpg", "HokuroN, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hatil_rooftop_solar_panels.jpg"]','physics','atom','deep',1,'2027-03-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270315-11-why-the-night-sky-is-dark','odrissho-mohabishwo','card','এত তারা, তবু রাত অন্ধকার কেন?','রাতের আকাশ: অসংখ্য তারা, মাঝে কালো ফাঁক','["১. মহাবিশ্বের বয়স সীমিত: অনেক দূরের তারার আলো এখনো পৌঁছায়নি।\\n২. মহাবিশ্ব প্রসারিত হচ্ছে: পুরোনো আলো টেনে লম্বা হয়ে চোখের বাইরে।\\n৩. তাই তারার ফাঁকে আকাশ কালো থাকে।", "এক কথায়: আকাশ কালো, কারণ মহাবিশ্বের একটা জন্মদিন আছে।\\nআকাশে খুঁজুন: শহরের বাইরে গেলে কত তারা বাড়ে?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Olbers%27s_paradox"}, {"label": "NASA Science", "url": "https://science.nasa.gov/dark-energy/"}]','[{"src": "/media/odrissho-mohabishwo/270315-11-why-the-night-sky-is-dark-1.webp", "width": 960, "height": 1200, "alt": "এত তারা, তবু রাত অন্ধকার কেন?, কার্ড 1"}, {"src": "/media/odrissho-mohabishwo/270315-11-why-the-night-sky-is-dark-2.webp", "width": 960, "height": 1200, "alt": "এত তারা, তবু রাত অন্ধকার কেন?, কার্ড 2"}]','["Arnab1804, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Dark_night_sky.jpg", "Talesofaviewfinder, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Starry_night_2025.jpg"]','physics','atom','deep',1,'2027-03-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270212-number-07-lightning-heat','kibhabe-chole','card','সংখ্যার ম্যাজিক: ৩০,০০০°','একটা বাজ পড়ার সময় তার পথের বাতাস প্রায় ৩০,০০০ ডিগ্রি সেলসিয়াস পর্যন্ত গরম হয়ে যায়, যা সূর্যের পৃষ্ঠের তাপমাত্রার প্রায় পাঁচ গুণ (সূর্যের পৃষ্ঠ প্রায় ৫,৫০০°)। (এটা চূড়ান্ত মান, ঠিক মাপা কঠিন বলে মূলত আলোর বর্ণালি থেকে হিসাব করা হয়।)','["গরম বাতাস হঠাৎ ফুলে ওঠে, আর সেই ধাক্কাই আমাদের কানে বজ্রের শব্দ।"]','[{"label": "NOAA JetStream", "url": "https://www.noaa.gov/jetstream/lightning/sound-of-thunder"}, {"label": "BBC Science Focus", "url": "https://www.sciencefocus.com/planet-earth/why-lightning-is-so-powerful"}]','[{"src": "/media/kibhabe-chole/270212-number-07-lightning-heat-1.webp", "width": 960, "height": 1200, "alt": "সংখ্যার ম্যাজিক: ৩০,০০০°, কার্ড 1"}]','["Friedrich Haag (CC BY-SA 4.0), Wikimedia Commons"]','physics','bolt','coral',1,'2027-02-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270107-01-why-the-clay-kolshi-keeps-water-cool','kibhabe-chole','card','মাটির কলসির পানি ঠান্ডা থাকে কীভাবে?','পোড়ামাটির কলসি: গায়ে অসংখ্য খুদে ছিদ্র','["১. কাঁচা পোড়ামাটির গায়ে খুদে ছিদ্র; ভেতরের পানি একটু একটু চুঁইয়ে বাইরে আসে।\\n২. বাইরের গায়ে সেই পানি বাষ্প হয়ে উড়ে যায়।\\n৩. বাষ্প হতে তাপ লাগে; সেই তাপ নেয় কলসির গা আর ভেতরের পানি।", "এক কথায়: কলসি ঘামে, তাই ভেতরের পানি ঠান্ডা থাকে।\\nঘরে পরীক্ষা: কলসির গায়ে হাত দিন: ভেজা, ঠান্ডা?"]','[{"label": "The Star Malaysia QuickCheck", "url": "https://thestar.com.my/news/true-or-not/2023/06/14/quickcheck-do-clay-039labu039-make-drinking-water-cooler"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Evaporative_cooler"}]','[{"src": "/media/kibhabe-chole/270107-01-why-the-clay-kolshi-keeps-water-cool-1.webp", "width": 960, "height": 1200, "alt": "মাটির কলসির পানি ঠান্ডা থাকে কীভাবে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270107-01-why-the-clay-kolshi-keeps-water-cool-2.webp", "width": 960, "height": 1200, "alt": "মাটির কলসির পানি ঠান্ডা থাকে কীভাবে?, কার্ড 2"}]','["Mahlawat at  Wikipedia, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Matka_in_Village.JPG", "PSatyalakshmi, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Mitti_ka_matka.jpg"]','physics','bolt','coral',1,'2027-01-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270114-02-how-the-tubewell-lifts-water','kibhabe-chole','card','টিউবওয়েল চাপলে পানি ওঠে কীভাবে?','হাতল চাপলে ভেতরের পিস্টন ওঠে, পেছনে ফাঁকা জায়গা','["১. হাতল চাপলে ভেতরের পিস্টন ওপরে ওঠে, নিচে বাতাসের চাপ কমে যায়।\\n২. বাইরের বাতাস তখন মাটির নিচের পানিকে পাইপ বেয়ে ঠেলে তোলে।\\n৩. এই ঠেলার জোর সীমিত: পানির স্তর ৭ মিটারের নিচে গেলে এই কল আর টানে না।", "এক কথায়: পানি টানে না কল, ঠেলে তোলে বাতাস।\\nভেবে দেখুন: স্ট্র দিয়ে শরবত টানাও কি একই খেলা?"]','[{"label": "Practical Action", "url": "https://samplecontents.library.ph/en-practical_action/Energy/Mechanical"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hand_pump"}]','[{"src": "/media/kibhabe-chole/270114-02-how-the-tubewell-lifts-water-1.webp", "width": 960, "height": 1200, "alt": "টিউবওয়েল চাপলে পানি ওঠে কীভাবে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270114-02-how-the-tubewell-lifts-water-2.webp", "width": 960, "height": 1200, "alt": "টিউবওয়েল চাপলে পানি ওঠে কীভাবে?, কার্ড 2"}]','["S.M.M.Musabbir Uddin, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Nolkup.jpg", "Nikhilb239, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Hand_pump_India.jpg"]','physics','bolt','coral',1,'2027-01-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270121-03-where-to-go-when-lightning-strikes','kibhabe-chole','card','বজ্রপাতের সময় কোথায় যাব?','মেঘ থেকে মাটিতে নামছে বিদ্যুৎ: উঁচু জিনিসে আগে','["১. ঝড়-মেঘে জমা বিদ্যুৎ হঠাৎ লাফিয়ে মাটিতে নামে, একেই বলে বজ্রপাত।\\n২. বাইরে কোথাও নিরাপদ নয়: পাকা বাড়ি বা জানালা বন্ধ গাড়িতে ঢুকুন।\\n৩. একলা গাছের নিচে দাঁড়াবেন না; মাঠ, পুকুর, নদী ছেড়ে আসুন।", "এক কথায়: মেঘ ডাকলেই ঘরে; শেষ ডাকের ৩০ মিনিট পরে বাইরে।\\nমনে রাখুন: মেঘ ডাকলে মাঠে খেলা বন্ধ, সোজা ঘরে।"]','[{"label": "CDC Lightning Safety", "url": "https://www.cdc.gov/lightning/safety/index.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lightning_safety"}]','[{"src": "/media/kibhabe-chole/270121-03-where-to-go-when-lightning-strikes-1.webp", "width": 960, "height": 1200, "alt": "বজ্রপাতের সময় কোথায় যাব?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270121-03-where-to-go-when-lightning-strikes-2.webp", "width": 960, "height": 1200, "alt": "বজ্রপাতের সময় কোথায় যাব?, কার্ড 2"}]','["The Modern Polymath, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Cloud-to-ground_lightning_strike.jpg", "NOAA Photo Library, Public domain, https://commons.wikimedia.org/wiki/File:Lightning_in_Dallas_2015.jpg"]','physics','bolt','coral',1,'2027-01-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270128-04-where-electricity-comes-from','kibhabe-chole','card','কারেন্ট আসে কোথা থেকে?','উঁচু খুঁটির তার: দূরের বিদ্যুৎকেন্দ্র থেকে আপনার সুইচ পর্যন্ত','["১. বিদ্যুৎকেন্দ্রে বাষ্প, পানি বা গ্যাস একটা বিশাল চাকা ঘোরায়: টারবাইন।\\n২. টারবাইন ঘোরায় জেনারেটর; ভেতরে চুম্বক আর তারের কয়েল মিলে বিদ্যুৎ তৈরি হয়।\\n৩. চাহিদা যোগানের চেয়ে বেশি হলে এলাকা ধরে পালা করে বন্ধ: লোডশেডিং।", "এক কথায়: আপনার ফ্যান ঘোরে, কারণ দূরে একটা চাকা ঘুরছে।\\nভেবে দেখুন: আপনার বিদ্যুৎ কোন কেন্দ্র থেকে আসে?"]','[{"label": "U.S. EIA", "url": ""}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rolling_blackout"}]','[{"src": "/media/kibhabe-chole/270128-04-where-electricity-comes-from-1.webp", "width": 960, "height": 1200, "alt": "কারেন্ট আসে কোথা থেকে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270128-04-where-electricity-comes-from-2.webp", "width": 960, "height": 1200, "alt": "কারেন্ট আসে কোথা থেকে?, কার্ড 2"}]','["A S M Jobaer, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:High-voltage_transmission_tower_under_a_hazy_sky_in_Bangladesh.jpg", "Abu Sayeed, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Inside_a_Power_Station_in_Bangladesh.jpg"]','physics','bolt','coral',1,'2027-01-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270204-05-where-the-rainbow-ends','kibhabe-chole','card','রংধনু কোথায় শেষ হয়?','বাংলাদেশের আকাশে রংধনু: শেষ মাথা খুঁজে লাভ নেই','["১. রোদ বৃষ্টির ফোঁটায় ঢুকে বাঁকে, ভেতরে প্রতিফলিত হয়, রঙে ভাগ হয়ে বেরোয়।\\n২. রংধনু দেখা যায় যখন সূর্য থাকে পেছনে আর বৃষ্টির ফোঁটা থাকে সামনে।\\n৩. আপনি সরলে রংধনুও সরে; আসলে এটা পুরো গোল, মাটি নিচের অর্ধেক ঢেকে রাখে।", "এক কথায়: রংধনুর শেষ মাথা নেই: প্রত্যেকে দেখে নিজের রংধনু।\\nঘরে পরীক্ষা: রোদ পিঠে রেখে পানি ছিটান: রংধনু!"]','[{"label": "Met Office", "url": "https://weather.metoffice.gov.uk/learn-about/weather/optical-effects/rainbows"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rainbow"}]','[{"src": "/media/kibhabe-chole/270204-05-where-the-rainbow-ends-1.webp", "width": 960, "height": 1200, "alt": "রংধনু কোথায় শেষ হয়?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270204-05-where-the-rainbow-ends-2.webp", "width": 960, "height": 1200, "alt": "রংধনু কোথায় শেষ হয়?, কার্ড 2"}]','["Md Shaifuzzaman Ayon, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Beautiful_Rainbow_located_at_Diya_Bari_area.jpg", "Engr.Raju, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Double_rainbow_at_bd.jpg"]','physics','bolt','coral',1,'2027-02-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270211-06-does-a-fan-cool-the-room','kibhabe-chole','card','ফ্যান কি ঘর ঠান্ডা করে?','ঘুরন্ত ফ্যান: বাতাস নাড়ায়, তাপমাত্রা কমায় না','["১. ফ্যান ঘরের বাতাসের তাপমাত্রা কমায় না, শুধু বাতাস নাড়ায়।\\n২. চলন্ত বাতাস গায়ের তাপ দ্রুত সরিয়ে নেয়, ঘাম শুকায়: তাই আরাম লাগে।\\n৩. খালি ঘরে ফ্যান চালালে লাভ নেই, উল্টো মোটর একটু তাপ দেয়।", "এক কথায়: ফ্যান ঠান্ডা করে মানুষকে, ঘরকে না।\\nমনে রাখুন: ঘর ছাড়লে ফ্যান বন্ধ: বিল কমবে।"]','[{"label": "Popular Science", "url": ""}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Evaporation"}]','[{"src": "/media/kibhabe-chole/270211-06-does-a-fan-cool-the-room-1.webp", "width": 960, "height": 1200, "alt": "ফ্যান কি ঘর ঠান্ডা করে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270211-06-does-a-fan-cool-the-room-2.webp", "width": 960, "height": 1200, "alt": "ফ্যান কি ঘর ঠান্ডা করে?, কার্ড 2"}]','["Muthukumaran Esakkiappan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Fan_2024.jpg", "Veera.sj, CC0, https://commons.wikimedia.org/wiki/File:09_Rotating_Ceiling_fan_at_5th_of_a_second.JPG"]','physics','bolt','coral',1,'2027-02-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270218-07-where-wet-clothes-water-goes','kibhabe-chole','card','ভেজা কাপড়ের পানি যায় কোথায়?','ঢাকার ছাদে কাপড় শুকানো: পানি মিশে যায় বাতাসে','["১. রোদের তাপে কাপড়ের পানি বাষ্প হয়ে বাতাসে মিশে যায়।\\n২. রোদ গরম হলে আর হাওয়া বইলে কাপড় তাড়াতাড়ি শুকায়।\\n৩. বর্ষায় বাতাস আগেই ভেজা, তাই কাপড় শুকাতে সময় লাগে।", "এক কথায়: পানি হারায় না, বাষ্প হয়ে বাতাসে চলে যায়।\\nঘরে পরীক্ষা: দুটো ভেজা রুমাল: একটা রোদে, একটা ঘরে।"]','[{"label": "USGS Water Science School", "url": "https://www.usgs.gov/special-topics/water-science-school/science/evaporation-and-water-cycle"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Evaporation"}]','[{"src": "/media/kibhabe-chole/270218-07-where-wet-clothes-water-goes-1.webp", "width": 960, "height": 1200, "alt": "ভেজা কাপড়ের পানি যায় কোথায়?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270218-07-where-wet-clothes-water-goes-2.webp", "width": 960, "height": 1200, "alt": "ভেজা কাপড়ের পানি যায় কোথায়?, কার্ড 2"}]','["A S M Jobaer, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rooftop_lifestyle_and_laundry_in_Dhaka.jpg", "Christian Haugen, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Clothes_hanging_to_dry.jpg"]','physics','bolt','coral',1,'2027-02-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270225-08-how-the-ips-keeps-the-light-on','kibhabe-chole','card','কারেন্ট নেই, তবু বাতি জ্বলে কীভাবে?','ইনভার্টার: ব্যাটারির জমানো বিদ্যুৎ ঘরের উপযোগী করে','["১. কারেন্ট থাকলে আইপিএস নিজের ব্যাটারি চার্জ করে রাখে।\\n২. ব্যাটারি দেয় একমুখী বিদ্যুৎ (DC), কিন্তু ঘরের ফ্যান-বাতি চলে AC-তে।\\n৩. কারেন্ট গেলে ইনভার্টার DC-কে AC বানিয়ে দেয়, তাই বাতি জ্বলে।", "এক কথায়: আইপিএস বিদ্যুৎ বানায় না, জমিয়ে রাখে আর বদলে দেয়।\\nভেবে দেখুন: সোলার প্যানেলও কি DC দেয়?"]','[{"label": "Explain that Stuff", "url": "https://www.explainthatstuff.com/how-inverters-work.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Power_inverter"}]','[{"src": "/media/kibhabe-chole/270225-08-how-the-ips-keeps-the-light-on-1.webp", "width": 960, "height": 1200, "alt": "কারেন্ট নেই, তবু বাতি জ্বলে কীভাবে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270225-08-how-the-ips-keeps-the-light-on-2.webp", "width": 960, "height": 1200, "alt": "কারেন্ট নেই, তবু বাতি জ্বলে কীভাবে?, কার্ড 2"}]','["Jeremyida002, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:An_Inverter.jpg", "No machine-readable author pro, Public domain, https://commons.wikimedia.org/wiki/File:Photo-CarBattery.jpg"]','physics','bolt','coral',1,'2027-02-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270304-09-why-hot-water-cracks-a-glass','kibhabe-chole','card','গরম পানিতে কাচের গ্লাস ফাটে কেন?','হঠাৎ গরম পানি ঢালায় ফেটে যাওয়া কাচ','["১. গরম হলে কাচ একটু ফুলে বড় হয়, ঠান্ডা হলে আবার ছোট হয়।\\n২. হঠাৎ গরম পানি ঢাললে ভেতরের দিক ফোলে, বাইরের দিক তখনো ঠান্ডা।\\n৩. দুই দিকের টানাটানি কাচ সইতে না পারলেই ফাটল: একে বলে থার্মাল শক।", "এক কথায়: গ্লাস ফাটে গরমে না, হঠাৎ গরমে।\\nমনে রাখুন: আগে গ্লাসে একটু গরম পানি ঘুরিয়ে নিন।"]','[{"label": "American Ceramic Society Foundation", "url": ""}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Thermal_shock"}]','[{"src": "/media/kibhabe-chole/270304-09-why-hot-water-cracks-a-glass-1.webp", "width": 960, "height": 1200, "alt": "গরম পানিতে কাচের গ্লাস ফাটে কেন?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270304-09-why-hot-water-cracks-a-glass-2.webp", "width": 960, "height": 1200, "alt": "গরম পানিতে কাচের গ্লাস ফাটে কেন?, কার্ড 2"}]','["Ladon, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Broken_glass_through_thermal_shock_-_1st_of_3.jpg", "Ladon, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Broken_glass_through_thermal_shock_-_3rd_of_3.jpg"]','physics','bolt','coral',1,'2027-03-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270311-10-how-a-kite-stays-up','kibhabe-chole','card','ঘুড়ি আকাশে টিকে থাকে কীভাবে?','পুরান ঢাকার সাকরাইন: আকাশ ভরা ঘুড়ি','["১. বাতাস ঘুড়ির গায়ে ধাক্কা দেয়: ওপরে তোলে (লিফট), পেছনে ঠেলে (ড্র্যাগ)।\\n২. উল্টো দিকে টানে দুজন: ঘুড়ির নিজের ওজন আর হাতের সুতা।\\n৩. এই টানগুলো সমান হলে ঘুড়ি স্থির; বাতাস থামলে বা সুতা ছিঁড়লে পতন।", "এক কথায়: ঘুড়ি ওড়ে বাতাস আর সুতার টানাটানিতে।\\nভেবে দেখুন: বাতাস না থাকলে দৌড়ালে ঘুড়ি ওড়ে কেন?"]','[{"label": "NASA Glenn Research Center", "url": "https://www.grc.nasa.gov/www/k-12/airplane/kitefor.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kite"}]','[{"src": "/media/kibhabe-chole/270311-10-how-a-kite-stays-up-1.webp", "width": 960, "height": 1200, "alt": "ঘুড়ি আকাশে টিকে থাকে কীভাবে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270311-10-how-a-kite-stays-up-2.webp", "width": 960, "height": 1200, "alt": "ঘুড়ি আকাশে টিকে থাকে কীভাবে?, কার্ড 2"}]','["Ehsanul Siddiq Aranya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Kite-Filled_Skies_of_Shakrain_Festival.jpg", "Ehsanul Siddiq Aranya, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Joyful_Kite_Flying_at_Shakrain_Festival.jpg"]','physics','bolt','coral',1,'2027-03-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270318-11-how-a-switch-lights-the-bulb','kibhabe-chole','card','সুইচ টিপলেই বাতি জ্বলে কীভাবে?','সুইচ অন: তারের পথ এক টুকরো হলো','["১. বিদ্যুৎ চলে শুধু পুরো একটা গোল পথে (সার্কিট), যার কোথাও ফাঁক নেই।\\n২. সুইচ অফ মানে পথে একটা ফাঁক: বিদ্যুৎ থেমে যায়।\\n৩. সুইচ অন করলে ফাঁক জোড়া লাগে, বিদ্যুৎ ঘুরে আসে, বাতি জ্বলে।", "এক কথায়: সুইচ আসলে একটা দরজা: খুললে থামে, বন্ধ করলে চলে।\\nঘরে পরীক্ষা: টর্চ খুলে দেখুন: সুইচ কোথায় পথ জুড়ছে?"]','[{"label": "Explain that Stuff", "url": "https://www.explainthatstuff.com/electricity.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Electrical_network"}]','[{"src": "/media/kibhabe-chole/270318-11-how-a-switch-lights-the-bulb-1.webp", "width": 960, "height": 1200, "alt": "সুইচ টিপলেই বাতি জ্বলে কীভাবে?, কার্ড 1"}, {"src": "/media/kibhabe-chole/270318-11-how-a-switch-lights-the-bulb-2.webp", "width": 960, "height": 1200, "alt": "সুইচ টিপলেই বাতি জ্বলে কীভাবে?, কার্ড 2"}]','["WikiGrower1, CC BY 4.0, https://commons.wikimedia.org/wiki/File:Light_switch_turned_on.jpg", "A S M Jobaer, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Vintage_electrical_switchboard_with_ceramic_fuses_and_toggle_switches,_Bangladesh_2026.jpg"]','physics','bolt','coral',1,'2027-03-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270103-01-why-seedlings-in-the-dark-turn-yellow','bigganir-moto-bhabi','card','অন্ধকারে চারা হলুদ কেন?','একই জাতের দুই চারা: একটা অন্ধকারে, একটা আলোতে','["✔ আলো ছাড়া চারায় ক্লোরোফিল তৈরি হয় না, তাই রং সবুজ না হয়ে সাদা-হলুদ।\\n✔ আলো খুঁজতে চারা তাড়াতাড়ি লম্বা হয়; কাণ্ড সরু, পাতা ছোট।\\n✔ আলো-ই কারণ কি না বুঝতে লাগে তুলনার টব: একই বীজ, একই পানি, শুধু আলো আলাদা।", "বিজ্ঞানীর কৌশল: তুলনার টব (কন্ট্রোল)\\nএক কথায়: একটা জিনিস বদলাও, বাকি সব এক রাখো; তবেই কারণ ধরা পড়ে।\\nঘরে করুন: দুই বাটিতে মুগ ভেজান: একটা আলমারির অন্ধকারে, অন্যটা জানালার আলোয়; ৫ দিন পর মেলান।"]','[{"label": "LibreTexts Botany", "url": "https://bio.libretexts.org/Bookshelves/Botany/Botany_(Ha_Morrow_and_Algiers"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Etiolation'']"}]','[{"src": "/media/bigganir-moto-bhabi/270103-01-why-seedlings-in-the-dark-turn-yellow-1.webp", "width": 960, "height": 1200, "alt": "অন্ধকারে চারা হলুদ কেন?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270103-01-why-seedlings-in-the-dark-turn-yellow-2.webp", "width": 960, "height": 1200, "alt": "অন্ধকারে চারা হলুদ কেন?, কার্ড 2"}]','["Mathias Zeidler, CC0, https://commons.wikimedia.org/wiki/File:Keimlinge_Arabidopsis_D-light.png", "சஞ்சீவி சிவகுமார், CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Etiolation_of_plants.JPG"]','physics','telescope','teal',1,'2027-01-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270110-02-does-a-crow-call-bring-guests','bigganir-moto-bhabi','card','কাক ডাকলে কি মেহমান আসে?','ঢাকার শান্তিনগরের পাতিকাক: রোজ বহুবার ডাকে','["✔ কাক দিনে বহুবার ডাকে; মেহমানও মাঝে মাঝে আসেন। দুটো একসাথে ঘটবেই।\\n✔ যেদিন মিলে যায়, সেদিনটা মনে থাকে; না মেলার দিনগুলো আমরা ভুলে যাই।\\n✔ একসাথে ঘটা মানেই একটা আরেকটার কারণ না; দরকার গুনে রাখা হিসাব।", "বিজ্ঞানীর কৌশল: মিলে যাওয়া বনাম গুনে দেখা\\nএক কথায়: মনে রাখা নয়, খাতায় গোনা হিসাবই সত্য বলে।\\nঘরে করুন: দুই সপ্তাহ খাতায় দুই ঘর রাখুন: কাক ডাকল কি না, আর সেদিন মেহমান এলেন কি না।"]','[{"label": "APA Dictionary of Psychology", "url": "https://dictionary.apa.org/confirmation-bias''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Correlation_does_not_imply_causation'']"}]','[{"src": "/media/bigganir-moto-bhabi/270110-02-does-a-crow-call-bring-guests-1.webp", "width": 960, "height": 1200, "alt": "কাক ডাকলে কি মেহমান আসে?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270110-02-does-a-crow-call-bring-guests-2.webp", "width": 960, "height": 1200, "alt": "কাক ডাকলে কি মেহমান আসে?, কার্ড 2"}]','["TawsifSalam, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:House_Crow_(Corvus_splendens)_in_Shantinagar,_Dhaka,_Bangladesh,_17_March_2015.JPG", "Kamrul512, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Crow_Bangladesh.JPG"]','physics','telescope','teal',1,'2027-01-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270117-03-who-decided-how-long-a-metre-is','bigganir-moto-bhabi','card','মিটার কে ঠিক করল?','১৮৮৯ সালের ''আসল মিটার'': প্লাটিনাম-ইরিডিয়ামের দণ্ড','["✔ বিঘত-হাতের মাপ মানুষে মানুষে আলাদা; তাই সবাই মিলে এক মাপ ঠিক হলো।\\n✔ ১৮৮৯ থেকে প্লাটিনাম-ইরিডিয়ামের এক দণ্ডের দুই দাগের দূরত্বই ছিল এক মিটার।\\n✔ ১৯৮৩ থেকে মিটার মানে আলো এক সেকেন্ডের ২৯,৯৭,৯২,৪৫৮ ভাগের এক ভাগে যতটা যায়।", "বিজ্ঞানীর কৌশল: সবার এক মাপ (স্ট্যান্ডার্ড)\\nএক কথায়: একই মাপকাঠি থাকলে ঢাকা আর প্যারিসের মাপ মিলে যায়।\\nঘরে করুন: তিনজন বিঘতে একই খাট মাপুন, পরে ফিতায়।"]','[{"label": "NIST", "url": "https://www.nist.gov/si-redefinition/meter''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/History_of_the_metre'']"}]','[{"src": "/media/bigganir-moto-bhabi/270117-03-who-decided-how-long-a-metre-is-1.webp", "width": 960, "height": 1200, "alt": "মিটার কে ঠিক করল?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270117-03-who-decided-how-long-a-metre-is-2.webp", "width": 960, "height": 1200, "alt": "মিটার কে ঠিক করল?, কার্ড 2"}]','["Unknown authorUnknown author, Public domain, https://commons.wikimedia.org/wiki/File:Platinum-Iridium_meter_bar.jpg", "William Warby from London, CC BY 2.0, https://commons.wikimedia.org/wiki/File:3cm_-_Flickr_-_wwarby.jpg"]','physics','telescope','teal',1,'2027-01-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270124-04-could-the-horse-really-count','bigganir-moto-bhabi','card','ঘোড়া কি অঙ্ক জানত?','জার্মানির ''চালাক হান্স'': খুর ঠুকে অঙ্কের উত্তর দিত','["✔ প্রশ্নকর্তা উত্তর জানলে আর হান্স তাঁকে দেখতে পেলে প্রায় সবসময় ঠিক বলত।\\n✔ ১৯০৭ সালে ফুংস্ট দেখালেন: প্রশ্নকর্তা আড়ালে থাকলে হান্স প্রায় সবই ভুল করে।\\n✔ আসলে প্রশ্নকর্তার মুখ আর শরীরের খুদে নড়াচড়া দেখে সে থামত; কেউ টেরও পেত না।", "বিজ্ঞানীর কৌশল: অন্ধ পরীক্ষা (ব্লাইন্ড টেস্ট)\\nএক কথায়: যে পরীক্ষা নিচ্ছে সে উত্তর জানলে, না চেয়েও ফল বদলে দিতে পারে।\\nঘরে করুন: চোখ বেঁধে দুই ব্র্যান্ডের বিস্কুট চেখে দেখুন; অন্য কেউ ঠিক করবে কোনটা আগে দেবে।"]','[{"label": "NCBI PMC article PMC3921203", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3921203''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Clever_Hans'']"}]','[{"src": "/media/bigganir-moto-bhabi/270124-04-could-the-horse-really-count-1.webp", "width": 960, "height": 1200, "alt": "ঘোড়া কি অঙ্ক জানত?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270124-04-could-the-horse-really-count-2.webp", "width": 960, "height": 1200, "alt": "ঘোড়া কি অঙ্ক জানত?, কার্ড 2"}]','["Karl Krall, Public domain, https://commons.wikimedia.org/wiki/File:Hans_zeigt_Zahlen_an.jpg", "Karl Krall, Public domain, https://commons.wikimedia.org/wiki/File:Hans_1910.jpg"]','physics','telescope','teal',1,'2027-01-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270131-05-is-a-photo-proof','bigganir-moto-bhabi','card','ছবি দেখলেই কি প্রমাণ?','১৯১৭, ইংল্যান্ডের কটিংলি: দুই বোনের তোলা ''পরীর ছবি''','["✔ ১৯১৭ সালে দুই কিশোরী বোন এলসি আর ফ্রান্সেস ''পরী''র কয়েকটা ছবি তুললেন।\\n✔ শার্লক হোমসের লেখক কোনান ডয়েলও ছবিগুলোকে সত্যি বলে প্রচার করলেন।\\n✔ ১৯৮৩ সালে তাঁরা স্বীকার করেন: পরীগুলো বই থেকে আঁকা ছবি, হ্যাটপিনে দাঁড় করানো।", "বিজ্ঞানীর কৌশল: কে বলছে, কীভাবে জানে?\\nএক কথায়: নামী মানুষ বিশ্বাস করলেই কিছু সত্য হয় না; চাই যাচাই করা প্রমাণ।\\nশেয়ারের আগে: ছবিটা আর কোথায় এসেছে, অন্তত একটা বিশ্বস্ত সূত্রে খুঁজে দেখুন।"]','[{"label": "Science and Media Museum blog", "url": "https://blog.scienceandmediamuseum.org.uk/cottingleys-scientific-fairies-and-enchanting-technology/''"}, {"label": "Historic UK", "url": "https://www.historic-uk.com/CultureUK/The-Fairies-of-Cottingley/''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cottingley_Fairies'']"}]','[{"src": "/media/bigganir-moto-bhabi/270131-05-is-a-photo-proof-1.webp", "width": 960, "height": 1200, "alt": "ছবি দেখলেই কি প্রমাণ?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270131-05-is-a-photo-proof-2.webp", "width": 960, "height": 1200, "alt": "ছবি দেখলেই কি প্রমাণ?, কার্ড 2"}]','["Frances Griffiths, Public domain, https://commons.wikimedia.org/wiki/File:Cottingley_Fairies_4.jpg", "Frances Griffiths and Elsie Wr, Public domain, https://commons.wikimedia.org/wiki/File:Cottingley_Fairies_5.jpg"]','physics','telescope','teal',1,'2027-01-31');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270207-06-do-continents-move','bigganir-moto-bhabi','card','মহাদেশ কি সরে?','১৮৫৮ সালের আঁকা: আটলান্টিক খোলার আগে আর পরে','["✔ ১৯১২ সালে ভেগেনার বললেন: সব মহাদেশ একসময় জোড়া ছিল, পরে সরে গেছে।\\n✔ প্রমাণ: মেসোসরাসের মতো একই প্রাণীর ফসিল মেলে আফ্রিকা আর দক্ষিণ আমেরিকায়।\\n✔ কী শক্তিতে সরে, বোঝাতে না পারায় বহু বছর কেউ মানেনি; ১৯৬০-এর দশকে সমুদ্রতলের প্রমাণে মানল।", "বিজ্ঞানীর কৌশল: নতুন প্রমাণে মত বদলানো\\nএক কথায়: ভুল মানা হার নয়; নতুন প্রমাণে মত বদলানোই বিজ্ঞান।\\nঘরে করুন: পুরোনো মানচিত্র থেকে আফ্রিকা আর দক্ষিণ আমেরিকা কেটে পাশাপাশি বসিয়ে দেখুন।"]','[{"label": "UC Museum of Paleontology", "url": "https://ucmp.berkeley.edu/geology/techist.html''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Continental_drift'']"}]','[{"src": "/media/bigganir-moto-bhabi/270207-06-do-continents-move-1.webp", "width": 960, "height": 1200, "alt": "মহাদেশ কি সরে?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270207-06-do-continents-move-2.webp", "width": 960, "height": 1200, "alt": "মহাদেশ কি সরে?, কার্ড 2"}]','[", Public domain, https://commons.wikimedia.org/wiki/File:Antonio_Snider-Pellegrini_Opening_of_the_Atlantic.jpg", "Fabirichter, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Snider-Pellegrini_Wegener_fossil_map-01.png"]','physics','telescope','teal',1,'2027-02-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270214-07-does-a-coin-prefer-one-side','bigganir-moto-bhabi','card','কয়েন কি এক পিঠ বেশি ভালোবাসে?','বাংলাদেশের ৫ টাকার কয়েন: দুই পিঠ, সমান সুযোগ','["✔ অল্প কয়েকবার টসে এক পিঠ বারবার ওঠা খুব স্বাভাবিক; এটা কাকতালীয়।\\n✔ ১৯৪০-এর দশকে গণিতবিদ কেরিখ ১০,০০০ বার টস করে হেড পান ৫,০৬৭ বার।\\n✔ যত বেশি বার টস, অনুপাত তত অর্ধেকের কাছে: একেই বলে বড় সংখ্যার নিয়ম।", "বিজ্ঞানীর কৌশল: অনেকবার করে দেখা\\nএক কথায়: দুই-তিনবারে রায় নয়; বেশি বার করলেই আসল ছবি দেখা যায়।\\nঘরে করুন: ৫ টাকার কয়েন ১০ বার, তারপর ১০০ বার টস করুন; দুই হিসাবের অনুপাত মেলান।"]','[{"label": "Prof. Matt blog", "url": "https://profmatt.squarespace.com/kerrich''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/John_Edmund_Kerrich'']"}]','[{"src": "/media/bigganir-moto-bhabi/270214-07-does-a-coin-prefer-one-side-1.webp", "width": 960, "height": 1200, "alt": "কয়েন কি এক পিঠ বেশি ভালোবাসে?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270214-07-does-a-coin-prefer-one-side-2.webp", "width": 960, "height": 1200, "alt": "কয়েন কি এক পিঠ বেশি ভালোবাসে?, কার্ড 2"}]','["মোহাম্মদ জনি হোসেন, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:%E0%A7%AB_%E0%A6%9F%E0%A6%BE%E0%A6%95%E0%A6%BE_%E0%A6%95%E0%A6%AF%E0%A6%BC%E0%A7%87%E0%A6%A8_%E0%A6%85%E0%A6%AD%E0%A6%BF%E0%A6", "মোহাম্মদ জনি হোসেন, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:%E0%A7%AB_%E0%A6%9F%E0%A6%BE%E0%A6%95%E0%A6%BE_%E0%A6%95%E0%A6%AF%E0%A6%BC%E0%A7%87%E0%A6%A8_%E0%A6%AC%E0%A6%BF%E0%A6%AA%E0%A6"]','physics','telescope','teal',1,'2027-02-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270221-08-how-rain-is-measured','bigganir-moto-bhabi','card','বৃষ্টি মাপে কীভাবে?','বৃষ্টিমাপক যন্ত্র: ওপরে ফানেল, ভেতরে মাপার নল','["✔ ওপরের ফানেল বৃষ্টি ধরে সরু মাপার নলে ফেলে।\\n✔ প্রচলিত যন্ত্রে ফানেলের মুখ নলের ১০ গুণ চওড়া; তাই অল্প বৃষ্টিও নলে উঁচু হয়ে ওঠে।\\n✔ বৃষ্টি মাপা হয় গভীরতায়, মিলিমিটারে; নিয়ম করে লিখে রাখলে বছরের হিসাব মেলে।", "বিজ্ঞানীর কৌশল: মেপে লিখে রাখা\\nএক কথায়: ''অনেক বৃষ্টি'' বললে তর্ক হয়; ''৪০ মিলিমিটার'' বললে সবাই একমত।\\nঘরে করুন: সোজা দেয়ালের বয়াম উঠানে রাখুন; বৃষ্টির পর স্কেলে পানির উচ্চতা মাপুন।"]','[{"label": "US National Weather Service", "url": ""}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rain_gauge'']"}]','[{"src": "/media/bigganir-moto-bhabi/270221-08-how-rain-is-measured-1.webp", "width": 960, "height": 1200, "alt": "বৃষ্টি মাপে কীভাবে?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270221-08-how-rain-is-measured-2.webp", "width": 960, "height": 1200, "alt": "বৃষ্টি মাপে কীভাবে?, কার্ড 2"}]','["Bocholter, Public domain, https://commons.wikimedia.org/wiki/File:Rain_gauge_Hellmann.jpg", "Mr Setson, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:RAIN_GAUGE.jpg"]','physics','telescope','teal',1,'2027-02-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270228-09-why-the-broth-did-not-spoil','bigganir-moto-bhabi','card','ঝোল পচল না কেন?','লুই পাস্তুরের ''হাঁসের-গলা'' ফ্লাস্ক, ১৮৫৯','["✔ আগে ভাবা হতো, জীবাণু নিজে নিজেই জন্মায়।\\n✔ পাস্তুর ঝোল ফুটিয়ে বাঁকা গলার ফ্লাস্কে রাখলেন: বাতাস ঢোকে, ধুলা-জীবাণু বাঁকে আটকায়।\\n✔ গলা অক্ষত থাকতে ঝোল পরিষ্কার; গলা ভাঙতেই জীবাণু ঢুকে ঝোল ঘোলা।", "বিজ্ঞানীর কৌশল: পুরোনো ধারণা পরীক্ষায় ফেলা\\nএক কথায়: সবাই মানে বলেই সত্য নয়; পরীক্ষা যা দেখায়, সেটাই মানি।\\nঘরে দেখুন: এক বাটি ভাত ঢেকে, আরেক বাটি খোলা রাখুন; কোনটা আগে নষ্ট হয় দেখুন, খাবেন না।"]','[{"label": "Lumen Learning", "url": "https://courses.lumenlearning.com/suny-microbiology/chapter/spontaneous-generation''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Spontaneous_generation'']"}]','[{"src": "/media/bigganir-moto-bhabi/270228-09-why-the-broth-did-not-spoil-1.webp", "width": 960, "height": 1200, "alt": "ঝোল পচল না কেন?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270228-09-why-the-broth-did-not-spoil-2.webp", "width": 960, "height": 1200, "alt": "ঝোল পচল না কেন?, কার্ড 2"}]','[", CC BY 4.0, https://commons.wikimedia.org/wiki/File:Swan-necked_flask_used_by_Pasteur._Wellcome_M0012521.jpg", ", CC BY 4.0, https://commons.wikimedia.org/wiki/File:Copy_of_Pasteur%27s_flask_used_in_his_experiments_on_spontaneo_Wellcome_L0057281.jpg"]','physics','telescope','teal',1,'2027-02-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270307-10-which-paper-plane-flies-farther','bigganir-moto-bhabi','card','কোন প্লেন বেশি দূর যায়?','নদীর পাড়ে কাগজের প্লেন ওড়ানো (লাওস)','["✔ একসাথে ডানা, কাগজ আর ছোড়ার জোর বদলালে বোঝা যায় না কোনটায় লাভ হলো।\\n✔ ঠিক নিয়ম: একবারে শুধু একটা জিনিস বদলাও, বাকি সব এক রাখো।\\n✔ প্রতিটা নকশা কয়েকবার ছুড়ে দূরত্ব মাপো; একবারের ফলে ভরসা নেই।", "বিজ্ঞানীর কৌশল: একবারে একটা বদল\\nএক কথায়: সব একসাথে বদলালে জেতার কারণটাই হারিয়ে যায়।\\nঘরে করুন: একই কাগজে দুই প্লেন বানান, শুধু ডানার ভাঁজ আলাদা; ৫ বার করে ছুড়ে মাপুন।"]','[{"label": "Carleton SERC", "url": "https://serc.carleton.edu/sp/mnstep/activities/35929.html''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Scientific_control'']"}]','[{"src": "/media/bigganir-moto-bhabi/270307-10-which-paper-plane-flies-farther-1.webp", "width": 960, "height": 1200, "alt": "কোন প্লেন বেশি দূর যায়?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270307-10-which-paper-plane-flies-farther-2.webp", "width": 960, "height": 1200, "alt": "কোন প্লেন বেশি দূর যায়?, কার্ড 2"}]','["Erik Albers, CC0, https://commons.wikimedia.org/wiki/File:Kids_throwing_paper_planes_over_river_Nam_Khan,_Luang_Prabang.JPG", "Arthurfan828, CC BY 3.0, https://commons.wikimedia.org/wiki/File:White_paper_airplane.jpg"]','physics','telescope','teal',1,'2027-03-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270314-11-why-cats-purr','bigganir-moto-bhabi','card','বিড়াল কেন ঘরঘর করে?','বাংলাদেশের দুই পাড়ার বিড়াল, সাদা আর কালো','["✔ খুশিতে ঘরঘর করে, ভয় বা ব্যথাতেও করে।\\n✔ শব্দটা আসে গলার স্বরযন্ত্র থেকে, এটুকু জানা; পুরো কলকব্জা নিয়ে এখনো তর্ক চলছে।\\n✔ কেন করে, তার পুরো উত্তরও এখনো অজানা।", "বিজ্ঞানীর কৌশল: ''জানি না'' বলতে পারা\\nএক কথায়: ''এখনো জানি না'' বলাটাই নতুন খোঁজের শুরু।\\nখেয়াল করুন: বিড়াল কখন কখন ঘরঘর করে, এক সপ্তাহ খাতায় লিখে রাখুন।"]','[{"label": "Live Science", "url": "https://www.livescience.com/animals/cats/why-cats-purr-is-a-surprisingly-long-standing-mystery-now-were-one-step-closer-to-solving-it''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Purr'']"}]','[{"src": "/media/bigganir-moto-bhabi/270314-11-why-cats-purr-1.webp", "width": 960, "height": 1200, "alt": "বিড়াল কেন ঘরঘর করে?, কার্ড 1"}, {"src": "/media/bigganir-moto-bhabi/270314-11-why-cats-purr-2.webp", "width": 960, "height": 1200, "alt": "বিড়াল কেন ঘরঘর করে?, কার্ড 2"}]','["Tanvir Rahat, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:White_cat_and_black_cat_of_Bangladesh_02.jpg", "Kryesmin, CC0, https://commons.wikimedia.org/wiki/File:Cats_of_Bangladesh_01.jpg"]','physics','telescope','teal',1,'2027-03-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270106-01-the-first-computer-bug-was-a-real-moth','jontro-ar-ai','card','কম্পিউটারের প্রথম বাগ','১৯৪৭ সালের লগবুকে টেপ দিয়ে আটকানো আসল পোকা','["▸ ৯ সেপ্টেম্বর ১৯৪৭: হার্ভার্ডের মার্ক টু কম্পিউটার বারবার ভুল করছিল।\\n▸ খুঁজে দেখা গেল, একটা রিলের দুই কাঁটার মাঝখানে আটকে মরে আছে একটা মথ।\\n▸ মথটা লগবুকে টেপ দিয়ে লাগিয়ে লেখা হলো: ''বাগ পাওয়ার প্রথম আসল ঘটনা''।", "এক কথায়: ''বাগ'' শব্দটা আগেও ছিল; এই মথটা তাকে বিখ্যাত করল।\\nজানেন কি: প্রোগ্রামের ভুল খুঁজে সারানোকে আজও বলে ''ডিবাগিং'', মানে পোকা তাড়ানো।"]','[{"label": "Computer History Museum", "url": "https://www.computerhistory.org/tdih/september/9/''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Software_bug'']"}]','[{"src": "/media/jontro-ar-ai/270106-01-the-first-computer-bug-was-a-real-moth-1.webp", "width": 960, "height": 1200, "alt": "কম্পিউটারের প্রথম বাগ, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270106-01-the-first-computer-bug-was-a-real-moth-2.webp", "width": 960, "height": 1200, "alt": "কম্পিউটারের প্রথম বাগ, কার্ড 2"}]','["Courtesy of the Naval Surface , Public domain, https://commons.wikimedia.org/wiki/File:First_Computer_Bug,_1947.jpg"]','tech','bolt','teal',1,'2027-01-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270113-02-why-the-keyboard-says-qwerty','jontro-ar-ai','card','কিবোর্ড কেন QWERTY?','১৮৭৪ সালের শোলস-গ্লিডেন টাইপরাইটার: এখান থেকেই শুরু','["▸ ১৮৭০-এর দশকে শোলস আর তাঁর সঙ্গীরা টাইপরাইটারের চাবি বারবার সাজিয়েছেন।\\n▸ চালু গল্প: পাশাপাশি অক্ষরের লিভার যেন জট না পাকায়, তাই এমন সাজ।\\n▸ তখনকার লিভার চলত ধীরে; পাশাপাশি দুটো একসাথে উঠলে আটকে যেত।", "এক কথায়: আজকের ফোনেও চলছে ১৮৭০-এর দশকের টাইপরাইটারের সাজ!\\nদেখুন: ফোনের কিবোর্ডে অক্ষরের ওপরের সারির প্রথম ছয়টা পড়ুন: সেই একই সাজ!"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/QWERTY'']"}, {"label": "MIT", "url": "https://www.mit.edu/~jcb/Dvorak/history.html''"}]','[{"src": "/media/jontro-ar-ai/270113-02-why-the-keyboard-says-qwerty-1.webp", "width": 960, "height": 1200, "alt": "কিবোর্ড কেন QWERTY?, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270113-02-why-the-keyboard-says-qwerty-2.webp", "width": 960, "height": 1200, "alt": "কিবোর্ড কেন QWERTY?, কার্ড 2"}]','["Dr. Bernd Gross, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sholes-Glidden_1874.jpg", "Tony Casillo, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_Sholes_%26_Glidden_Typewriter_of_1873.jpg"]','tech','bolt','teal',1,'2027-01-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270120-03-why-a-mouse-is-called-a-mouse','jontro-ar-ai','card','মাউসের নাম কেন মাউস?','১৯৬৪ সালের প্রথম মাউস: কাঠের বাক্স আর দুটো চাকা','["▸ ১৯৬৪ সালে এঙ্গেলবার্টের নকশায় এসআরআই-এর বিল ইংলিশ কাঠের খোলে এটা বানান।\\n▸ কাঠের খোলের নিচে আড়াআড়ি দুটো চাকা: একটা ডান-বাঁ, একটা ওপর-নিচ মাপত।\\n▸ এঙ্গেলবার্ট বলেছেন: দেখতে লেজওয়ালা ইঁদুরের মতো, তাই সবাই বলত মাউস।", "এক কথায়: লেজওয়ালা ইঁদুরের মতো দেখতে, তাই নাম মাউস।\\nখেয়াল করুন: আজকের মাউস উল্টে দেখুন: চাকার জায়গায় এখন জ্বলে ছোট্ট একটা আলো।"]','[{"label": "Computer History Museum", "url": "https://www.computerhistory.org/revolution/input-output/14/350''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Computer_mouse'']"}]','[{"src": "/media/jontro-ar-ai/270120-03-why-a-mouse-is-called-a-mouse-1.webp", "width": 960, "height": 1200, "alt": "মাউসের নাম কেন মাউস?, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270120-03-why-a-mouse-is-called-a-mouse-2.webp", "width": 960, "height": 1200, "alt": "মাউসের নাম কেন মাউস?, কার্ড 2"}]','["The wub, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Replica_of_prototype_Engelbart_mouse,_circa_1964,_Computer_History_Museum.jpg", "Michael Hicks from Saint Paul, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Douglas_Engelbart%27s_prototype_mouse,_angled_-_Computer_History_Museum.jpg"]','tech','bolt','teal',1,'2027-01-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270127-04-the-first-programmers-rewired-the-computer','jontro-ar-ai','card','প্রথম প্রোগ্রাম লেখা হতো তারে','১৯৪৬ সালের এনিয়াক: পুরো ঘরজোড়া এক কম্পিউটার','["▸ এনিয়াকে প্রায় ১৮ হাজার ভ্যাকুয়াম টিউব ছিল; ওজন ২৭ টনের মতো।\\n▸ নতুন হিসাব করাতে হলে তার খুলে আবার জুড়তে হতো, সুইচ ঘোরাতে হতো।\\n▸ এই কাজ করতেন ছয়জন নারী প্রোগ্রামার; একেকটা সেটআপে লাগত কয়েক দিন।", "এক কথায়: আজ যা কি-বোর্ডে লিখি, তখন তা হাতে তার জুড়ে বানাতে হতো!\\nভাবুন: আজকের একটা ছোট অ্যাপও যদি হাতে তার জুড়ে বানাতে হতো, কত দিন লাগত?"]','[{"label": "Computer History Museum", "url": "https://www.computerhistory.org/revolution/birth-of-the-computer/4/78''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/ENIAC'']"}]','[{"src": "/media/jontro-ar-ai/270127-04-the-first-programmers-rewired-the-computer-1.webp", "width": 960, "height": 1200, "alt": "প্রথম প্রোগ্রাম লেখা হতো তারে, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270127-04-the-first-programmers-rewired-the-computer-2.webp", "width": 960, "height": 1200, "alt": "প্রথম প্রোগ্রাম লেখা হতো তারে, কার্ড 2"}]','["Unidentified U.S. Army photogr, Public domain, https://commons.wikimedia.org/wiki/File:Two_women_operating_ENIAC_(full_resolution).jpg"]','tech','bolt','teal',1,'2027-01-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270203-05-when-a-computer-beat-the-chess-champion','jontro-ar-ai','card','যন্ত্র যেদিন দাবা জিতল','মে ১৯৯৭: আইবিএমের ডিপ ব্লু বনাম বিশ্বচ্যাম্পিয়ন কাসপারভ','["▸ ছয় খেলার ম্যাচে ডিপ ব্লু জিতল দুটি, কাসপারভ একটি, আর বাকি তিনটি খেলা ড্র।\\n▸ ফল ৩.৫ বনাম ২.৫; আগের বছর কাসপারভই এই যন্ত্রকে হারিয়েছিলেন।\\n▸ ডিপ ব্লু প্রতি সেকেন্ডে প্রায় ২০ কোটি অবস্থান হিসাব করত, মানুষের মতো ''ভাবত'' না।", "এক কথায়: গতিতে যন্ত্র জিতল; কিন্তু খেলাটা বুঝে খেলে এখনও মানুষই।\\nখেলুন: আজ কারও সঙ্গে এক দান দাবা খেলুন, প্রতিটা চালের আগে তিনটা চাল ভাবুন।"]','[{"label": "IBM History", "url": "https://www.ibm.com/history/deep-blue''"}, {"label": "Computer History Museum", "url": "https://www.computerhistory.org/timeline/ai-robotics/'']"}]','[{"src": "/media/jontro-ar-ai/270203-05-when-a-computer-beat-the-chess-champion-1.webp", "width": 960, "height": 1200, "alt": "যন্ত্র যেদিন দাবা জিতল, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270203-05-when-a-computer-beat-the-chess-champion-2.webp", "width": 960, "height": 1200, "alt": "যন্ত্র যেদিন দাবা জিতল, কার্ড 2"}]','["Erik Pitti from San Diego, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Say_hello_to_Deep_Blue_(2586059148).jpg", "Erik Pitti from San Diego, CC BY 2.0, https://commons.wikimedia.org/wiki/File:One_of_Deep_Blue%27s_processors_(2586060990).jpg"]','tech','bolt','teal',1,'2027-02-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270210-06-the-first-transistor','jontro-ar-ai','card','প্রথম ট্রানজিস্টর','১৯৪৭ সালের প্রথম ট্রানজিস্টর (প্রতিরূপ), বেল ল্যাবস','["▸ ২৩ ডিসেম্বর ১৯৪৭: বার্ডিন আর ব্র্যাটেন প্রথম ট্রানজিস্টর চালিয়ে দেখান।\\n▸ জার্মেনিয়ামের এক টুকরোর ওপর খুব কাছাকাছি দুটো সোনার কাঁটা বসানো।\\n▸ এটা কথার শব্দ জোরালো করতে পারত; বড় বড় ভ্যাকুয়াম টিউবের জায়গা নিল এটাই।", "এক কথায়: এই ছোট্ট যন্ত্রের বংশধরেরা আজ আপনার ফোনের চিপে কোটি কোটি।\\nজানেন কি: ট্রানজিস্টর এসেছিল বলেই রেডিও পকেটে ঢোকার মতো ছোট হতে পেরেছিল।"]','[{"label": "Computer History Museum", "url": "https://www.computerhistory.org/revolution/digital-logic/12/273''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/History_of_the_transistor'']"}]','[{"src": "/media/jontro-ar-ai/270210-06-the-first-transistor-1.webp", "width": 960, "height": 1200, "alt": "প্রথম ট্রানজিস্টর, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270210-06-the-first-transistor-2.webp", "width": 960, "height": 1200, "alt": "প্রথম ট্রানজিস্টর, কার্ড 2"}]','["Mister rf, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:A_replica_of_the_first_working_transistor.jpg", "Revol Web, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Replica_of_first_transistor.jpg"]','tech','bolt','teal',1,'2027-02-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270217-07-why-the-save-icon-is-a-floppy-disk','jontro-ar-ai','card','সেভ বাটন কেন ফ্লপি?','বড় কালোটা ৮ ইঞ্চি; সামনে ছোট ফ্লপি আর পেনড্রাইভ','["▸ ১৯৭১ সালে আইবিএম প্রথম বাণিজ্যিক ফ্লপি ডিস্ক আনে, মাপ ৮ ইঞ্চি।\\n▸ এটা পাঞ্চ কার্ড আর কাগজের ফিতার জায়গা নিল; পরে এল ছোট ৫¼ আর ৩½ ইঞ্চি।\\n▸ ফ্লপি এখন প্রায় উধাও, পেনড্রাইভ এসেছে; কিন্তু সেভ বাটনে ছবিটা রয়ে গেছে।", "এক কথায়: জিনিসটা হারিয়ে গেছে, তার ছবিটা এখনও প্রতিদিন আমাদের হাতে।\\nখুঁজুন: ফোনে বা কম্পিউটারে কোন কোন অ্যাপে এখনও ফ্লপির ছবিওয়ালা সেভ বাটন আছে, গুনে দেখুন।"]','[{"label": "Computer History Museum", "url": "https://www.computerhistory.org/storageengine/timeline/''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Floppy_disk'']"}]','[{"src": "/media/jontro-ar-ai/270217-07-why-the-save-icon-is-a-floppy-disk-1.webp", "width": 960, "height": 1200, "alt": "সেভ বাটন কেন ফ্লপি?, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270217-07-why-the-save-icon-is-a-floppy-disk-2.webp", "width": 960, "height": 1200, "alt": "সেভ বাটন কেন ফ্লপি?, কার্ড 2"}]','["Pamporoff, Public domain, https://commons.wikimedia.org/wiki/File:8%60%60_floppy_disk.jpg", "George Chernilevsky, Public domain, https://commons.wikimedia.org/wiki/File:Floppy_disk_2009_G1.jpg"]','tech','bolt','teal',1,'2027-02-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270224-08-a-loom-that-read-punched-cards','jontro-ar-ai','card','তাঁত পড়ত ফুটো-কার্ড','জাকার্ড তাঁত: স্কটল্যান্ডের জাতীয় জাদুঘরে','["▸ ১৮০৪ সালে জোসেফ মারি জাকার্ড তাঁতে ফুটো-করা কার্ডের শিকল লাগান।\\n▸ প্রতিটা কার্ড নকশার এক সারি; যেখানে ফুটো, সেখানের সুতাটা ওপরে ওঠে।\\n▸ কার্ড বদলালেই নকশা বদলায়; এই বুদ্ধি পরে নেন কম্পিউটারের পূর্বসূরি ব্যাবেজ।", "এক কথায়: কম্পিউটার প্রোগ্রামের এক দাদা আসলে একটা কাপড় বোনার তাঁত!\\nদেখুন: বেনারসি বা জামদানির জটিল নকশা খেয়াল করুন: প্রতিটা সারি আলাদা।"]','[{"label": "Computer History Museum", "url": "https://www.computerhistory.org/babbage/engines/''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jacquard_machine'']"}]','[{"src": "/media/jontro-ar-ai/270224-08-a-loom-that-read-punched-cards-1.webp", "width": 960, "height": 1200, "alt": "তাঁত পড়ত ফুটো-কার্ড, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270224-08-a-loom-that-read-punched-cards-2.webp", "width": 960, "height": 1200, "alt": "তাঁত পড়ত ফুটো-কার্ড, কার্ড 2"}]','["Stephencdickson, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:A_Jacquard_loom_showing_information_punchcards,_National_Museum_of_Scotland.jpg", "Ramón from Llanera, CC BY-SA 2.0, https://commons.wikimedia.org/wiki/File:Jacquard_loom_in_Varanasi.jpg"]','tech','bolt','teal',1,'2027-02-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270303-09-how-a-phone-recognises-your-face-in-the-dark','jontro-ar-ai','card','ফোন মুখ চেনে কীভাবে?','ফেস আইডির প্রজেক্টর দেয়ালে ফেললে দেখা যায় এমন বিন্দু','["▸ ফোন মুখের ওপর হাজার হাজার ইনফ্রারেড বিন্দু ফেলে; চোখে এগুলো দেখা যায় না।\\n▸ ইনফ্রারেড ক্যামেরা বিন্দুগুলোর ছড়ানো দেখে মুখের উঁচু-নিচু মাপ বানায়।\\n▸ সেই মাপ আগে রাখা মাপের সঙ্গে মেলে কি না দেখে; তাই অন্ধকারেও কাজ করে।", "এক কথায়: ফোন মুখের ''ছবি'' না, মুখের ত্রিমাত্রিক মানচিত্র মেলায়।\\nজানেন কি: অ্যাপলের হিসাবে অচেনা কেউ আপনার ফোন খুলে ফেলার সম্ভাবনা ১০ লাখে ১-এরও কম।"]','[{"label": "Apple Support", "url": "https://support.apple.com/en-us/102381''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Face_ID'']"}]','[{"src": "/media/jontro-ar-ai/270303-09-how-a-phone-recognises-your-face-in-the-dark-1.webp", "width": 960, "height": 1200, "alt": "ফোন মুখ চেনে কীভাবে?, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270303-09-how-a-phone-recognises-your-face-in-the-dark-2.webp", "width": 960, "height": 1200, "alt": "ফোন মুখ চেনে কীভাবে?, কার্ড 2"}]','["Phiarc, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Apple_Face_ID_infrared_dot_projector.jpg"]','tech','bolt','teal',1,'2027-03-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270317-11-eliza-the-first-chatbot-people-trusted','jontro-ar-ai','card','প্রথম চ্যাটবট এলাইজা','আইবিএম ৭০৯৪: এমআইটিতে এমন যন্ত্রে এলাইজা চলত','["▸ ১৯৬৬ সালে এমআইটির জোসেফ ওয়াইজেনবাম বানান এলাইজা, প্রথম দিকের চ্যাটবট।\\n▸ এটা আপনার কথাই ঘুরিয়ে প্রশ্ন বানাত, যেন একজন মনোবিদ কথা বলছেন।\\n▸ অনেকে এর কাছে মনের কথা খুলে বলতেন; এতে ওয়াইজেনবাম নিজেই অবাক হন।", "এক কথায়: যন্ত্র বুঝুক বা না বুঝুক, আমরা সহজেই ভেবে নিই সে বুঝছে।\\nমনে রাখুন: চ্যাটবট ভুলও বলে আত্মবিশ্বাসের সঙ্গে; জরুরি তথ্য অন্য জায়গায় মিলিয়ে নিন।"]','[{"label": "MIT News", "url": "https://news.mit.edu/2008/obit-weizenbaum-0310''"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/ELIZA'']"}]','[{"src": "/media/jontro-ar-ai/270317-11-eliza-the-first-chatbot-people-trusted-1.webp", "width": 960, "height": 1200, "alt": "প্রথম চ্যাটবট এলাইজা, কার্ড 1"}, {"src": "/media/jontro-ar-ai/270317-11-eliza-the-first-chatbot-people-trusted-2.webp", "width": 960, "height": 1200, "alt": "প্রথম চ্যাটবট এলাইজা, কার্ড 2"}]','["ArnoldReinhold, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:IBM_7094_console2.agr.JPG", "Marcin Wichary from San Franci, CC BY 2.0, https://commons.wikimedia.org/wiki/File:CHM_Artifacts_IBM_Model_7094_console_(2273107469).jpg"]','tech','bolt','teal',1,'2027-03-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270211-map-06-sahara','prithibi-amar-ghor','card','ভাবুর ম্যাপ: সাহারা মরুভূমি','উত্তর আফ্রিকা জুড়ে ছড়ানো সাহারা পৃথিবীর সবচেয়ে বড় উষ্ণ মরুভূমি, আয়তন প্রায় ৯০ লাখ বর্গকিলোমিটার (উৎসভেদে ৮৬ থেকে ৯২ লাখ)।','["আমরা সাহারা বলতে শুধু বালির ঢেউ ভাবি, অথচ বালির টিলা আর বালুর সমতল মিলিয়ে বড়জোর প্রায় এক-চতুর্থাংশ জায়গা (সূত্রভেদে ১২ থেকে ২৫ শতাংশ)। বাকিটা পাথুরে মালভূমি, কাঁকুরে সমতল আর পাহাড়।", "সাহারার মাঝামাঝি একটা বিন্দু থেকে ঢাকার সোজা দূরত্ব প্রায় ৭,৯০০ কিলোমিটার। সাহারায় একদিন কাটাতে হলে সাথে কী রাখতেন?"]','[{"label": "Encyclopaedia Britannica", "url": "https://www.britannica.com/place/Sahara-desert-Africa"}, {"label": "Geographical", "url": "https://geographical.co.uk/science-environment/geo-explainer-the-sahara-desert"}, {"label": "Distance", "url": "https://www.britannica.com/place/Sahara-desert-Africa"}]','[{"src": "/media/prithibi-amar-ghor/270211-map-06-sahara-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: সাহারা মরুভূমি, কার্ড 1"}]','["Thomas Fuhrmann (CC BY-SA 4.0), Wikimedia Commons"]','nature','drop','mint',1,'2027-02-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270225-map-08-antarctica','prithibi-amar-ghor','card','ভাবুর ম্যাপ: অ্যান্টার্কটিকা','পৃথিবীর একেবারে নিচের মহাদেশ অ্যান্টার্কটিকার বরফের চাদরেই জমা আছে পৃথিবীর বরফের সিংহভাগ (পৃথিবীর মিঠা পানির প্রায় ৬০ থেকে ৭০ শতাংশ)।','["মজার ব্যাপার, এত বরফ থাকলেও জায়গাটা সবচেয়ে শুকনো মহাদেশ: বছরে গড়ে বৃষ্টি-তুষার পড়ে প্রায় ১৫০ মিলিমিটার, ভেতরের দিকে ৫০ মিলিমিটারেরও কম।"]','[{"label": "British Antarctic Survey", "url": "https://www.bas.ac.uk/about/education-and-schools/antarctic-factsheet/"}, {"label": "American Museum of Natural History", "url": "https://www.amnh.org/learn-teach/curriculum-collections/antarctica/the-coldest-driest-windiest-highest-continent/some-background-on-antarctica"}, {"label": "Distance", "url": "https://www.bas.ac.uk/about/education-and-schools/antarctic-factsheet/"}]','[{"src": "/media/prithibi-amar-ghor/270225-map-08-antarctica-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: অ্যান্টার্কটিকা, কার্ড 1"}]','["Virtual-Pano (CC BY-SA 4.0), Wikimedia Commons"]','nature','drop','mint',1,'2027-02-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270107-map-01-salar-de-uyuni','prithibi-amar-ghor','card','ভাবুর ম্যাপ: সালার দে উয়ুনি, বলিভিয়া','দক্ষিণ আমেরিকার আন্দিজ পাহাড়ের কোলে প্রায় ১০,৫০০ বর্গকিলোমিটার জুড়ে শুধু সাদা লবণ! এটাই পৃথিবীর সবচেয়ে বড় লবণের সমতল, উচ্চতা সাগরতল থেকে ৩,৬৫০ মিটারের বেশি।','["বর্ষায় কয়েক সেন্টিমিটার পানি জমলে পুরো এলাকা আয়না হয়ে আকাশকে নিচে উল্টো করে দেখায়। তখন কোথায় মাটি আর কোথায় আকাশ, বোঝাই দায়!", "ঢাকা থেকে সোজা উড়ে গেলে দূরত্ব প্রায় ১৭,৭০০ কিলোমিটার। আপনি হলে প্রথম ছবিটা কোন ভঙ্গিতে তুলতেন?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Salar_de_Uyuni"}, {"label": "Encyclopaedia Britannica", "url": "https://www.britannica.com/place/Salar-de-Uyuni"}, {"label": "Distance", "url": "https://en.wikipedia.org/wiki/Salar_de_Uyuni"}]','[{"src": "/media/prithibi-amar-ghor/270107-map-01-salar-de-uyuni-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: সালার দে উয়ুনি, বলিভিয়া, কার্ড 1"}]','["Abel Maestro Garcia (Public domain), Wikimedia Commons"]','nature','drop','mint',1,'2027-01-07');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270114-map-02-dead-sea','prithibi-amar-ghor','card','ভাবুর ম্যাপ: মৃত সাগর','জর্ডান আর ইসরায়েলের মাঝখানে এই হ্রদের পানির তল সাগরতল থেকে ৪৩০ মিটারেরও বেশি নিচে, যা স্থলভাগের সবচেয়ে নিচু জায়গা। পানিতে লবণ প্রায় ৩৪%, মানে সাধারণ সাগরের প্রায় ১০ গুণ নোনা।','["এত নোনা পানির ঘনত্ব বেশি, তাই মানুষ সহজেই ভেসে থাকে। তবে চোখে পানি লাগলে ভীষণ জ্বলে, সাবধান!", "ঢাকা থেকে সোজা দূরত্ব প্রায় ৫,৪০০ কিলোমিটার। ভেসে ভেসে বই পড়তে পারবেন বলে মনে হয়?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Salar_de_Uyuni"}, {"label": "Encyclopaedia Britannica", "url": "https://www.britannica.com/place/Salar-de-Uyuni"}, {"label": "Distance", "url": "https://en.wikipedia.org/wiki/Salar_de_Uyuni"}]','[{"src": "/media/prithibi-amar-ghor/270114-map-02-dead-sea-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: মৃত সাগর, কার্ড 1"}]','[]','nature','drop','mint',1,'2027-01-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270121-map-03-coxs-bazar','prithibi-amar-ghor','card','ভাবুর ম্যাপ: কক্সবাজার','বাংলাদেশের দক্ষিণ-পূর্ব কোণে বঙ্গোপসাগরের ধারে কক্সবাজার সৈকত প্রায় ১২০ কিলোমিটার লম্বা। একে পৃথিবীর অন্যতম দীর্ঘ প্রাকৃতিক বালুকাবেলা বলা হয়।','["সাগর পশ্চিমে, তাই শীতের বিকেলে সূর্য ডোবে একেবারে ঢেউয়ের বুকে।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Bangladesh Consulate Sydney (MoFA)", "url": ""}, {"label": "Distance", "url": ""}]','[{"src": "/media/prithibi-amar-ghor/270121-map-03-coxs-bazar-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: কক্সবাজার, কার্ড 1"}]','[]','nature','drop','mint',1,'2027-01-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270128-map-04-everest','prithibi-amar-ghor','card','ভাবুর ম্যাপ: মাউন্ট এভারেস্ট','পৃথিবীর সবচেয়ে উঁচু পর্বতচূড়া এভারেস্ট। ২০২০ সালের ডিসেম্বরে নেপাল ও চীন একসাথে ঘোষণা করেছে, এর উচ্চতা সাগরতল থেকে ৮,৮৪৮.৮৬ মিটার। (নেপাল আগে ব্যবহার করত ১৯৫৪ সালের মাপ, ৮,৮৪৮ মিটার।)','["ঢাকা থেকে সোজা দূরত্ব মাত্র প্রায় ৫৮০ কিলোমিটার, যদিও পথটা কঠিন!"]','[{"label": "The Kathmandu Post", "url": ""}, {"label": "Al Jazeera", "url": ""}, {"label": "Distance", "url": ""}]','[{"src": "/media/prithibi-amar-ghor/270128-map-04-everest-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: মাউন্ট এভারেস্ট, কার্ড 1"}]','[]','nature','drop','mint',1,'2027-01-28');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270304-map-09-lake-baikal','prithibi-amar-ghor','card','ভাবুর ম্যাপ: বৈকাল হ্রদ','সাইবেরিয়ার বৈকাল হ্রদ পৃথিবীর সবচেয়ে গভীর হ্রদ: গভীরতা প্রায় ১,৬০০ থেকে ১,৭০০ মিটার (মাপের উৎসভেদে কিছুটা আলাদা)। বয়সও আনুমানিক ২.৫ কোটি বছর, যা একে সবচেয়ে পুরোনো হ্রদগুলোর একটি করেছে।','["ইউনেস্কো বলছে, পৃথিবীর অজমাট মিঠা পানির প্রায় ২০ শতাংশ এই একটি হ্রদে।", "ঢাকা থেকে সোজা দূরত্ব প্রায় ৩,৬০০ কিলোমিটার (স্থানাঙ্ক থেকে হিসাব করা)। প্রশ্ন: এত পুরোনো হ্রদের তলায় কী লুকিয়ে আছে বলে মনে হয়?"]','[{"label": "UNESCO World Heritage Centre", "url": "https://whc.unesco.org/en/list/754/"}, {"label": "Encyclopaedia Britannica", "url": "https://www.britannica.com/place/Lake-Baikal"}]','[{"src": "/media/prithibi-amar-ghor/270304-map-09-lake-baikal-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: বৈকাল হ্রদ, কার্ড 1"}]','["Vyacheslav Argenberg (CC BY 4.0), Wikimedia Commons"]','nature','drop','mint',1,'2027-03-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270318-map-11-uluru','prithibi-amar-ghor','card','ভাবুর ম্যাপ: উলুরু, অস্ট্রেলিয়া','অস্ট্রেলিয়ার মাঝখানের মরুভূমিতে একাই দাঁড়িয়ে এক বিশাল লাল বেলেপাথরের চাঁই, নাম উলুরু। মরুভূমির সমতল থেকে উচ্চতা ৩৪৮ মিটার (সমুদ্রতল থেকে প্রায় ৮৬৩ মিটার)।','["পাথরটা ভেতরে ধূসর। ওপরের পৃষ্ঠের লোহা মরচে ধরে লাল হয়েছে, আর বেশিরভাগ অংশ নাকি মাটির নিচে।\\nউলুরু স্থানীয় আনাঙ্গু আদিবাসীদের কাছে একটি পবিত্র স্থান।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Uluru"}, {"label": "WorldAtlas", "url": "https://www.worldatlas.com/mountains/uluru-ayers-rock.html"}]','[{"src": "/media/prithibi-amar-ghor/270318-map-11-uluru-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: উলুরু, অস্ট্রেলিয়া, কার্ড 1"}]','["Dietmar Rabich (CC BY-SA 4.0), Wikimedia Commons"]','nature','drop','mint',1,'2027-03-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270325-map-12-nohkalikai-falls','prithibi-amar-ghor','card','ভাবুর ম্যাপ: নহকালিকাই জলপ্রপাত','আমাদের উত্তর-পূর্ব সীমান্তের ওপারে ভারতের মেঘালয়ে চেরাপুঞ্জির কাছে এই ঝরনা। উচ্চতা প্রায় ৩৪০ মিটার, ভারতের সবচেয়ে উঁচু প্লাঞ্জ ঝরনা। প্লাঞ্জ মানে পানি পাথর ছুঁয়ে নামে না, সোজা ঝাঁপিয়ে পড়ে।','["বঙ্গোপসাগরের মৌসুমি বাতাস খাসি পাহাড়ে বাধা পেয়ে ওপরে উঠে যায় আর ভারী বৃষ্টি ঝরায়। চেরাপুঞ্জি-মৌসিনরাম অঞ্চল পৃথিবীর অন্যতম বেশি বৃষ্টির জায়গা, এই বৃষ্টিই ঝরনাকে প্রাণ দেয়।\\nনামের অর্থ ‘কা লিকাইয়ের লাফ’, নিয়ে স্থানীয় একটি লোককথাও আছে।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nohkalikai_Falls"}, {"label": "Incredible India (Ministry of Tourism)", "url": "https://www.incredibleindia.gov.in/en/meghalaya/cherrapunjee/nohkalikai-falls"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cherrapunji"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mawsynram"}]','[{"src": "/media/prithibi-amar-ghor/270325-map-12-nohkalikai-falls-1.webp", "width": 960, "height": 1200, "alt": "ভাবুর ম্যাপ: নহকালিকাই জলপ্রপাত, কার্ড 1"}]','["Bikash9c (CC BY-SA 4.0), Wikimedia Commons"]','nature','drop','mint',1,'2027-03-25');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270106-01-earth-s-thin-blanket-of-air','prithibi-amar-ghor','card','কম্বল না থাকলে পৃথিবী বরফ','মহাকাশ স্টেশন থেকে তোলা: পৃথিবীর কিনারে বাতাসের স্তর','["▸ কার্বন ডাই-অক্সাইড, মিথেন, জলীয় বাষ্পের মতো গ্যাস মাটি থেকে ওঠা তাপ ধরে রাখে।\\n▸ এই গ্যাসের কম্বল না থাকলে পৃথিবীর তাপমাত্রা থাকত হিমাঙ্কের নিচে।\\n▸ তেল, গ্যাস আর কয়লা পোড়ালে বাতাসে বাড়তি কার্বন ডাই-অক্সাইড মেশে; কম্বল মোটা হয়।", "এক কথায়: কম্বলটা দরকারি; সমস্যা হলো আমরা সেটা দিন দিন মোটা করছি।\\nআজকের ছোট কাজ: ঘর থেকে বের হওয়ার আগে লাইট আর ফ্যানের সুইচ বন্ধ করে যান।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১৩\\nসূত্র: NASA Science, ''What is the greenhouse effect?'' (greenhouse gases: carbon dioxide, methane, ozone, nitrous oxide, CFCs, water vapour; burning fossil fuels released CO2 that traps extra heat); UCAR Center for Science Education, ''The Greenhouse Effect'' (greenhouse gases absorb heat radiated from the surface; without the greenhouse effect Earth''s temperature would be below freezing; burning fossil fuels releases CO2)\\n#জলবায়ু #গ্রিনহাউস #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/"}, {"label": "UCAR Center for Science Education", "url": "https://scied.ucar.edu/learning-zone/how-climate-works/greenhouse-effect"}]','[{"src": "/media/prithibi-amar-ghor/270106-01-earth-s-thin-blanket-of-air-1.webp", "width": 960, "height": 1200, "alt": "কম্বল না থাকলে পৃথিবী বরফ, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270106-01-earth-s-thin-blanket-of-air-2.webp", "width": 960, "height": 1200, "alt": "কম্বল না থাকলে পৃথিবী বরফ, কার্ড 2"}]','["NASA, Public domain, https://commons.wikimedia.org/wiki/File:ISS-24_Crescent_moon_and_the_thin_line_of_Earth%27s_atmosphere.jpg", "NASA Earth Observatory, Public domain, https://commons.wikimedia.org/wiki/File:Top_of_Atmosphere.jpg"]','nature','drop','mint',1,'2027-01-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270113-02-vegetable-gardens-that-float','prithibi-amar-ghor','card','পানির ওপর ফলে বেগুন-ঢেঁড়স','দক্ষিণের বিলে ভাসমান ''ধাপ'' বাগান, ওপর থেকে তোলা ছবি','["▸ গোপালগঞ্জ, পিরোজপুর, বরিশালে বন্যায় ডোবা জমিতে কৃষকেরা বানান ''ধাপ'' বা ''বাইরা''।\\n▸ নিচে কচুরিপানা আর বাঁশ, ওপরে পচা পাতার সার; তাতে ফলে ঢেঁড়স, বেগুন, শসা, লালশাক।\\n▸ ২০১৫ সালে জাতিসংঘের এফএও এই ধাপ চাষকে বিশ্ব কৃষি-ঐতিহ্যের স্বীকৃতি দেয়।", "এক কথায়: পানি সরে না? তাহলে বাগানটাই পানির ওপর ভাসিয়ে দাও!\\nআজকের ছোট কাজ: পুরোনো বালতি বা ভাঙা টবে একটা মরিচ বা টমেটোর চারা লাগান।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ২, ১৩\\nসূত্র: FAO GIAHS, ''Floating Garden Agricultural Practices, Bangladesh'' (Gopalganj, Pirojpur, Barisal; bed ''dhap'' of water hyacinth, plant residues and bamboo; okra, brinjal, cucumber, amaranth and more; designated GIAHS 2015); Rosa Luxemburg Stiftung, ''The floating gardens of Bangladesh'' (called dhap or baira; water hyacinth, bamboo, crop residues; FAO GIAHS 2015)\\n#ভাসমান_বাগান #কৃষি #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "FAO GIAHS", "url": "https://www.fao.org/giahs/giahs-around-the-world/bangladesh-floating-garden-agricultural-practices/en"}, {"label": "Rosa Luxemburg Stiftung", "url": "https://www.rosalux.de/en/news/id/53969/the-floating-gardens-of-bangladesh"}]','[{"src": "/media/prithibi-amar-ghor/270113-02-vegetable-gardens-that-float-1.webp", "width": 960, "height": 1200, "alt": "পানির ওপর ফলে বেগুন-ঢেঁড়স, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270113-02-vegetable-gardens-that-float-2.webp", "width": 960, "height": 1200, "alt": "পানির ওপর ফলে বেগুন-ঢেঁড়স, কার্ড 2"}]','["Azimronnie, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Traditional_floating_vegetable_garden_40.jpg", "Azimronnie, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Traditional_floating_vegetable_garden_11.jpg"]','nature','drop','mint',1,'2027-01-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270120-03-who-names-the-cyclones','prithibi-amar-ghor','card','১৬৯টি ঝড়ের নাম তৈরি','১৯ মে ২০২০: বঙ্গোপসাগরে আম্ফান, নাসার উপগ্রহ থেকে','["▸ বাংলাদেশসহ ১৩টি দেশ ১৩টি করে নাম দিয়েছে; মোট ১৬৯টি নামের নতুন তালিকা।\\n▸ আগের তালিকাটা ২০০৪ সালের, বাংলাদেশসহ আটটি দেশ মিলে বানানো।\\n▸ কোনো ঝড়ে একবার একটা নাম ব্যবহার হলে সেই নাম আর কখনো ফিরে আসে না।", "এক কথায়: নাম দেয় বাংলাদেশসহ ১৩টি দেশ; একটা নাম কেবল একবার।\\nআজকের ছোট কাজ: পরিবারের সবাই মিলে জেনে নিন ঝড়ের সময় সবচেয়ে কাছের আশ্রয়কেন্দ্র কোনটা।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১৩\\nসূত্র: WMO, ''New list of names issued for tropical cyclones over north Indian Ocean'' (1 May 2020; 169 names, 13 from each of 13 WMO/ESCAP panel members incl. Bangladesh; old 2004 list from eight countries; a used name is never used again); Down To Earth, ''IMD presents new, neutral names...'' (names will not be repeated; all but one name, Amphan, of the older list used); Drishti IAS, ''New List of Names of Tropical Cyclones'' (169 names, 13 each for 13 countries; original list from eight countries incl. Bangladesh)\\n#ঘূর্ণিঝড় #আবহাওয়া #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "WMO", "url": "https://wmo.int/node/12752"}, {"label": "Down To Earth", "url": "https://www.downtoearth.org.in/natural-disasters/imd-presents-new-neutral-names-for-future-cyclones-in-north-indian-ocean-70782"}, {"label": "Drishti IAS", "url": "https://www.drishtiias.com/daily-updates/daily-news-analysis/new-list-of-names-of-tropical-cyclones/print_manually"}]','[{"src": "/media/prithibi-amar-ghor/270120-03-who-names-the-cyclones-1.webp", "width": 960, "height": 1200, "alt": "১৬৯টি ঝড়ের নাম তৈরি, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270120-03-who-names-the-cyclones-2.webp", "width": 960, "height": 1200, "alt": "১৬৯টি ঝড়ের নাম তৈরি, কার্ড 2"}]','["MODIS Land Rapid Response Team, Public domain, https://commons.wikimedia.org/wiki/File:Tropical_Cyclone_Amphan_(MODIS_2020-05-19).jpg", "NASA image by Jesse Allen, Public domain, https://commons.wikimedia.org/wiki/File:Cyclone_Mala_26_apr_2006_0435Z.jpg"]','nature','drop','mint',1,'2027-01-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270127-04-cyclone-shelters-on-stilts','prithibi-amar-ghor','card','১৯৭০-এ ছিল মাত্র ৪৪টি','উঁচু পিলারের ওপর দাঁড়ানো ঘূর্ণিঝড় আশ্রয়কেন্দ্র, বাংলাদেশ','["▸ ১৯৭০ সালের ভোলা ঘূর্ণিঝড়ের সময় সারা দেশে আশ্রয়কেন্দ্র ছিল মাত্র ৪৪টি।\\n▸ ভোলার পর শুরু হয় সাইক্লোন প্রিপেয়ার্ডনেস প্রোগ্রাম (সিপিপি); স্বেচ্ছাসেবকেরা মাইকে সতর্ক করে মানুষকে আশ্রয়কেন্দ্রে যেতে সাহায্য করেন।\\n▸ এখন ১৪ হাজারের বেশি আশ্রয়কেন্দ্র আছে, তবু উপকূলের সব মানুষের জন্য সেটা যথেষ্ট নয়।", "এক কথায়: আগে থেকে সংকেত আর কাছের আশ্রয়, এই দুটোই প্রাণ বাঁচায়।\\nআজকের ছোট কাজ: আপনার এলাকার আশ্রয়কেন্দ্রের নাম একটা কাগজে লিখে ঘরে টাঙিয়ে রাখুন।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১৩, ১১\\nসূত্র: The Business Standard / ICCCAD, ''50 years of cyclone preparedness'' (only 44 cyclone shelters in 1970; CPP set up by the Bangladesh Red Crescent Society after Cyclone Bhola; more than 14,000 shelters per IFRC, still insufficient); ''Building Resilience from the Grassroots: The Cyclone Preparedness Programme at 50'' (PMC9657222; volunteers give early warning with megaphones, sirens and help vulnerable residents reach shelters; thousands of shelters built)\\n#ঘূর্ণিঝড় #আশ্রয়কেন্দ্র #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "The Business Standard / ICCCAD", "url": "https://icccad.net/the-business-standard/50-years-of-cyclone-preparedness-success-in-saving-lives-but-not-livelihood-over-the-past-30-years-the-number-of-cyclone-shelters-have-increased-from-400-to-14000-but-it-is-still-insufficient-for/"}, {"label": "''Building Resilience from the Grassroots", "url": ""}]','[{"src": "/media/prithibi-amar-ghor/270127-04-cyclone-shelters-on-stilts-1.webp", "width": 960, "height": 1200, "alt": "১৯৭০-এ ছিল মাত্র ৪৪টি, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270127-04-cyclone-shelters-on-stilts-2.webp", "width": 960, "height": 1200, "alt": "১৯৭০-এ ছিল মাত্র ৪৪টি, কার্ড 2"}]','["Helena Wright, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Cyclone_Shelter_(15265520285).jpg", "Helena Wright, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Cyclone_Shelter_Construction_(15078948837).jpg"]','nature','drop','mint',1,'2027-01-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270203-05-rooftop-solar-for-village-homes','prithibi-amar-ghor','card','৪১ লাখ ঘরে সোলার','টিনের চালে বসানো সোলার হোম সিস্টেমের প্যানেল','["▸ গ্রিডের বিদ্যুৎ নেই এমন গ্রামে চালে ছোট সোলার প্যানেল বসিয়ে বাতি, পাখা, টিভি আর মোবাইল চার্জের কাজ চালানো হয়।\\n▸ ইডকলের ভাষায়, এটি বিশ্বের সবচেয়ে বড় অফ-গ্রিড বিদ্যুতায়ন কর্মসূচি বলে স্বীকৃত।\\n▸ এই কর্মসূচিতে প্রায় ৪১ লাখ সোলার সিস্টেম বসেছে, আর ঘরে কেরোসিনের বাতির জায়গা নিয়েছে সোলারের আলো।", "এক কথায়: গ্রিড না এলেও রোদ এসেছে; তাই ঘরে আলো জ্বলে।\\nআজকের ছোট কাজ: দিনের বেলা পর্দা সরিয়ে প্রাকৃতিক আলোয় কাজ করুন, বাতি বন্ধ রাখুন।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ৭, ১৩\\nসূত্র: IDCOL, ''Solar Home System Program'' (acclaimed as the largest off-grid electrification program in the world; about 4.13 million SHSs installed; users replaced kerosene lamps with SHS light and run TV, radio, fan, mobile charger); energypedia NAE case study / TBS News (about 4.1 million systems by 2016-18; not re-opened, used only as cross-check)\\n#সোলার #নবায়নযোগ্য_শক্তি #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "IDCOL", "url": "https://idcol.org/idcol_new/public/renewable/solar-home-system-program"}, {"label": "energypedia NAE case study / TBS News", "url": "https://energypedia.info/wiki/NAE_Case_Study:_Bangladesh,_IDCOL_Solar_Home_Systems"}]','[{"src": "/media/prithibi-amar-ghor/270203-05-rooftop-solar-for-village-homes-1.webp", "width": 960, "height": 1200, "alt": "৪১ লাখ ঘরে সোলার, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270203-05-rooftop-solar-for-village-homes-2.webp", "width": 960, "height": 1200, "alt": "৪১ লাখ ঘরে সোলার, কার্ড 2"}]','["Helena Wright, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Solar_Panel_on_Roof.jpg", "Helena Wright, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Solar_building_(36816349445).jpg"]','nature','drop','mint',1,'2027-02-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270210-06-polythene-ban-and-the-jute-bag','prithibi-amar-ghor','card','পাটের ব্যাগ ৩ মাসে পচে','পাটখেত: যে গাছ থেকে সোনালী আঁশ আসে','["▸ ২০০২ সালে বাংলাদেশ পলিথিন ব্যাগের ব্যবহার সম্পূর্ণ নিষিদ্ধ করার ঘোষণা দেয়।\\n▸ সস্তা বিকল্প ছিল না আর নজরদারিও দুর্বল ছিল, তাই ব্যবহার থামেনি।\\n▸ বিজ্ঞানী মোবারক আহমদ খান পাটের সেলুলোজ থেকে ''সোনালী ব্যাগ'' বানান; তাঁর কথায়, মাটিতে পুঁতলে প্রায় তিন মাসে ব্যাগটা পচে যায়।", "এক কথায়: নিষেধের সঙ্গে ভালো বিকল্প থাকলে তবেই কাজ হয়।\\nআজকের ছোট কাজ: বাজারে যাওয়ার সময় সঙ্গে একটা কাপড় বা পাটের থলে নিয়ে যান, ফেলনা ব্যাগ ছাড়াই।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১২, ১৪\\nসূত্র: The Daily Star, ''Polythene Ban in Bangladesh'' (Bangladesh announced a complete ban on polythene bags in 2002; authorities reluctant to enforce, alternatives scarce); Global Citizen, ''Bangladeshi Scientist Invents Biodegradable Single-Use Bag Made From Jute'' (Mubarak Ahmad Khan; jute cellulose; biodegradable, breaks down in about three months buried in soil); UNB, ''Bangladesh has the answer to polythene menace'' (thin polythene banned 2002; Sonali bag from jute cellulose)\\n#পলিথিন #পাট #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "The Daily Star", "url": "https://www.thedailystar.net/business/economy/news/polythene-ban-litmus-test-will-and-eco-innovation-3801776"}, {"label": "Global Citizen", "url": "https://www.globalcitizen.org/en/content/bangladesh-invents-biodegradable-throw-away-bag/"}, {"label": "UNB", "url": "https://unb.com.bd/category/Special/bangladesh-has-the-answer-to-polythene-menace/10981"}]','[{"src": "/media/prithibi-amar-ghor/270210-06-polythene-ban-and-the-jute-bag-1.webp", "width": 960, "height": 1200, "alt": "পাটের ব্যাগ ৩ মাসে পচে, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270210-06-polythene-ban-and-the-jute-bag-2.webp", "width": 960, "height": 1200, "alt": "পাটের ব্যাগ ৩ মাসে পচে, কার্ড 2"}]','["Engr.Raju, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Jute_Field.jpg", "Efkanakbiyik, CC0, https://commons.wikimedia.org/wiki/File:Baghashtag-Jute-bag.jpg"]','nature','drop','mint',1,'2027-02-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270217-07-rice-that-survives-salt','prithibi-amar-ghor','card','লোনা মাটিতেও ধান ফলে','পানি ভরা জমিতে রোপা ধানের চারা, বাংলাদেশ','["▸ সমুদ্রের লোনা পানি ঢুকলে উপকূলের জমিতে সাধারণ ধান ভালো হয় না।\\n▸ ব্রি ধান৪৭ বোরো মৌসুমের জন্য বানানো লবণসহনশীল জাত, যার কথা আইআরআরআই-এর গবেষণা-নথিতে আছে।\\n▸ নতুন ব্রি ধান৯৭ ও ধান৯৯ উচ্চ লবণসহনশীল জাত হিসেবে ছাড়া হয়েছে।", "এক কথায়: লোনা জমিতেও চাষ চলে, কারণ জাতটাই লবণ সইতে পারে।\\nআজকের ছোট কাজ: ভাত বাড়ার সময় যতটা লাগবে ততটাই নিন, যেন পাতে কিছু না থাকে।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ২, ১৩\\nসূত্র: CGSpace / IRRI, International Rice Research Notes 32(1) 2007, ''BRRI Dhan47: A salt tolerant variety for the Boro season'' (title and listing opened; page has no abstract); PLOS ONE via PMC10810675, ''Developing climate-resilient rice varieties (BRRI dhan97 and BRRI dhan99) suitable for salt-stress environments in Bangladesh'' (abstract opened: salinity variation is the main cause of yield swings; two lines IR83484-3-B-7-1-1-1 and HHZ5-DT20-DT2-DT1 released as BRRI dhan97/dhan99 high salinity-tolerant varieties and out-yielded checks in trials; released as high salinity-tolerant varieties; develop salt-tolerant rice is the most pragmatic strategy; BRRI dhan67 used as tolerant check)\\n#ধান #লবণাক্ততা #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "CGSpace / IRRI", "url": "https://cgspace.cgiar.org/items/b72e6cfd-726a-412d-adf3-50e1c683430a"}, {"label": "PLOS ONE via PMC10810675", "url": ""}]','[{"src": "/media/prithibi-amar-ghor/270217-07-rice-that-survives-salt-1.webp", "width": 960, "height": 1200, "alt": "লোনা মাটিতেও ধান ফলে, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270217-07-rice-that-survives-salt-2.webp", "width": 960, "height": 1200, "alt": "লোনা মাটিতেও ধান ফলে, কার্ড 2"}]','["Ibrahim Husain Meraj, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Paddy_field,_Gaibandha,_Bangladesh_1.JPG", "Chand Ali from DHAKA, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Paddy_field_in_Bangladesh_(32901445855).jpg"]','nature','drop','mint',1,'2027-02-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270224-08-fresh-water-is-rare','prithibi-amar-ghor','card','পানির ৩%-এরও কম মিঠা','গাইবান্ধার একটি গ্রামের পুকুর, বাংলাদেশ','["▸ পৃথিবীর মোট পানির মধ্যে মিঠা পানি আছে ৩ শতাংশেরও কম মাত্র।\\n▸ সেই মিঠা পানির ৬৮ শতাংশের বেশি বরফে জমা, আর প্রায় ৩০ শতাংশ মাটির নিচে।\\n▸ নদী আর হ্রদের পানি মিঠা পানির ০.৩ শতাংশেরও কম; অথচ আমাদের পান, রান্না আর চাষের বেশির ভাগ কাজ চলে এই পানিতেই।", "এক কথায়: মোট পানির তুলনায় নদীর মিঠা পানি এক চিমটি।\\nআজকের ছোট কাজ: দাঁত মাজার সময় আর সাবান মাখার সময় ট্যাপ বন্ধ রাখুন, অনেক পানি বাঁচবে।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ৬\\nসূত্র: National Geographic Education, ''Earth''s Fresh Water'' (less than 3 % of Earth''s water is fresh; over 68 % of it in ice and glaciers, just over 30 % groundwater, about 0.3 % in lakes, rivers and swamps); USGS Water Science School, ''How much water is there on Earth?'' (over 68 percent of freshwater in ice and glaciers, 30 percent in the ground; fresh lakes 0.26 %, rivers 0.006 % of freshwater)\\n#মিঠা_পানি #পানি_সংকট #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "National Geographic Education", "url": "https://education.nationalgeographic.org/resource/earths-fresh-water/"}, {"label": "USGS Water Science School", "url": "https://www.usgs.gov/water-science-school/science/how-much-water-there-earth"}]','[{"src": "/media/prithibi-amar-ghor/270224-08-fresh-water-is-rare-1.webp", "width": 960, "height": 1200, "alt": "পানির ৩%-এরও কম মিঠা, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270224-08-fresh-water-is-rare-2.webp", "width": 960, "height": 1200, "alt": "পানির ৩%-এরও কম মিঠা, কার্ড 2"}]','["Ifteebd10, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Meghna_River,_Narsingdi.jpg", "Ifteebd10, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Meghna_River_with_a_boat,_Narsingdi.jpg"]','nature','drop','mint',1,'2027-02-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270303-09-trees-cool-the-city','prithibi-amar-ghor','card','ঢাকা ৪০ বছরে ১.৪° গরম','ঢাকার বায়তুল মোকাররমের উঠানে রোদ থেকে ছাতার নিচে আশ্রয়','["▸ ঘন বসতির বড় শহর আশপাশের চেয়ে বেশি গরম থাকে; যুক্তরাষ্ট্রে দিনে গড়ে ১ থেকে ৭ ডিগ্রি ফারেনহাইট বেশি।\\n▸ বিশ্বব্যাংক: চার দশকে ঢাকার সর্বোচ্চ তাপমাত্রা বেড়েছে ১.৪ ডিগ্রি, গোটা দেশের গড়ে ১.১ ডিগ্রি।\\n▸ গাছ ছায়া দেয়, আর পাতা থেকে পানি বাষ্প হয়ে আশপাশের বাতাস ঠান্ডা করে।", "এক কথায়: একটা গাছ মানে ছায়া, আর শহরের জন্য একটু ঠান্ডা।\\nআজকের ছোট কাজ: আজ আপনার রাস্তায় কয়টা বড় গাছ আছে গুনে দেখুন, তারপর বন্ধুকে বলুন।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১১, ১৩\\nসূত্র: US EPA, ''Learn About Heat Islands'' (US urban daytime temperatures about 1-7 F higher than outlying areas; larger, denser cities see the greatest differences; trees cool by shade and by transpiring water from leaves); Dhaka Tribune, ''Dhaka: an urban heat island'' (World Bank: Dhaka maximum temperature up 1.4 C over four decades vs 1.1 C national; loss of green space and vegetation a factor)\\n#গাছ #শহরের_গরম #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "US EPA", "url": ""}, {"label": "Dhaka Tribune", "url": "https://www.dhakatribune.com/bangladesh/dhaka/392187/dhaka-%E2%80%93-an-urban-heat-island"}]','[{"src": "/media/prithibi-amar-ghor/270303-09-trees-cool-the-city-1.webp", "width": 960, "height": 1200, "alt": "ঢাকা ৪০ বছরে ১.৪° গরম, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270303-09-trees-cool-the-city-2.webp", "width": 960, "height": 1200, "alt": "ঢাকা ৪০ বছরে ১.৪° গরম, কার্ড 2"}]','["A S M Jobaer, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Tree-lined_road_at_Aftabnagar_in_Dhaka_with_roadside_canopy_02.jpg", "Aashaa, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:July_Dhaka_Road_2024_view_tree.jpg"]','nature','drop','mint',1,'2027-03-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270310-10-food-we-throw-away','prithibi-amar-ghor','card','১০৫ কোটি টন খাবার ফেলা','বাজারের সবজির পসরা: এর অনেকটাই শেষে ফেলা হয়','["▸ ইউএনইপির ২০২৪ সালের প্রতিবেদন: ২০২২ সালে বিশ্বে ১০৫ কোটি টন খাবার নষ্ট হয়েছে।\\n▸ এটা ভোক্তাদের কাছে পৌঁছানো মোট খাবারের প্রায় পাঁচ ভাগের এক ভাগ।\\n▸ এর প্রায় ৬০ শতাংশ আসে ঘর থেকে; অথচ ৭৮ কোটির বেশি মানুষ ক্ষুধায় আছে।", "এক কথায়: খাবার নষ্টের সবচেয়ে বড় অংশ আমাদের নিজেদের ঘরে।\\nআজকের ছোট কাজ: রান্নার আগে ফ্রিজ দেখে নিন; যা সবচেয়ে পুরোনো, সেটা আগে খেয়ে ফেলুন।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১২, ২\\nসূত্র: UN News, ''With 783 million people going hungry, a fifth of all food goes to waste'' (27 March 2024; 1.05 billion tonnes wasted in 2022, 19 % of food available to consumers, households up to 60 %); BioCycle, ''UN''s 2024 Food Waste Index Attributes 60% Of Food Waste To Households'' (1.05 billion metric tons; one-fifth (19 %); households 631 million tonnes = 60 %). Both report UNEP Food Waste Index Report 2024.\\n#খাবার #অপচয় #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "UN News", "url": "https://news.un.org/en/story/2024/03/1148036"}, {"label": "BioCycle", "url": "https://www.biocycle.net/2024-food-waste-index/"}, {"label": "one-fifth", "url": ""}]','[{"src": "/media/prithibi-amar-ghor/270310-10-food-we-throw-away-1.webp", "width": 960, "height": 1200, "alt": "১০৫ কোটি টন খাবার ফেলা, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270310-10-food-we-throw-away-2.webp", "width": 960, "height": 1200, "alt": "১০৫ কোটি টন খাবার ফেলা, কার্ড 2"}]','["PizzaToast, CC0, https://commons.wikimedia.org/wiki/File:Vegetables_from_a_food_retailer%27s_container.jpg", "PizzaToast, CC0, https://commons.wikimedia.org/wiki/File:Edible_food_from_a_food_retailer%27s_container.jpg"]','nature','drop','mint',1,'2027-03-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270317-11-17-goals-one-planet','prithibi-amar-ghor','card','১৬৯টি কাজ, একটাই পৃথিবী','অ্যাপোলো ১৭ থেকে তোলা পৃথিবীর ছবি, ১৯৭২','["▸ ২০১৫ সালের সেপ্টেম্বরে জাতিসংঘের সব সদস্য দেশ ২০৩০ এজেন্ডা গ্রহণ করে।\\n▸ এতে ১৭টি টেকসই উন্নয়ন লক্ষ্য আর ১৬৯টি উপলক্ষ্য আছে; সবগুলো ২০৩০ সালের মধ্যে পূরণ করার লক্ষ্য ধরা হয়েছে।\\n▸ লক্ষ্যগুলো একটার সঙ্গে আরেকটা জড়ানো: ক্ষুধা, পানি, জলবায়ু, শিক্ষা, সবই একসাথে।", "এক কথায়: এই সিরিজের প্রতিটি পোস্ট এই ১৭ লক্ষ্যের কোনো একটার গল্প।\\nআজকের ছোট কাজ: ১৭টির মধ্যে যেটা আপনার সবচেয়ে কাছের মনে হয়, তার একটা ছোট কাজ ঠিক করুন।", "জাতিসংঘের টেকসই উন্নয়ন লক্ষ্য (এসডিজি): ১৩, ১৭\\nসূত্র: United Nations, ''Transforming our world: the 2030 Agenda for Sustainable Development'' (sdgs.un.org; leaders met at UN Headquarters 25-27 September 2015; 17 Sustainable Development Goals with 169 targets); UN UNOSD, ''Sustainable Development Goals'' (adopted by all UN Member States in 2015; 17 goals and 169 targets)\\n#এসডিজি #টেকসই_উন্নয়ন #পৃথিবী_আমার_ঘর #ভাবা_যায়"]','[{"label": "United Nations", "url": ""}, {"label": "UN UNOSD", "url": "https://sdgs.un.org/2030agenda"}]','[{"src": "/media/prithibi-amar-ghor/270317-11-17-goals-one-planet-1.webp", "width": 960, "height": 1200, "alt": "১৬৯টি কাজ, একটাই পৃথিবী, কার্ড 1"}, {"src": "/media/prithibi-amar-ghor/270317-11-17-goals-one-planet-2.webp", "width": 960, "height": 1200, "alt": "১৬৯টি কাজ, একটাই পৃথিবী, কার্ড 2"}]','["NASA/Apollo 17 crew", "taken by , Public domain, https://commons.wikimedia.org/wiki/File:The_Blue_Marble_(remastered).jpg", "Ranjithsiji, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Wikimania_2019_sustainable_development_goals_card.jpg"]','nature','drop','mint',1,'2027-03-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270108-01-capuchin-monkeys-and-fair-pay','bhabur-bhabna','card','বানর ছুড়ে ফেলল ফ্রি শসা','পাশের জন আঙুর পেলে, ২০০৩ সালের পরীক্ষায়','["▸ ২০০৩ সালে সারা ব্রসনান ও ফ্রান্স দ্য ভাল ইয়েরকিস কেন্দ্রে পাঁচটি স্ত্রী ক্যাপুচিন বানরের উপর পরীক্ষা চালান।\\n▸ নুড়ি দিলে বদলে খাবার মিলত। দুজনই শসা পেলে প্রায় সবাই নিয়ে নিত।\\n▸ পাশের জন একই কাজে আঙুর পেলে শসা নেওয়া কমে গেল; কেউ কেউ ছুড়ে ফেলল।", "এক কথায়: বিজ্ঞানীরা এখনও তর্ক করেন: এটা কি সত্যিই ন্যায্যতার বোধ, নাকি শুধু ভালো খাবার দেখে হতাশা, তা নিয়ে?\\nজানেন কি: প্রথম পরীক্ষায় বানর ছিল মাত্র পাঁচটি; পরের গবেষণায় কোথাও একই ফল মিলেছে, কোথাও মেলেনি।"]','[{"label": "Emory Report", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/bhabur-bhabna/270108-01-capuchin-monkeys-and-fair-pay-1.webp", "width": 960, "height": 1200, "alt": "বানর ছুড়ে ফেলল ফ্রি শসা, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270108-01-capuchin-monkeys-and-fair-pay-2.webp", "width": 960, "height": 1200, "alt": "বানর ছুড়ে ফেলল ফ্রি শসা, কার্ড 2"}]','["ChloeCrease, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Capuchin_monkeys_eating.jpg"]','history','bulb','coral',1,'2027-01-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270115-02-lost-wallets-and-honesty','bhabur-bhabna','card','বেশি টাকা, বেশি ফেরত','৪০ দেশে ১৭,৩০৩টি ''হারানো'' মানিব্যাগ','["▸ ২০১৯ সালে গবেষকরা হোটেল, ব্যাংক, পোস্ট অফিসের মতো জায়গায় ব্যাগগুলো জমা দেন।\\n▸ ভেতরে কার্ড, মুদির তালিকা, চাবি; কোনোটায় টাকা ছিল, কোনোটায় ছিল না।\\n▸ টাকা ছাড়া ব্যাগের প্রায় ৪০%, অল্প টাকার ৫১%, বেশি টাকার ৭২% মালিকের কাছে ফিরল।", "এক কথায়: টাকা বেশি থাকলে ব্যাগ বেশিবার ফিরেছে। গবেষকদের মতে চোর হতে না চাওয়া অনেক সময় লোভের চেয়ে জোরালো।\\nজানেন কি: দেশে দেশে হার আলাদা ছিল, তবু ৪০টির মধ্যে ৩৮ দেশেই টাকাসহ ব্যাগ বেশি ফিরেছে।"]','[{"label": "University of Zurich news", "url": ""}, {"label": "ScienceDaily", "url": "https://sciencedaily.com/releases/2019/06/190620153447.htm"}]','[{"src": "/media/bhabur-bhabna/270115-02-lost-wallets-and-honesty-1.webp", "width": 960, "height": 1200, "alt": "বেশি টাকা, বেশি ফেরত, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270115-02-lost-wallets-and-honesty-2.webp", "width": 960, "height": 1200, "alt": "বেশি টাকা, বেশি ফেরত, কার্ড 2"}]','["Martin Cooper, CC BY 2.0, https://commons.wikimedia.org/wiki/File:Lost_wallet_(10623155873).jpg"]','history','bulb','coral',1,'2027-01-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270122-03-i-cut-you-choose','bhabur-bhabna','card','যে কাটে, সে নেয় শেষে','পিঠা ভাগের ন্যায্য নিয়ম','["▸ নিয়মটা সহজ: একজন কাটে, অন্যজন আগে নিজের টুকরা বেছে নেয়।\\n▸ যে কাটে, সে জানে না অন্যজন কোনটা নেবে; তাই সে নিজের হিসাবে সমান করেই কাটে।\\n▸ ফলে দুজনেই নিজের হিসাবে অন্তত অর্ধেক পায়, কেউ অন্যের টুকরায় লোভ করে না।", "এক কথায়: গণিতে একে ''ডিভাইড অ্যান্ড চুজ'' বলে। দুজনের জন্য নিয়মটা ন্যায্য; বেশি মানুষ হলে আরও জটিল নিয়ম লাগে।\\nঘরে করে দেখুন: পরের বার বন্ধু বা ভাইবোনের সঙ্গে একটা পিঠা এভাবে ভাগ করে দেখুন।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Divide_and_choose"}, {"label": "University of Northern Iowa math notes", "url": ""}]','[{"src": "/media/bhabur-bhabna/270122-03-i-cut-you-choose-1.webp", "width": 960, "height": 1200, "alt": "যে কাটে, সে নেয় শেষে, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270122-03-i-cut-you-choose-2.webp", "width": 960, "height": 1200, "alt": "যে কাটে, সে নেয় শেষে, কার্ড 2"}]','["কাঠপিপঁড়ে, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:%E0%A6%9A%E0%A6%BF%E0%A6%A4%E0%A7%81%E0%A6%87_%E0%A6%AA%E0%A6%BF%E0%A6%A0%E0%A7%87_%E0%A7%A7.jpg"]','history','bulb','coral',1,'2027-01-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270129-04-marshmallow-and-trust','bhabur-bhabna','card','৩ মিনিট বনাম ১২ মিনিট','কথা ভাঙা বনাম কথা রাখা, ২০১৩ সালের পরীক্ষা','["▸ ২০১৩ সালে রচেস্টারে ২৮ জন শিশুকে একটি মার্শম্যালো দিয়ে বলা হয়: অপেক্ষা করলে আরেকটা পাবে।\\n▸ আগে কারও সঙ্গে কথা রাখা হয়, কারও সঙ্গে ভাঙা হয়।\\n▸ কথা-রাখা দল গড়ে ১২ মিনিট অপেক্ষা করল, অন্য দল প্রায় ৩ মিনিট।", "এক কথায়: শুধু ধৈর্যের জোর নয়, অপেক্ষা করা নির্ভর করে ''কথা রাখা হবে'' এই ভরসার ওপরও।\\nজানেন কি: কথা-রাখা দলের ১৪ জনের ৯ জন পুরো ১৫ মিনিট থেকেছে; অন্য দলে মাত্র ১ জন।"]','[{"label": "University of Rochester news", "url": ""}, {"label": "PMC3730121", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3730121"}]','[{"src": "/media/bhabur-bhabna/270129-04-marshmallow-and-trust-1.webp", "width": 960, "height": 1200, "alt": "৩ মিনিট বনাম ১২ মিনিট, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270129-04-marshmallow-and-trust-2.webp", "width": 960, "height": 1200, "alt": "৩ মিনিট বনাম ১২ মিনিট, কার্ড 2"}]','["John Morgan, CC BY 2.0, https://commons.wikimedia.org/wiki/File:White_Marshmallows.jpg"]','history','bulb','coral',1,'2027-01-29');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270205-05-rats-free-a-trapped-cagemate','bhabur-bhabna','card','বন্ধুকে মুক্ত করল ৩০টির ২৩টি ইঁদুর','২০১১ সালে শিকাগোর এক গবেষণা','["▸ ২০১১ সালে শিকাগোয় এক ইঁদুর মুক্ত থাকত, তার সঙ্গী আটকা থাকত বাক্সে।\\n▸ ৩০টি ইঁদুরের মধ্যে ২৩টি শেষ পর্যন্ত বাক্সের দরজা খুলে সঙ্গীকে বের করতে শিখল।\\n▸ বাক্স খালি থাকলে বা সেখানে খেলনা থাকলে প্রায় কেউ খুলল না: ৪০টির মধ্যে মাত্র ৫টি।", "এক কথায়: ইঁদুর অন্যের কষ্টে সাড়া দেয়, প্রমাণ মিলেছে। তবে একে ''দয়া'' বলা যায় কি না, তর্ক আছে।\\nজানেন কি: বন্ধুকে মুক্ত করা আর চকলেট, দুটোই পেলে ইঁদুররা প্রায়ই চকলেট ভাগও করেছে।"]','[{"label": "UChicago Medicine news", "url": ""}, {"label": "PMC3760221", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3760221"}]','[{"src": "/media/bhabur-bhabna/270205-05-rats-free-a-trapped-cagemate-1.webp", "width": 960, "height": 1200, "alt": "বন্ধুকে মুক্ত করল ৩০টির ২৩টি ইঁদুর, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270205-05-rats-free-a-trapped-cagemate-2.webp", "width": 960, "height": 1200, "alt": "বন্ধুকে মুক্ত করল ৩০টির ২৩টি ইঁদুর, কার্ড 2"}]','["Janet Stephens (photographer), Public domain, https://commons.wikimedia.org/wiki/File:Wistar_rat.jpg"]','history','bulb','coral',1,'2027-02-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270212-06-socrates-and-questions','bhabur-bhabna','card','সক্রেটিস কিছুই লেখেননি','তবু আজও তাঁর প্রশ্ন নিয়ে ভাবি','["▸ সক্রেটিস প্রাচীন এথেন্সের দার্শনিক (প্রায় ৪৭০–৩৯৯ খ্রিস্টপূর্ব); নিজের লেখা টিকে নেই।\\n▸ তাঁর কথা জানা যায় প্লেটো ও জেনোফনের লেখায়; তিনি প্রশ্ন করে মানুষকে ভাবাতেন।\\n▸ ৩৯৯ খ্রিস্টপূর্বে তাঁর মৃত্যুদণ্ড হয়। প্লেটোর বর্ণনায়: না-ভাবা জীবন বাঁচার যোগ্য নয়।", "এক কথায়: তাঁর প্রশ্নের ধরন থেকেই ''সক্রেটিক পদ্ধতি'' এসেছে। আসল সক্রেটিস কেমন ছিলেন, তা নিয়ে তর্ক আছে।\\nঘরে করে দেখুন: একটা বিশ্বাস নিয়ে নিজেকে তিনবার জিজ্ঞেস করুন: কেন?"]','[{"label": "Stanford Encyclopedia of Philosophy", "url": "https://plato.stanford.edu/entries/socrates"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Socrates"}]','[{"src": "/media/bhabur-bhabna/270212-06-socrates-and-questions-1.webp", "width": 960, "height": 1200, "alt": "সক্রেটিস কিছুই লেখেননি, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270212-06-socrates-and-questions-2.webp", "width": 960, "height": 1200, "alt": "সক্রেটিস কিছুই লেখেননি, কার্ড 2"}]','["Copy of Lysippos (?), Public domain, https://commons.wikimedia.org/wiki/File:Socrates_Louvre.jpg"]','history','bulb','coral',1,'2027-02-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270219-07-moral-machine-and-self-driving-cars','bhabur-bhabna','card','গাড়ি বাছে কাকে? ৪ কোটি সিদ্ধান্ত','২৩৩টি দেশ ও অঞ্চলের মানুষ খেলেছে','["▸ এমআইটির ''মোরাল মেশিন'' খেলায় এমন সড়ক দেখানো হয়, যেখানে দুর্ঘটনা এড়ানো যাবে না।\\n▸ মানুষ বেছে নেয় কাদের বাঁচানো উচিত। ২০১৮ সালে নেচারে প্রায় ৪ কোটি সিদ্ধান্তের ফল ছাপা হয়।\\n▸ বেশি মানুষ, তরুণ, আর প্রাণীর আগে মানুষ: এদের বাঁচানোর ঝোঁক ছিল প্রায় সবখানেই।", "এক কথায়: কিন্তু অঞ্চলভেদে পছন্দ আলাদা ছিল। তাই গাড়ির ''নীতি'' কে ঠিক করবে, তা নিয়ে সবাই একমত নয়।\\nজানেন কি: দেশগুলো তিন দলে ভাগ হয়েছিল; দলভেদে কাকে আগে বাঁচানো হবে, পছন্দ বদলেছে।"]','[{"label": "MIT Media Lab Moral Machine page", "url": ""}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Moral_Machine"}]','[{"src": "/media/bhabur-bhabna/270219-07-moral-machine-and-self-driving-cars-1.webp", "width": 960, "height": 1200, "alt": "গাড়ি বাছে কাকে? ৪ কোটি সিদ্ধান্ত, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270219-07-moral-machine-and-self-driving-cars-2.webp", "width": 960, "height": 1200, "alt": "গাড়ি বাছে কাকে? ৪ কোটি সিদ্ধান্ত, কার্ড 2"}]','["Grendelkhan, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Waymo_self-driving_car_front_view.gk.jpg"]','history','bulb','coral',1,'2027-02-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270226-08-vampire-bats-share-food','bhabur-bhabna','card','বাদুড় ভাগ করে নিজের রক্ত','ক্ষুধার্ত সঙ্গীকে ভ্যাম্পায়ার বাদুড় খাওয়ায়','["▸ ভ্যাম্পায়ার বাদুড় রাতে শিকারে বেরিয়ে প্রায়ই খালি হাতে ফেরে।\\n▸ ক্ষুধার্ত সঙ্গীকে তারা নিজের খাওয়া রক্তের কিছুটা মুখ থেকে ফিরিয়ে দেয়।\\n▸ বেশিরভাগ ভাগ মা-বাচ্চা বা আত্মীয়ের মধ্যে; ঘনিষ্ঠ অনাত্মীয় সঙ্গীর মধ্যেও হয়।", "এক কথায়: যে আগে খাইয়েছে, সে পরে বেশি পায়: একে ''পারস্পরিক সাহায্য'' বলে। আত্মীয়তাও বড় কারণ।\\nজানেন কি: কোস্টা রিকার মাঠ-গবেষণায় বন্য খাবার-ভাগের প্রায় ৭০% ছিল মায়ের বাচ্চাকে খাওয়ানো।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Common_vampire_bat"}, {"label": "Science News on Wilkinson''s vampire bat ", "url": ""}]','[{"src": "/media/bhabur-bhabna/270226-08-vampire-bats-share-food-1.webp", "width": 960, "height": 1200, "alt": "বাদুড় ভাগ করে নিজের রক্ত, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270226-08-vampire-bats-share-food-2.webp", "width": 960, "height": 1200, "alt": "বাদুড় ভাগ করে নিজের রক্ত, কার্ড 2"}]','["Gerry Carter, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Common_vampire_bat,_Desmodus_rotundus.jpg"]','history','bulb','coral',1,'2027-02-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270305-09-toddlers-happier-giving','bhabur-bhabna','card','নিজের খাবার দিলে শিশু বেশি খুশি','২২ মাস বয়সী ২০ জন শিশুর পরীক্ষা','["▸ ২০১২ সালে গবেষকরা প্রায় ২২ মাস বয়সী ২০ জন শিশুকে নিয়ে একটি পরীক্ষা করেন।\\n▸ শিশুরা একটি পুতুলকে খাবার দেয়: কখনও গবেষকের ''পাওয়া'' খাবার, কখনও নিজের খাবার।\\n▸ হাসি দেখে বোঝা গেল: দিতে বেশি খুশি, নিজের খাবার দিলে আরও বেশি।", "এক কথায়: ছোট বয়স থেকেই দিতে মানুষ আনন্দ পায়, এমন ইঙ্গিত মিলেছে। তবে নমুনা ছোট।\\nঘরে করে দেখুন: আজ একটা ছোট কিছু কাউকে দিয়ে দেখুন: পরে নিজের মন কেমন লাগে।"]','[{"label": "PMC3375233", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3375233"}, {"label": "ScienceDaily", "url": ""}]','[{"src": "/media/bhabur-bhabna/270305-09-toddlers-happier-giving-1.webp", "width": 960, "height": 1200, "alt": "নিজের খাবার দিলে শিশু বেশি খুশি, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270305-09-toddlers-happier-giving-2.webp", "width": 960, "height": 1200, "alt": "নিজের খাবার দিলে শিশু বেশি খুশি, কার্ড 2"}]','["Sm faysal, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Egg_Chitoi_Pitha_from_Bangladesh.jpg"]','history','bulb','coral',1,'2027-03-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270312-10-ship-of-theseus','bhabur-bhabna','card','সব তক্তা বদলালে, জাহাজ একই?','প্রাচীন গ্রিসের এক ধাঁধা','["▸ প্রাচীন গ্রিসে এথেনীয়রা বীর থিসিয়াসের জাহাজ বহু বছর রেখেছিল।\\n▸ পচা তক্তার জায়গায় নতুন তক্তা বসত। প্লুটার্কের লেখায় দার্শনিকদের তর্ক আছে।\\n▸ প্রশ্ন: সব তক্তা বদলালে কি আগের জাহাজই? হবসের প্রশ্ন: পুরনো তক্তা জুড়ে আরেকটা বানালে?", "এক কথায়: এর একটাই ''ঠিক'' উত্তর নেই। ''একই থাকা'' বলতে কী বোঝাই, তার ওপর উত্তর নির্ভর করে।\\nঘরে করে দেখুন: প্রিয় পুরনো জিনিসের কোন অংশ বদলালে সেটা আর ''আপনার'' থাকে না?"]','[{"label": "Stanford Encyclopedia of Philosophy", "url": "https://plato.stanford.edu/entries/identity-time"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ship_of_Theseus"}]','[{"src": "/media/bhabur-bhabna/270312-10-ship-of-theseus-1.webp", "width": 960, "height": 1200, "alt": "সব তক্তা বদলালে, জাহাজ একই?, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270312-10-ship-of-theseus-2.webp", "width": 960, "height": 1200, "alt": "সব তক্তা বদলালে, জাহাজ একই?, কার্ড 2"}]','["ThoughtIdRetired, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Clinker_built_dinghy_awaiting_restoration.jpg"]','history','bulb','coral',1,'2027-03-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270319-11-cambridge-declaration-on-consciousness','bhabur-bhabna','card','অক্টোপাসেরও আছেচেতনার গঠন','২০১২ সালের কেমব্রিজ ঘোষণা: বিজ্ঞানীদের কথা','["▸ ৭ জুলাই ২০১২, কেমব্রিজ বিশ্ববিদ্যালয়ের এক সম্মেলনে স্নায়ুবিজ্ঞানীরা একটি ঘোষণা দেন।\\n▸ তাঁদের মতে, চেতনার জন্য দরকারি মস্তিষ্কের গঠন শুধু মানুষের নেই।\\n▸ সব স্তন্যপায়ী, পাখি ও অক্টোপাসসহ আরও অনেক প্রাণীর মধ্যে এমন গঠন আছে বলে ঘোষণায় বলা হয়।", "এক কথায়: এটা বিজ্ঞানীদের ঘোষণা, আইন নয়। চেতনা ঠিক কী, ঘোষণা তার সংজ্ঞা দেয়নি।\\nজানেন কি: ঘোষণাপত্রে সই হয়েছিল ওই দিন সন্ধ্যায়, স্টিফেন হকিংয়ের উপস্থিতিতে।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cambridge_Declaration_on_Consciousness"}, {"label": "Kurzweil Library", "url": "https://thekurzweillibrary.com/animals-are-conscious-and-should-be-treated-as-such"}]','[{"src": "/media/bhabur-bhabna/270319-11-cambridge-declaration-on-consciousness-1.webp", "width": 960, "height": 1200, "alt": "অক্টোপাসেরও আছেচেতনার গঠন, কার্ড 1"}, {"src": "/media/bhabur-bhabna/270319-11-cambridge-declaration-on-consciousness-2.webp", "width": 960, "height": 1200, "alt": "অক্টোপাসেরও আছেচেতনার গঠন, কার্ড 2"}]','["H. Zell, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Octopus_vulgaris_03.jpg"]','history','bulb','coral',1,'2027-03-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270221-zoom-08-shaheed-minar','shobder-jadu','card','শহীদ দিবস ও আন্তর্জাতিক মাতৃভাষা দিবসে শ্রদ্ধাঞ্জলি। 🕊️','১. ১৯৫২ সালের ২১ ফেব্রুয়ারি মাতৃভাষা বাংলার মর্যাদার দাবিতে প্রাণ দিয়েছিলেন ভাষাশহীদরা। তাঁদের স্মরণে গড়া হয়েছে কেন্দ্রীয় শহীদ মিনার। নকশা ভাস্কর হামিদুর রহমানের, সাথে ছিলেন নভেরা আহমদ।','["২. ১৯৭১ সালে মুক্তিযুদ্ধের সময় পাকিস্তানি সেনাবাহিনী মিনারটি ভেঙে দেয়। স্বাধীনতার পর ১৯৭২ সালে আবার গড়া শুরু হয়।\\n৩. ইউনেস্কো ১৯৯৯ সালের ১৭ নভেম্বর ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস ঘোষণা করে, পালন শুরু হয় ২০০০ সাল থেকে।"]','[{"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Shaheed_Minar"}, {"label": "The Financial Express", "url": "https://thefinancialexpress.com.bd/views/turbulent-history-of-shaheed-minar-1582387861"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/International_Mother_Language_Day"}]','[{"src": "/media/shobder-jadu/270221-zoom-08-shaheed-minar-1.webp", "width": 960, "height": 1200, "alt": "শহীদ দিবস ও আন্তর্জাতিক মাতৃভাষা দিবসে শ্রদ্ধাঞ্জলি। 🕊️, কার্ড 1"}]','["Biswarup Ganguly (CC BY 3.0), Wikimedia Commons"]','history','book','coral',1,'2027-02-21');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270326-number-13-smriti-soudho','shobder-jadu','card','স্বাধীনতা দিবসে শ্রদ্ধাঞ্জলি। 🕊️','সাভারে, ঢাকা থেকে প্রায় ৩৫ কিলোমিটার উত্তর-পশ্চিমে জাতীয় স্মৃতিসৌধ, ১৯৭১ সালের মুক্তিযুদ্ধে শহীদদের স্মরণে। এর সর্বোচ্চ উচ্চতা প্রায় ১৫০ ফুট (প্রায় ৪৬ মিটার)।','["১৯৭৮ সালের জাতীয় নকশা প্রতিযোগিতায় জিতে স্থপতি সৈয়দ মাইনুল হোসেন এর নকশা করেন। উদ্বোধন হয় ১৯৮২ সালের ১৬ ডিসেম্বর।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Martyrs%27_Memorial"}, {"label": "A Walk in the World", "url": "https://awalkintheworld.com/national-monument-bangladesh/"}]','[{"src": "/media/shobder-jadu/270326-number-13-smriti-soudho-1.webp", "width": 960, "height": 1200, "alt": "স্বাধীনতা দিবসে শ্রদ্ধাঞ্জলি। 🕊️, কার্ড 1"}]','["Mfsam12 (CC BY-SA 4.0), Wikimedia Commons"]','history','book','coral',1,'2027-03-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270108-01-cha-and-tea-one-leaf-two-names','shobder-jadu','card','স্থলপথে ''চা'', সাগরপথে ''টি''','শ্রীমঙ্গলের চা বাগান: এখান থেকেই আসে আপনার কাপের চা','["▸ চীনা অক্ষর ‘茶’ একটাই, কিন্তু অঞ্চলভেদে উচ্চারণ আলাদা: কোথাও ''চা'', কোথাও ''তে''।\\n▸ স্থলপথে, মানে সিল্ক রোড ধরে, গেছে ''চা''; তাই আমাদের ''চা'', ফার্সিতে ''চায়''।\\n▸ সাগরপথে ডাচ বণিকরা নিয়ে গেছে ফুকিয়ানের ''তে''; তাই ইংরেজিতে ''টি''।", "এক কথায়: স্থলপথে ''চা'', সাগরপথে ''টি'': একটা শব্দ, দুই রাস্তা।\\nখুঁজে দেখুন: আজ কয়েকজনকে জিজ্ঞেস করুন, তাঁদের ভাষায় বা এলাকায় চা-কে কী বলে, আর লিখে রাখুন।"]','[{"label": "Horniman Museum", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270108-01-cha-and-tea-one-leaf-two-names-1.webp", "width": 960, "height": 1200, "alt": "স্থলপথে ''চা'', সাগরপথে ''টি'', কার্ড 1"}, {"src": "/media/shobder-jadu/270108-01-cha-and-tea-one-leaf-two-names-2.webp", "width": 960, "height": 1200, "alt": "স্থলপথে ''চা'', সাগরপথে ''টি'', কার্ড 2"}]','[]','history','book','coral',1,'2027-01-08');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270115-02-sukumar-ray-abol-tabol-nonsense-verse','shobder-jadu','card','মাত্র ৩৫ বছরে অবোল তাবোল','সুকুমার রায় আর তাঁর ''অবোল তাবোল'' (১৯২৩)','["▸ সুকুমার রায় জন্মান ১৮৮৭ সালে কলকাতায়; বেঁচেছিলেন মাত্র ৩৫ বছর।\\n▸ কলেজে পড়ার সময় তিনি বন্ধুদের নিয়ে গড়েছিলেন ''নন-সেন্স ক্লাব''।\\n▸ ১৯২৩ সালের ''অবোল তাবোল'' বাংলা সাহিত্যে মজার অর্থহীন ছড়ার সবচেয়ে চেনা বই।", "এক কথায়: অর্থহীন শোনালেও কথা নিয়ে এই খেলা ভাষা বোঝারই প্রমাণ।\\nলিখে ফেলুন: আজ দুই লাইনের একটা উদ্ভট ছড়া বানান, যার মাথামুন্ডু নেই কিন্তু মিল আছে।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}, {"label": "portrait public domain", "url": ""}]','[{"src": "/media/shobder-jadu/270115-02-sukumar-ray-abol-tabol-nonsense-verse-1.webp", "width": 960, "height": 1200, "alt": "মাত্র ৩৫ বছরে অবোল তাবোল, কার্ড 1"}, {"src": "/media/shobder-jadu/270115-02-sukumar-ray-abol-tabol-nonsense-verse-2.webp", "width": 960, "height": 1200, "alt": "মাত্র ৩৫ বছরে অবোল তাবোল, কার্ড 2"}]','[]','history','book','coral',1,'2027-01-15');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270122-03-portuguese-words-in-bangla','shobder-jadu','card','জানালা আসলে পর্তুগিজ শব্দ!','রোজকার কয়েকটা শব্দ এসেছে পর্তুগিজ ভাষা থেকে','["▸ ১৫১৮ সালে পর্তুগিজ জাহাজ চট্টগ্রামে নোঙর ফেলে; তারপর থেকে তাদের শব্দ বাংলায় ঢুকতে থাকে।\\n▸ জানালা এসেছে পর্তুগিজ janela থেকে, চাবি chave থেকে, বালতি balde থেকে।\\n▸ আলমারি, বারান্দা, সাবান, পেরেক আর গির্জাও একই পথে এসেছে।", "এক কথায়: ঘরের চেনা জিনিসের নামে লুকিয়ে আছে সাগর পাড়ি দেওয়া শব্দ।\\nখুঁজে দেখুন: আজ ঘরে জানালা, চাবি আর বালতি খুঁজে বের করুন; প্রতিটার পর্তুগিজ নাম মুখে বলুন।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270122-03-portuguese-words-in-bangla-1.webp", "width": 960, "height": 1200, "alt": "জানালা আসলে পর্তুগিজ শব্দ!, কার্ড 1"}, {"src": "/media/shobder-jadu/270122-03-portuguese-words-in-bangla-2.webp", "width": 960, "height": 1200, "alt": "জানালা আসলে পর্তুগিজ শব্দ!, কার্ড 2"}]','[]','history','book','coral',1,'2027-01-22');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270129-04-bangla-script-from-brahmi','shobder-jadu','card','বাংলা হরফের বয়স প্রায় হাজার বছর','তামার ফলকে খোদাই করা পুরোনো লিপি, যা থেকে আজকের বাংলা','["▸ বাংলা লিপি এসেছে ব্রাহ্মী লিপি থেকে; সম্রাট অশোকের শিলালিপিতেও এই ব্রাহ্মী দেখা যায়।\\n▸ গুপ্ত যুগের লিপি পেরিয়ে ধাপে ধাপে অক্ষরের গড়ন বদলেছে।\\n▸ একাদশ-দ্বাদশ শতকের তামার ফলকে লিপিটা প্রায় চেনা বাংলা রূপে মেলে।", "এক কথায়: আজকের বাংলা হরফ হাজার বছরের এক লম্বা বদলের ফল।\\nলিখুন: আজ নিজের নামটা সবচেয়ে সুন্দর হাতের লেখায় লিখে একজনকে দেখান।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270129-04-bangla-script-from-brahmi-1.webp", "width": 960, "height": 1200, "alt": "বাংলা হরফের বয়স প্রায় হাজার বছর, কার্ড 1"}, {"src": "/media/shobder-jadu/270129-04-bangla-script-from-brahmi-2.webp", "width": 960, "height": 1200, "alt": "বাংলা হরফের বয়স প্রায় হাজার বছর, কার্ড 2"}]','[]','history','book','coral',1,'2027-01-29');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270205-05-amar-sonar-bangla-national-anthem','shobder-jadu','card','মুক্তিযুদ্ধের সময়েই জাতীয় সংগীত','''আমার সোনার বাংলা'': রবীন্দ্রনাথ ঠাকুরের গান','["▸ গানটা লিখেছেন রবীন্দ্রনাথ ঠাকুর; এতে বাংলার আকাশ-বাতাসের প্রতি ভালোবাসার কথা আছে।\\n▸ ১৯৭১ সালে মুক্তিযুদ্ধের সময় প্রবাসী সরকার গানটি গ্রহণ করে।\\n▸ পরে সংবিধান একে দেশের জাতীয় সংগীত বলে ঘোষণা করে।", "এক কথায়: একজন কবির লেখা গান আজ একটা দেশের কণ্ঠস্বর।\\nগেয়ে দেখুন: আজ গানটার প্রথম চার লাইন মন দিয়ে গেয়ে বা শুনে দেখুন।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270205-05-amar-sonar-bangla-national-anthem-1.webp", "width": 960, "height": 1200, "alt": "মুক্তিযুদ্ধের সময়েই জাতীয় সংগীত, কার্ড 1"}, {"src": "/media/shobder-jadu/270205-05-amar-sonar-bangla-national-anthem-2.webp", "width": 960, "height": 1200, "alt": "মুক্তিযুদ্ধের সময়েই জাতীয় সংগীত, কার্ড 2"}]','[]','history','book','coral',1,'2027-02-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270212-06-nazrul-the-rebel-poet','shobder-jadu','card','নজরুলকে স্বাধীন ঢাকায় আনা হয় ১৯৭২-এ','১৯৭২ সালে স্বাধীন বাংলাদেশে আনা হয়েছিল তাঁকে','["▸ কাজী নজরুল ইসলাম জন্মান ২৪ মে ১৮৯৯, বর্ধমানের চুরুলিয়া গ্রামে।\\n▸ কবিতায় অন্যায়ের বিরুদ্ধে সাহসী কথা লিখে তিনি ''বিদ্রোহী কবি'' নামে পরিচিত হন।\\n▸ ২৪ মে ১৯৭২ তাঁকে ঢাকায় আনা হয়; ২৯ আগস্ট ১৯৭৬ ঢাকাতেই তিনি মারা যান।", "এক কথায়: বিদ্রোহী কবি আজ বাংলাদেশের জাতীয় কবি।\\nপড়ুন: আজ নজরুলের একটা কবিতা বা গান খুঁজে নিয়ে জোরে পড়ুন বা শুনুন।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270212-06-nazrul-the-rebel-poet-1.webp", "width": 960, "height": 1200, "alt": "নজরুলকে স্বাধীন ঢাকায় আনা হয় ১৯৭২-এ, কার্ড 1"}, {"src": "/media/shobder-jadu/270212-06-nazrul-the-rebel-poet-2.webp", "width": 960, "height": 1200, "alt": "নজরুলকে স্বাধীন ঢাকায় আনা হয় ১৯৭২-এ, কার্ড 2"}]','[]','history','book','coral',1,'2027-02-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270219-07-21-february-mother-language-day','shobder-jadu','card','একুশের গল্প এখন পুরো বিশ্বের','ঢাকার কেন্দ্রীয় শহীদ মিনার','["▸ ১৯৫২ সালের ২১ ফেব্রুয়ারি ঢাকায় মাতৃভাষার জন্য মানুষ প্রাণ দেন।\\n▸ ১৯৯৯ সালের ১৭ নভেম্বর ইউনেস্কো দিনটিকে আন্তর্জাতিক মাতৃভাষা দিবস ঘোষণা করে।\\n▸ প্রস্তাব এসেছিল বাংলাদেশ থেকে; ২০০০ সাল থেকে সারা বিশ্বে দিনটি পালিত হয়।", "এক কথায়: আমাদের মায়ের ভাষার দিন আজ সারা বিশ্বের সব মায়ের ভাষার দিন।\\nশিখুন: আজ অন্য ভাষার ''মা'' ডাক শিখুন; কাছের কেউ সেই ভাষা জানলে তাঁর কাছে শিখে নিন।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270219-07-21-february-mother-language-day-1.webp", "width": 960, "height": 1200, "alt": "একুশের গল্প এখন পুরো বিশ্বের, কার্ড 1"}, {"src": "/media/shobder-jadu/270219-07-21-february-mother-language-day-2.webp", "width": 960, "height": 1200, "alt": "একুশের গল্প এখন পুরো বিশ্বের, কার্ড 2"}]','[]','history','book','coral',1,'2027-02-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270226-08-how-the-book-fair-began','shobder-jadu','card','বইমেলা শুরু হয়েছিল চটের ওপর','১৯৭২: আমগাছের নিচে মাটিতে বিছানো কয়েকটা বই','["▸ ১৯৭২ সালে ভাষা আন্দোলনের স্মরণে বাংলা একাডেমির অনুষ্ঠানে চিত্তরঞ্জন সাহা বই সাজিয়ে বসেন।\\n▸ আমগাছের নিচে মাটিতে চট বিছিয়ে তিনি বইগুলো রেখেছিলেন।\\n▸ ১৯৭৮ সালে বাংলা একাডেমি আনুষ্ঠানিকভাবে মেলাটি চালু করে; এখন পুরো ফেব্রুয়ারি জুড়ে চলে।", "এক কথায়: এক টুকরো চটের ওপর শুরু হওয়া মেলা আজ পুরো মাসের উৎসব।\\nকিনুন: এবার মেলা থেকে একটা অচেনা লেখকের বই কিনে তার প্রথম পাতা পড়ে দেখুন।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270226-08-how-the-book-fair-began-1.webp", "width": 960, "height": 1200, "alt": "বইমেলা শুরু হয়েছিল চটের ওপর, কার্ড 1"}, {"src": "/media/shobder-jadu/270226-08-how-the-book-fair-began-2.webp", "width": 960, "height": 1200, "alt": "বইমেলা শুরু হয়েছিল চটের ওপর, কার্ড 2"}]','[]','history','book','coral',1,'2027-02-26');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270305-09-madhusudan-blank-verse-and-sonnet','shobder-jadu','card','বাংলায় প্রথম সনেট লেখেন মধুসূদন','মাইকেল মধুসূদন দত্তের নতুন ছন্দ','["▸ মধুসূদন দত্ত জন্মান ১৮২৪ সালে, যশোরের সাগরদাঁড়িতে।\\n▸ ১৮৬০ সালে তিনি প্রথম অমিত্রাক্ষর ছন্দ ব্যবহার করেন, যেখানে লাইনের শেষে মিল রাখতে হয় না।\\n▸ ১৮৬১ সালের ''মেঘনাদবধ কাব্য'' সেই ছন্দেই লেখা; বাংলা ভাষার প্রথম সনেটও তাঁর হাতে।", "এক কথায়: মিলের বাঁধন ভেঙে তিনি বাংলা কবিতায় নতুন পথ খুলে দেন।\\nলিখে দেখুন: মিল ছাড়া চার লাইন লিখুন, প্রতি লাইনে ১৪টা করে অক্ষর রেখে।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270305-09-madhusudan-blank-verse-and-sonnet-1.webp", "width": 960, "height": 1200, "alt": "বাংলায় প্রথম সনেট লেখেন মধুসূদন, কার্ড 1"}, {"src": "/media/shobder-jadu/270305-09-madhusudan-blank-verse-and-sonnet-2.webp", "width": 960, "height": 1200, "alt": "বাংলায় প্রথম সনেট লেখেন মধুসূদন, কার্ড 2"}]','[]','history','book','coral',1,'2027-03-05');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270312-10-lalon-songs-live-by-mouth','shobder-jadu','card','মুখে মুখে ফেরা লালনের গান','লালনের গান আজও আসরে আসরে গাওয়া হয়','["▸ লালন ফকির আনুমানিক ১৭৭৪ থেকে ১৮৯০ সাল পর্যন্ত বেঁচে ছিলেন; তিনি বাউল সাধক।\\n▸ কুষ্টিয়ার ছেঁউড়িয়ায় তাঁর আখড়া; প্রতি বছর সেখানে কয়েক দিনের মেলা বসে।\\n▸ তাঁর গান শিষ্যরা মুখে মুখে গেয়ে বাঁচিয়ে রেখেছেন।", "এক কথায়: যে গান মানুষের গলায় গলায় এতদিন বেঁচে আছে।\\nশুনুন: আজ একটা লালনগীতি মন দিয়ে শুনুন; একটা লাইনের মানে নিজের ভাষায় লিখে ফেলুন।"]','[{"label": "Banglapedia", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/shobder-jadu/270312-10-lalon-songs-live-by-mouth-1.webp", "width": 960, "height": 1200, "alt": "মুখে মুখে ফেরা লালনের গান, কার্ড 1"}, {"src": "/media/shobder-jadu/270312-10-lalon-songs-live-by-mouth-2.webp", "width": 960, "height": 1200, "alt": "মুখে মুখে ফেরা লালনের গান, কার্ড 2"}]','[]','history','book','coral',1,'2027-03-12');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270319-11-tagore-nobel-prize-gitanjali','shobder-jadu','card','ইউরোপের বাইরে প্রথম সাহিত্য নোবেল','১৯১৩: রবীন্দ্রনাথ ঠাকুর ও ''গীতাঞ্জলি''','["▸ রবীন্দ্রনাথ ঠাকুর জন্মান ১৮৬১ সালে কলকাতার জোড়াসাঁকোয়।\\n▸ ১৯১৩ সালে সাহিত্যে নোবেল পুরস্কার পান; ''গীতাঞ্জলি'' ছিল এর কেন্দ্রে।\\n▸ তিনি ইউরোপের বাইরের প্রথম সাহিত্য নোবেলজয়ী; ইংরেজি সংস্করণের ভূমিকা লেখেন ডব্লিউ. বি. ইয়েটস।", "এক কথায়: বাংলা ভাষার কবির লেখা পৌঁছে গেল সারা পৃথিবীতে।\\nপড়ুন: আজ গীতাঞ্জলির একটা গান বা কবিতা জোরে পড়ুন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Banglapedia", "url": ""}]','[{"src": "/media/shobder-jadu/270319-11-tagore-nobel-prize-gitanjali-1.webp", "width": 960, "height": 1200, "alt": "ইউরোপের বাইরে প্রথম সাহিত্য নোবেল, কার্ড 1"}, {"src": "/media/shobder-jadu/270319-11-tagore-nobel-prize-gitanjali-2.webp", "width": 960, "height": 1200, "alt": "ইউরোপের বাইরে প্রথম সাহিত্য নোবেল, কার্ড 2"}]','[]','history','book','coral',1,'2027-03-19');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270102-01-jamdani-is-woven-not-printed','ronge-ronge-bangla','card','জামদানির ফুল ছাপা নয়, তাঁতে বোনা!','কালো জামদানিতে সোনালী ফুলের নকশা, নারায়ণগঞ্জ','["▸ জামদানি পাতলা, স্বচ্ছ সুতি কাপড়, যা ঢাকার আশপাশে হস্তচালিত তাঁতে বোনা হয়।\\n▸ নকশা ছাপা বা আঁকা নয়; তাঁতেই ''ডিসকন্টিনিউয়াস ওয়েফট'' পদ্ধতিতে সরাসরি বোনা হয়, কাপড়ের সাথেই।\\n▸ ২০১৩ সালে ইউনেস্কো জামদানি বোনার শিল্পকে মানবজাতির অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় যুক্ত করে।", "এক কথায়: জামদানির ফুল আঁকা নয়, সুতো দিয়ে বোনা।\\nনিজে করে দেখি: জামা বা শাড়ির নকশায় আঙুল বুলিয়ে দেখুন: নকশা ছাপা, নাকি সুতোয় বোনা?"]','[{"label": "UNESCO", "url": "https://ich.unesco.org/en/decisions/8.COM/8.4"}, {"label": "The Daily Star", "url": "https://www.thedailystar.net/news/jamdani-recognised-as-intangible-cultural-heritage-by-unesco"}]','[{"src": "/media/ronge-ronge-bangla/270102-01-jamdani-is-woven-not-printed-1.webp", "width": 960, "height": 1200, "alt": "জামদানির ফুল ছাপা নয়, তাঁতে বোনা!, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270102-01-jamdani-is-woven-not-printed-2.webp", "width": 960, "height": 1200, "alt": "জামদানির ফুল ছাপা নয়, তাঁতে বোনা!, কার্ড 2"}]','["Wasiul Bahar, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Jamdani_display_at_BSCIC_Jamdani_palli,_Narayanganj_4.jpg", "Aashaa, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Jamdani_Saree_2014.jpg"]','history','sparkle','coral',1,'2027-01-02');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270109-02-rickshaw-art-tells-stories','ronge-ronge-bangla','card','রিকশার ছবি এখন ইউনেস্কোর ঐতিহ্য','২০২৩ সালে স্বীকৃতি পাওয়া রিকশা-চিত্র: পেছনের পর্দার ফুল-পাখি','["▸ ঢাকার রিকশার প্রায় প্রতিটি অংশ ফুল, পাখি, প্রাণী, গ্রামের দৃশ্য আর লেখা দিয়ে সাজানো হয়।\\n▸ ছবি আঁকা ফরমায়েশি কাজ; এই দক্ষতা সন্তান ও কাছের আত্মীয়দের মধ্যে শেখানো হয়।\\n▸ ২০২৩ সালের ডিসেম্বরে ইউনেস্কো ঢাকার রিকশা ও রিকশা-চিত্রকে অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় যুক্ত করে।", "এক কথায়: রিকশা শুধু যান নয়, শহরের চলন্ত ছবির গ্যালারি।\\nনিজে করে দেখি: পরের বার রিকশায় উঠলে পেছনের ছবিতে কী কী আঁকা আছে গুনে দেখুন।"]','[{"label": "Dhaka Tribune", "url": "https://www.dhakatribune.com/bangladesh/333159/unesco-recognizes-rickshaws-and-rickshaw-paintings"}, {"label": "BSS News", "url": "https://www.bssnews.net/news/161915"}]','[{"src": "/media/ronge-ronge-bangla/270109-02-rickshaw-art-tells-stories-1.webp", "width": 960, "height": 1200, "alt": "রিকশার ছবি এখন ইউনেস্কোর ঐতিহ্য, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270109-02-rickshaw-art-tells-stories-2.webp", "width": 960, "height": 1200, "alt": "রিকশার ছবি এখন ইউনেস্কোর ঐতিহ্য, কার্ড 2"}]','["Kritzolina, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rickshaws_in_Chittagong_-_detail_03.jpg", "Kritzolina, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Rickshaws_in_Chittagong_-_detail_02.jpg"]','history','sparkle','coral',1,'2027-01-09');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270116-03-shital-pati-from-murta-cane','ronge-ronge-bangla','card','শীতলপাটি এখন ইউনেস্কোর ঐতিহ্য (২০১৭)','মুর্তা বেতে বোনা পাটি, নকশায় নৌকা, মাছ আর পাখি','["▸ শীতলপাটি তৈরি হয় ''মুর্তা'' নামের সবুজ বেতের ফালি বুনে; গাছটা সিলেট অঞ্চলের নিচু জলাভূমিতে প্রচুর জন্মে।\\n▸ মুর্তা জোগাড় ও ফালি তৈরির কাজ বেশি করেন পুরুষেরা, আর বোনার কাজে নারীরা বেশি জড়িত থাকেন, বিশেষ করে পরিবারের ভেতরে।\\n▸ ২০১৭ সালে ইউনেস্কো শীতলপাটি বোনার শিল্পকে অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় যুক্ত করে।", "এক কথায়: শীতলপাটি হাতে বোনা, আর মুর্তা বেতই এর প্রাণ।\\nনিজে করে দেখি: পাটি বা মাদুরে হাত বুলিয়ে দেখুন, ফালিগুলো কীভাবে ওপর-নিচ করে বোনা।"]','[{"label": "UNESCO", "url": "https://ich.unesco.org/en/decisions/12.COM/11.B.4"}, {"label": "The Daily Star", "url": "https://www.thedailystar.net/slow-reads/focus/news/the-quiet-lessons-shital-pati-4183636"}]','[{"src": "/media/ronge-ronge-bangla/270116-03-shital-pati-from-murta-cane-1.webp", "width": 960, "height": 1200, "alt": "শীতলপাটি এখন ইউনেস্কোর ঐতিহ্য (২০১৭), কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270116-03-shital-pati-from-murta-cane-2.webp", "width": 960, "height": 1200, "alt": "শীতলপাটি এখন ইউনেস্কোর ঐতিহ্য (২০১৭), কার্ড 2"}]','["Faizul Latif Chowdhury, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sheetal_Pati_Sunamganj.jpg", "Nurunnaby Chowdhury (Hasive), CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sheetal_Pati_at_Bangladesh_National_Museum,_Dhaka.jpg"]','history','sparkle','coral',1,'2027-01-16');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270123-04-nakshi-kantha','ronge-ronge-bangla','card','একটা কাঁথায় ৩-৭টা পুরোনো শাড়ি','সাদা কাঁথায় ফোঁড়ের সারি আর কমলা ফুল','["▸ নকশি কাঁথা বানানো হয় পুরোনো কাপড়, ফেলে দেওয়া শাড়ি, ধুতি আর লুঙ্গি দিয়ে।\\n▸ তিন থেকে সাতটা শাড়ি স্তরে স্তরে সাজিয়ে সরল ফোঁড় দিয়ে সেলাই করা হয়।\\n▸ আগে রঙিন শাড়ির পাড় থেকে সুতো টেনে নকশা তোলা হতো; মাঝখানে থাকে পদ্ম, কোণায় গাছ।", "এক কথায়: পুরোনো কাপড় ফেলনা নয়; সুতোর ফোঁড়ে সেটাই নতুন নকশা।\\nনিজে করে দেখি: পুরোনো কাপড়ের টুকরোয় সুঁই-সুতো দিয়ে সারি সারি ফোঁড় তুলে দেখুন।"]','[{"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Nakshi_Kantha"}, {"label": "Cooper Hewitt", "url": "https://www.cooperhewitt.org/2016/11/22/kantha/"}]','[{"src": "/media/ronge-ronge-bangla/270123-04-nakshi-kantha-1.webp", "width": 960, "height": 1200, "alt": "একটা কাঁথায় ৩-৭টা পুরোনো শাড়ি, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270123-04-nakshi-kantha-2.webp", "width": 960, "height": 1200, "alt": "একটা কাঁথায় ৩-৭টা পুরোনো শাড়ি, কার্ড 2"}]','["A junaid alam khan (talk), Public domain, https://commons.wikimedia.org/wiki/File:Nakshi_kantha_(Flower_motif).JPG", "Auyon, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Kantha_Closeup.jpg"]','history','sparkle','coral',1,'2027-01-23');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270130-05-dotara-two-strings','ronge-ronge-bangla','card','কাঠের খোলে চামড়া টেনে বানানো হয় দোতারা','চামড়ায় ঢাকা গোল খোল আর মাথায় তার বাঁধার খুঁটি, দোতারা','["▸ ফাঁপা কাঠের খোলে চামড়া টেনে দোতারা বানানো হয়; ওপরের কাঠে পাখির নকশা খোদাই থাকে।\\n▸ নামের মানে দুই তার, কিন্তু বাস্তবে এতে চার বা ছয় তারও লাগানো হয়।\\n▸ ভাওয়াইয়া গান ''দোতারা গান'' নামেও পরিচিত; ইউনেস্কোর বাউল গানের বিবরণে দোতারা যন্ত্রের নামটা আলাদা করে উল্লেখ করা আছে।", "এক কথায়: নাম দেখে যন্ত্র চেনা যায় না; আগে তার গুনে দেখতে হয়!\\nনিজে করে দেখি: পরের বার ভাওয়াইয়া বা বাউল গান শুনলে কান পেতে বলুন, কয়টা তারের সুর শোনা যাচ্ছে।"]','[{"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Dotara"}, {"label": "UNESCO", "url": "https://ich.unesco.org/en/RL/baul-songs-00107"}]','[{"src": "/media/ronge-ronge-bangla/270130-05-dotara-two-strings-1.webp", "width": 960, "height": 1200, "alt": "কাঠের খোলে চামড়া টেনে বানানো হয় দোতারা, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270130-05-dotara-two-strings-2.webp", "width": 960, "height": 1200, "alt": "কাঠের খোলে চামড়া টেনে বানানো হয় দোতারা, কার্ড 2"}]','["Aniruddha Buragohain, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Lukobadya_dotara.jpg", "Contact Base (WB), CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Baul_instruments_in_the_making.jpg (coin, cropped)"]','history','sparkle','coral',1,'2027-01-30');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270206-06-alpona-rice-paste','ronge-ronge-bangla','card','আলপনা আঁকা হয় চালবাটায়','দোরগোড়ায় চালের গুঁড়োয় আঁকা সাদা আলপনা','["▸ আলপনা মেঝে ও দেয়ালের লোকশিল্প; এ শিল্প বেশির ভাগ নারীরাই বাঁচিয়ে রেখেছেন।\\n▸ রং হয় রোদে শুকানো আতপ চালের গুঁড়ো বা চালবাটা পানিতে গুলে।\\n▸ নকশা সাধারণত হাতে, না থামা রেখায় আঁকা হয়; মোটিফে থাকে ধানের শীষ, পদ্ম, মাছ, পেঁচা।", "এক কথায়: সাদা আলপনা মানে চালেরই আঁকা ছবি।\\nনিজে করে দেখি: একটু চালের গুঁড়ো পানিতে গুলে বারান্দার মেঝেতে ছোট একটা ফুল আঁকুন।"]','[{"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Alpana"}, {"label": "The Federal", "url": "https://thefederal.com/category/features/how-alpana-the-floor-art-of-bengal-became-a-part-of-its-culture-milieu-180500"}]','[{"src": "/media/ronge-ronge-bangla/270206-06-alpona-rice-paste-1.webp", "width": 960, "height": 1200, "alt": "আলপনা আঁকা হয় চালবাটায়, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270206-06-alpona-rice-paste-2.webp", "width": 960, "height": 1200, "alt": "আলপনা আঁকা হয় চালবাটায়, কার্ড 2"}]','["Shonamug, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Alpona_or_drawings_made_right_at_the_doorstep_with_chalk_water_is_mandatory_during_marriage_in_any_Bengali_household_in_India.This_is_re", "Tripan123, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:White-alpana_design.jpg"]','history','sparkle','coral',1,'2027-02-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270213-07-kantajew-terracotta','ronge-ronge-bangla','card','ইটের দেয়ালে পোড়ামাটির গল্প','কান্তনগর মন্দিরের টেরাকোটা ফলক, দিনাজপুর','["▸ দিনাজপুরের কান্তনগর মন্দির ইটের তৈরি; দেয়াল ঢাকা পোড়ামাটির ফলকে।\\n▸ ফলকে রামায়ণ-মহাভারত, কৃষ্ণের লীলা, শিকার, শোভাযাত্রা আর নদীতে নৌকাবিহারের নানা দৃশ্য খোদাই করা আছে।\\n▸ মহারাজা প্রাণনাথ শুরু করেন, তাঁর দত্তক পুত্র রামনাথ শেষ করেন; কাজ শেষ হয় ১৭৫২ সালে।", "এক কথায়: এখানে দেয়ালটাই গল্পের বই, আর পাতাগুলো পোড়ামাটির।\\nনিজে করে দেখি: পোড়ামাটির টাইল বা হাঁড়ির গায়ে আঙুল বুলিয়ে নকশার খাঁজ অনুভব করুন।"]','[{"label": "Banglapedia", "url": "https://en.banglapedia.org/index.php/Kantanagar_Temple"}, {"label": "Janomot", "url": "https://english.janomot.com/news/153902/the-historical-terracotta-kantaji-temple-at-kaharole-in-bangladesh"}]','[{"src": "/media/ronge-ronge-bangla/270213-07-kantajew-terracotta-1.webp", "width": 960, "height": 1200, "alt": "ইটের দেয়ালে পোড়ামাটির গল্প, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270213-07-kantajew-terracotta-2.webp", "width": 960, "height": 1200, "alt": "ইটের দেয়ালে পোড়ামাটির গল্প, কার্ড 2"}]','["মোহাম্মদ মোল্লা মিলন, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:%E0%A6%95%E0%A6%BE%E0%A6%A8%E0%A7%8D%E0%A6%A4%E0%A6%A8%E0%A6%97%E0%A6%B0_%E0%A6%AE%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A6%BF%E0%A6", "Rahul_Kumar_Sanjowal, CC0, https://commons.wikimedia.org/wiki/File:Kantajew_Temple,_Dinajpur.jpeg"]','history','sparkle','coral',1,'2027-02-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270220-08-flute-holes-and-pitch','ronge-ronge-bangla','card','বাঁশির ফুটো খুললে সুর চড়ে','নকশা করা বাঁশের বাঁশি, ফুটোসহ','["▸ বাঁশির ভেতরের বাতাস কেঁপে ওঠে বলেই আওয়াজ হয়, যখন ফুঁ ফুটোর পাশ দিয়ে যায়।\\n▸ বাতাসের স্তম্ভ ছোট হলে সুর চড়ে ওঠে, আর লম্বা হলে সুর নিচে নেমে যায়, এটাই বাঁশির মূল হিসাব।\\n▸ ফুটো খুললে বাতাসের স্তম্ভ কার্যত ছোট হয়ে যায়, আর তাই সুর আগের চেয়ে চড়া হয়ে যায়।", "এক কথায়: ফুটো খোলা মানে বাঁশি কার্যত ছোট হওয়া, তাই সুরও চড়া।\\nনিজে করে দেখি: খালি বোতলের মুখে ফুঁ দিয়ে সুর শুনুন; এরপর পানি ঢেলে আবার ফুঁ দিন।"]','[{"label": "UNSW Music Acoustics", "url": "https://newt.phys.unsw.edu.au/jw/fluteacoustics.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Flute"}]','[{"src": "/media/ronge-ronge-bangla/270220-08-flute-holes-and-pitch-1.webp", "width": 960, "height": 1200, "alt": "বাঁশির ফুটো খুললে সুর চড়ে, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270220-08-flute-holes-and-pitch-2.webp", "width": 960, "height": 1200, "alt": "বাঁশির ফুটো খুললে সুর চড়ে, কার্ড 2"}]','["Mp3moment, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Bengali_bamboo_flutes.jpg", "Pallab Kumar Nath, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Bamboo_flutes.jpg"]','history','sparkle','coral',1,'2027-02-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270227-09-clay-colours-and-fire','ronge-ronge-bangla','card','মাটির রঙ বলে দেয় আগুনের ভেতরের কথা','পাশাপাশি লাল আর কালো মাটির পাত্র, বাংলাদেশের বাজার','["▸ মাটিতে লোহার যৌগ থাকে; পোড়ানোর সময় তার রঙ কী হবে, তা নির্ভর করে ভাটার বাতাসের অক্সিজেনের ওপর।\\n▸ অক্সিজেন প্রচুর থাকলে লোহা লাল-বাদামি যৌগ (Fe₂O₃) হয়ে থাকে, তাই পাত্র লালচে হয়।\\n▸ অক্সিজেন কেটে দিলে, প্রায় ৯০০ ডিগ্রিতে, লোহা কালো যৌগে বদলায়, তাই পাত্র কালো হয়।", "এক কথায়: লাল-কালো হাঁড়ির পার্থক্য: আগুনে অক্সিজেনের কম-বেশি।\\nনিজে করে দেখি: জং ধরা লোহার রঙ আর লাল মাটির হাঁড়ির রঙ পাশাপাশি রেখে মিলিয়ে দেখুন।"]','[{"label": "PotteryTeachers", "url": "https://potteryteachers.com/difference-between-oxidation-and-reduction-firing/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Three-phase_firing"}]','[{"src": "/media/ronge-ronge-bangla/270227-09-clay-colours-and-fire-1.webp", "width": 960, "height": 1200, "alt": "মাটির রঙ বলে দেয় আগুনের ভেতরের কথা, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270227-09-clay-colours-and-fire-2.webp", "width": 960, "height": 1200, "alt": "মাটির রঙ বলে দেয় আগুনের ভেতরের কথা, কার্ড 2"}]','["Dolon Prova, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Pottery_of_Bangladesh.jpg", "Frameofashik, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:The_traditional_pottery_of_Bangladesh_728.jpg"]','history','sparkle','coral',1,'2027-02-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270306-10-bhapa-pitha-steam','ronge-ronge-bangla','card','পিঠার সাদা কুয়াশা আসলে পানির ফোঁটা','মাটির থালায় ভাপা পিঠা, চালের গুঁড়ো আর গুড়ের পুর','["▸ ভাপা পিঠা চালের গুঁড়োয় তৈরি বাষ্পে সেদ্ধ পিঠা; বাংলাদেশে এটা শীতের ঐতিহ্যবাহী খাবার।\\n▸ পানির বাষ্প অদৃশ্য; বাতাসে সব সময় জলীয় বাষ্প থাকে, কিন্তু আমরা তা দেখি না।\\n▸ গরম বাষ্প ঠান্ডা বাতাসে লাগলে ঘনীভূত হয়ে ক্ষুদ্র পানির ফোঁটা হয়; সেই ফোঁটার ঝাঁকই সাদা কুয়াশার মতো দেখায়।", "এক কথায়: সাদা ভাপ বাষ্প নয়; বাষ্প ঠান্ডা হয়ে বানানো পানির ফোঁটা।\\nনিজে করে দেখি: গরম চায়ের কাপ থেকে ওঠা ভাপ দূর থেকে দেখুন: কাপের ঠিক ওপরে কি ফাঁকা জায়গা আছে?"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bhapa_pitha"}, {"label": "USGS Water Science School", "url": "https://www.usgs.gov/water-science-school/science/condensation-and-water-cycle"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bhapa_pitha"}]','[{"src": "/media/ronge-ronge-bangla/270306-10-bhapa-pitha-steam-1.webp", "width": 960, "height": 1200, "alt": "পিঠার সাদা কুয়াশা আসলে পানির ফোঁটা, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270306-10-bhapa-pitha-steam-2.webp", "width": 960, "height": 1200, "alt": "পিঠার সাদা কুয়াশা আসলে পানির ফোঁটা, কার্ড 2"}]','["Dolon Prova, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Bhapa_Pitha_%E0%A6%AD%E0%A6%BE%E0%A6%AA%E0%A6%BE_%E0%A6%AA%E0%A6%BF%E0%A6%A0%E0%A6%BE.jpg", "ANKAN, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Bhapa_Pitha.jpg"]','history','sparkle','coral',1,'2027-03-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270313-11-sixty-dome-mosque','ronge-ronge-bangla','card','ষাট গম্বুজ মসজিদ বানাতে ১৭ বছর লেগেছিল','পোড়া ইটের দেয়াল আর গম্বুজের সারি, ষাট গম্বুজ মসজিদ, বাগেরহাট','["▸ বাগেরহাটের ষাট গম্বুজ মসজিদ সুলতানি আমলে, পঞ্চদশ শতকে তৈরি।\\n▸ বানিয়েছেন সুন্দরবনের শাসক উলুগ খান জাহান; কাজ ১৪৪২ সালে শুরু হয়ে ১৪৫৯ সালে শেষ হয়।\\n▸ বাগেরহাটের মসজিদ-নগরীর ভবন পোড়া ইটে গড়া, আর এটি ইউনেস্কো বিশ্ব ঐতিহ্যস্থান।", "এক কথায়: পোড়া ইটের এই গম্বুজ-ঘর ৫০০ বছরেরও বেশি সময় ধরে টিকে আছে।\\nনিজে করে দেখি: আপনার এলাকার সবচেয়ে পুরোনো দালানটা খুঁজে তার বয়স জানার চেষ্টা করুন।"]','[{"label": "Beautiful Bangladesh", "url": "https://beautifulbangladesh.gov.bd/district-destination/bagerhat/heritage/56"}, {"label": "Google Arts & Culture", "url": "https://artsandculture.google.com/entity/mosque-city-of-bagerhat/m072lh5?hl=en"}]','[{"src": "/media/ronge-ronge-bangla/270313-11-sixty-dome-mosque-1.webp", "width": 960, "height": 1200, "alt": "ষাট গম্বুজ মসজিদ বানাতে ১৭ বছর লেগেছিল, কার্ড 1"}, {"src": "/media/ronge-ronge-bangla/270313-11-sixty-dome-mosque-2.webp", "width": 960, "height": 1200, "alt": "ষাট গম্বুজ মসজিদ বানাতে ১৭ বছর লেগেছিল, কার্ড 2"}]','["মোয়ায মাহমুদ, CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Sixty_Dome_Mosque,Bagerhat.jpg", "Rds26, CC BY-SA 3.0, https://commons.wikimedia.org/wiki/File:Sixty_Dome_Mosque_in_Bagerhat_Bangladesh.JPG"]','history','sparkle','coral',1,'2027-03-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270106-01-peyaj','rannaghorer-biggan-season-1','card','পেঁয়াজ নয়, কাঁদায় একটা গ্যাস!','পেঁয়াজ নিজে কাঁদায় না। কাটার আগে ওর ভেতরে কান্নার গ্যাসটাই নেই!','["কাটলে কোষ ভাঙে, দুটি এনজাইম সালফার-যৌগকে প্রোপ্যানথিয়াল এস-অক্সাইড নামের উবে-যাওয়া গ্যাসে বদলে দেয়। গ্যাস চোখের পানির সাথে মিশে মৃদু অ্যাসিড হয়, তাই চোখ জ্বলে, পানি আসে।\\nটিপ: কাটার আগে কিছুক্ষণ ফ্রিজে রাখলে বিক্রিয়া ধীর হয়।"]','[{"label": "The Conversation", "url": ""}, {"label": "Wikipedia", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270106-01-peyaj-1.webp", "width": 960, "height": 1200, "alt": "পেঁয়াজ নয়, কাঁদায় একটা গ্যাস!, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270106-01-peyaj-2.webp", "width": 960, "height": 1200, "alt": "পেঁয়াজ নয়, কাঁদায় একটা গ্যাস!, কার্ড 2"}]','["Amada44, Wikimedia Commons, সর্বজনীন সম্পত্তি https://commons.wikimedia.org/wiki/File:Red_onion_cut.jpg"]','food','pot','coral',1,'2027-01-06');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270113-02-dudh-uchle','rannaghorer-biggan-season-1','card','দুধ উপচে পড়ে, পানি নয় কেন?','পানি ফুটলে বুদবুদ ফেটে যায়। দুধ ফুটলে কেন উপচে পড়ে?','["দুধের কেসিন প্রোটিন গরমে বুদবুদের গায়ে লেগে সেটিকে শক্ত রাখে, ওপরে সর পড়ে বাষ্প আটকে দেয়। চাপ বাড়তে বাড়তে ফেনা হাঁড়ি ছাপিয়ে বেরোয়।\\nটিপ: বড় মুখের হাঁড়ি নিন, আঁচ কমান। কাঠের চামচ অল্প সময় কাজ করে, নামিয়ে নেওয়াই নিশ্চিত।"]','[{"label": "Phys.org / The Conversation", "url": ""}, {"label": "University of Illinois Physics Van Q&A", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270113-02-dudh-uchle-1.webp", "width": 960, "height": 1200, "alt": "দুধ উপচে পড়ে, পানি নয় কেন?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270113-02-dudh-uchle-2.webp", "width": 960, "height": 1200, "alt": "দুধ উপচে পড়ে, পানি নয় কেন?, কার্ড 2"}]','["Bssasidhar, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Overflowing_boiling_milk_during_gruhapravesam.jpg"]','food','pot','coral',1,'2027-01-13');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270114-03-khejur-ros','rannaghorer-biggan-season-1','card','খেজুরের রস কাঁচা খাওয়া নিরাপদ?','শীতের খেজুরের রস কাঁচা খাওয়া কি নিরাপদ?','["WHO জানায়, নিপাহ ভাইরাস সংক্রমণের একটি পথ বাদুড়ে দূষিত কাঁচা খেজুরের রস। বাংলাদেশে ২০০১ সাল থেকে প্রায় প্রতি বছর নিপাহ শনাক্ত হয়েছে।\\nরস ফুটিয়ে নিয়ে খান। গাছে রসের হাঁড়ি ঢেকে রাখলে বাদুড়ের ছোঁয়া কমে (গবেষণায় ৮৫% রাত থেকে ৩৫% রাত)।"]','[{"label": "WHO Nipah virus fact sheet", "url": ""}, {"label": "Nahar et al. 2012", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270114-03-khejur-ros-1.webp", "width": 960, "height": 1200, "alt": "খেজুরের রস কাঁচা খাওয়া নিরাপদ?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270114-03-khejur-ros-2.webp", "width": 960, "height": 1200, "alt": "খেজুরের রস কাঁচা খাওয়া নিরাপদ?, কার্ড 2"}]','["Sadeed10646, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Khejur_rosh.jpg"]','food','pot','coral',1,'2027-01-14');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270120-04-bhat-chotchote','rannaghorer-biggan-season-1','card','কোনো ভাত ঝরঝরে, কোনোটা চটচটে!','একই রান্না, তবু কোনো চাল ঝরঝরে, কোনোটা চটচটে। কারণ চালের স্টার্চ।','["চালের স্টার্চে আছে অ্যামাইলোজ ও অ্যামাইলোপেকটিন। রান্নার সময় দানা থেকে অ্যামাইলোপেকটিন বেরিয়ে দানার গায়ে লেগে চটচটে ভাব আনে; অ্যামাইলোজ বেশি হলে দানা শক্ত থাকে।\\nঝরঝরে ভাত চাইলে বেশি অ্যামাইলোজের চাল বেছে নিন।"]','[{"label": "PMC5338010", "url": ""}, {"label": "PubMed 29805029", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270120-04-bhat-chotchote-1.webp", "width": 960, "height": 1200, "alt": "কোনো ভাত ঝরঝরে, কোনোটা চটচটে!, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270120-04-bhat-chotchote-2.webp", "width": 960, "height": 1200, "alt": "কোনো ভাত ঝরঝরে, কোনোটা চটচটে!, কার্ড 2"}]','["Douglas Perkins, Wikimedia Commons, CC0 https://commons.wikimedia.org/wiki/File:A_bowl_of_rice.jpg"]','food','pot','coral',1,'2027-01-20');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270127-05-holud-dag','rannaghorer-biggan-season-1','card','হলুদের দাগ উঠতে চায় না কেন?','হলুদ লাগলে দাগ কেন উঠতে চায় না?','["হলুদের রং কারকিউমিন পানিতে প্রায় মেশে না, কিন্তু তেল-চর্বিতে মেশে। আর আলোতে তার রং ধীরে ফিকে হয়।\\nটিপ: দাগে আগে সামান্য তেল বা সাবান ঘষুন, তারপর ধুয়ে রোদে মেলুন।"]','[{"label": "PMC3744901 and PMC12408333", "url": ""}, {"label": "stain-removal tip is an inference from t", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270127-05-holud-dag-1.webp", "width": 960, "height": 1200, "alt": "হলুদের দাগ উঠতে চায় না কেন?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270127-05-holud-dag-2.webp", "width": 960, "height": 1200, "alt": "হলুদের দাগ উঠতে চায় না কেন?, কার্ড 2"}]','["Barbara-Ingeborg, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Grounded_turmeric.jpg"]','food','pot','coral',1,'2027-01-27');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270203-06-pressure-cooker','rannaghorer-biggan-season-1','card','প্রেশার কুকার সময় বাঁচায় কীভাবে?','প্রেশার কুকারে রান্না এত তাড়াতাড়ি হয় কেন?','["বন্ধ হাঁড়িতে বাষ্প আটকে চাপ বাড়ে, আর চাপ বাড়লে পানির ফুটনাঙ্কও বাড়ে। ১৫ psi-তে পানি প্রায় ১২১°সে. পর্যন্ত গরম হয়, তাই রান্নার সময় প্রায় এক-তৃতীয়াংশে নামে।\\nটিপ: ঢাকনা খোলার আগে চাপ পুরো নামতে দিন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "HyperPhysics", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270203-06-pressure-cooker-1.webp", "width": 960, "height": 1200, "alt": "প্রেশার কুকার সময় বাঁচায় কীভাবে?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270203-06-pressure-cooker-2.webp", "width": 960, "height": 1200, "alt": "প্রেশার কুকার সময় বাঁচায় কীভাবে?, কার্ড 2"}]','["Wikimedia Commons, CC BY-SA 3.0 https://commons.wikimedia.org/wiki/File:Pressure_cooker.jpg"]','food','pot','coral',1,'2027-02-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270210-07-iftar-khejur','rannaghorer-biggan-season-1','card','ইফতারে খেজুর কেন ভালো শুরু?','রমজানের ইফতারে খেজুর দিয়ে শুরু করার রীতির পেছনে কী আছে?','["খেজুর দ্রুত শক্তি জোগায়। WHO-র আঞ্চলিক দপ্তর ইফতার শুরুর জন্য তিনটি খেজুরের কথা বলে, ধীরে খেতে বলে, আর ইফতার-সেহরির মাঝে প্রচুর পানি (৮-১০ কাপ) পানের পরামর্শ দেয়।\\nডায়াবেটিস, উচ্চ রক্তচাপ বা কিডনির রোগ থাকলে রোজার আগে ডাক্তারের পরামর্শ নিন।"]','[{"label": "WHO EMRO nutrition / Ramadan pages", "url": ""}, {"label": "WHO Bangladesh", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270210-07-iftar-khejur-1.webp", "width": 960, "height": 1200, "alt": "ইফতারে খেজুর কেন ভালো শুরু?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270210-07-iftar-khejur-2.webp", "width": 960, "height": 1200, "alt": "ইফতারে খেজুর কেন ভালো শুরু?, কার্ড 2"}]','["Amirhusenjihed, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Traditional_Iftar_platter_with_Biryani_and_Dates_in_Sylhet,_Bangladesh_(1).jpg"]','food','pot','coral',1,'2027-02-10');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270217-08-ilish-tel','rannaghorer-biggan-season-1','card','ইলিশ এত তেলতেলে কেন?','ইলিশ এত তেলতেলে, আর সেই তেলেই কী লুকিয়ে?','["ইলিশ চর্বিসমৃদ্ধ মাছ। সেই চর্বিতে আছে ডিএইচএ ও ইপিএ নামের ওমেগা-৩। ভারতের এক গবেষণায় ১০০ গ্রাম ইলিশে ডিএইচএ প্রায় ৯৩০ মিগ্রা পাওয়া গেছে (মান আকার-নদীভেদে বদলায়)।\\nটিপ: পরিমাণ মেপে খান; ভাজার বদলে ঝোল বা ভাপায় বাড়তি তেল কমে।"]','[{"label": "PMC4989070", "url": ""}, {"label": "PMC6917730", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270217-08-ilish-tel-1.webp", "width": 960, "height": 1200, "alt": "ইলিশ এত তেলতেলে কেন?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270217-08-ilish-tel-2.webp", "width": 960, "height": 1200, "alt": "ইলিশ এত তেলতেলে কেন?, কার্ড 2"}]','["Rajeeb (Marajozkee), Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Hilsa_fish.jpg"]','food','pot','coral',1,'2027-02-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270218-09-fridge-gorom','rannaghorer-biggan-season-1','card','গরম খাবার ফ্রিজে রাখা যাবে না?','গরম খাবার ঠান্ডা না করে ফ্রিজে রাখা যাবে না, এটা কি সত্যি?','["CDC বলছে, গরম খাবারও ফ্রিজে রাখা যায়। ছোট ও অগভীর কয়েকটি পাত্রে ভাগ করলে দ্রুত ঠান্ডা হয়। রান্নার ২ ঘণ্টার মধ্যে (প্রচণ্ড গরমে ১ ঘণ্টা) ফ্রিজে রাখুন; ফ্রিজ ৪°সে. বা তার নিচে।\\nআবার গরম করলে ভালো করে গরম করে নিন।"]','[{"label": "CDC Food Safety prevention page", "url": ""}, {"label": "FDA Tips to Chill Food", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270218-09-fridge-gorom-1.webp", "width": 960, "height": 1200, "alt": "গরম খাবার ফ্রিজে রাখা যাবে না?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270218-09-fridge-gorom-2.webp", "width": 960, "height": 1200, "alt": "গরম খাবার ফ্রিজে রাখা যাবে না?, কার্ড 2"}]','["Bretwa, Wikimedia Commons, CC0 https://commons.wikimedia.org/wiki/File:Food_into_a_refrigerator_-_20111002.jpg"]','food','pot','coral',1,'2027-02-18');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270224-10-jhal-pani','rannaghorer-biggan-season-1','card','ঝাল লাগলে পানি খেলে কমে?','ঝাল লাগলে ঢকঢক পানি খেলে কি ঝাল কমে?','["ক্যাপসাইসিন পানিতে মেশে না, তাই পানিতে বিশেষ লাভ হয় না। দুধের কেসিন একে মিশিয়ে নিতে পারে, তাই দুধ বা দই বেশি কাজে দেয়।\\nমরিচ কাটার পর চোখে হাত দেবেন না।"]','[{"label": "Wikipedia", "url": ""}, {"label": "Penn State research on dairy proteins an", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270224-10-jhal-pani-1.webp", "width": 960, "height": 1200, "alt": "ঝাল লাগলে পানি খেলে কমে?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270224-10-jhal-pani-2.webp", "width": 960, "height": 1200, "alt": "ঝাল লাগলে পানি খেলে কমে?, কার্ড 2"}]','["Medhi jyoti, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Green_chillies_variety.jpg"]','food','pot','coral',1,'2027-02-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270303-11-lebu-ayron','rannaghorer-biggan-season-1','card','শাক-ডালে লেবু: কেন দরকারি?','ডাল বা শাকে লেবু নিংড়ালে সত্যিই কি লাভ হয়?','["ভিটামিন সি উদ্ভিজ্জ (নন-হিম) আয়রনের শোষণ বাড়াতে সাহায্য করে। লেবু ভিটামিন সি-র ভালো উৎস, যদিও লেবুর ওপর সরাসরি পরীক্ষা এখানে ধরা হয়নি।\\nচা আয়রন শোষণ কমাতে পারে, তাই খাবারের সময় চা এড়ানো ভালো।"]','[{"label": "Harvard Nutrition Source", "url": ""}, {"label": "PMC13696866", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270303-11-lebu-ayron-1.webp", "width": 960, "height": 1200, "alt": "শাক-ডালে লেবু: কেন দরকারি?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270303-11-lebu-ayron-2.webp", "width": 960, "height": 1200, "alt": "শাক-ডালে লেবু: কেন দরকারি?, কার্ড 2"}]','["Ivar Leidus, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Lemon_-_whole_and_split.jpg"]','food','pot','coral',1,'2027-03-03');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270304-12-thanda-bhat','rannaghorer-biggan-season-1','card','ঠান্ডা ভাত গরম করলে বিষ?','ঠান্ডা ভাত গরম করে খেলে কি বিষ হয়?','["আসল সমস্যা ভাত ঘরের তাপে বেশিক্ষণ পড়ে থাকা। তখন ব্যাসিলাস সেরিয়াস বেড়ে এমন বিষ বানায়, যা আবার গরম করলেও নষ্ট হয় না। ভাত দ্রুত ঠান্ডা করে ফ্রিজে (৫°সে.-র নিচে) রাখুন।\\nঘরের তাপে ঘণ্টার পর ঘণ্টা পড়ে থাকা ভাত ফেলে দিন।"]','[{"label": "Wikipedia", "url": ""}, {"label": "second source status in Sources.md", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270304-12-thanda-bhat-1.webp", "width": 960, "height": 1200, "alt": "ঠান্ডা ভাত গরম করলে বিষ?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270304-12-thanda-bhat-2.webp", "width": 960, "height": 1200, "alt": "ঠান্ডা ভাত গরম করলে বিষ?, কার্ড 2"}]','["Sohel Commons, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Ilish_Bhaat.jpg"]','food','pot','coral',1,'2027-03-04');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270311-13-tel-bar-bar','rannaghorer-biggan-season-1','card','ভাজার তেল বারবার চালানো ঠিক?','একই তেলে বারবার ভাজা কি নিরাপদ?','["বারবার গরম করা তেলে পোলার যৌগ, অ্যালডিহাইড ও ট্রান্স ফ্যাটের মতো ক্ষতিকর যৌগ জমে। গবেষণা বেশিরভাগই ল্যাব ও প্রাণীর ওপর, তবু সাবধান থাকাই ভালো।\\nকালচে রং, ধোঁয়া বা বাসি গন্ধ হলে তেল ফেলে দিন।"]','[{"label": "PMC7254282", "url": ""}, {"label": "PMC12071793", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270311-13-tel-bar-bar-1.webp", "width": 960, "height": 1200, "alt": "ভাজার তেল বারবার চালানো ঠিক?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270311-13-tel-bar-bar-2.webp", "width": 960, "height": 1200, "alt": "ভাজার তেল বারবার চালানো ঠিক?, কার্ড 2"}]','["Marajozkee, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Onion_Pakora_01.jpg"]','food','pot','coral',1,'2027-03-11');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270317-14-ayodin-lobon','rannaghorer-biggan-season-1','card','লবণে আয়োডিন কেন মেশানো?','লবণে আয়োডিন মেশানো হয় কেন?','["আয়োডিনের অভাবে গলগণ্ডসহ নানা সমস্যা হয়। তাই WHO ও UNICEF ১৯৯৩ সালে সব খাবার লবণে আয়োডিন মেশানোর সুপারিশ করে। বাংলাদেশে ৫০ পিপিএম আয়োডিনের লক্ষ্য ছিল, তবু গ্রামে গর্ভবতী নারীদের ঘাটতির প্রমাণ মিলেছে।\\nআয়োডিনযুক্ত লবণ কিনুন, কিন্তু লবণ পরিমিত খান।"]','[{"label": "UNICEF Sustainable Elimination of Iodine", "url": ""}, {"label": "PMC6860684", "url": ""}, {"label": "WHO USI guidance via PMC summaries", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270317-14-ayodin-lobon-1.webp", "width": 960, "height": 1200, "alt": "লবণে আয়োডিন কেন মেশানো?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270317-14-ayodin-lobon-2.webp", "width": 960, "height": 1200, "alt": "লবণে আয়োডিন কেন মেশানো?, কার্ড 2"}]','["Poyraz 72, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Table_salt_with_salt_shaker_V1.jpg"]','food','pot','coral',1,'2027-03-17');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270324-15-pauruti-fole','rannaghorer-biggan-season-1','card','পাউরুটি ফোলে কীভাবে?','পাউরুটি ফোলে কীভাবে?','["ইস্ট ময়দার চিনি খেয়ে কার্বন ডাই-অক্সাইড ছাড়ে, আর গ্লুটেনের জাল সেই গ্যাস আটকে রাখে। তাই ময়দা ফোলে। ওভেনের তাপে আরেকটু ফোলে, একে বলে ওভেন স্প্রিং।\\nটিপ: উষ্ণ জায়গায় ঢেকে রাখলে ইস্ট বেশি সক্রিয় থাকে।"]','[{"label": "Britannica", "url": ""}, {"label": "Iowa State University Extension", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270324-15-pauruti-fole-1.webp", "width": 960, "height": 1200, "alt": "পাউরুটি ফোলে কীভাবে?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270324-15-pauruti-fole-2.webp", "width": 960, "height": 1200, "alt": "পাউরুটি ফোলে কীভাবে?, কার্ড 2"}]','["Wald1siedel, Wikimedia Commons, CC BY-SA 4.0 https://commons.wikimedia.org/wiki/File:Bread_dough_in_baskets_01.JPG"]','food','pot','coral',1,'2027-03-24');
INSERT INTO bj_posts (slug,series_slug,kind,title,hook,body,sources,images,image_credits,topic,doodle,bg,read_minutes,published_at) VALUES ('270331-16-pakka-am','rannaghorer-biggan-season-1','card','পাকা আম মিষ্টি হয় কীভাবে?','কাঁচা আম টক, পাকা আম মিষ্টি। মাঝখানে কী ঘটে?','["কাঁচা আমে স্টার্চ বেশি। পাকার সময় এনজাইম স্টার্চকে চিনিতে ভাঙে, পেকটিন ভেঙে আম নরম হয়, অম্লতা কমে। ইথিলিন এই পাকা নিয়ন্ত্রণে বড় ভূমিকা রাখে।\\nটিপ: পাকা ফলের কাছে রাখলে কাঁচা আম দ্রুত পাকে।"]','[{"label": "UC Davis Postharvest", "url": ""}, {"label": "PMC9818659", "url": ""}]','[{"src": "/media/rannaghorer-biggan-season-1/270331-16-pakka-am-1.webp", "width": 960, "height": 1200, "alt": "পাকা আম মিষ্টি হয় কীভাবে?, কার্ড 1"}, {"src": "/media/rannaghorer-biggan-season-1/270331-16-pakka-am-2.webp", "width": 960, "height": 1200, "alt": "পাকা আম মিষ্টি হয় কীভাবে?, কার্ড 2"}]','["Sivahari, Wikimedia Commons, CC BY-SA 3.0 https://commons.wikimedia.org/wiki/File:Cut_ripe_mango_pieces.JPG"]','food','pot','coral',1,'2027-03-31');
